/**
 * CUBiO Component Specification Builder
 * Generates structured UI component specifications.
 */

import {
  FUAComponentSpec,
  FUAComponentCategory,
  FUAPropDefinition,
  FUAStateDefinition,
  FUAEventDefinition,
  FUAAccessibilityRule,
  FUAResponsiveBehavior,
} from './types';
import { DesignSystemAdapter } from './designSystemAdapter';

export class ComponentSpecificationBuilder {
  private readonly designSystem: DesignSystemAdapter;

  constructor(designSystem: DesignSystemAdapter = new DesignSystemAdapter()) {
    this.designSystem = designSystem;
  }

  public buildSpecification(
    componentName: string,
    category: FUAComponentCategory = 'COMPOSITE',
    description: string = '',
    customProps: FUAPropDefinition[] = [],
    customState: FUAStateDefinition[] = [],
    customEvents: FUAEventDefinition[] = []
  ): FUAComponentSpec {
    const defaultProps: FUAPropDefinition[] = [
      { name: 'className', type: 'string', required: false, description: 'Optional CSS class overrides' },
      { name: 'disabled', type: 'boolean', required: false, defaultValue: 'false', description: 'Disables interaction' },
    ];

    const defaultState: FUAStateDefinition[] = [
      { name: 'isLoading', type: 'boolean', initialValue: 'false', description: 'Component loading state' },
    ];

    const defaultEvents: FUAEventDefinition[] = [
      { name: 'onClick', payloadType: 'React.MouseEvent<HTMLElement>', description: 'Triggered upon user interaction' },
    ];

    const accessibility: FUAAccessibilityRule = {
      role: category === 'MODAL' ? 'dialog' : category === 'DRAWER' ? 'region' : 'generic',
      ariaLabels: [`${componentName}-label`, `${componentName}-description`],
      keyboardInteractions: ['Escape to close', 'Tab to cycle focus', 'Enter/Space to activate'],
      focusManagement: category === 'MODAL' ? 'Trap focus inside dialog, restore on close' : 'Default DOM order',
      wcagCriterion: 'WCAG 2.1 AA (1.4.3 Contrast, 2.1.1 Keyboard, 4.1.2 Name Role Value)',
    };

    const responsive: FUAResponsiveBehavior = {
      mobileBreakpoint: 'w-full px-2',
      tabletBreakpoint: 'md:w-3/4 md:px-4',
      desktopBreakpoint: 'lg:w-full lg:max-w-4xl',
      collapseToDrawer: category === 'MODAL',
    };

    const tokens = [
      'bg-zinc-950',
      'border-zinc-800',
      'text-zinc-100',
      'hover:bg-zinc-900',
      'transition-colors',
    ];

    const icon = this.designSystem.getSuggestedIcon(componentName);

    return {
      componentName,
      category,
      description: description || `CUBiO Sovereign UI Component: ${componentName}`,
      props: [...defaultProps, ...customProps],
      state: [...defaultState, ...customState],
      events: [...defaultEvents, ...customEvents],
      accessibility,
      responsive,
      designTokens: tokens,
      suggestedIcons: [icon],
    };
  }
}
