/**
 * CUBiO AI - 3D Memory Studio
 * AGENT-008 - AOA (Agent Orchestration Agent)
 * src/cubio/agents/aoa/dependencyScheduler.ts
 *
 * DAG validation, cycle detection (Kahn's / DFS algorithm),
 * topological ordering, and layer-by-layer dependency execution scheduler.
 */

import {
  AOASubtaskDefinition,
  AOADagValidationResult,
  AOABoundsConfig,
  DEFAULT_AOA_BOUNDS,
} from './types';

export class DependencyScheduler {
  constructor(private readonly bounds: AOABoundsConfig = DEFAULT_AOA_BOUNDS) {}

  /**
   * Validates DAG properties and returns topological order.
   */
  public validateDag(subtasks: readonly AOASubtaskDefinition[]): AOADagValidationResult {
    const inDegree = new Map<string, number>();
    const adj = new Map<string, string[]>();
    const errors: string[] = [];
    const allTaskIds = new Set(subtasks.map((s) => s.subtaskId));

    for (const st of subtasks) {
      inDegree.set(st.subtaskId, 0);
      adj.set(st.subtaskId, []);
    }

    for (const st of subtasks) {
      const deps = st.dependencies ?? [];
      for (const dep of deps) {
        if (!allTaskIds.has(dep)) {
          errors.push(`Task '${st.subtaskId}' has missing dependency '${dep}'.`);
          continue;
        }
        adj.get(dep)!.push(st.subtaskId);
        inDegree.set(st.subtaskId, (inDegree.get(st.subtaskId) || 0) + 1);
      }
    }

    // Kahn's algorithm for topological sorting and cycle detection
    const queue: string[] = [];
    for (const [id, deg] of inDegree.entries()) {
      if (deg === 0) queue.push(id);
    }

    const topologicalOrder: string[] = [];
    while (queue.length > 0) {
      const curr = queue.shift()!;
      topologicalOrder.push(curr);

      for (const neighbor of adj.get(curr) || []) {
        const nextDeg = (inDegree.get(neighbor) || 0) - 1;
        inDegree.set(neighbor, nextDeg);
        if (nextDeg === 0) {
          queue.push(neighbor);
        }
      }
    }

    // Check for cycles
    const cyclesDetected: string[][] = [];
    if (topologicalOrder.length < subtasks.length) {
      const remainingNodes = subtasks
        .filter((s) => !topologicalOrder.includes(s.subtaskId))
        .map((s) => s.subtaskId);
      cyclesDetected.push(remainingNodes);
      errors.push(`Cyclic dependency detected involving tasks: [${remainingNodes.join(', ')}].`);
    }

    // Check maximum dependency depth
    const depthMap = new Map<string, number>();
    for (const id of topologicalOrder) {
      const st = subtasks.find((s) => s.subtaskId === id)!;
      let maxParentDepth = 0;
      const deps = st.dependencies ?? [];
      for (const dep of deps) {
        maxParentDepth = Math.max(maxParentDepth, depthMap.get(dep) || 0);
      }
      const curDepth = deps.length === 0 ? 1 : maxParentDepth + 1;
      depthMap.set(id, curDepth);
      if (curDepth > this.bounds.maxDependencyDepth) {
        errors.push(
          `Subtask '${id}' exceeds max dependency depth (${curDepth} > ${this.bounds.maxDependencyDepth}).`
        );
      }
    }

    return {
      isValid: errors.length === 0,
      topologicalOrder: Object.freeze(topologicalOrder),
      cyclesDetected: Object.freeze(cyclesDetected),
      unresolvableDependencies: Object.freeze([]),
      errors: Object.freeze(errors),
    };
  }

  /**
   * Partitions subtasks into parallel execution layers based on topological dependencies.
   */
  public partitionExecutionLayers(
    subtasks: readonly AOASubtaskDefinition[],
    topologicalOrder: readonly string[]
  ): readonly (readonly string[])[] {
    const subtaskMap = new Map(subtasks.map((s) => [s.subtaskId, s]));
    const completedTasks = new Set<string>();
    const remainingTasks = new Set(topologicalOrder);
    const layers: string[][] = [];

    while (remainingTasks.size > 0) {
      const currentLayer: string[] = [];

      for (const id of remainingTasks) {
        const st = subtaskMap.get(id)!;
        const deps = st.dependencies ?? [];
        const allDepsSatisfied = deps.every((dep) => completedTasks.has(dep));
        if (allDepsSatisfied) {
          currentLayer.push(id);
        }
      }

      if (currentLayer.length === 0) {
        // Safety break if stuck
        break;
      }

      for (const id of currentLayer) {
        completedTasks.add(id);
        remainingTasks.delete(id);
      }

      layers.push(currentLayer);
    }

    return Object.freeze(layers.map((l) => Object.freeze(l)));
  }
}
