/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-012 — RRA (Research & Retrieval Agent)
 * src/cubio/agents/rra/types.ts
 *
 * Authoritative contracts for research requests, source references,
 * atomic facts, evidence mapping, contradiction reporting, and bounds.
 */

import { ResearchDomainCategory } from '../../intelligence/universal/research/types';

export type RRASourceScope =
  | 'SOVEREIGN_KB'
  | 'LOCAL_WORKSPACE'
  | 'PROJECT_MEMORY'
  | 'FORENSIC_INDEX';

export type RRASupportStatus =
  | 'SUPPORTED'
  | 'PARTIALLY_SUPPORTED'
  | 'UNSUPPORTED'
  | 'CONTRADICTED'
  | 'INSUFFICIENT_EVIDENCE'
  | 'NOT_EVALUATED';

export type RRARequestStatus =
  | 'SUCCEEDED'
  | 'PARTIAL'
  | 'INSUFFICIENT_EVIDENCE'
  | 'BLOCKED'
  | 'FAILED'
  | 'TIMED_OUT'
  | 'CANCELLED';

export interface RRASourceReference {
  readonly sourceId: string;
  readonly sourceType: RRASourceScope;
  readonly title: string;
  readonly uriOrLocation: string;
  readonly snippet: string;
  readonly reliabilityScore: number; // 0.0 to 1.0
  readonly domainCategory?: ResearchDomainCategory;
  readonly publishedDate?: string;
  readonly author?: string;
  readonly contentChecksum: string;
}

export interface RRAFinding {
  readonly findingId: string;
  readonly claim: string;
  readonly supportStatus: RRASupportStatus;
  readonly evidenceReferences: readonly string[]; // IDs of sources or facts
  readonly contradictingEvidenceReferences: readonly string[];
  readonly confidence: number; // 0.0 to 1.0
  readonly limitations: readonly string[];
}

export interface RRAConflictRecord {
  readonly conflictId: string;
  readonly topic: string;
  readonly sourceAId: string;
  readonly sourceBId: string;
  readonly statementA: string;
  readonly statementB: string;
  readonly conflictDescription: string;
}

export interface RRACitation {
  readonly index: number;
  readonly sourceId: string;
  readonly title: string;
  readonly uriOrLocation: string;
  readonly inlineRef: string; // e.g. "[^1]"
  readonly formattedReference: string;
}

export interface RRAResearchRequest {
  readonly requestId: string;
  readonly taskId?: string;
  readonly query: string;
  readonly researchObjective?: string;
  readonly requestingPrincipal?: string;
  readonly authorizedSourceScopes?: readonly RRASourceScope[];
  readonly maxSources?: number;
  readonly maxFindings?: number;
  readonly maxOutputBytes?: number;
  readonly correlationId?: string;
  readonly includeProjectMemory?: boolean;
  readonly timeoutMs?: number;
}

export interface RRAResearchReport {
  readonly reportId: string;
  readonly requestId: string;
  readonly query: string;
  readonly status: RRARequestStatus;
  readonly sourcesRetrieved: readonly RRASourceReference[];
  readonly findings: readonly RRAFinding[];
  readonly conflicts: readonly RRAConflictRecord[];
  readonly citations: readonly RRACitation[];
  readonly summary: string;
  readonly reportChecksum: string;
  readonly durationMs: number;
  readonly isActuationBlocked: boolean;
  readonly limitations: readonly string[];
  readonly timestamp: number;
}

export interface RRABoundsConfig {
  readonly defaultMaxSources: number;
  readonly hardMaxSources: number;
  readonly defaultMaxFindings: number;
  readonly hardMaxFindings: number;
  readonly maxOutputBytes: number;
  readonly maxQueryLength: number;
  readonly minQueryLength: number;
  readonly defaultTimeoutMs: number;
}

export const DEFAULT_RRA_BOUNDS: RRABoundsConfig = Object.freeze({
  defaultMaxSources: 3,
  hardMaxSources: 10,
  defaultMaxFindings: 10,
  hardMaxFindings: 25,
  maxOutputBytes: 128 * 1024, // 128 KB
  maxQueryLength: 1024,
  minQueryLength: 3,
  defaultTimeoutMs: 30_000,
});
