/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-009 — CEA (Code Execution Agent)
 * src/cubio/agents/cea/ceaAgent.ts
 *
 * Central facade for AGENT-009-CEA.
 * Coordinates request validation, policy checks, resource acquisition,
 * restricted execution, output sanitization, and evidence generation.
 * Permanently locks is_actuation_blocked = true.
 */

import {
  CEARequest,
  CEAResult,
  CEABoundsConfig,
  DEFAULT_CEA_BOUNDS,
  CEALifecycleState,
} from './types';
import { CommandRegistry } from './commandRegistry';
import { RequestValidator } from './requestValidator';
import { ExecutionPolicy } from './executionPolicy';
import { ResourceLimits } from './resourceLimits';
import { ExecutionAdapter } from './executionAdapter';
import { ExecutionEvidence } from './executionEvidence';

export class CodeExecutionAgent {
  public static readonly AGENT_ID = 'AGENT-009-CEA';
  public static readonly AGENT_NAME = 'Code Execution Agent';
  public static readonly VERSION = '1.0.0';

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public readonly is_actuation_blocked: boolean = true;

  private readonly registry: CommandRegistry;
  private readonly validator: RequestValidator;
  private readonly limits: ResourceLimits;
  private readonly adapter: ExecutionAdapter;
  private readonly bounds: CEABoundsConfig;

  constructor(
    customBounds: CEABoundsConfig = DEFAULT_CEA_BOUNDS,
    customRootDir?: string,
    customRegistry?: CommandRegistry,
    customAdapter?: ExecutionAdapter
  ) {
    this.bounds = customBounds;
    this.registry = customRegistry || new CommandRegistry();
    this.validator = new RequestValidator(this.registry, this.bounds, customRootDir);
    this.limits = new ResourceLimits(this.bounds);
    this.adapter = customAdapter || new ExecutionAdapter(this.bounds, customRootDir);
  }

  public getRegistry(): CommandRegistry {
    return this.registry;
  }

  /**
   * Primary entry point: Executes an authorized and validated code execution request.
   */
  public async execute(request: CEARequest): Promise<CEAResult> {
    const startedAt = Date.now();

    // 1. Mandatory Sovereign Actuation Lock Evaluation
    const policyCheck = ExecutionPolicy.evaluatePolicy(request);
    if (!policyCheck.isAllowed) {
      return this.buildImmediateFailure(
        request,
        'BLOCKED',
        startedAt,
        `POLICY_VIOLATION: ${policyCheck.reason}`
      );
    }

    // 2. Intake Schema & Argument Validation Gate
    const validation = this.validator.validate(request);
    if (!validation.isValid) {
      return this.buildImmediateFailure(
        request,
        'REJECTED',
        startedAt,
        `VALIDATION_FAILURE: ${validation.errors.join('; ')}`
      );
    }

    const sanitizedReq = validation.sanitizedRequest!;
    const approvedCmd = this.registry.getCommand(sanitizedReq.commandId)!;

    // 3. Resource & Concurrency Acquisition
    let capacityRelease: (() => void) | null = null;
    try {
      const cap = this.limits.acquireCapacity();
      capacityRelease = cap.release;
    } catch (err: any) {
      return this.buildImmediateFailure(
        sanitizedReq,
        'BLOCKED',
        startedAt,
        err?.message || 'RESOURCE_CAPACITY_EXCEEDED'
      );
    }

    // 4. Restricted Execution
    try {
      const result = await this.adapter.execute(sanitizedReq, approvedCmd);
      return result;
    } catch (err: any) {
      return this.buildImmediateFailure(
        sanitizedReq,
        'FAILED',
        startedAt,
        `EXECUTION_EXCEPTION: ${err?.message || String(err)}`
      );
    } finally {
      if (capacityRelease) {
        capacityRelease();
      }
    }
  }

  /**
   * AOA AgentInvoker contract compatibility helper.
   */
  public async invoke(payload: Record<string, unknown>): Promise<CEAResult> {
    return this.execute(payload as unknown as CEARequest);
  }

  private buildImmediateFailure(
    request: Partial<CEARequest>,
    status: CEALifecycleState,
    startedAt: number,
    failureReason: string
  ): CEAResult {
    const finishedAt = Date.now();
    const stdout = '';
    const stderr = failureReason;
    const stdoutHash = ExecutionEvidence.hashContent(stdout);
    const stderrHash = ExecutionEvidence.hashContent(stderr);

    const evidenceHash = ExecutionEvidence.computeEvidenceHash({
      requestId: request.requestId || 'UNKNOWN',
      taskId: request.taskId || 'UNKNOWN',
      commandId: request.commandId || 'NONE',
      status,
      exitCode: -1,
      stdoutHash,
      stderrHash,
      durationMs: Math.max(1, finishedAt - startedAt),
      policyVersion: this.bounds.policyVersion,
      isActuationBlocked: true,
    });

    return Object.freeze({
      requestId: request.requestId || 'UNKNOWN',
      taskId: request.taskId || 'UNKNOWN',
      commandId: request.commandId || 'NONE',
      status,
      startedAt,
      finishedAt,
      durationMs: Math.max(1, finishedAt - startedAt),
      exitCode: -1,
      stdout,
      stderr,
      truncated: false,
      timedOut: false,
      cancelled: false,
      sandboxVerified: false,
      policyVersion: this.bounds.policyVersion,
      evidenceHash,
      failureReason,
      correlationId: request.correlationId || request.requestId || 'UNKNOWN',
      isActuationBlocked: true,
    });
  }
}
