/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-011 — OMA (Observability & Monitoring Agent)
 * src/cubio/agents/oma/types.ts
 *
 * Formal contracts for normalized events, metrics, health records,
 * diagnostic summaries, and resource bounds.
 */

export type OMAHealthStatus =
  | 'HEALTHY'
  | 'DEGRADED'
  | 'UNHEALTHY'
  | 'UNKNOWN'
  | 'NOT_INSTRUMENTED'
  | 'BLOCKED';

export type OMASeverity =
  | 'INFO'
  | 'WARN'
  | 'ERROR'
  | 'CRITICAL';

export type OMAEventType =
  | 'TASK_STARTED'
  | 'TASK_COMPLETED'
  | 'TASK_FAILED'
  | 'TASK_BLOCKED'
  | 'TASK_TIMED_OUT'
  | 'SECURITY_DECISION'
  | 'EXECUTION_RECORD'
  | 'GATE_VERDICT'
  | 'HEARTBEAT'
  | 'ALERT_TRIGGERED';

export interface OMANormalizedEvent {
  readonly eventId: string;
  readonly eventType: OMAEventType;
  readonly timestamp: number;
  readonly sourceAgentId: string;
  readonly taskId?: string;
  readonly correlationId?: string;
  readonly severity: OMASeverity;
  readonly status: string;
  readonly durationMs?: number;
  readonly policyVersion?: string;
  readonly evidenceReferences: readonly string[];
  readonly sanitizedMetadata: Readonly<Record<string, unknown>>;
}

export interface OMAPercentiles {
  readonly p50Ms: number;
  readonly p95Ms: number;
  readonly p99Ms: number;
}

export interface OMAMetricSummary {
  readonly totalEvents: number;
  readonly successCount: number;
  readonly failureCount: number;
  readonly timeoutCount: number;
  readonly blockedCount: number;
  readonly averageDurationMs: number;
  readonly percentiles: OMAPercentiles;
  readonly windowStartMs: number;
  readonly windowEndMs: number;
}

export interface OMAAgentHealthRecord {
  readonly agentId: string;
  readonly healthStatus: OMAHealthStatus;
  readonly lastActiveTimestamp: number;
  readonly totalTasks: number;
  readonly failureRate: number;
  readonly details: string;
}

export interface OMAAlertRule {
  readonly ruleId: string;
  readonly name: string;
  readonly condition: (events: readonly OMANormalizedEvent[]) => boolean;
  readonly severity: OMASeverity;
  readonly description: string;
}

export interface OMAAlertRecord {
  readonly alertId: string;
  readonly ruleId: string;
  readonly severity: OMASeverity;
  readonly timestamp: number;
  readonly message: string;
  readonly evidenceReferences: readonly string[];
}

export interface OMABoundsConfig {
  readonly maxRetainedEvents: number;
  readonly maxLatencySamplesPerKey: number;
  readonly maxAlertsRetained: number;
  readonly maxMetadataBytes: number;
  readonly aggregationWindowMs: number;
}

export const DEFAULT_OMA_BOUNDS: OMABoundsConfig = Object.freeze({
  maxRetainedEvents: 1000,
  maxLatencySamplesPerKey: 500,
  maxAlertsRetained: 100,
  maxMetadataBytes: 4096, // 4 KB
  aggregationWindowMs: 300_000, // 5 minutes
});
