/**
 * CUBiO Memory & Lifecycle Analyzer
 * Evaluates cache boundaries, LRU eviction policies, and database connection cleanup.
 */

import { DSACacheLifecycleReport } from './types';

export class MemoryLifecycleAnalyzer {
  public evaluateComponentLifecycle(componentName: string, configOrCode: any): DSACacheLifecycleReport {
    let hasCapacityBound = false;
    let maxCapacity: number | undefined;
    let evictionStrategy: string | undefined;
    let connectionDisposalValid = true;
    let unboundedGrowthRisk = false;

    if (typeof configOrCode === 'object' && configOrCode !== null) {
      if ('maxCapacity' in configOrCode || 'maxItems' in configOrCode || 'maxTokens' in configOrCode) {
        hasCapacityBound = true;
        maxCapacity = configOrCode.maxCapacity || configOrCode.maxItems || configOrCode.maxTokens;
      }
      if ('evictionStrategy' in configOrCode) {
        evictionStrategy = configOrCode.evictionStrategy;
      }
      if ('autoDispose' in configOrCode) {
        connectionDisposalValid = Boolean(configOrCode.autoDispose);
      }
    } else if (typeof configOrCode === 'string') {
      const lower = configOrCode.toLowerCase();
      hasCapacityBound = lower.includes('limit') || lower.includes('max') || lower.includes('cap');
      evictionStrategy = lower.includes('lru') ? 'LRU' : lower.includes('fifo') ? 'FIFO' : undefined;
      connectionDisposalValid = lower.includes('dispose') || lower.includes('close') || lower.includes('finally');
    }

    if (!hasCapacityBound) {
      unboundedGrowthRisk = true;
    }

    return {
      component: componentName,
      hasCapacityBound,
      maxCapacity,
      evictionStrategy: evictionStrategy || (hasCapacityBound ? 'BOUNDED_CAP' : 'NONE'),
      connectionDisposalValid,
      unboundedGrowthRisk,
    };
  }
}
