/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-009 — CEA (Code Execution Agent)
 * src/cubio/agents/cea/types.ts
 *
 * Core data contracts, schemas, lifecycle states, and bounds configurations.
 */

export type CEALifecycleState =
  | 'CREATED'
  | 'VALIDATING'
  | 'AUTHORIZING'
  | 'QUEUED'
  | 'RUNNING'
  | 'COLLECTING_EVIDENCE'
  | 'SUCCEEDED'
  | 'REJECTED'
  | 'BLOCKED'
  | 'FAILED'
  | 'TIMED_OUT'
  | 'CANCELLED'
  | 'CLEANUP_FAILED';

export type CEAOperationType =
  | 'TEST_EXECUTION'
  | 'TYPE_CHECK'
  | 'LINT_CHECK'
  | 'STATIC_ANALYSIS'
  | 'INSPECTION';

export type CEAPermittedCaller =
  | 'CUBIO-NATIVE-PMA'
  | 'AGENT-008-AOA'
  | 'AGENT-003-TGA'
  | 'AGENT-013-CDA'
  | 'AGENT-009-CEA'
  | 'SYSTEM_INTERNAL';

export interface CEARequest {
  readonly requestId: string;
  readonly taskId: string;
  readonly requestedBy: CEAPermittedCaller | string;
  readonly authorizedBy?: string;
  readonly operationType: CEAOperationType;
  readonly commandId: string;
  readonly arguments: readonly string[];
  readonly workingDirectoryId?: string;
  readonly timeoutMs?: number;
  readonly outputLimitBytes?: number;
  readonly correlationId?: string;
  readonly policyVersion?: string;
  readonly envOverrides?: Readonly<Record<string, string>>;
}

export interface CEAResult {
  readonly requestId: string;
  readonly taskId: string;
  readonly commandId: string;
  readonly status: CEALifecycleState;
  readonly startedAt: number;
  readonly finishedAt: number;
  readonly durationMs: number;
  readonly exitCode: number | null;
  readonly stdout: string;
  readonly stderr: string;
  readonly truncated: boolean;
  readonly timedOut: boolean;
  readonly cancelled: boolean;
  readonly sandboxVerified: boolean;
  readonly policyVersion: string;
  readonly evidenceHash: string;
  readonly failureReason?: string;
  readonly correlationId: string;
  readonly isActuationBlocked: boolean;
}

export interface CEAApprovedCommand {
  readonly commandId: string;
  readonly description: string;
  readonly executable: string;
  readonly allowedArgumentsPattern: readonly RegExp[];
  readonly allowedOperationTypes: readonly CEAOperationType[];
  readonly maxTimeoutMs: number;
  readonly maxStdoutBytes: number;
  readonly maxStderrBytes: number;
  readonly allowsNetwork: boolean;
  readonly allowsFilesystemWrite: boolean;
  readonly requiredAuthorizationLevel: 'PMA_APPROVED' | 'INTERNAL_AOA' | 'TGA_RUNNER';
}

export interface CEABoundsConfig {
  readonly maxConcurrentExecutions: number;
  readonly maxQueueCapacity: number;
  readonly defaultTimeoutMs: number;
  readonly maxTimeoutMs: number;
  readonly maxStdoutBytes: number;
  readonly maxStderrBytes: number;
  readonly maxArgumentCount: number;
  readonly maxArgumentLength: number;
  readonly maxRetainedRecords: number;
  readonly policyVersion: string;
}

export const DEFAULT_CEA_BOUNDS: CEABoundsConfig = Object.freeze({
  maxConcurrentExecutions: 2,
  maxQueueCapacity: 16,
  defaultTimeoutMs: 30_000,
  maxTimeoutMs: 120_000,
  maxStdoutBytes: 256 * 1024, // 256 KB
  maxStderrBytes: 128 * 1024, // 128 KB
  maxArgumentCount: 16,
  maxArgumentLength: 256,
  maxRetainedRecords: 100,
  policyVersion: '1.0.0-CANONICAL',
});
