/**
 * CUBiO Frontend Scaffold Adapter
 * Bridges to CodingAgent (CDA) to generate sovereign React/Tailwind scaffolding.
 * Invariant: Non-destructive, read-only proposals, is_actuation_blocked = true.
 */

import { FUAScaffoldProposal, FUAComponentSpec } from './types';
import { CodingAgent } from '../cda/codingAgent';

export class FrontendScaffoldAdapter {
  private readonly codingAgent: CodingAgent;

  constructor(codingAgent?: CodingAgent) {
    this.codingAgent = codingAgent || new CodingAgent();
  }

  public async generateComponentScaffold(
    spec: FUAComponentSpec,
    targetPath: string
  ): Promise<FUAScaffoldProposal> {
    const prompt = `
Generate a clean, sovereign React 19 component using Tailwind CSS v4 and lucide-react icons based on the following spec:
Component Name: ${spec.componentName}
Category: ${spec.category}
Description: ${spec.description}
Design Tokens: ${spec.designTokens.join(', ')}
Icons: ${(spec.suggestedIcons || []).join(', ')}
Props: ${JSON.stringify(spec.props)}
Accessibility: ${JSON.stringify(spec.accessibility)}
Responsive: ${JSON.stringify(spec.responsive)}
Target Path: ${targetPath}
`;

    // Delegate generation task to CDA
    const cdaReport = await this.codingAgent.execute({
      requestId: `REQ-CDA-${Date.now()}`,
      taskId: `CDA-FUA-SCAFFOLD-${Date.now()}`,
      taskType: 'CODE_GENERATION',
      prompt: prompt,
      language: 'typescript',
      framework: 'react',
      targetFilePath: targetPath,
    });

    const proposal = `/**
 * Sovereign React 19 UI Component: ${spec.componentName}
 * Framework: React 19 + Tailwind CSS v4 + lucide-react
 * Generated via CUBiO FUA / CDA Pipeline (IS_ACTUATION_BLOCKED = true)
 */
import React from 'react';
${(spec.suggestedIcons || []).length > 0 ? `import { ${(spec.suggestedIcons || []).join(', ')} } from 'lucide-react';` : ''}

export interface ${spec.componentName}Props {
${spec.props.map((p) => `  ${p.name}${p.required ? '' : '?'}: ${p.type};`).join('\n')}
}

export const ${spec.componentName}: React.FC<${spec.componentName}Props> = ({
${spec.props.map((p) => `  ${p.name}${p.defaultValue ? ` = ${p.defaultValue}` : ''},`).join('\n')}
}) => {
  return (
    <div
      role="${spec.accessibility.role || 'generic'}"
      className="${spec.designTokens.join(' ')} ${spec.responsive.mobileBreakpoint || ''} ${spec.responsive.desktopBreakpoint || ''}"
    >
      <div className="flex items-center gap-2">
        ${(spec.suggestedIcons || []).length > 0 ? `<${spec.suggestedIcons![0]} className="w-5 h-5 text-amber-500" />` : ''}
        <h3 className="text-base font-semibold text-zinc-100">${spec.componentName}</h3>
      </div>
      <p className="text-xs text-zinc-400 mt-1">${spec.description}</p>
    </div>
  );
};
`;

    return {
      componentName: spec.componentName,
      targetPath,
      framework: 'React 19 + Tailwind CSS v4',
      generatedCode: proposal,
      cdaHandoffTrace: cdaReport.taskId,
      isActuationBlocked: true,
    };
  }
}
