/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-014 — MAA (Mathematics Agent)
 * src/cubio/agents/maa/mathematicsAgent.ts
 *
 * Central facade for AGENT-014-MAA.
 * Enforces IS_ACTUATION_BLOCKED = true permanently.
 * Safe mathematical solving, bounds protection, tamper-evident SHA-256 reporting.
 */

import * as crypto from 'crypto';
import {
  MAAMathematicsRequest,
  MAAMathematicsReport,
  MAABoundsConfig,
  DEFAULT_MAA_BOUNDS,
  MAARequestStatus,
  MAAVerificationRecord,
} from './types';
import { ExpressionValidator } from './expressionValidator';
import { MathEngineAdapter } from './mathEngineAdapter';
import { CalculationVerifier } from './calculationVerifier';
import { ReasoningFormatter } from './reasoningFormatter';

export class MathematicsAgent {
  public static readonly AGENT_ID = 'AGENT-014-MAA';
  public static readonly AGENT_NAME = 'Mathematics Agent';
  public static readonly VERSION = '1.0.0';

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public get is_actuation_blocked(): boolean {
    return true;
  }

  private readonly defaultBounds: MAABoundsConfig;
  private readonly engineAdapter: MathEngineAdapter;

  constructor(
    customBounds: MAABoundsConfig = DEFAULT_MAA_BOUNDS,
    customEngine?: MathEngineAdapter
  ) {
    this.defaultBounds = customBounds;
    this.engineAdapter = customEngine || new MathEngineAdapter();
  }

  /**
   * Primary entry point: Executes a bounded mathematical computation request.
   */
  public async execute(request: MAAMathematicsRequest): Promise<MAAMathematicsReport> {
    const startTimeMs = Date.now();
    const requestId = request?.requestId || `REQ_MAA_${Date.now()}`;
    const taskId = request?.taskId || `TASK_MAA_${Date.now()}`;
    const taskType = request?.taskType || 'ARITHMETIC_EVALUATION';

    // 1. Fail-closed null/type validation
    if (!request || typeof request !== 'object') {
      return this.buildErrorReport(
        requestId,
        taskId,
        taskType,
        'FAILED',
        'Invalid mathematical request: payload is null or not an object',
        startTimeMs,
        this.defaultBounds
      );
    }

    // 2. Reject malicious actuation override attempts
    if (request.bypassActuationLock === true) {
      return this.buildErrorReport(
        requestId,
        taskId,
        taskType,
        'BLOCKED',
        'Hardware actuation override attempt rejected fail-closed. IS_ACTUATION_BLOCKED is immutable.',
        startTimeMs,
        this.defaultBounds
      );
    }

    // 3. Resolve bounds
    const bounds: MAABoundsConfig = {
      ...this.defaultBounds,
      ...(request.bounds || {}),
    };

    // 4. Expression / prompt validation
    const expression = (request.expression || '').trim();
    const prompt = (request.prompt || '').trim();

    if (!expression && !prompt && !request.numericList && !request.matrixA) {
      return this.buildErrorReport(
        requestId,
        taskId,
        taskType,
        'FAILED',
        'Request lacks expression, prompt, numeric list, or matrix data',
        startTimeMs,
        bounds
      );
    }

    // Check expression safety if text is provided
    if (expression) {
      const validation = ExpressionValidator.validate(expression, bounds);
      if (!validation.isValid) {
        let status: MAARequestStatus = 'INVALID_SYNTAX';
        if (validation.errorCode === 'INJECTION_DETECTED') status = 'BLOCKED';
        if (validation.errorCode === 'EXPRESSION_TOO_LONG' || validation.errorCode === 'NESTING_TOO_DEEP') status = 'BOUNDS_EXCEEDED';

        return this.buildErrorReport(
          requestId,
          taskId,
          taskType,
          status,
          `Expression validation rejected: ${validation.reason}`,
          startTimeMs,
          bounds
        );
      }
    }

    // 5. Compute mathematical result
    const evalResult = this.engineAdapter.evaluate(
      taskType,
      expression,
      prompt,
      request.variables,
      request.matrixA,
      request.matrixB,
      request.numericList,
      bounds
    );

    const durationMs = Date.now() - startTimeMs;

    if (!evalResult.success) {
      const status: MAARequestStatus = evalResult.isDivisionByZero ? 'DIVISION_BY_ZERO' : 'FAILED';
      return this.buildErrorReport(
        requestId,
        taskId,
        taskType,
        status,
        evalResult.error || 'Evaluation failed',
        startTimeMs,
        bounds
      );
    }

    // 6. Verification
    const verification: MAAVerificationRecord = CalculationVerifier.verifyNumericResult(
      evalResult.resultValue,
      expression || prompt
    );

    // 7. Format explanation
    const fullExplanation = ReasoningFormatter.formatSummary(
      taskType,
      evalResult.derivationSteps,
      evalResult.explanation
    );

    // 8. Build final report & SHA-256 signature
    const baseReport = {
      reportId: `REP_MAA_${crypto.randomBytes(6).toString('hex')}`,
      requestId,
      taskId,
      taskType,
      status: 'SUCCEEDED' as const,
      resultValue: evalResult.resultValue,
      formattedResult: evalResult.formattedResult,
      explanation: fullExplanation,
      derivationSteps: evalResult.derivationSteps,
      verification,
      boundsEnforced: bounds,
      executionDurationMs: durationMs,
      generatedAt: new Date().toISOString(),
      is_actuation_blocked: true as const,
    };

    const checksumPayload = JSON.stringify({
      reportId: baseReport.reportId,
      requestId,
      taskId,
      status: baseReport.status,
      resultValue: baseReport.resultValue,
      formattedResult: baseReport.formattedResult,
      is_actuation_blocked: true,
    });
    const reportChecksum = crypto.createHash('sha256').update(checksumPayload).digest('hex');

    return Object.freeze({
      ...baseReport,
      reportChecksum,
    });
  }

  /**
   * Invokes MAA adhering to AOA AgentInvoker contract.
   */
  public async invoke(payload: Record<string, unknown>, timeoutMs?: number): Promise<MAAMathematicsReport> {
    const req = payload as unknown as MAAMathematicsRequest;
    return this.execute(req);
  }

  private buildErrorReport(
    requestId: string,
    taskId: string,
    taskType: any,
    status: MAARequestStatus,
    errorMessage: string,
    startTimeMs: number,
    bounds: MAABoundsConfig
  ): MAAMathematicsReport {
    const reportId = `REP_MAA_ERR_${crypto.randomBytes(6).toString('hex')}`;
    const baseReport = {
      reportId,
      requestId,
      taskId,
      taskType,
      status,
      formattedResult: `Error: ${errorMessage}`,
      explanation: errorMessage,
      derivationSteps: [],
      verification: {
        verified: false,
        method: 'NONE' as const,
        tolerance: 0,
        delta: 0,
        details: errorMessage,
      },
      boundsEnforced: bounds,
      executionDurationMs: Date.now() - startTimeMs,
      generatedAt: new Date().toISOString(),
      is_actuation_blocked: true as const,
    };

    const checksum = crypto.createHash('sha256').update(JSON.stringify(baseReport)).digest('hex');

    return Object.freeze({
      ...baseReport,
      reportChecksum: checksum,
    });
  }
}
