/**
 * CUBiO Data & Storage Agent (DSA) Types & Interfaces
 * Agent ID: AGENT-018-DSA
 * Canonical Name: Data & Storage Agent
 * Permanent Invariant: IS_ACTUATION_BLOCKED = true
 */

export const DSA_AGENT_ID = 'AGENT-018-DSA' as const;
export const DSA_AGENT_NAME = 'Data & Storage Agent' as const;
export const DSA_VERSION = '1.0.0' as const;

export type DSATaskType =
  | 'STORAGE_INVENTORY'
  | 'STORAGE_CONTRACT_AUDIT'
  | 'QUERY_EFFICIENCY_ANALYSIS'
  | 'DATA_INTEGRITY_CHECK'
  | 'MEMORY_LIFECYCLE_AUDIT'
  | 'CHECKPOINT_VALIDATION';

export type DSAStorageDomain =
  | 'CANONICAL_VDB'
  | 'SQLITE_ADAPTER'
  | 'CHECKPOINT_3DMEMORY'
  | 'MEMORY_TIERS'
  | 'GENERAL_STORAGE';

export interface DSAStorageFinding {
  findingId: string;
  category: 'PERFORMANCE' | 'INTEGRITY' | 'BOUNDARY' | 'LIFECYCLE' | 'SCHEMA';
  severity: 'INFO' | 'WARNING' | 'CRITICAL';
  title: string;
  targetComponent: string;
  evidence: string;
  recommendation: string;
  limitations?: string;
}

export interface DSAStorageServiceDescriptor {
  serviceName: string;
  sourcePath: string;
  isAuthoritative: boolean;
  persistenceType: 'SQLITE_DISK' | 'IN_MEMORY' | 'CHECKPOINT_BUNDLE';
  supportedOperations: string[];
  boundIndexes: string[];
}

export interface DSAQueryAnalysisReport {
  querySqlOrDescription: string;
  isBounded: boolean;
  wholeTableScanRisk: boolean;
  missingIndexCandidates: string[];
  estimatedComplexity: string;
  recommendation: string;
}

export interface DSADataIntegrityReport {
  target: string;
  totalRecordsChecked: number;
  schemaCompliant: boolean;
  missingRequiredFields: string[];
  serializationRoundTripValid: boolean;
  duplicateKeyCandidates: string[];
  summary: string;
}

export interface DSACacheLifecycleReport {
  component: string;
  hasCapacityBound: boolean;
  maxCapacity?: number;
  evictionStrategy?: string;
  connectionDisposalValid: boolean;
  unboundedGrowthRisk: boolean;
}

export interface DSACheckpointReport {
  checkpointPathOrId: string;
  formatMagic: string;
  schemaVersion: number;
  isActuationBlocked: boolean;
  merkleRootValid: boolean;
  totalCells: number;
  isValid: boolean;
}

export interface DSABoundsConfig {
  maxInspectedRecords: number;
  maxFindings: number;
  maxExecutionTimeMs: number;
}

export const DEFAULT_DSA_BOUNDS: DSABoundsConfig = {
  maxInspectedRecords: 500,
  maxFindings: 50,
  maxExecutionTimeMs: 10000,
};

export interface DSARequest {
  taskId: string;
  taskType: DSATaskType;
  storageDomain?: DSAStorageDomain;
  targetPathOrQuery?: string;
  rawPayload?: any;
  context?: Record<string, any>;
  bounds?: Partial<DSABoundsConfig>;
}

export interface DSAReport {
  taskId: string;
  agentId: typeof DSA_AGENT_ID;
  taskType: DSATaskType;
  success: boolean;
  timestamp: string;
  isActuationBlocked: boolean;
  inventory?: DSAStorageServiceDescriptor[];
  findings?: DSAStorageFinding[];
  queryAnalysis?: DSAQueryAnalysisReport[];
  integrity?: DSADataIntegrityReport;
  lifecycle?: DSACacheLifecycleReport;
  checkpoint?: DSACheckpointReport;
  metrics: {
    durationMs: number;
    itemsInspected: number;
  };
  errors?: string[];
  signature: string;
}
