/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-016 — SAA (System Architecture Agent)
 * src/cubio/agents/saa/architectureFindingAnalyzer.ts
 *
 * Classifies, deduplicates, and evaluates architectural findings.
 * Generates evidence-based recommendations.
 */

import {
  SAAFindingRecord,
  SAARecommendationRecord,
  SAAComponentRecord,
  SAABoundsConfig,
} from './types';

export class ArchitectureFindingAnalyzer {
  /**
   * Evaluates findings and generates prioritized architectural recommendations.
   */
  public static generateRecommendations(
    findings: readonly SAAFindingRecord[],
    components: readonly SAAComponentRecord[],
    bounds: SAABoundsConfig
  ): readonly SAARecommendationRecord[] {
    const recommendations: SAARecommendationRecord[] = [];

    // Group findings by category
    const cycles = findings.filter((f) => f.category === 'CIRCULAR_DEPENDENCY');
    const mismatches = findings.filter((f) => f.category === 'REGISTRY_BINDING_MISMATCH');
    const violations = findings.filter((f) => f.category === 'LAYER_BOUNDARY_VIOLATION');
    const orphans = findings.filter((f) => f.category === 'DISCONNECTED_MODULE');

    if (cycles.length > 0) {
      recommendations.push({
        recommendationId: 'REC_BREAK_CYCLES',
        title: `Decouple ${cycles.length} Circular Module Dependencies`,
        rationale: 'Circular dependencies compromise determinism, compile times, and modularity.',
        targetComponents: Array.from(new Set(cycles.flatMap((c) => c.affectedComponents))),
        regressionRisks: ['Ensure exported types remain accessible during interface refactoring'],
        impact: 'HIGH',
      });
    }

    if (mismatches.length > 0) {
      recommendations.push({
        recommendationId: 'REC_SYNC_REGISTRY',
        title: `Reconcile ${mismatches.length} Agent Registry Discrepancies`,
        rationale: 'AOA dispatcher relies on exact correspondence between declared status and invoker bindings.',
        targetComponents: Array.from(new Set(mismatches.flatMap((m) => m.affectedComponents))),
        regressionRisks: ['Check downstream DAG orchestration dependencies before unbinding'],
        impact: 'HIGH',
      });
    }

    if (violations.length > 0) {
      recommendations.push({
        recommendationId: 'REC_ENFORCE_LAYERS',
        title: `Restore Layer Boundary Isolation (${violations.length} violations)`,
        rationale: 'Unchecked cross-layer imports bypass safety gates and weaken sovereign isolation.',
        targetComponents: Array.from(new Set(violations.flatMap((v) => v.affectedComponents))),
        regressionRisks: ['Verify API gateway routing adapters when redirecting bypass calls'],
        impact: 'HIGH',
      });
    }

    if (orphans.length > 0) {
      recommendations.push({
        recommendationId: 'REC_INTEGRATE_ORPHANS',
        title: `Review ${orphans.length} Disconnected Modules`,
        rationale: 'Isolated modules may represent dead code, obsolete experiments, or missing integration hooks.',
        targetComponents: Array.from(new Set(orphans.flatMap((o) => o.affectedComponents))),
        regressionRisks: ['Verify if module is dynamically loaded or standalone CLI script before pruning'],
        impact: 'LOW',
      });
    }

    // Default recommendation if system is clean
    if (recommendations.length === 0) {
      recommendations.push({
        recommendationId: 'REC_MAINTAIN_HEALTH',
        title: 'Maintain Current Architectural Health & Boundary Invariants',
        rationale: 'Inspected components exhibit healthy layer isolation, zero circular dependencies, and consistent contracts.',
        targetComponents: components.slice(0, 5).map((c) => c.componentId),
        regressionRisks: ['None'],
        impact: 'LOW',
      });
    }

    return Object.freeze(recommendations);
  }
}
