/**
 * CUBiO Frontend Inventory Adapter
 * Discovers and parses existing frontend components and views across CUBiO.
 */

import * as fs from 'fs';
import * as path from 'path';

export interface DiscoveredUIComponent {
  name: string;
  relativePath: string;
  isView: boolean;
  isModal: boolean;
  hasIcons: boolean;
  hasThreeJs: boolean;
  exports: string[];
}

export class FrontendInventoryAdapter {
  private readonly projectRoot: string;

  constructor(projectRoot: string = process.cwd()) {
    this.projectRoot = projectRoot;
  }

  public scanFrontendComponents(): DiscoveredUIComponent[] {
    const targetDirs = [
      path.join(this.projectRoot, 'src', 'components'),
      path.join(this.projectRoot, 'src', 'cubio', 'web', 'components'),
      path.join(this.projectRoot, 'src', 'cubio', 'web', 'agents_console'),
      path.join(this.projectRoot, 'src', 'cubio', 'web'),
    ];

    const results: DiscoveredUIComponent[] = [];

    for (const dir of targetDirs) {
      if (!fs.existsSync(dir)) continue;

      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        if (!entry.isFile()) continue;
        if (!entry.name.endsWith('.tsx') && !entry.name.endsWith('.jsx')) continue;

        const fullPath = path.join(dir, entry.name);
        const relPath = path.relative(this.projectRoot, fullPath).replace(/\\/g, '/');
        const content = fs.readFileSync(fullPath, 'utf8');

        const componentName = path.basename(entry.name, path.extname(entry.name));
        const isModal = componentName.toLowerCase().includes('modal');
        const isView = componentName.toLowerCase().includes('view') || componentName.toLowerCase().includes('app') || componentName.toLowerCase().includes('console');
        const hasIcons = content.includes('lucide-react');
        const hasThreeJs = content.includes('three') || content.includes('@types/three');

        // Simple export extraction
        const exportMatches = content.match(/export\s+(?:const|function|class|default)\s+([a-zA-Z0-9_]+)/g) || [];
        const exports = exportMatches.map((m) => m.split(/\s+/).pop() || componentName);

        results.push({
          name: componentName,
          relativePath: relPath,
          isView,
          isModal,
          hasIcons,
          hasThreeJs,
          exports: exports.length > 0 ? exports : [componentName],
        });
      }
    }

    return results;
  }
}
