/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-019 — POA (Performance Optimization Agent)
 * src/cubio/agents/poa/runtimeProfiler.ts
 *
 * High-precision elapsed time and process memory sampling with strict bounds.
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import { POARuntimeMeasurement, POABoundsConfig, DEFAULT_POA_BOUNDS } from './types';

export class RuntimeProfiler {
  constructor(private readonly bounds: POABoundsConfig = DEFAULT_POA_BOUNDS) {}

  /**
   * Times an asynchronous operation with high precision and captures heap delta.
   */
  public async profileAsync<T>(
    label: string,
    operation: () => Promise<T>
  ): Promise<{ result: T; measurement: POARuntimeMeasurement }> {
    const startHeap = this.getSafeHeapUsed();
    const startRss = this.getSafeRss();
    const startTime = performance.now();

    try {
      const result = await operation();
      const durationMs = Math.max(0.01, performance.now() - startTime);
      const endHeap = this.getSafeHeapUsed();
      const endRss = this.getSafeRss();

      const measurement: POARuntimeMeasurement = {
        label,
        durationMs: Number(durationMs.toFixed(3)),
        heapDeltaBytes: endHeap - startHeap,
        rssDeltaBytes: endRss - startRss,
        timestamp: Date.now(),
        successful: true,
      };

      return { result, measurement };
    } catch (err: any) {
      const durationMs = Math.max(0.01, performance.now() - startTime);
      const measurement: POARuntimeMeasurement = {
        label,
        durationMs: Number(durationMs.toFixed(3)),
        heapDeltaBytes: 0,
        timestamp: Date.now(),
        successful: false,
        error: err?.message || String(err),
      };

      throw Object.assign(err, { measurement });
    }
  }

  /**
   * Times a synchronous operation.
   */
  public profileSync<T>(
    label: string,
    operation: () => T
  ): { result: T; measurement: POARuntimeMeasurement } {
    const startHeap = this.getSafeHeapUsed();
    const startRss = this.getSafeRss();
    const startTime = performance.now();

    try {
      const result = operation();
      const durationMs = Math.max(0.01, performance.now() - startTime);
      const endHeap = this.getSafeHeapUsed();
      const endRss = this.getSafeRss();

      const measurement: POARuntimeMeasurement = {
        label,
        durationMs: Number(durationMs.toFixed(3)),
        heapDeltaBytes: endHeap - startHeap,
        rssDeltaBytes: endRss - startRss,
        timestamp: Date.now(),
        successful: true,
      };

      return { result, measurement };
    } catch (err: any) {
      const durationMs = Math.max(0.01, performance.now() - startTime);
      const measurement: POARuntimeMeasurement = {
        label,
        durationMs: Number(durationMs.toFixed(3)),
        heapDeltaBytes: 0,
        timestamp: Date.now(),
        successful: false,
        error: err?.message || String(err),
      };

      throw Object.assign(err, { measurement });
    }
  }

  private getSafeHeapUsed(): number {
    try {
      if (typeof process !== 'undefined' && process.memoryUsage) {
        return process.memoryUsage().heapUsed;
      }
    } catch {}
    return 0;
  }

  private getSafeRss(): number {
    try {
      if (typeof process !== 'undefined' && process.memoryUsage) {
        return process.memoryUsage().rss;
      }
    } catch {}
    return 0;
  }
}
