/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-011 — OMA (Observability & Monitoring Agent)
 * src/cubio/agents/oma/alertEvaluator.ts
 *
 * Evaluates deterministic alert rules over the normalized event stream.
 */

import { OMANormalizedEvent, OMAAlertRecord, OMAAlertRule, OMABoundsConfig, DEFAULT_OMA_BOUNDS } from './types';

export class AlertEvaluator {
  private readonly rules: Map<string, OMAAlertRule> = new Map();
  private readonly alerts: OMAAlertRecord[] = [];
  private readonly bounds: OMABoundsConfig;

  constructor(bounds: OMABoundsConfig = DEFAULT_OMA_BOUNDS) {
    this.bounds = bounds;
    this.bootstrapCanonicalRules();
  }

  private bootstrapCanonicalRules(): void {
    // 1. Repeated Failures Alert
    this.registerRule({
      ruleId: 'RULE_REPEATED_FAILURES',
      name: 'Repeated Task Execution Failures',
      severity: 'ERROR',
      description: 'Multiple task failures observed within recent window',
      condition: (events) => {
        const failures = events.filter((e) => e.status === 'FAILED' || e.status === 'FAIL');
        return failures.length >= 3;
      },
    });

    // 2. High Timeout Rate Alert
    this.registerRule({
      ruleId: 'RULE_ELEVATED_TIMEOUTS',
      name: 'Elevated Execution Timeouts',
      severity: 'WARN',
      description: 'Multiple execution timeouts observed',
      condition: (events) => {
        const timeouts = events.filter((e) => e.status === 'TIMED_OUT');
        return timeouts.length >= 2;
      },
    });

    // 3. Security Breach / Actuation Override Alert
    this.registerRule({
      ruleId: 'RULE_SECURITY_ACTUATION_OVERRIDE',
      name: 'Actuation Override Attack Detected',
      severity: 'CRITICAL',
      description: 'An unauthorized attempt to circumvent actuation lock was recorded',
      condition: (events) => {
        return events.some(
          (e) =>
            e.eventType === 'SECURITY_DECISION' &&
            e.evidenceReferences.some((ref) => ref.includes('UNAUTHORIZED_ACTUATION_ATTEMPT'))
        );
      },
    });
  }

  public registerRule(rule: OMAAlertRule): void {
    this.rules.set(rule.ruleId, Object.freeze({ ...rule }));
  }

  /**
   * Evaluates all registered alert rules against recent events.
   */
  public evaluate(events: readonly OMANormalizedEvent[]): readonly OMAAlertRecord[] {
    const triggered: OMAAlertRecord[] = [];

    for (const rule of this.rules.values()) {
      if (rule.condition(events)) {
        const alert: OMAAlertRecord = Object.freeze({
          alertId: `ALT-${Date.now().toString(36)}-${rule.ruleId}`,
          ruleId: rule.ruleId,
          severity: rule.severity,
          timestamp: Date.now(),
          message: rule.description,
          evidenceReferences: Object.freeze(
            events.slice(-5).map((e) => e.eventId)
          ),
        });

        triggered.push(alert);
        if (this.alerts.length >= this.bounds.maxAlertsRetained) {
          this.alerts.shift();
        }
        this.alerts.push(alert);
      }
    }

    return Object.freeze(triggered);
  }

  public getRetainedAlerts(): readonly OMAAlertRecord[] {
    return Object.freeze([...this.alerts]);
  }
}
