/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-011 — OMA (Observability & Monitoring Agent)
 * src/cubio/agents/oma/metricsAggregator.ts
 *
 * Computes rolling performance statistics, durations, timeout rates,
 * and P50/P95/P99 latency percentiles within bounded in-memory windows.
 */

import { OMANormalizedEvent, OMAMetricSummary, OMAPercentiles, OMABoundsConfig, DEFAULT_OMA_BOUNDS } from './types';

export class MetricsAggregator {
  private readonly bounds: OMABoundsConfig;
  private readonly events: OMANormalizedEvent[] = [];
  private readonly durationSamples: number[] = [];

  constructor(bounds: OMABoundsConfig = DEFAULT_OMA_BOUNDS) {
    this.bounds = bounds;
  }

  /**
   * Records an event and applies FIFO bounds.
   */
  public recordEvent(event: OMANormalizedEvent): void {
    if (this.events.length >= this.bounds.maxRetainedEvents) {
      this.events.shift(); // Evict oldest
    }
    this.events.push(event);

    if (typeof event.durationMs === 'number') {
      if (this.durationSamples.length >= this.bounds.maxLatencySamplesPerKey) {
        this.durationSamples.shift();
      }
      this.durationSamples.push(event.durationMs);
    }
  }

  /**
   * Computes summary metrics over the current bounded window.
   */
  public computeSummary(): OMAMetricSummary {
    const now = Date.now();
    const windowStart = now - this.bounds.aggregationWindowMs;
    const windowEvents = this.events.filter((e) => e.timestamp >= windowStart);

    let successes = 0;
    let failures = 0;
    let timeouts = 0;
    let blocked = 0;
    let totalDuration = 0;
    let durationCount = 0;

    for (const e of windowEvents) {
      if (
        e.status === 'SUCCEEDED' ||
        e.status === 'SUCCESS' ||
        e.status === 'COMPLETED' ||
        e.status === 'PERMITTED' ||
        e.status === 'ALLOW' ||
        e.status === 'PASS' ||
        e.status === 'PASSED'
      ) {
        successes++;
      } else if (e.status === 'TIMED_OUT') {
        timeouts++;
      } else if (e.status === 'BLOCKED') {
        blocked++;
      } else if (e.status === 'FAILED' || e.status === 'DENY' || e.status === 'FAIL') {
        failures++;
      }

      if (typeof e.durationMs === 'number') {
        totalDuration += e.durationMs;
        durationCount++;
      }
    }

    const avgDuration = durationCount > 0 ? Math.round(totalDuration / durationCount) : 0;
    const percentiles = this.calculatePercentiles(this.durationSamples);

    return Object.freeze({
      totalEvents: windowEvents.length,
      successCount: successes,
      failureCount: failures,
      timeoutCount: timeouts,
      blockedCount: blocked,
      averageDurationMs: avgDuration,
      percentiles,
      windowStartMs: windowStart,
      windowEndMs: now,
    });
  }

  public calculatePercentiles(samples: readonly number[]): OMAPercentiles {
    if (!samples || samples.length === 0) {
      return { p50Ms: 0, p95Ms: 0, p99Ms: 0 };
    }

    const sorted = [...samples].sort((a, b) => a - b);
    const p50Idx = Math.floor(sorted.length * 0.5);
    const p95Idx = Math.min(sorted.length - 1, Math.floor(sorted.length * 0.95));
    const p99Idx = Math.min(sorted.length - 1, Math.floor(sorted.length * 0.99));

    return Object.freeze({
      p50Ms: sorted[p50Idx],
      p95Ms: sorted[p95Idx],
      p99Ms: sorted[p99Idx],
    });
  }

  public getRetainedEvents(): readonly OMANormalizedEvent[] {
    return Object.freeze([...this.events]);
  }
}
