export type ResourceOperation = 'READ' | 'PROPOSE' | 'MODIFY' | 'EXECUTE' | 'RELEASE';

export type SecuritySensitivityLevel = 'LOW' | 'NORMAL' | 'HIGH' | 'CONSEQUENTIAL_RESTRICTED';

export interface AgentPermissionProfile {
  readonly agentId: string;
  readonly allowedOperations: readonly ResourceOperation[];
  readonly allowedSubsystems: readonly string[];
  readonly maxFileTouchScope: 'NONE' | 'FOCUSED_LOCAL' | 'WIDE' | 'AUDIT_ONLY';
  readonly canExecuteShell: boolean;
  readonly canModifyFiles: boolean;
  readonly canReleaseArtifacts: boolean;
  readonly requiresExplicitApprovalForModify: boolean;
}

export interface UserApprovalRecord {
  readonly approvalId: string;
  readonly taskId: string;
  readonly action: string;
  readonly targetResource: string;
  readonly requestedByAgentId: string;
  readonly status: 'PENDING' | 'APPROVED' | 'REJECTED' | 'EXPIRED';
  readonly approvalToken?: string;
  readonly grantedScope: string;
  readonly timestamp: string;
  readonly expiresAt: string;
}

export interface SecurityAuditEntry {
  readonly entryId: string;
  readonly timestamp: string;
  readonly eventType:
    | 'ACCESS_PERMITTED'
    | 'ACCESS_DENIED'
    | 'APPROVAL_REQUESTED'
    | 'APPROVAL_GRANTED'
    | 'APPROVAL_REJECTED'
    | 'ADVERSARIAL_ATTACK_BLOCKED'
    | 'ACTUATION_OVERRIDE_PREVENTED'
    | 'PROTECTED_AUTHORITY_TAMPER_BLOCKED'
    | 'SECRET_LEAK_MASKED';
  readonly subjectId: string; // agentId or taskId
  readonly action: string;
  readonly resource: string;
  readonly verdict: 'ALLOW' | 'DENY' | 'FLAG';
  readonly reason: string;
  readonly integrityHash: string;
}

export interface BoundaryValidationResult {
  readonly allowed: boolean;
  readonly reason: string;
  readonly requiresApproval: boolean;
  readonly approvalAction?: string;
  readonly threatDetected?: string;
  readonly auditEntryId: string;
}

