/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-019 — POA (Performance Optimization Agent)
 * src/cubio/agents/poa/bottleneckAnalyzer.ts
 *
 * Evidence-based bottleneck classification and severity assessment.
 * Distinguishes measured degradation from static warnings and inferred hypotheses.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import {
  POABottleneckFinding,
  POABottleneckClassification,
  POABenchmarkResult,
  POARuntimeMeasurement,
  POABoundsConfig,
  DEFAULT_POA_BOUNDS,
} from './types';
import { DSAQueryAnalysisReport, DSACacheLifecycleReport } from '../dsa/types';

export class BottleneckAnalyzer {
  constructor(private readonly bounds: POABoundsConfig = DEFAULT_POA_BOUNDS) {}

  /**
   * Analyzes active benchmark results to classify measured bottlenecks.
   */
  public analyzeBenchmark(benchmark: POABenchmarkResult): POABottleneckFinding[] {
    const findings: POABottleneckFinding[] = [];

    // Check tail latency (P95)
    if (benchmark.percentiles.p95Ms > this.bounds.p95LatencyWarningThresholdMs) {
      findings.push({
        findingId: `FIND-LATENCY-${benchmark.benchmarkId}`,
        classification: 'MEASURED_BOTTLENECK',
        severity: benchmark.percentiles.p95Ms > this.bounds.p95LatencyWarningThresholdMs * 2 ? 'CRITICAL' : 'WARNING',
        targetSubsystem: benchmark.targetName,
        title: `Excessive P95 Tail Latency in ${benchmark.targetName}`,
        description: `P95 latency of ${benchmark.percentiles.p95Ms}ms exceeds SLA limit of ${this.bounds.p95LatencyWarningThresholdMs}ms.`,
        evidence: `Benchmark ${benchmark.benchmarkId}: Sample count ${benchmark.sampleCount}, P50=${benchmark.percentiles.p50Ms}ms, P95=${benchmark.percentiles.p95Ms}ms, P99=${benchmark.percentiles.p99Ms}ms, Ops/sec=${benchmark.opsPerSec}`,
        baselineMetrics: {
          durationMs: benchmark.totalDurationMs,
          p95Ms: benchmark.percentiles.p95Ms,
        },
        confidence: benchmark.sampleCount >= 10 ? 0.95 : 0.6,
        limitations: benchmark.sampleCount < 10 ? 'Small sample count (<10 iterations) may introduce variance.' : undefined,
      });
    }

    // Check heap memory growth
    if (benchmark.heapDeltaBytes > this.bounds.heapDeltaWarningThresholdBytes) {
      findings.push({
        findingId: `FIND-HEAP-${benchmark.benchmarkId}`,
        classification: 'MEASURED_BOTTLENECK',
        severity: 'WARNING',
        targetSubsystem: benchmark.targetName,
        title: `High Heap Memory Growth during ${benchmark.targetName}`,
        description: `Heap allocation delta of ${Math.round(benchmark.heapDeltaBytes / 1024)} KB exceeds threshold of ${Math.round(this.bounds.heapDeltaWarningThresholdBytes / 1024)} KB.`,
        evidence: `Observed heapDeltaBytes=${benchmark.heapDeltaBytes} over ${benchmark.sampleCount} iterations.`,
        baselineMetrics: {
          memoryDeltaBytes: benchmark.heapDeltaBytes,
        },
        confidence: 0.9,
      });
    }

    return findings;
  }

  /**
   * Analyzes DSA query analysis report to classify query bottlenecks.
   */
  public analyzeQueryReport(queryReport: DSAQueryAnalysisReport): POABottleneckFinding[] {
    const findings: POABottleneckFinding[] = [];

    if (queryReport.wholeTableScanRisk) {
      findings.push({
        findingId: `FIND-QUERY-FULLSCAN-${Date.now().toString(36)}`,
        classification: 'STATIC_RISK',
        severity: 'CRITICAL',
        targetSubsystem: 'STORAGE_QUERY',
        title: 'Full Table Scan Risk in Storage Access',
        description: 'Query performs an unconstrained read across all rows without WHERE or LIMIT clause.',
        evidence: `Query: "${queryReport.querySqlOrDescription}". Estimated complexity: ${queryReport.estimatedComplexity}. Recommendation: ${queryReport.recommendation}`,
        baselineMetrics: {
          complexity: queryReport.estimatedComplexity,
        },
        confidence: 0.95,
      });
    } else if (queryReport.missingIndexCandidates.length > 0) {
      findings.push({
        findingId: `FIND-QUERY-UNINDEXED-${Date.now().toString(36)}`,
        classification: 'STATIC_RISK',
        severity: 'WARNING',
        targetSubsystem: 'STORAGE_QUERY',
        title: 'Unindexed JSON Column Filtering Risk',
        description: 'Query filters on JSON properties without virtual column index coverage.',
        evidence: `Missing index candidates: ${queryReport.missingIndexCandidates.join(', ')}`,
        baselineMetrics: {
          complexity: queryReport.estimatedComplexity,
        },
        confidence: 0.85,
      });
    }

    return findings;
  }

  /**
   * Analyzes DSA memory lifecycle report.
   */
  public analyzeLifecycleReport(lifecycleReport: DSACacheLifecycleReport): POABottleneckFinding[] {
    const findings: POABottleneckFinding[] = [];

    if (lifecycleReport.unboundedGrowthRisk) {
      findings.push({
        findingId: `FIND-CACHE-UNBOUNDED-${lifecycleReport.component}`,
        classification: 'STATIC_RISK',
        severity: 'CRITICAL',
        targetSubsystem: lifecycleReport.component,
        title: `Unbounded Growth Risk in ${lifecycleReport.component}`,
        description: 'Component lacks capacity caps or eviction policies, creating runaway heap expansion risk.',
        evidence: `Component: ${lifecycleReport.component}, hasCapacityBound=${lifecycleReport.hasCapacityBound}, evictionStrategy=${lifecycleReport.evictionStrategy}`,
        confidence: 0.9,
      });
    }

    return findings;
  }
}
