/**
 * CUBiO AI — 3D Memory Studio
 * Dynamic Agent-to-Skill Invocation Framework
 * src/cubio/skills/dynamicSkillInvoker.ts
 *
 * Implements Phase 21 requirements:
 * 1. Runtime skill discovery & selection matching specific subtask objectives and payloads.
 * 2. Loads only the minimum relevant skill instructions or handlers (avoids loading all 20).
 * 3. Strict permission validation (verifies requesting agent is permitted to use the skill).
 * 4. Passes validated task context, acceptance criteria, and input schema to the skill.
 * 5. Executes skill handlers with timeout safety, capturing cryptographic provenance.
 * 6. Records skill ID, version, invocation reason, input reference, result status, and evidence.
 * 7. Controlled error handling for unavailable, failed, conflicting, or unauthorized skills.
 * 8. Recursion prevention (depth guard) and protection against unbounded skill chains.
 * 9. Distinguishes skill recommendations from skills that actually executed successfully.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import { createHash } from 'crypto';
import { SkillRegistry } from './registry';
import {
  SkillExecutionResult,
  SkillInvocationEvidence,
  SkillManifest,
} from './types';
import { AOASubtaskDefinition } from '../agents/aoa/types';

export interface SkillInvocationTraceRecord {
  readonly skillId: string;
  readonly skillName: string;
  readonly skillVersion: string;
  readonly invokingAgentId: string;
  readonly subtaskId: string;
  readonly invocationReason: string;
  readonly inputReferenceHash: string;
  readonly status: 'SUCCESS' | 'FAILED' | 'REJECTED' | 'SKIPPED_RECOMMENDATION_ONLY';
  readonly executionLatencyMs: number;
  readonly evidenceHash?: string;
  readonly error?: string;
  readonly outputData?: unknown;
  readonly executedAt: string;
}

export interface DynamicSkillResolutionResult {
  readonly subtaskId: string;
  readonly targetAgentId: string;
  readonly recommendedSkillIds: readonly string[];
  readonly executedSkillTraces: readonly SkillInvocationTraceRecord[];
  readonly overallSuccess: boolean;
  readonly combinedSkillOutputs: Record<string, unknown>;
  readonly errors: readonly string[];
}

export interface DynamicSkillSelectorOptions {
  readonly maxSkillsPerSubtask?: number; // default: 3
  readonly maxInvocationDepth?: number;  // default: 2 (prevents recursive chains)
}

export class DynamicSkillInvoker {
  public static readonly IS_ACTUATION_BLOCKED = true;
  private static readonly DEFAULT_MAX_SKILLS = 3;
  private static readonly DEFAULT_MAX_DEPTH = 2;

  private readonly registry: SkillRegistry;
  private readonly maxSkills: number;
  private readonly maxDepth: number;

  // Active invocation stack per subtask to prevent recursion / cyclic loops
  private readonly activeInvocationStack: Set<string> = new Set();

  constructor(options?: DynamicSkillSelectorOptions) {
    this.registry = SkillRegistry.getInstance();
    this.maxSkills = options?.maxSkillsPerSubtask ?? DynamicSkillInvoker.DEFAULT_MAX_SKILLS;
    this.maxDepth = options?.maxInvocationDepth ?? DynamicSkillInvoker.DEFAULT_MAX_DEPTH;
  }

  /**
   * Discovers and selects the minimum relevant skills for a subtask based on the
   * agent's permissions, subtask objective, payload keywords, and declared requiredSkills.
   */
  public selectSkillsForSubtask(subtask: AOASubtaskDefinition): string[] {
    const selected = new Set<string>();
    const agentId = subtask.targetAgentId;
    const text = `${subtask.objective} ${JSON.stringify(subtask.payload || {})}`.toLowerCase();

    // 1. Explicitly required skills declared in the subtask definition
    if (subtask.requiredSkills && subtask.requiredSkills.length > 0) {
      for (const reqSkill of subtask.requiredSkills) {
        selected.add(reqSkill);
      }
    }

    // 2. Dynamic discovery based on agent identity and objective keywords
    switch (agentId) {
      case 'AGENT-017-FUA': {
        // UI/UX Design & Frontend Review
        if (text.includes('ui') || text.includes('frontend') || text.includes('component') || text.includes('heading') || text.includes('layout')) {
          selected.add('SKILL-017-UIUX-DESIGN-FRONTEND-REVIEW');
        }
        break;
      }

      case 'AGENT-014-MAA': {
        // Mathematical Computation
        if (text.includes('math') || text.includes('modular') || text.includes('arithmetic') || text.includes('369') || text.includes('root')) {
          selected.add('SKILL-014-MATHEMATICAL-COMPUTATION');
        }
        break;
      }

      case 'AGENT-010-SGA':
      case 'AGENT-004-SGA': {
        // Security & Permission Validation
        if (text.includes('security') || text.includes('permission') || text.includes('governance') || text.includes('boundary') || text.includes('actuation')) {
          selected.add('SKILL-010-SECURITY-PERMISSION-VALIDATION');
        }
        break;
      }

      case 'AGENT-002-DRA': {
        // Dependency & Reuse Analysis
        if (text.includes('dependency') || text.includes('reuse') || text.includes('conflict') || text.includes('import')) {
          selected.add('SKILL-002-DEPENDENCY-REUSE-ANALYSIS');
        }
        break;
      }

      case 'AGENT-004-EIA': {
        // Evidence & Artifact Audit
        if (text.includes('evidence') || text.includes('artifact') || text.includes('provenance') || text.includes('audit')) {
          selected.add('SKILL-004-EVIDENCE-ARTIFACT-AUDIT');
        }
        break;
      }

      case 'AGENT-003-TGA': {
        // Test & Gate Validation
        if (text.includes('test') || text.includes('gate') || text.includes('validation') || text.includes('regression')) {
          selected.add('SKILL-003-TEST-GATE-VALIDATION');
        }
        break;
      }

      case 'AGENT-013-CDA': {
        // Code Generation & Analysis
        if (text.includes('code') || text.includes('synthes') || text.includes('interface') || text.includes('patch')) {
          selected.add('SKILL-013-CODE-GENERATION-ANALYSIS');
        }
        // Shared Ponytail code quality
        if (text.includes('quality') || text.includes('refactor') || text.includes('clean') || text.includes('ponytail')) {
          selected.add('SKILL-SHARED-PONYTAIL-CODE-QUALITY');
        }
        break;
      }

      case 'AGENT-015-BFA': {
        // Bug diagnosis
        if (text.includes('bug') || text.includes('defect') || text.includes('fix') || text.includes('stack')) {
          selected.add('SKILL-015-BUG-DIAGNOSIS-FIX-PROPOSALS');
        }
        // Shared Ponytail code quality
        if (text.includes('quality') || text.includes('refactor') || text.includes('ponytail')) {
          selected.add('SKILL-SHARED-PONYTAIL-CODE-QUALITY');
        }
        break;
      }

      case 'AGENT-016-SAA': {
        // System architecture review
        if (text.includes('architecture') || text.includes('system') || text.includes('subsystem') || text.includes('boundary')) {
          selected.add('SKILL-016-SYSTEM-ARCHITECTURE-REVIEW');
        }
        // Shared Ponytail code quality
        if (text.includes('quality') || text.includes('clean') || text.includes('ponytail')) {
          selected.add('SKILL-SHARED-PONYTAIL-CODE-QUALITY');
        }
        break;
      }

      case 'AGENT-019-POA': {
        // Performance profiling & optimization
        if (text.includes('perf') || text.includes('latency') || text.includes('profile') || text.includes('benchmark')) {
          selected.add('SKILL-019-PERFORMANCE-PROFILING-OPTIMIZATION');
        }
        break;
      }

      case 'AGENT-020-RDA': {
        // Release readiness & manifest
        if (text.includes('release') || text.includes('manifest') || text.includes('readiness')) {
          selected.add('SKILL-020-RELEASE-READINESS-MANIFEST');
        }
        break;
      }

      case 'AGENT-018-DSA': {
        // Data & storage analysis
        if (text.includes('storage') || text.includes('db') || text.includes('database') || text.includes('sqlite') || text.includes('schema')) {
          selected.add('SKILL-018-DATA-STORAGE-ANALYSIS');
        }
        break;
      }

      case 'AGENT-001-MEA': {
        // Context retrieval & memory
        if (text.includes('context') || text.includes('memory') || text.includes('history')) {
          selected.add('SKILL-001-CONTEXT-RETRIEVAL');
        }
        break;
      }

      case 'AGENT-011-OMA': {
        // Runtime metrics
        if (text.includes('metric') || text.includes('observability') || text.includes('telemetry')) {
          selected.add('SKILL-011-RUNTIME-METRICS-OBSERVABILITY');
        }
        break;
      }

      case 'AGENT-012-RRA': {
        // Repository research
        if (text.includes('research') || text.includes('search') || text.includes('symbol')) {
          selected.add('SKILL-012-REPOSITORY-RESEARCH-RETRIEVAL');
        }
        break;
      }

      default:
        break;
    }

    // Limit to minimum necessary (maxSkills threshold)
    return Array.from(selected).slice(0, this.maxSkills);
  }

  /**
   * Prepares the specific input for a given skill from the subtask objective and payload.
   */
  private prepareSkillInput(
    manifest: SkillManifest,
    subtask: AOASubtaskDefinition
  ): Record<string, unknown> {
    const payload = (subtask.payload || {}) as Record<string, unknown>;
    const objective = subtask.objective;

    switch (manifest.skillId) {
      case 'SKILL-017-UIUX-DESIGN-FRONTEND-REVIEW':
        return {
          componentName: payload.componentName || payload.targetComponent || 'WebsiteHeroSection',
        };

      case 'SKILL-014-MATHEMATICAL-COMPUTATION':
        return {
          expression: String(payload.expression || payload.value || '369'),
          modulus: 9,
        };

      case 'SKILL-010-SECURITY-PERMISSION-VALIDATION':
        return {
          requiredScope: String(payload.requiredScope || payload.action || 'EXECUTE_SUBTASK'),
          callerToken: String(payload.callerToken || 'CUBIO_PMA_AUTH_TOKEN'),
        };

      case 'SKILL-002-DEPENDENCY-REUSE-ANALYSIS':
        return {
          candidateComponent: String(payload.candidateModule || payload.candidateComponent || 'src/core/address369.ts'),
        };

      case 'SKILL-004-EVIDENCE-ARTIFACT-AUDIT':
        return {
          artifactPath: String(payload.artifactPath || payload.path || 'phase21_evidence.json'),
        };

      case 'SKILL-003-TEST-GATE-VALIDATION':
        return {
          gateId: String(payload.gateId || 'GATE-PHASE21'),
          targetPhase: 'PHASE-21',
        };

      case 'SKILL-013-CODE-GENERATION-ANALYSIS':
        return {
          taskDescription: String(payload.taskDescription || objective || 'Generate clean implementation'),
        };

      case 'SKILL-SHARED-PONYTAIL-CODE-QUALITY':
        return {
          proposedChanges: String(payload.proposedChanges || '// Minimalist implementation\nexport const valid = true;'),
        };

      case 'SKILL-015-BUG-DIAGNOSIS-FIX-PROPOSALS':
        return {
          errorLog: String(payload.errorMessage || objective || 'Defect trace'),
        };

      case 'SKILL-016-SYSTEM-ARCHITECTURE-REVIEW':
        return {
          subsystemName: String(payload.subsystemName || 'CORE_ARCHITECTURE'),
        };

      case 'SKILL-019-PERFORMANCE-PROFILING-OPTIMIZATION':
        return {
          benchmarkName: String(payload.benchmarkName || 'SubtaskBenchmark'),
        };

      case 'SKILL-020-RELEASE-READINESS-MANIFEST':
        return {
          targetRelease: 'v1.0.0-rc',
          dryRun: true,
        };

      case 'SKILL-018-DATA-STORAGE-ANALYSIS':
        return {
          tableName: String(payload.tableName || 'studio_records'),
        };

      case 'SKILL-001-CONTEXT-RETRIEVAL':
        return {
          query: String(payload.query || objective || 'Task context'),
        };

      default:
        return { ...payload };
    }
  }

  /**
   * Dynamically resolves, validates, loads, and executes all relevant skills for a subtask.
   */
  public async invokeSkillsForSubtask(
    subtask: AOASubtaskDefinition,
    callerPermissions: readonly string[] = []
  ): Promise<DynamicSkillResolutionResult> {
    const subtaskId = subtask.subtaskId;
    const targetAgentId = subtask.targetAgentId;
    const traces: SkillInvocationTraceRecord[] = [];
    const combinedSkillOutputs: Record<string, unknown> = {};
    const errors: string[] = [];

    // 1. Recursion & Unbounded Chain Guard
    if (this.activeInvocationStack.has(subtaskId)) {
      const err = `RECURSIVE_SKILL_INVOCATION_BLOCKED: Subtask '${subtaskId}' is already in the active skill invocation stack.`;
      errors.push(err);
      return {
        subtaskId,
        targetAgentId,
        recommendedSkillIds: [],
        executedSkillTraces: [],
        overallSuccess: false,
        combinedSkillOutputs: {},
        errors: [err],
      };
    }

    if (this.activeInvocationStack.size >= this.maxDepth) {
      const err = `MAX_INVOCATION_DEPTH_EXCEEDED: Call stack depth limit (${this.maxDepth}) reached. Unbounded skill chaining prevented.`;
      errors.push(err);
      return {
        subtaskId,
        targetAgentId,
        recommendedSkillIds: [],
        executedSkillTraces: [],
        overallSuccess: false,
        combinedSkillOutputs: {},
        errors: [err],
      };
    }

    this.activeInvocationStack.add(subtaskId);

    try {
      // 2. Discover minimum relevant skills
      const recommendedSkillIds = this.selectSkillsForSubtask(subtask);

      if (recommendedSkillIds.length === 0) {
        return {
          subtaskId,
          targetAgentId,
          recommendedSkillIds: [],
          executedSkillTraces: [],
          overallSuccess: true,
          combinedSkillOutputs: {},
          errors: [],
        };
      }

      // 3. Process and execute each selected skill individually
      for (const skillId of recommendedSkillIds) {
        const invocationReason = `Auto-selected for agent ${targetAgentId} to fulfill subtask objective: "${subtask.objective.slice(0, 60)}..."`;

        // Check if skill exists
        const manifest = this.registry.getSkillManifest(skillId);
        if (!manifest) {
          const errMsg = `Skill '${skillId}' not found in registry.`;
          errors.push(errMsg);
          traces.push({
            skillId,
            skillName: 'UNKNOWN',
            skillVersion: '0.0.0',
            invokingAgentId: targetAgentId,
            subtaskId,
            invocationReason,
            inputReferenceHash: '0'.repeat(64),
            status: 'FAILED',
            executionLatencyMs: 0,
            error: errMsg,
            executedAt: new Date().toISOString(),
          });
          continue;
        }

        // Check agent permission
        const isPermitted = manifest.permittedAgents.includes('*') || manifest.permittedAgents.includes(targetAgentId);
        if (!isPermitted) {
          const errMsg = `Agent '${targetAgentId}' is unauthorized to invoke skill '${skillId}'. Permitted: [${manifest.permittedAgents.join(', ')}]`;
          errors.push(errMsg);
          traces.push({
            skillId,
            skillName: manifest.name,
            skillVersion: manifest.version,
            invokingAgentId: targetAgentId,
            subtaskId,
            invocationReason,
            inputReferenceHash: '0'.repeat(64),
            status: 'REJECTED',
            executionLatencyMs: 0,
            error: errMsg,
            executedAt: new Date().toISOString(),
          });
          continue;
        }

        // Prepare validated input
        const skillInput = this.prepareSkillInput(manifest, subtask);
        const inputHash = createHash('sha256').update(JSON.stringify(skillInput)).digest('hex');

        // Execute skill through registry
        try {
          const execRes: SkillExecutionResult = await this.registry.executeSkill(
            skillId,
            targetAgentId,
            skillInput,
            callerPermissions
          );

          if (execRes.success) {
            combinedSkillOutputs[skillId] = execRes.data;
            traces.push({
              skillId,
              skillName: manifest.name,
              skillVersion: manifest.version,
              invokingAgentId: targetAgentId,
              subtaskId,
              invocationReason,
              inputReferenceHash: inputHash,
              status: 'SUCCESS',
              executionLatencyMs: execRes.executionLatencyMs,
              evidenceHash: execRes.provenance.outputHashSha256,
              outputData: execRes.data,
              executedAt: execRes.provenance.executedAt,
            });
          } else {
            const errMsg = execRes.error || 'Skill execution failed';
            errors.push(errMsg);
            traces.push({
              skillId,
              skillName: manifest.name,
              skillVersion: manifest.version,
              invokingAgentId: targetAgentId,
              subtaskId,
              invocationReason,
              inputReferenceHash: inputHash,
              status: 'FAILED',
              executionLatencyMs: execRes.executionLatencyMs,
              error: errMsg,
              executedAt: execRes.provenance.executedAt,
            });
          }
        } catch (execErr: any) {
          const errMsg = execErr.message || 'Unhandled exception in skill execution';
          errors.push(errMsg);
          traces.push({
            skillId,
            skillName: manifest.name,
            skillVersion: manifest.version,
            invokingAgentId: targetAgentId,
            subtaskId,
            invocationReason,
            inputReferenceHash: inputHash,
            status: 'FAILED',
            executionLatencyMs: 0,
            error: errMsg,
            executedAt: new Date().toISOString(),
          });
        }
      }

      const overallSuccess = errors.length === 0 && traces.every((t) => t.status === 'SUCCESS');

      return {
        subtaskId,
        targetAgentId,
        recommendedSkillIds,
        executedSkillTraces: traces,
        overallSuccess,
        combinedSkillOutputs,
        errors,
      };
    } finally {
      this.activeInvocationStack.delete(subtaskId);
    }
  }
}
