/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-013 — CDA (Coding Agent)
 * src/cubio/agents/cda/codingAgent.ts
 *
 * Central facade for AGENT-013-CDA.
 * Orchestrates code generation, error diagnosis, bug fixing, test synthesis,
 * and structured patch proposal generation.
 * Enforces permanent actuation lockout and non-destructive output policy.
 */

import * as crypto from 'crypto';
import {
  CDACodingRequest,
  CDACodingReport,
  CDABugFinding,
  CDAPatchProposal,
  CDABoundsConfig,
  DEFAULT_CDA_BOUNDS,
  CDARequestStatus,
} from './types';
import { CodingEngineAdapter } from './codingEngineAdapter';
import { CodeAnalysisAdapter } from './codeAnalysisAdapter';
import { PatchProposalBuilder } from './patchProposalBuilder';
import { OutputSanitizer } from '../cea/outputSanitizer';

export class CodingAgent {
  public static readonly AGENT_ID = 'AGENT-013-CDA';
  public static readonly AGENT_NAME = 'Coding Agent';
  public static readonly VERSION = '1.0.0';

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public get is_actuation_blocked(): boolean {
    return true;
  }

  private readonly bounds: CDABoundsConfig;
  private readonly codingAdapter: CodingEngineAdapter;
  private readonly analysisAdapter: CodeAnalysisAdapter;
  private readonly proposalBuilder: PatchProposalBuilder;

  constructor(
    customBounds: CDABoundsConfig = DEFAULT_CDA_BOUNDS,
    customCodingAdapter?: CodingEngineAdapter,
    customAnalysisAdapter?: CodeAnalysisAdapter,
    customProposalBuilder?: PatchProposalBuilder
  ) {
    this.bounds = customBounds;
    this.codingAdapter = customCodingAdapter || new CodingEngineAdapter();
    this.analysisAdapter = customAnalysisAdapter || new CodeAnalysisAdapter();
    this.proposalBuilder = customProposalBuilder || new PatchProposalBuilder();
  }

  /**
   * Primary entry point: Executes a bounded coding request.
   */
  public async execute(request: CDACodingRequest): Promise<CDACodingReport> {
    const startTimeMs = Date.now();
    const requestId = request?.requestId || `REQ_CDA_${Date.now()}`;
    const taskId = request?.taskId || `TASK_CDA_${Date.now()}`;

    // 1. Validate request payload fail-closed
    if (!request || typeof request !== 'object') {
      return this.buildErrorReport(
        requestId,
        taskId,
        'FAILED',
        'Invalid coding request: payload is null or not an object',
        startTimeMs
      );
    }

    // 2. Reject malicious actuation override attempts
    if (request.bypassActuationLock === true) {
      return this.buildErrorReport(
        requestId,
        taskId,
        'BLOCKED',
        'Hardware actuation override attempt rejected fail-closed. IS_ACTUATION_BLOCKED is immutable.',
        startTimeMs
      );
    }

    const prompt = (request.prompt || '').trim();
    if (!prompt && !request.codeSnippet && !request.errorTrace && !request.existingFiles) {
      return this.buildErrorReport(
        requestId,
        taskId,
        'INSUFFICIENT_CONTEXT',
        'Request lacks prompt, code snippet, error trace, or workspace files.',
        startTimeMs
      );
    }

    // 3. Bounds enforcement
    const effectiveBounds: CDABoundsConfig = {
      ...this.bounds,
      ...(request.bounds || {}),
    };

    if (prompt.length > effectiveBounds.maxPromptLength) {
      return this.buildErrorReport(
        requestId,
        taskId,
        'FAILED',
        `Prompt length ${prompt.length} exceeds maximum allowed ${effectiveBounds.maxPromptLength}`,
        startTimeMs
      );
    }

    if (request.codeSnippet && request.codeSnippet.length > effectiveBounds.maxCodeInputLength) {
      return this.buildErrorReport(
        requestId,
        taskId,
        'FAILED',
        `Code snippet length ${request.codeSnippet.length} exceeds maximum allowed ${effectiveBounds.maxCodeInputLength}`,
        startTimeMs
      );
    }

    // Treat prompt & code snippet as untrusted: sanitize against secret leaks
    const sanitizedPrompt = OutputSanitizer.sanitize(prompt).sanitizedText;
    const sanitizedSnippet = request.codeSnippet
      ? OutputSanitizer.sanitize(request.codeSnippet).sanitizedText
      : '';

    const language = request.language || 'typescript';
    const taskType = request.taskType || 'CODE_GENERATION';

    try {
      switch (taskType) {
        case 'CODE_GENERATION': {
          const genResult = await this.codingAdapter.generateCode({
            prompt: sanitizedPrompt,
            language,
            framework: request.framework,
            existingFiles: request.existingFiles,
            targetFilePath: request.targetFilePath,
          });

          const patch = this.proposalBuilder.buildProposal({
            taskId,
            targetFilePath: request.targetFilePath || genResult.filename,
            operation: 'CREATE',
            rationale: `Synthesized code for: ${sanitizedPrompt}`,
            proposedContent: genResult.code,
            diffSummary: `Generated ${genResult.lineCount} lines (${genResult.language})`,
            linesModified: [1, genResult.lineCount],
            regressionRisks: ['Ensure imports align with project dependencies'],
            verificationCommands: ['npx tsc --noEmit'],
          });

          return this.finalizeReport({
            requestId,
            taskId,
            taskType,
            status: patch.patchStatus === 'BLOCKED' ? 'BLOCKED' : 'SUCCEEDED',
            language: genResult.language,
            generatedCode: genResult.code,
            explanation: genResult.explanation,
            findings: [],
            patchProposals: [patch],
            suggestedTests: genResult.tests,
            dependencies: genResult.imports ? [...genResult.imports] : [],
            regressionRisks: patch.potentialRegressionRisks ? [...patch.potentialRegressionRisks] : [],
            provenanceSource: genResult.providerId || 'CubiOUniversalCodingEngine',
            startTimeMs,
            errors: patch.patchStatus === 'BLOCKED' ? ['Protected file target blocked'] : [],
          });
        }

        case 'BUG_DIAGNOSIS': {
          const trace = request.errorTrace || sanitizedPrompt;
          const snippet = sanitizedSnippet || (request.existingFiles ? Object.values(request.existingFiles)[0] : '');
          const diagReport = this.analysisAdapter.diagnoseError(trace, snippet);

          const finding: CDABugFinding = {
            findingId: diagReport.diagnosisId,
            errorType: diagReport.errorType,
            rootCause: diagReport.rootCause,
            offendingFile: diagReport.offendingFile,
            offendingLine: diagReport.offendingLineNumber,
            evidenceSummary: `Diagnosed from trace: ${trace.slice(0, 150)}`,
            confidence: diagReport.confidence,
            suggestedFixStrategy: diagReport.fixStrategy,
          };

          const patch = this.proposalBuilder.buildProposal({
            taskId,
            targetFilePath: diagReport.offendingFile || request.targetFilePath || 'diagnosedFile.ts',
            operation: 'MODIFY',
            rationale: diagReport.rootCause,
            originalContent: snippet,
            proposedContent: diagReport.suggestedPatch,
            diffSummary: `Suggested patch for ${diagReport.errorType}`,
            linesModified: diagReport.offendingLineNumber ? [diagReport.offendingLineNumber] : [1],
            regressionRisks: ['Verify type check passes with applied fix'],
            verificationCommands: ['npx tsc --noEmit'],
          });

          return this.finalizeReport({
            requestId,
            taskId,
            taskType,
            status: patch.patchStatus === 'BLOCKED' ? 'BLOCKED' : 'SUCCEEDED',
            language,
            findings: [finding],
            patchProposals: [patch],
            dependencies: [],
            regressionRisks: patch.potentialRegressionRisks ? [...patch.potentialRegressionRisks] : [],
            provenanceSource: 'CubiOCodeAnalysisEngine',
            startTimeMs,
            errors: patch.patchStatus === 'BLOCKED' ? ['Protected file target blocked'] : [],
          });
        }

        case 'PATCH_PROPOSAL': {
          const codeToFix = sanitizedSnippet || (request.existingFiles ? Object.values(request.existingFiles)[0] : '');
          if (!codeToFix) {
            return this.buildErrorReport(
              requestId,
              taskId,
              'INSUFFICIENT_CONTEXT',
              'Patch proposal requires codeSnippet or existingFiles to modify.',
              startTimeMs
            );
          }

          const bugReport = this.analysisAdapter.fixBug(codeToFix, sanitizedPrompt);
          const patch = this.proposalBuilder.buildProposal({
            taskId,
            targetFilePath: request.targetFilePath || 'patchedFile.ts',
            operation: 'MODIFY',
            rationale: bugReport.rootCauseSummary,
            originalContent: codeToFix,
            proposedContent: bugReport.fixedCode,
            diffSummary: bugReport.diffSummary,
            linesModified: bugReport.linesModified,
            regressionRisks: ['Ensure downstream calls handle optional returns or updated types'],
            verificationCommands: ['npx tsc --noEmit'],
          });

          return this.finalizeReport({
            requestId,
            taskId,
            taskType,
            status: patch.patchStatus === 'BLOCKED' ? 'BLOCKED' : 'SUCCEEDED',
            language,
            findings: [],
            patchProposals: [patch],
            dependencies: [],
            regressionRisks: patch.potentialRegressionRisks ? [...patch.potentialRegressionRisks] : [],
            provenanceSource: 'BugFixer',
            startTimeMs,
            errors: patch.patchStatus === 'BLOCKED' ? ['Target file is protected authority'] : [],
          });
        }

        case 'CODE_EXPLANATION': {
          const codeToExplain = sanitizedSnippet || sanitizedPrompt;
          const explanationRes = await this.codingAdapter.explainCode(codeToExplain, language);

          return this.finalizeReport({
            requestId,
            taskId,
            taskType,
            status: 'SUCCEEDED',
            language,
            explanation: explanationRes.summary,
            findings: [],
            patchProposals: [],
            dependencies: [],
            regressionRisks: explanationRes.potentialEdgeCases ? [...explanationRes.potentialEdgeCases] : [],
            provenanceSource: 'CubiOUniversalCodingEngine.explainCode',
            startTimeMs,
            errors: [],
          });
        }

        case 'CODE_REFACTOR': {
          const codeToRefactor = sanitizedSnippet || sanitizedPrompt;
          const refactorRes = await this.codingAdapter.refactorCode({
            code: codeToRefactor,
            strategy: 'HARDEN_TYPE_SAFETY',
            language,
          });

          const patch = this.proposalBuilder.buildProposal({
            taskId,
            targetFilePath: request.targetFilePath || 'refactoredFile.ts',
            operation: 'MODIFY',
            rationale: `Applied refactor strategy: ${refactorRes.strategyApplied}`,
            originalContent: codeToRefactor,
            proposedContent: refactorRes.refactoredCode,
            diffSummary: refactorRes.changesMade.join('; '),
            regressionRisks: refactorRes.improvements ? [...refactorRes.improvements] : [],
            verificationCommands: ['npx tsc --noEmit'],
          });

          return this.finalizeReport({
            requestId,
            taskId,
            taskType,
            status: patch.patchStatus === 'BLOCKED' ? 'BLOCKED' : 'SUCCEEDED',
            language,
            findings: [],
            patchProposals: [patch],
            dependencies: [],
            regressionRisks: patch.potentialRegressionRisks ? [...patch.potentialRegressionRisks] : [],
            provenanceSource: 'CubiOUniversalCodingEngine.refactorCode',
            startTimeMs,
            errors: patch.patchStatus === 'BLOCKED' ? ['Protected file target blocked'] : [],
          });
        }

        case 'TEST_GENERATION': {
          const codeToTest = sanitizedSnippet || sanitizedPrompt;
          const testRes = await this.codingAdapter.generateTests({
            code: codeToTest,
            testFramework: 'vitest',
            language,
            includeInvariants: true,
          });

          const patch = this.proposalBuilder.buildProposal({
            taskId,
            targetFilePath: request.targetFilePath || 'generated.test.ts',
            operation: 'CREATE',
            rationale: `Generated ${testRes.testCasesCount} unit tests using ${testRes.framework}`,
            proposedContent: testRes.testCode,
            diffSummary: `Test cases for: ${testRes.coveredFunctions.join(', ')}`,
            regressionRisks: ['Verify test runner executes in local environment'],
            verificationCommands: ['npx tsx generated.test.ts'],
          });

          return this.finalizeReport({
            requestId,
            taskId,
            taskType,
            status: patch.patchStatus === 'BLOCKED' ? 'BLOCKED' : 'SUCCEEDED',
            language,
            generatedCode: testRes.testCode,
            suggestedTests: testRes.testCode,
            findings: [],
            patchProposals: [patch],
            dependencies: [testRes.framework],
            regressionRisks: patch.potentialRegressionRisks ? [...patch.potentialRegressionRisks] : [],
            provenanceSource: 'CubiOUniversalCodingEngine.generateTests',
            startTimeMs,
            errors: patch.patchStatus === 'BLOCKED' ? ['Protected file target blocked'] : [],
          });
        }

        case 'REPOSITORY_ANALYSIS': {
          const files = request.existingFiles || {};
          const analysisReport = this.analysisAdapter.analyzeRepository(files);

          return this.finalizeReport({
            requestId,
            taskId,
            taskType,
            status: 'SUCCEEDED',
            language: analysisReport.dominantLanguage,
            explanation: `Repository Health Score: ${analysisReport.codeHealthScore}/100. Total Files: ${analysisReport.totalFiles}. Total Lines: ${analysisReport.totalLinesOfCode}.`,
            findings: [],
            patchProposals: [],
            dependencies: [],
            regressionRisks: analysisReport.complexityHotspots ? [...analysisReport.complexityHotspots] : [],
            provenanceSource: 'CubiOCodeAnalysisEngine.analyzeRepository',
            startTimeMs,
            errors: [],
          });
        }

        default: {
          return this.buildErrorReport(
            requestId,
            taskId,
            'FAILED',
            `Unsupported coding task type: ${(request as any).taskType}`,
            startTimeMs
          );
        }
      }
    } catch (err: any) {
      return this.buildErrorReport(
        requestId,
        taskId,
        'FAILED',
        `Exception occurred during coding execution: ${err.message || String(err)}`,
        startTimeMs
      );
    }
  }

  /**
   * Compatibility adapter for AOA AgentInvoker.
   */
  public async invoke(payload: Record<string, unknown>, timeoutMs?: number): Promise<CDACodingReport> {
    const effectiveTimeout = timeoutMs || this.bounds.maxExecutionMs;
    let timerHandle: NodeJS.Timeout | undefined;

    try {
      return await Promise.race([
        this.execute(payload as unknown as CDACodingRequest),
        new Promise<CDACodingReport>((_, reject) => {
          timerHandle = setTimeout(
            () => reject(new Error(`[CDA_TIMEOUT] Execution exceeded ${effectiveTimeout}ms`)),
            effectiveTimeout
          );
        }),
      ]);
    } catch (err: any) {
      return this.buildErrorReport(
        String(payload?.requestId || `REQ_CDA_${Date.now()}`),
        String(payload?.taskId || `TASK_CDA_${Date.now()}`),
        err.message?.includes('TIMEOUT') ? 'TIMED_OUT' : 'FAILED',
        err.message || String(err),
        Date.now()
      );
    } finally {
      if (timerHandle !== undefined) {
        clearTimeout(timerHandle);
      }
    }
  }

  private finalizeReport(params: {
    requestId: string;
    taskId: string;
    taskType: any;
    status: CDARequestStatus;
    language: string;
    generatedCode?: string;
    explanation?: string;
    findings: readonly CDABugFinding[];
    patchProposals: readonly CDAPatchProposal[];
    suggestedTests?: string;
    dependencies: readonly string[];
    regressionRisks: readonly string[];
    provenanceSource: string;
    startTimeMs: number;
    errors: readonly string[];
  }): CDACodingReport {
    const durationMs = Math.max(1, Date.now() - params.startTimeMs);
    const contentToHash = JSON.stringify({
      taskId: params.taskId,
      status: params.status,
      code: params.generatedCode,
      findings: params.findings,
      patches: params.patchProposals.map((p) => p.proposalChecksum),
    });

    const reportChecksum = crypto.createHash('sha256').update(contentToHash).digest('hex');
    const reportId = `REP_CDA_${reportChecksum.slice(0, 12).toUpperCase()}`;

    return Object.freeze({
      reportId,
      requestId: params.requestId,
      taskId: params.taskId,
      taskType: params.taskType,
      status: params.status,
      language: params.language,
      generatedCode: params.generatedCode,
      explanation: params.explanation,
      findings: Object.freeze([...params.findings]),
      patchProposals: Object.freeze([...params.patchProposals]),
      suggestedTests: params.suggestedTests,
      dependencies: Object.freeze([...params.dependencies]),
      regressionRisks: Object.freeze([...params.regressionRisks]),
      provenanceSource: params.provenanceSource,
      reportChecksum,
      durationMs,
      errors: Object.freeze([...params.errors]),
    });
  }

  private buildErrorReport(
    requestId: string,
    taskId: string,
    status: CDARequestStatus,
    errorMessage: string,
    startTimeMs: number
  ): CDACodingReport {
    const durationMs = Math.max(1, Date.now() - startTimeMs);
    const reportChecksum = crypto
      .createHash('sha256')
      .update(`${requestId}:${taskId}:${status}:${errorMessage}`)
      .digest('hex');

    return Object.freeze({
      reportId: `REP_CDA_ERR_${reportChecksum.slice(0, 10).toUpperCase()}`,
      requestId,
      taskId,
      taskType: 'CODE_GENERATION',
      status,
      language: 'typescript',
      findings: Object.freeze([]),
      patchProposals: Object.freeze([]),
      dependencies: Object.freeze([]),
      regressionRisks: Object.freeze([]),
      provenanceSource: 'CDA_ERROR_HANDLER',
      reportChecksum,
      durationMs,
      errors: Object.freeze([errorMessage]),
    });
  }
}
