/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-010 — SGA (Security & Governance Agent)
 * src/cubio/agents/sga/securityAuditAgent.ts
 *
 * Central facade for AGENT-010-SGA.
 * Evaluates security controls, authorization boundaries, policy compliance,
 * and evidence-backed governance across the multi-agent ecosystem.
 * Permanently locks is_actuation_blocked = true.
 */

import {
  SGASecurityRequest,
  SGASecurityDecision,
  SGABoundsConfig,
  DEFAULT_SGA_BOUNDS,
} from './types';
import { AuthorizationEvaluator } from './authorizationEvaluator';
import { IdentityAdapter } from './identityAdapter';
import { PolicyEvaluationAdapter } from './policyEvaluationAdapter';

export class SecurityGovernanceAgent {
  public static readonly AGENT_ID = 'AGENT-010-SGA';
  public static readonly AGENT_NAME = 'Security & Governance Agent';
  public static readonly VERSION = '1.0.0';

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public readonly is_actuation_blocked: boolean = true;

  private readonly evaluator: AuthorizationEvaluator;
  private readonly identityAdapter: IdentityAdapter;
  private readonly policyAdapter: PolicyEvaluationAdapter;
  private readonly bounds: SGABoundsConfig;

  constructor(
    customBounds: SGABoundsConfig = DEFAULT_SGA_BOUNDS,
    customRootDir?: string,
    customIdentity?: IdentityAdapter,
    customPolicy?: PolicyEvaluationAdapter
  ) {
    this.bounds = customBounds;
    this.identityAdapter = customIdentity || new IdentityAdapter();
    this.policyAdapter = customPolicy || new PolicyEvaluationAdapter(customRootDir);
    this.evaluator = new AuthorizationEvaluator(
      this.bounds,
      customRootDir,
      this.identityAdapter,
      this.policyAdapter
    );
  }

  /**
   * Evaluates security, identity, and governance compliance for a request.
   */
  public auditRequest(request: SGASecurityRequest): SGASecurityDecision {
    return this.evaluator.evaluate(request);
  }

  /**
   * AOA AgentInvoker contract compatibility helper.
   */
  public async invoke(payload: Record<string, unknown>): Promise<SGASecurityDecision> {
    return this.auditRequest(payload as unknown as SGASecurityRequest);
  }

  public getEvaluator(): AuthorizationEvaluator {
    return this.evaluator;
  }
}
