/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-012 — RRA (Research & Retrieval Agent)
 * src/cubio/agents/rra/claimEvidenceMapper.ts
 *
 * Maps research claims to supporting or opposing retrieved evidence.
 * Categorizes claims into SUPPORTED, PARTIALLY_SUPPORTED, CONTRADICTED,
 * or INSUFFICIENT_EVIDENCE without fabricating citations or assuming verification.
 */

import * as crypto from 'crypto';
import { RRASourceReference, RRAFinding, RRASupportStatus, RRAConflictRecord } from './types';

export class ClaimEvidenceMapper {
  /**
   * Generates grounded findings from query, retrieved sources, and detected conflicts.
   */
  public static mapClaims(
    query: string,
    sources: readonly RRASourceReference[],
    conflicts: readonly RRAConflictRecord[],
    maxFindings: number = 10
  ): readonly RRAFinding[] {
    const findings: RRAFinding[] = [];

    if (sources.length === 0) {
      // Explicit insufficient evidence finding
      findings.push(
        Object.freeze({
          findingId: 'FIND_NO_EVIDENCE',
          claim: `Investigation for query "${query}" yielded zero supporting evidence from authorized scopes.`,
          supportStatus: 'INSUFFICIENT_EVIDENCE',
          evidenceReferences: Object.freeze([]),
          contradictingEvidenceReferences: Object.freeze([]),
          confidence: 0.0,
          limitations: Object.freeze(['No matching sources retrieved in approved local stores']),
        })
      );
      return Object.freeze(findings);
    }

    const queryTokens = query.toLowerCase().split(/\s+/).filter((t) => t.length > 2);

    for (let i = 0; i < sources.length && findings.length < maxFindings; i++) {
      const source = sources[i];
      const findingId = `FIND_${crypto
        .createHash('sha256')
        .update(`${source.sourceId}:${i}:${query}`)
        .digest('hex')
        .slice(0, 8)}`;

      // Check if source title or snippet matches query tokens
      const textLower = (source.title + ' ' + source.snippet).toLowerCase();
      const matchCount = queryTokens.filter((token) => textLower.includes(token)).length;
      const matchRatio = queryTokens.length > 0 ? matchCount / queryTokens.length : 1.0;

      // Check if this source is involved in any conflict
      const relatedConflict = conflicts.find(
        (c) => c.sourceAId === source.sourceId || c.sourceBId === source.sourceId
      );

      let supportStatus: RRASupportStatus = 'SUPPORTED';
      let confidence = Math.min(0.99, Number((source.reliabilityScore * 0.9 + matchRatio * 0.1).toFixed(3)));
      const limitations: string[] = [];
      const contradictingRefs: string[] = [];

      if (relatedConflict) {
        supportStatus = 'CONTRADICTED';
        contradictingRefs.push(relatedConflict.conflictId);
        limitations.push(relatedConflict.conflictDescription);
        confidence = Math.min(confidence, 0.5);
      } else if (matchRatio < 0.3) {
        supportStatus = 'PARTIALLY_SUPPORTED';
        limitations.push('Only partial term overlap between query and retrieved source passage');
        confidence = Math.min(confidence, 0.6);
      }

      findings.push(
        Object.freeze({
          findingId,
          claim: source.snippet.slice(0, 200),
          supportStatus,
          evidenceReferences: Object.freeze([source.sourceId]),
          contradictingEvidenceReferences: Object.freeze(contradictingRefs),
          confidence,
          limitations: Object.freeze(limitations),
        })
      );
    }

    return Object.freeze(findings);
  }
}
