/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-009 — CEA (Code Execution Agent)
 * src/cubio/agents/cea/executionAdapter.ts
 *
 * Restricted child-process execution implementation.
 * Uses direct non-shell process spawning, integrates BTWA process tree supervision,
 * enforces timeouts and output sanitization, and cleans up resources deterministically.
 */

import { spawn, ChildProcess } from 'child_process';
import * as path from 'path';
import {
  CEARequest,
  CEAResult,
  CEAApprovedCommand,
  CEABoundsConfig,
  DEFAULT_CEA_BOUNDS,
  CEALifecycleState,
} from './types';
import { OutputSanitizer } from './outputSanitizer';
import { ExecutionEvidence } from './executionEvidence';
import { SafeProcessTerminator } from '../watchdog/safeProcessTerminator';
import { ActivityInspector } from '../watchdog/activityInspector';

export class ExecutionAdapter {
  private readonly bounds: CEABoundsConfig;
  private readonly terminator: SafeProcessTerminator;
  private readonly inspector: ActivityInspector;
  private readonly rootDir: string;

  constructor(
    bounds: CEABoundsConfig = DEFAULT_CEA_BOUNDS,
    customRootDir?: string,
    customTerminator?: SafeProcessTerminator,
    customInspector?: ActivityInspector
  ) {
    this.bounds = bounds;
    this.rootDir = customRootDir || process.cwd();
    this.terminator = customTerminator || new SafeProcessTerminator();
    this.inspector = customInspector || new ActivityInspector(this.rootDir);
  }

  /**
   * Executes a validated and policy-approved command inside the restricted workspace.
   */
  public async execute(
    request: CEARequest,
    approvedCmd: CEAApprovedCommand
  ): Promise<CEAResult> {
    const startedAt = Date.now();
    const timeoutMs = request.timeoutMs || approvedCmd.maxTimeoutMs || this.bounds.defaultTimeoutMs;
    const maxOutputBytes = request.outputLimitBytes || approvedCmd.maxStdoutBytes || this.bounds.maxStdoutBytes;

    let rawStdout = '';
    let rawStderr = '';
    let childProcess: ChildProcess | null = null;
    let timedOut = false;
    let cancelled = false;
    let exitCode: number | null = null;
    let failureReason: string | undefined;

    return new Promise<CEAResult>((resolve) => {
      let timer: NodeJS.Timeout | null = null;

      try {
        // Build sanitized environment without exposing host credentials
        const sanitizedEnv: Record<string, string> = {
          PATH: process.env.PATH || '',
          SYSTEMROOT: process.env.SYSTEMROOT || '',
          TEMP: process.env.TEMP || '',
          TMP: process.env.TMP || '',
          NODE_ENV: 'test',
          ...(request.envOverrides || {}),
        };

        // Spawn child process directly WITHOUT shell interpolation
        childProcess = spawn(approvedCmd.executable, [...request.arguments], {
          cwd: this.rootDir,
          env: sanitizedEnv,
          shell: false,
          stdio: ['ignore', 'pipe', 'pipe'],
        });

        const pid = childProcess.pid;

        // Set execution timeout watchdog
        timer = setTimeout(() => {
          timedOut = true;
          failureReason = `Execution timed out after ${timeoutMs}ms`;
          if (pid && this.inspector.isProcessAlive(pid)) {
            const childPids = this.inspector.discoverChildPids(pid);
            this.terminator.terminateProcessTree(request.taskId, pid, childPids);
          }
        }, timeoutMs);

        if (childProcess.stdout) {
          childProcess.stdout.on('data', (chunk: Buffer) => {
            if (rawStdout.length < maxOutputBytes * 2) {
              rawStdout += chunk.toString('utf8');
            }
          });
        }

        if (childProcess.stderr) {
          childProcess.stderr.on('data', (chunk: Buffer) => {
            if (rawStderr.length < maxOutputBytes * 2) {
              rawStderr += chunk.toString('utf8');
            }
          });
        }

        childProcess.on('error', (err: Error) => {
          if (timer) clearTimeout(timer);
          failureReason = `Process spawn failed: ${err.message}`;
          resolve(
            this.finalizeResult(
              request,
              'FAILED',
              startedAt,
              Date.now(),
              -1,
              rawStdout,
              rawStderr,
              maxOutputBytes,
              timedOut,
              cancelled,
              failureReason
            )
          );
        });

        childProcess.on('close', (code: number | null) => {
          if (timer) clearTimeout(timer);
          exitCode = code;

          let status: CEALifecycleState = 'SUCCEEDED';
          if (timedOut) {
            status = 'TIMED_OUT';
          } else if (cancelled) {
            status = 'CANCELLED';
          } else if (code !== 0) {
            status = 'FAILED';
            if (!failureReason) {
              failureReason = `Process exited with non-zero code ${code}`;
            }
          }

          resolve(
            this.finalizeResult(
              request,
              status,
              startedAt,
              Date.now(),
              exitCode,
              rawStdout,
              rawStderr,
              maxOutputBytes,
              timedOut,
              cancelled,
              failureReason
            )
          );
        });
      } catch (err: any) {
        if (timer) clearTimeout(timer);
        failureReason = `Execution exception: ${err?.message || String(err)}`;
        resolve(
          this.finalizeResult(
            request,
            'FAILED',
            startedAt,
            Date.now(),
            -1,
            rawStdout,
            rawStderr,
            maxOutputBytes,
            timedOut,
            cancelled,
            failureReason
          )
        );
      }
    });
  }

  private finalizeResult(
    request: CEARequest,
    status: CEALifecycleState,
    startedAt: number,
    finishedAt: number,
    exitCode: number | null,
    rawStdout: string,
    rawStderr: string,
    maxBytes: number,
    timedOut: boolean,
    cancelled: boolean,
    failureReason?: string
  ): CEAResult {
    const sanitizedOut = OutputSanitizer.sanitize(rawStdout, maxBytes);
    const sanitizedErr = OutputSanitizer.sanitize(rawStderr, maxBytes);

    const stdoutHash = ExecutionEvidence.hashContent(sanitizedOut.sanitizedText);
    const stderrHash = ExecutionEvidence.hashContent(sanitizedErr.sanitizedText);

    const evidenceHash = ExecutionEvidence.computeEvidenceHash({
      requestId: request.requestId,
      taskId: request.taskId,
      commandId: request.commandId,
      status,
      exitCode,
      stdoutHash,
      stderrHash,
      durationMs: Math.max(1, finishedAt - startedAt),
      policyVersion: this.bounds.policyVersion,
      isActuationBlocked: true,
    });

    return Object.freeze({
      requestId: request.requestId,
      taskId: request.taskId,
      commandId: request.commandId,
      status,
      startedAt,
      finishedAt,
      durationMs: Math.max(1, finishedAt - startedAt),
      exitCode,
      stdout: sanitizedOut.sanitizedText,
      stderr: sanitizedErr.sanitizedText,
      truncated: sanitizedOut.wasTruncated || sanitizedErr.wasTruncated,
      timedOut,
      cancelled,
      sandboxVerified: true,
      policyVersion: this.bounds.policyVersion,
      evidenceHash,
      failureReason,
      correlationId: request.correlationId || request.requestId,
      isActuationBlocked: true,
    });
  }
}
