/**
 * CUBiO AI — Phase 24: Native CUBiO Model Training & Genesis
 * checkpoint_manager.ts
 *
 * Dedicated Checkpoint Manager for Native Models.
 * Strictly enforces structural and domain separation:
 * MODEL_CHECKPOINT (weights, architecture, manifest, lineage)
 * vs
 * COGNITIVE_MEMORY_CHECKPOINT (.3dmemory spatial state, knowledge records)
 *
 * Weights are NEVER placed into the persistent cognitive memory store.
 */

import { createHash } from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import {
  NativeModelCheckpoint,
  NativeModelConfig,
  TrainingCheckpointState,
  CUBIO_NATIVE_MODEL_ID,
} from './native_model_types';
import { CubiONativeModel } from './native_model_architecture';
import { ExternalModelGuard } from './external_model_guard';

export class CheckpointManager {
  /**
   * Creates a sealed NativeModelCheckpoint container from a trained model instance
   */
  public static createCheckpoint(
    model: CubiONativeModel,
    trainingRunId: string,
    lineageParentStateHash: string | null,
    evaluationScore = 1.0
  ): NativeModelCheckpoint {
    ExternalModelGuard.assertNativeOnly(model.modelId);

    const weights = model.getWeights();
    const inventory = model.getParameterInventory();
    const modelStateHash = model.computeWeightsHash();

    // Compute Merkle root across weight tensors
    const merkleHash = createHash('sha256');
    for (const t of inventory.tensors) {
      merkleHash.update(`${t.tensorName}:${t.parameterCount}`);
    }
    const weightsMerkleRoot = merkleHash.digest('hex');

    const checkpointId = `CHK_NATIVE_${Date.now()}_${modelStateHash.slice(0, 8)}`;

    return Object.freeze({
      checkpointId,
      modelId: model.modelId || CUBIO_NATIVE_MODEL_ID,
      containerType: 'CUBIO_NATIVE_MODEL_CHECKPOINT_V1',
      architectureVersion: '1.0.0',
      vocabularyVersion: '1.0.0',
      trainingRunId,
      lineageParentStateHash,
      modelStateHash,
      weightsMerkleRoot,
      parameterInventory: inventory,
      weights: {
        tokenEmbedding: weights.tokenEmbedding as any,
        positionalEmbedding: weights.positionalEmbedding as any,
        spatialEmbedding: weights.spatialEmbedding as any,
        layers: weights.layers as any,
        epistemicHead: weights.epistemicHead as any,
        lmHead: weights.lmHead as any,
      },
      evaluationScore,
      createdAt: new Date().toISOString(),
    });
  }

  public static readonly BINARY_MAGIC = 'CUBIO_BIN_CHK_V1';

  /**
   * Serializes a NativeModelWeights structure into a flat Float32Array
   */
  public static packWeights(weights: any, config?: Partial<NativeModelConfig>): Float32Array {
    const D = config?.embedDim ?? (weights.tokenEmbedding?.[0]?.length || 256);
    const dFF = config?.embedDim ? config.embedDim * 2 : (weights.layers?.[0]?.ffn1Weight?.[0]?.length || 512);
    const V = config?.vocabSize ?? (weights.tokenEmbedding?.length || 1024);
    const S = config?.numSpatialCells ?? (weights.spatialEmbedding?.length || 343);
    const maxSeqLen = config?.maxSeqLen ?? (weights.positionalEmbedding?.length || 320);
    const numLayers = weights.layers?.length || 8;

    const total = V * D + maxSeqLen * D + S * D + numLayers * (4 * D * D + D + D * dFF + dFF * D + D) + D * 7 + D * V;
    const flat = new Float32Array(total);
    let off = 0;

    for (let i = 0; i < V; i++) { flat.set(weights.tokenEmbedding[i], off); off += D; }
    for (let i = 0; i < maxSeqLen; i++) { flat.set(weights.positionalEmbedding[i], off); off += D; }
    for (let i = 0; i < S; i++) { flat.set(weights.spatialEmbedding[i], off); off += D; }
    for (let l = 0; l < numLayers; l++) {
      const lw = weights.layers[l];
      for (let j = 0; j < D; j++) { flat.set(lw.qWeight[j], off); off += D; }
      for (let j = 0; j < D; j++) { flat.set(lw.kWeight[j], off); off += D; }
      for (let j = 0; j < D; j++) { flat.set(lw.vWeight[j], off); off += D; }
      for (let j = 0; j < D; j++) { flat.set(lw.outWeight[j], off); off += D; }
      flat.set(lw.norm1Gamma, off); off += D;
      for (let j = 0; j < D; j++) { flat.set(lw.ffn1Weight[j], off); off += dFF; }
      for (let j = 0; j < dFF; j++) { flat.set(lw.ffn2Weight[j], off); off += D; }
      flat.set(lw.norm2Gamma, off); off += D;
    }
    for (let j = 0; j < D; j++) { flat.set(weights.epistemicHead[j], off); off += 7; }
    for (let j = 0; j < D; j++) { flat.set(weights.lmHead[j], off); off += V; }
    return flat;
  }

  /**
   * Unpacks a flat Float32Array into a NativeModelWeights structure
   */
  public static unpackWeights(flat: Float32Array, config?: Partial<NativeModelConfig>): any {
    const D = config?.embedDim ?? 256;
    const dFF = config?.embedDim ? config.embedDim * 2 : 512;
    let V = config?.vocabSize;
    let maxSeqLen = config?.maxSeqLen;
    if (!V) {
      if (flat.length > 5500000) {
        V = 4096;
        maxSeqLen = (flat.length <= 6450000 && flat.length >= 6300000) ? 192 : 320;
      } else {
        V = 1024;
        maxSeqLen = 320;
      }
    }
    if (!maxSeqLen) maxSeqLen = 320;
    const S = config?.numSpatialCells ?? 343;
    const numLayers = config?.numLayers ?? 8;

    let off = 0;
    const tokenEmbedding: number[][] = [];
    for (let i = 0; i < V; i++) { tokenEmbedding.push(Array.from(flat.subarray(off, off + D))); off += D; }

    const positionalEmbedding: number[][] = [];
    for (let i = 0; i < maxSeqLen; i++) { positionalEmbedding.push(Array.from(flat.subarray(off, off + D))); off += D; }

    const spatialEmbedding: number[][] = [];
    for (let i = 0; i < S; i++) { spatialEmbedding.push(Array.from(flat.subarray(off, off + D))); off += D; }

    const layers: any[] = [];
    for (let l = 0; l < numLayers; l++) {
      const qWeight: number[][] = [];
      for (let j = 0; j < D; j++) { qWeight.push(Array.from(flat.subarray(off, off + D))); off += D; }
      const kWeight: number[][] = [];
      for (let j = 0; j < D; j++) { kWeight.push(Array.from(flat.subarray(off, off + D))); off += D; }
      const vWeight: number[][] = [];
      for (let j = 0; j < D; j++) { vWeight.push(Array.from(flat.subarray(off, off + D))); off += D; }
      const outWeight: number[][] = [];
      for (let j = 0; j < D; j++) { outWeight.push(Array.from(flat.subarray(off, off + D))); off += D; }
      const norm1Gamma = Array.from(flat.subarray(off, off + D)); off += D;
      const ffn1Weight: number[][] = [];
      for (let j = 0; j < D; j++) { ffn1Weight.push(Array.from(flat.subarray(off, off + dFF))); off += dFF; }
      const ffn2Weight: number[][] = [];
      for (let j = 0; j < dFF; j++) { ffn2Weight.push(Array.from(flat.subarray(off, off + D))); off += D; }
      const norm2Gamma = Array.from(flat.subarray(off, off + D)); off += D;

      layers.push({ qWeight, kWeight, vWeight, outWeight, norm1Gamma, ffn1Weight, ffn2Weight, norm2Gamma });
    }

    const epistemicHead: number[][] = [];
    for (let j = 0; j < D; j++) { epistemicHead.push(Array.from(flat.subarray(off, off + 7))); off += 7; }

    const lmHead: number[][] = [];
    for (let j = 0; j < D; j++) { lmHead.push(Array.from(flat.subarray(off, off + V))); off += V; }

    return {
      tokenEmbedding,
      positionalEmbedding,
      spatialEmbedding,
      layers,
      epistemicHead,
      lmHead,
    };
  }

  /**
   * Saves a checkpoint to disk in high-efficiency binary format (CUBIO_BIN_CHK_V1)
   */
  public static saveBinaryCheckpoint(
    checkpoint: NativeModelCheckpoint,
    targetPath: string,
    extraMeta?: Record<string, any>
  ): string {
    if (targetPath.endsWith('.3dmemory') || targetPath.includes('.3dmemory')) {
      throw new Error('[DOMAIN_CONFLATION_ERROR] Cannot save native model weights into a .3dmemory cognitive memory container!');
    }

    const parentDir = path.dirname(targetPath);
    if (!fs.existsSync(parentDir)) {
      fs.mkdirSync(parentDir, { recursive: true });
    }

    // 1. Pack weights into Float32Array
    const flatWeights = this.packWeights(checkpoint.weights);

    // 2. Build metadata header without raw weight tensors
    const meta = {
      checkpointId: checkpoint.checkpointId,
      modelId: checkpoint.modelId,
      containerType: checkpoint.containerType,
      architectureVersion: checkpoint.architectureVersion,
      vocabularyVersion: checkpoint.vocabularyVersion,
      trainingRunId: checkpoint.trainingRunId,
      lineageParentStateHash: checkpoint.lineageParentStateHash,
      modelStateHash: checkpoint.modelStateHash,
      weightsMerkleRoot: checkpoint.weightsMerkleRoot,
      parameterInventory: checkpoint.parameterInventory,
      evaluationScore: checkpoint.evaluationScore,
      createdAt: checkpoint.createdAt,
      binaryFormat: 'FLOAT32_LITTLE_ENDIAN',
      totalParameters: flatWeights.length,
      modelConfig: {
        vocabSize: checkpoint.weights.tokenEmbedding.length,
        maxSeqLen: checkpoint.weights.positionalEmbedding.length,
        embedDim: checkpoint.weights.tokenEmbedding[0]?.length || 256,
        numLayers: checkpoint.weights.layers.length,
      },
      ...(extraMeta || {}),
    };

    const metaJson = JSON.stringify(meta);
    const metaBuf = Buffer.from(metaJson, 'utf-8');

    // 3. Assemble binary container:
    // [16 bytes Magic] + [4 bytes uint32 header length] + [header JSON bytes] + [raw Float32 bytes]
    const magicBuf = Buffer.alloc(16);
    magicBuf.write(this.BINARY_MAGIC, 'utf-8');

    const lenBuf = Buffer.alloc(4);
    lenBuf.writeUInt32LE(metaBuf.length, 0);

    const weightsBuf = Buffer.from(flatWeights.buffer, flatWeights.byteOffset, flatWeights.byteLength);

    const combined = Buffer.concat([magicBuf, lenBuf, metaBuf, weightsBuf]);
    const tempPath = `${targetPath}.${Date.now()}.${Math.floor(Math.random() * 1e6)}.tmp`;
    const fd = fs.openSync(tempPath, 'w');
    fs.writeSync(fd, combined);
    fs.fsyncSync(fd);
    fs.closeSync(fd);

    if (fs.existsSync(targetPath)) {
      try { fs.unlinkSync(targetPath); } catch (_) {}
    }
    fs.renameSync(tempPath, targetPath);
    return targetPath;
  }

  /**
   * Saves a checkpoint to disk inside a dedicated checkpoints directory (default: binary format)
   */
  public static saveCheckpoint(checkpoint: NativeModelCheckpoint, targetDir: string, useBinary = true): string {
    if (targetDir.endsWith('.3dmemory') || targetDir.includes('.3dmemory')) {
      throw new Error('[DOMAIN_CONFLATION_ERROR] Cannot save native model weights into a .3dmemory cognitive memory container!');
    }

    if (!fs.existsSync(targetDir)) {
      fs.mkdirSync(targetDir, { recursive: true });
    }

    const filename = `${checkpoint.checkpointId}.cubiomodel`;
    const targetPath = path.join(targetDir, filename);

    if (useBinary) {
      return this.saveBinaryCheckpoint(checkpoint, targetPath);
    }

    fs.writeFileSync(targetPath, JSON.stringify(checkpoint, null, 2), 'utf-8');
    return targetPath;
  }

  /**
   * Saves a training checkpoint to disk in binary format with weights + AdamW m/v arrays + training state.
   * Format:
   * [16 bytes Magic: 'CUBIO_BIN_CHK_V1']
   * [4 bytes uint32 LE header length]
   * [header JSON bytes] (metadata + trainingState)
   * [weights bytes] (Float32Array of totalParameters)
   * [m bytes] (Float32Array of trainable parameters)
   * [v bytes] (Float32Array of trainable parameters)
   */
  public static saveTrainingCheckpoint(
    checkpoint: NativeModelCheckpoint,
    m: Float32Array,
    v: Float32Array,
    trainingState: TrainingCheckpointState,
    targetPath: string,
    extraMeta?: Record<string, any>
  ): string {
    if (targetPath.endsWith('.3dmemory') || targetPath.includes('.3dmemory')) {
      throw new Error('[DOMAIN_CONFLATION_ERROR] Cannot save native model weights into a .3dmemory cognitive memory container!');
    }

    const parentDir = path.dirname(targetPath);
    if (!fs.existsSync(parentDir)) {
      fs.mkdirSync(parentDir, { recursive: true });
    }

    // 1. Pack weights into Float32Array
    const flatWeights = this.packWeights(checkpoint.weights);

    // 2. Build metadata header including trainingState and totalTrainableParams
    const meta = {
      checkpointId: checkpoint.checkpointId,
      modelId: checkpoint.modelId,
      containerType: checkpoint.containerType,
      architectureVersion: checkpoint.architectureVersion,
      vocabularyVersion: checkpoint.vocabularyVersion,
      trainingRunId: checkpoint.trainingRunId,
      lineageParentStateHash: checkpoint.lineageParentStateHash,
      modelStateHash: checkpoint.modelStateHash,
      weightsMerkleRoot: checkpoint.weightsMerkleRoot,
      parameterInventory: checkpoint.parameterInventory,
      evaluationScore: checkpoint.evaluationScore,
      createdAt: checkpoint.createdAt,
      binaryFormat: 'FLOAT32_LITTLE_ENDIAN',
      totalParameters: flatWeights.length,
      trainingState: {
        ...trainingState,
        totalTrainableParams: m.length,
        hasOptimizerState: true,
      },
      modelConfig: {
        vocabSize: checkpoint.weights.tokenEmbedding.length,
        maxSeqLen: checkpoint.weights.positionalEmbedding.length,
        embedDim: checkpoint.weights.tokenEmbedding[0]?.length || 256,
        numLayers: checkpoint.weights.layers.length,
      },
      ...(extraMeta || {}),
    };

    const metaJson = JSON.stringify(meta);
    const metaBuf = Buffer.from(metaJson, 'utf-8');

    // 3. Assemble binary container
    const magicBuf = Buffer.alloc(16);
    magicBuf.write(this.BINARY_MAGIC, 'utf-8');

    const lenBuf = Buffer.alloc(4);
    lenBuf.writeUInt32LE(metaBuf.length, 0);

    const weightsBuf = Buffer.from(flatWeights.buffer, flatWeights.byteOffset, flatWeights.byteLength);
    const mBuf = Buffer.from(m.buffer, m.byteOffset, m.byteLength);
    const vBuf = Buffer.from(v.buffer, v.byteOffset, v.byteLength);

    const combined = Buffer.concat([magicBuf, lenBuf, metaBuf, weightsBuf, mBuf, vBuf]);
    const tempPath = `${targetPath}.${Date.now()}.${Math.floor(Math.random() * 1e6)}.tmp`;
    const fd = fs.openSync(tempPath, 'w');
    fs.writeSync(fd, combined);
    fs.fsyncSync(fd);
    fs.closeSync(fd);

    if (fs.existsSync(targetPath)) {
      try { fs.unlinkSync(targetPath); } catch (_) {}
    }
    fs.renameSync(tempPath, targetPath);
    return targetPath;
  }

  /**
   * Loads a checkpoint from disk (backward-compatible: supports both CUBIO_BIN_CHK_V1 binary and legacy JSON)
   */
  public static loadCheckpoint(filePath: string): NativeModelCheckpoint {
    if (filePath.endsWith('.3dmemory')) {
      throw new Error('[DOMAIN_CONFLATION_ERROR] Cannot load model checkpoint from a .3dmemory cognitive store!');
    }

    const fileBuffer = fs.readFileSync(filePath);

    // Check for Binary Magic Header
    if (fileBuffer.length >= 20) {
      const magic = fileBuffer.subarray(0, 16).toString('utf-8').replace(/\0/g, '');
      if (magic === this.BINARY_MAGIC) {
        const headerLen = fileBuffer.readUInt32LE(16);
        const headerJson = fileBuffer.subarray(20, 20 + headerLen).toString('utf-8');
        const meta = JSON.parse(headerJson);

        const weightsOffset = 20 + headerLen;
        const totalWeightsParams = meta.totalParameters || 4894208;
        const weightsByteLen = totalWeightsParams * 4;
        const weightsBuffer = fileBuffer.subarray(weightsOffset, weightsOffset + weightsByteLen);
        let flatWeights: Float32Array;
        if (weightsBuffer.byteOffset % 4 === 0) {
          flatWeights = new Float32Array(
            weightsBuffer.buffer,
            weightsBuffer.byteOffset,
            totalWeightsParams
          );
        } else {
          const alignedBuffer = new ArrayBuffer(weightsByteLen);
          new Uint8Array(alignedBuffer).set(weightsBuffer);
          flatWeights = new Float32Array(alignedBuffer, 0, totalWeightsParams);
        }

        const weights = this.unpackWeights(flatWeights, meta.modelConfig || meta.config);

        return Object.freeze({
          checkpointId: meta.checkpointId,
          modelId: meta.modelId || CUBIO_NATIVE_MODEL_ID,
          containerType: 'CUBIO_NATIVE_MODEL_CHECKPOINT_V1',
          architectureVersion: meta.architectureVersion || '1.0.0',
          vocabularyVersion: meta.vocabularyVersion || '1.0.0',
          trainingRunId: meta.trainingRunId || 'UNKNOWN',
          lineageParentStateHash: meta.lineageParentStateHash ?? null,
          modelStateHash: meta.modelStateHash,
          weightsMerkleRoot: meta.weightsMerkleRoot,
          parameterInventory: meta.parameterInventory,
          weights,
          evaluationScore: meta.evaluationScore ?? 1.0,
          createdAt: meta.createdAt || new Date().toISOString(),
          trainingState: meta.trainingState ?? undefined,
        });
      }
    }

    // Fallback: Legacy JSON format
    const content = fileBuffer.toString('utf-8');
    const parsed: NativeModelCheckpoint = JSON.parse(content);

    if (parsed.containerType !== 'CUBIO_NATIVE_MODEL_CHECKPOINT_V1') {
      throw new Error(`Invalid container type in ${filePath}: ${parsed.containerType}`);
    }

    return parsed;
  }

  /**
   * Loads a training checkpoint from disk, reconstructing model checkpoint, AdamW m and v arrays, and training state
   */
  public static loadTrainingCheckpoint(filePath: string): {
    checkpoint: NativeModelCheckpoint;
    m: Float32Array | null;
    v: Float32Array | null;
    trainingState: TrainingCheckpointState | null;
  } {
    if (filePath.endsWith('.3dmemory')) {
      throw new Error('[DOMAIN_CONFLATION_ERROR] Cannot load model checkpoint from a .3dmemory cognitive store!');
    }

    const fileBuffer = fs.readFileSync(filePath);
    if (fileBuffer.length < 20) {
      throw new Error(`File ${filePath} is too small to be a valid checkpoint`);
    }

    const magic = fileBuffer.subarray(0, 16).toString('utf-8').replace(/\0/g, '');
    if (magic === this.BINARY_MAGIC) {
      const headerLen = fileBuffer.readUInt32LE(16);
      const headerJson = fileBuffer.subarray(20, 20 + headerLen).toString('utf-8');
      const meta = JSON.parse(headerJson);

      const weightsOffset = 20 + headerLen;
      const totalWeightsParams = meta.totalParameters || 4894208;
      const weightsByteLen = totalWeightsParams * 4;

      const weightsSlice = fileBuffer.subarray(weightsOffset, weightsOffset + weightsByteLen);
      let flatWeights: Float32Array;
      if (weightsSlice.byteOffset % 4 === 0) {
        flatWeights = new Float32Array(
          weightsSlice.buffer,
          weightsSlice.byteOffset,
          totalWeightsParams
        );
      } else {
        const aligned = new ArrayBuffer(weightsByteLen);
        new Uint8Array(aligned).set(weightsSlice);
        flatWeights = new Float32Array(aligned, 0, totalWeightsParams);
      }

      const weights = this.unpackWeights(flatWeights, meta.modelConfig || meta.config);
      const trainingState: TrainingCheckpointState | null = meta.trainingState || null;

      const checkpoint: NativeModelCheckpoint = Object.freeze({
        checkpointId: meta.checkpointId,
        modelId: meta.modelId || CUBIO_NATIVE_MODEL_ID,
        containerType: 'CUBIO_NATIVE_MODEL_CHECKPOINT_V1',
        architectureVersion: meta.architectureVersion || '1.0.0',
        vocabularyVersion: meta.vocabularyVersion || '1.0.0',
        trainingRunId: meta.trainingRunId || 'UNKNOWN',
        lineageParentStateHash: meta.lineageParentStateHash ?? null,
        modelStateHash: meta.modelStateHash,
        weightsMerkleRoot: meta.weightsMerkleRoot,
        parameterInventory: meta.parameterInventory,
        weights,
        evaluationScore: meta.evaluationScore ?? 1.0,
        createdAt: meta.createdAt || new Date().toISOString(),
        trainingState: trainingState ?? undefined,
      });

      let m: Float32Array | null = null;
      let v: Float32Array | null = null;

      if (meta.trainingState?.hasOptimizerState) {
        const trainableParams = meta.trainingState.totalTrainableParams || 4804608;
        const mOffset = weightsOffset + weightsByteLen;
        const mByteLen = trainableParams * 4;
        const vOffset = mOffset + mByteLen;
        const vByteLen = trainableParams * 4;

        if (fileBuffer.length >= vOffset + vByteLen) {
          const mSlice = fileBuffer.subarray(mOffset, mOffset + mByteLen);
          const alignedM = new ArrayBuffer(mByteLen);
          new Uint8Array(alignedM).set(mSlice);
          m = new Float32Array(alignedM, 0, trainableParams);

          const vSlice = fileBuffer.subarray(vOffset, vOffset + vByteLen);
          const alignedV = new ArrayBuffer(vByteLen);
          new Uint8Array(alignedV).set(vSlice);
          v = new Float32Array(alignedV, 0, trainableParams);
        }
      }

      return {
        checkpoint,
        m,
        v,
        trainingState,
      };
    }

    // Fallback: Legacy JSON format
    const content = fileBuffer.toString('utf-8');
    const parsed: any = JSON.parse(content);
    return {
      checkpoint: parsed,
      m: null,
      v: null,
      trainingState: parsed.trainingState ?? null,
    };
  }

  /**
   * Validates integrity of a binary checkpoint file on disk.
   */
  public static validateCheckpointFile(filePath: string): {
    valid: boolean;
    step?: number;
    valLoss?: number;
    trainingRunId?: string;
    hasOptimizerState?: boolean;
    mtime?: number;
    reason?: string;
  } {
    try {
      if (!fs.existsSync(filePath)) return { valid: false, reason: 'File does not exist' };
      const stat = fs.statSync(filePath);
      if (stat.size < 20) return { valid: false, reason: 'File too small (< 20 bytes)' };

      const fd = fs.openSync(filePath, 'r');
      const headerBytes = Buffer.alloc(20);
      fs.readSync(fd, headerBytes, 0, 20, 0);

      const magic = headerBytes.subarray(0, 16).toString('utf-8').replace(/\0/g, '');
      if (magic !== this.BINARY_MAGIC) {
        fs.closeSync(fd);
        return { valid: false, reason: `Invalid magic header: ${magic}` };
      }

      const headerLen = headerBytes.readUInt32LE(16);
      if (headerLen <= 0 || headerLen > 10 * 1024 * 1024) {
        fs.closeSync(fd);
        return { valid: false, reason: `Unreasonable header length: ${headerLen}` };
      }

      const jsonBuf = Buffer.alloc(headerLen);
      fs.readSync(fd, jsonBuf, 0, headerLen, 20);
      fs.closeSync(fd);

      const meta = JSON.parse(jsonBuf.toString('utf-8'));
      const totalParams = meta.totalParameters || 4894208;
      const weightsBytes = totalParams * 4;
      let expectedMinBytes = 20 + headerLen + weightsBytes;

      if (meta.trainingState?.hasOptimizerState) {
        const trainableParams = meta.trainingState.totalTrainableParams || 4804608;
        expectedMinBytes += trainableParams * 4 * 2;
      }

      if (stat.size < expectedMinBytes) {
        return { valid: false, reason: `Truncated file: size ${stat.size} < expected ${expectedMinBytes}` };
      }

      return {
        valid: true,
        step: meta.trainingState?.step,
        valLoss: meta.evaluationScore ? (1.0 / meta.evaluationScore) : undefined,
        trainingRunId: meta.trainingRunId,
        hasOptimizerState: !!meta.trainingState?.hasOptimizerState,
        mtime: stat.mtimeMs,
      };
    } catch (err: any) {
      return { valid: false, reason: err.message };
    }
  }

  /**
   * Scans an array of candidate checkpoint paths and selects the newest valid checkpoint.
   */
  public static findLatestValidCheckpoint(candidatePaths: string[]): {
    filePath: string | null;
    validation: ReturnType<typeof CheckpointManager.validateCheckpointFile> | null;
  } {
    let bestPath: string | null = null;
    let bestValidation: any = null;

    for (const p of candidatePaths) {
      const fullPath = path.resolve(p);
      const val = this.validateCheckpointFile(fullPath);
      if (val.valid) {
        if (!bestValidation || (val.step ?? 0) > (bestValidation.step ?? 0)) {
          bestPath = fullPath;
          bestValidation = val;
        } else if ((val.step ?? 0) === (bestValidation.step ?? 0) && (val.mtime ?? 0) > (bestValidation.mtime ?? 0)) {
          bestPath = fullPath;
          bestValidation = val;
        }
      }
    }

    return { filePath: bestPath, validation: bestValidation };
  }
}
