/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-009 — CEA (Code Execution Agent)
 * src/cubio/agents/cea/outputSanitizer.ts
 *
 * Sanitizes output streams by redacting secrets, access tokens, API keys,
 * and enforcing strict byte boundaries.
 */

export interface SanitizationResult {
  readonly sanitizedText: string;
  readonly wasTruncated: boolean;
  readonly secretsRedactedCount: number;
}

export class OutputSanitizer {
  // Regex patterns targeting credentials, private keys, authorization tokens, env dumps
  private static readonly SECRET_PATTERNS: readonly RegExp[] = [
    /(?:api[_-]?key|apikey|secret|token|password|auth|bearer)[\s:="']+(?:is[\s:="']+)?([A-Za-z0-9_\-\.]{12,})/gi,
    /sk-[A-Za-z0-9_\-\.]{20,}/g, // OpenAI-style keys
    /-----BEGIN (?:RSA |EC )?PRIVATE KEY-----[\s\S]*?-----END (?:RSA |EC )?PRIVATE KEY-----/gi,
    /ghp_[A-Za-z0-9]{36}/g, // GitHub personal access token
    /glpat-[A-Za-z0-9_\-]{20,}/g, // GitLab personal access token
    /ey[A-Za-z0-9_-]{10,}\.ey[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g, // JWT tokens
  ];

  /**
   * Sanitizes text, redacts sensitive secrets, and enforces maximum byte length.
   */
  public static sanitize(text: string, maxBytes: number): SanitizationResult {
    if (!text) {
      return { sanitizedText: '', wasTruncated: false, secretsRedactedCount: 0 };
    }

    let secretsCount = 0;
    let processed = text;

    for (const pattern of this.SECRET_PATTERNS) {
      pattern.lastIndex = 0;
      processed = processed.replace(pattern, (match, captureGroup) => {
        secretsCount++;
        if (captureGroup && match.includes(captureGroup)) {
          return match.replace(captureGroup, '[REDACTED_SECRET]');
        }
        return '[REDACTED_SECRET]';
      });
    }

    let wasTruncated = false;
    const buf = Buffer.from(processed, 'utf8');
    if (buf.length > maxBytes) {
      wasTruncated = true;
      // Slice cleanly at maxBytes and convert back to valid string
      processed = buf.subarray(0, maxBytes).toString('utf8') + '\n... [OUTPUT_TRUNCATED]';
    }

    return {
      sanitizedText: processed,
      wasTruncated,
      secretsRedactedCount: secretsCount,
    };
  }
}
