import {
  AOAAgentCapabilityDescriptor,
  AOAAgentStatus,
} from './types';

export interface AgentInvoker {
  invoke(payload: Record<string, unknown>, timeoutMs?: number): Promise<unknown>;
}

export interface RegisteredAgentEntry {
  readonly descriptor: AOAAgentCapabilityDescriptor;
  readonly invoker?: AgentInvoker;
}

