  public registerAgent(entry: RegisteredAgentEntry): void {
    this.registry.set(entry.descriptor.agentId, entry);
  }

  public bindInvoker(agentId: string, invoker: AgentInvoker): boolean {
    const existing = this.registry.get(agentId);
    if (!existing) return false;
    this.registry.set(agentId, {
      descriptor: existing.descriptor,
      invoker,
    });
    return true;
  }

  public getAgent(agentId: string): RegisteredAgentEntry | undefined {
    return this.registry.get(agentId);
  }

  public isAgentCallable(agentId: string): boolean {
    const entry = this.registry.get(agentId);
    if (!entry) return false;
    return entry.descriptor.status === 'IMPLEMENTED_CALLABLE' && typeof entry.invoker?.invoke === 'function';
  }

  public listAgents(): readonly AOAAgentCapabilityDescriptor[] {
    return Array.from(this.registry.values()).map((e) => e.descriptor);
  }

  public listCallableAgents(): readonly AOAAgentCapabilityDescriptor[] {
    return Array.from(this.registry.values())
      .map((e) => e.descriptor)
      .filter((d) => d.status === 'IMPLEMENTED_CALLABLE');
  }
