/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-020 — RDA (Release & Deployment Agent)
 * src/cubio/agents/rda/secretScanner.ts
 *
 * Scans release configurations, environment artifacts, and code strings for
 * potential secrets, private keys, API tokens, and credentials.
 * Implements strict redaction and fail-closed reporting.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import { RDACheckResult, RDASeverity } from './types';

export interface SecretScanFinding {
  readonly patternName: string;
  readonly severity: RDASeverity;
  readonly snippetRedacted: string;
  readonly location: string;
}

export class SecretScanner {
  // Regexes for common high-risk tokens / private keys
  private static readonly SECRET_PATTERNS: Array<{ name: string; pattern: RegExp; severity: RDASeverity }> = [
    { name: 'RSA_PRIVATE_KEY', pattern: /-----BEGIN (RSA )?PRIVATE KEY-----/, severity: 'CRITICAL' },
    { name: 'GENERIC_API_KEY', pattern: /(?:api_key|apikey|secret_key|private_key)\s*[:=]\s*['"][0-9a-zA-Z_\-]{16,}['"]/i, severity: 'CRITICAL' },
    { name: 'AWS_ACCESS_KEY', pattern: /AKIA[0-9A-Z]{16}/, severity: 'CRITICAL' },
    { name: 'GITHUB_TOKEN', pattern: /gh[pousr]_[0-9a-zA-Z]{36}/, severity: 'CRITICAL' },
    { name: 'PASSWORD_FIELD', pattern: /(?:password|passwd|pwd)\s*[:=]\s*['"][^'"]{6,}['"]/i, severity: 'WARNING' },
  ];

  /**
   * Scans a dictionary of environment variables or text content.
   */
  public scanText(content: string, location: string): SecretScanFinding[] {
    const findings: SecretScanFinding[] = [];
    if (!content) return findings;

    for (const rule of SecretScanner.SECRET_PATTERNS) {
      if (rule.pattern.test(content)) {
        findings.push({
          patternName: rule.name,
          severity: rule.severity,
          snippetRedacted: `[REDACTED_SECRET_${rule.name}]`,
          location,
        });
      }
    }

    return findings;
  }

  /**
   * Scans an environment object (e.g. process.env or simulated env map).
   */
  public scanEnv(env: Record<string, string | undefined>): SecretScanFinding[] {
    const findings: SecretScanFinding[] = [];
    const sensitiveKeys = ['SECRET', 'PASSWORD', 'PRIVATE_KEY', 'TOKEN', 'AUTH_KEY'];

    for (const [key, val] of Object.entries(env)) {
      if (!val) continue;
      const upperKey = key.toUpperCase();
      const isSensitiveKey = sensitiveKeys.some(s => upperKey.includes(s));
      
      if (isSensitiveKey) {
        findings.push({
          patternName: `SENSITIVE_ENV_VAR_${key}`,
          severity: 'CRITICAL',
          snippetRedacted: `***REDACTED***`,
          location: `env:${key}`,
        });
      }

      // Also check content
      const contentFindings = this.scanText(val, `env:${key}`);
      findings.push(...contentFindings);
    }

    return findings;
  }

  /**
   * Helper to redact sensitive values from any string before emitting into reports.
   */
  public redactString(str: string): string {
    if (!str) return '';
    let sanitized = str;
    for (const rule of SecretScanner.SECRET_PATTERNS) {
      sanitized = sanitized.replace(rule.pattern, `[REDACTED_${rule.name}]`);
    }
    return sanitized;
  }

  /**
   * Formulates an RDACheckResult from a scan.
   */
  public evaluate(content: string, location: string): RDACheckResult {
    const findings = this.scanText(content, location);
    if (findings.length === 0) {
      return {
        checkId: 'CHK-SEC-01',
        name: 'Secret & Credential Exposure Scan',
        category: 'SECURITY_SECRETS',
        status: 'PASS',
        severity: 'INFO',
        evidence: `Zero secret patterns detected in ${location}.`,
      };
    }

    const hasCritical = findings.some(f => f.severity === 'CRITICAL');
    return {
      checkId: 'CHK-SEC-01',
      name: 'Secret & Credential Exposure Scan',
      category: 'SECURITY_SECRETS',
      status: 'FAIL',
      severity: hasCritical ? 'CRITICAL' : 'WARNING',
      evidence: `Found ${findings.length} secret exposure risk(s) in ${location}: ${findings.map(f => f.patternName).join(', ')}`,
      details: { findings },
    };
  }
}
