/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-013 — CDA (Coding Agent)
 * src/cubio/agents/cda/types.ts
 *
 * Authoritative contracts for coding requests, code analysis, bug diagnosis,
 * patch proposals, code synthesis, verification requests, and bounds.
 */

export type CDATaskType =
  | 'CODE_GENERATION'
  | 'BUG_DIAGNOSIS'
  | 'PATCH_PROPOSAL'
  | 'CODE_EXPLANATION'
  | 'CODE_REFACTOR'
  | 'TEST_GENERATION'
  | 'REPOSITORY_ANALYSIS';

export type CDARequestStatus =
  | 'SUCCEEDED'
  | 'PARTIAL'
  | 'INSUFFICIENT_CONTEXT'
  | 'BLOCKED'
  | 'FAILED'
  | 'TIMED_OUT'
  | 'CANCELLED';

export type CDAPatchStatus =
  | 'PROPOSED'
  | 'INVALID'
  | 'BLOCKED'
  | 'NEEDS_REVIEW'
  | 'REJECTED';

export type CDAPatchOperation = 'CREATE' | 'MODIFY' | 'REPLACE';

export interface CDABoundsConfig {
  readonly maxCodeInputLength: number; // default: 50,000 chars
  readonly maxPromptLength: number; // default: 4,000 chars
  readonly maxOutputBytes: number; // default: 131,072 bytes (128 KB)
  readonly maxExecutionMs: number; // default: 10,000 ms
  readonly maxPatchesPerProposal: number; // default: 5
}

export const DEFAULT_CDA_BOUNDS: CDABoundsConfig = Object.freeze({
  maxCodeInputLength: 50_000,
  maxPromptLength: 4_000,
  maxOutputBytes: 131_072,
  maxExecutionMs: 10_000,
  maxPatchesPerProposal: 5,
});

export interface CDACodingRequest {
  readonly requestId: string;
  readonly taskId: string;
  readonly taskType: CDATaskType;
  readonly prompt: string;
  readonly language?: string;
  readonly framework?: string;
  readonly targetFilePath?: string;
  readonly codeSnippet?: string;
  readonly errorTrace?: string;
  readonly existingFiles?: Readonly<Record<string, string>>;
  readonly affectedSubsystems?: readonly string[];
  readonly contextTurns?: readonly { role: string; content: string }[];
  readonly bounds?: Partial<CDABoundsConfig>;
  readonly bypassActuationLock?: boolean; // Attacker test payload - must be rejected
}

export interface CDABugFinding {
  readonly findingId: string;
  readonly errorType: string;
  readonly rootCause: string;
  readonly offendingFile?: string;
  readonly offendingLine?: number;
  readonly evidenceSummary: string;
  readonly confidence: number; // 0.0 to 1.0
  readonly suggestedFixStrategy: string;
}

export interface CDAPatchProposal {
  readonly proposalId: string;
  readonly taskId: string;
  readonly targetFilePath: string;
  readonly operation: CDAPatchOperation;
  readonly patchStatus: CDAPatchStatus;
  readonly rationale: string;
  readonly originalContentExcerpt?: string;
  readonly proposedContent: string;
  readonly diffSummary: string;
  readonly linesModified: readonly number[];
  readonly targetPathChecksum?: string;
  readonly proposalChecksum: string;
  readonly potentialRegressionRisks: readonly string[];
  readonly suggestedVerificationCommands: readonly string[];
}

export interface CDACodingReport {
  readonly reportId: string;
  readonly requestId: string;
  readonly taskId: string;
  readonly taskType: CDATaskType;
  readonly status: CDARequestStatus;
  readonly language: string;
  readonly generatedCode?: string;
  readonly explanation?: string;
  readonly findings: readonly CDABugFinding[];
  readonly patchProposals: readonly CDAPatchProposal[];
  readonly suggestedTests?: string;
  readonly dependencies: readonly string[];
  readonly regressionRisks: readonly string[];
  readonly provenanceSource: string; // which existing engine generated output
  readonly reportChecksum: string;
  readonly durationMs: number;
  readonly errors: readonly string[];
}
