import { IS_ACTUATION_BLOCKED } from '../../../funnel02/constants';
import { CEARequest } from './types';

export interface PolicyCheckResult {
  readonly isAllowed: boolean;
  readonly reason?: string;
}

export class ExecutionPolicy {
  public static readonly CANONICAL_POLICY_VERSION = '1.0.0-CANONICAL';

  /**
   * Evaluates if request complies with sovereign execution policy and actuation locks.
   */
  public static evaluatePolicy(request: CEARequest): PolicyCheckResult {
    // 1. Mandatory Sovereign Actuation Lock (Funnel 02 invariant)
    if (!IS_ACTUATION_BLOCKED) {
      return {
        isAllowed: false,
        reason: 'CRITICAL_SAFETY_VIOLATION: Global IS_ACTUATION_BLOCKED constant is not true',
      };
    }

    // 2. Caller policy checks
    if (!request.requestedBy) {
      return { isAllowed: false, reason: 'Caller identity is missing' };
    }

    // 3. Operation class evaluation
    // Permitted: Development/test execution within workspace
    // Prohibited: System administration, deployment, direct disk writes to root
    const allowedOps = ['TEST_EXECUTION', 'TYPE_CHECK', 'LINT_CHECK', 'STATIC_ANALYSIS', 'INSPECTION'];
    if (!allowedOps.includes(request.operationType)) {
      return {
        isAllowed: false,
        reason: `Operation class '${request.operationType}' is not permitted by execution policy`,
      };
    }

    return { isAllowed: true };
  }
}
