/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-020 — RDA (Release & Deployment Agent)
 * src/cubio/agents/rda/aoaAdapter.ts
 *
 * AOA Dispatcher integration adapter for AGENT-020-RDA.
 * Connects standard AOA orchestration payload to ReleaseDeploymentAgent.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import { AgentInvoker } from '../aoa/agentRegistryAdapter';
import { ReleaseDeploymentAgent } from './releaseDeploymentAgent';
import { RDARequest, RDAReport } from './types';

export class RDAAOAAdapter implements AgentInvoker {
  private readonly agent: ReleaseDeploymentAgent;

  constructor(agent?: ReleaseDeploymentAgent) {
    this.agent = agent || new ReleaseDeploymentAgent();
  }

  public async invoke(payload: Record<string, unknown>, timeoutMs?: number): Promise<RDAReport> {
    const request: RDARequest = {
      taskId: (payload.taskId as string) || `AOA-RDA-${Date.now()}`,
      taskType: (payload.taskType as any) || 'RELEASE_READINESS_AUDIT',
      targetVersion: payload.targetVersion as string | undefined,
      isDryRun: payload.isDryRun !== false,
      context: payload.context as any,
    };

    if (timeoutMs && timeoutMs > 0) {
      return Promise.race([
        this.agent.execute(request),
        new Promise<RDAReport>((_, reject) =>
          setTimeout(() => reject(new Error(`AOA invocation timed out after ${timeoutMs}ms`)), timeoutMs)
        ),
      ]);
    }

    return this.agent.execute(request);
  }
}
