/**
 * CUBiO AI — 3D Memory Studio
 * Agent Skills Framework
 * src/cubio/skills/types.ts
 *
 * Canonical types and contracts for Agent Skills discovery, validation,
 * loading, execution, permission constraints, and provenance tracking.
 */

/**
 * Universal constraint for actuation safety:
 * Skills are prohibited from physical actuation or bypass of the core safety lock.
 */
export const SKILL_ACTUATION_BLOCKED = true;

/**
 * Canonical safety constraint flags for skill execution.
 */
export interface SkillSafetyConstraints {
  /** Whether the skill attempts filesystem mutations (strictly audited/scoped) */
  readonly allowFilesystemWrite: boolean;
  /** Whether network access is permitted (default false) */
  readonly allowNetworkAccess: boolean;
  /** Whether shell/process execution is permitted (default false) */
  readonly allowProcessSpawn: boolean;
  /**
   * Hardware or physical actuation is strictly prohibited.
   * If true, the skill will fail verification automatically.
   */
  readonly requiresActuation?: boolean;
  /** Maximum execution time budget in milliseconds */
  readonly maxTimeoutMs: number;
}

/**
 * Canonical Manifest defining a registered Skill.
 */
export interface SkillManifest {
  /** Unique canonical skill identifier (e.g., 'SKILL-369-LATTICE-CALC', 'SKILL-CODE-AST-REFACTOR') */
  readonly skillId: string;
  /** Human-readable skill name */
  readonly name: string;
  /** Semantic description of the skill's purpose */
  readonly purpose: string;
  /** Semantic version string (e.g., '1.0.0') */
  readonly version: string;
  /** Capability tags for discovery (e.g., ['SPATIAL_MATH', 'COORDINATE_TRANSFORM']) */
  readonly capabilities: readonly string[];
  /** Expected input parameters JSON schema reference or structural definition */
  readonly inputSchema: Record<string, unknown>;
  /** Expected output structure JSON schema reference or structural definition */
  readonly outputSchema: Record<string, unknown>;
  /** Array of permitted Agent IDs authorized to invoke or load this skill. Use ['*'] for universal */
  readonly permittedAgents: readonly string[];
  /** Explicit safety constraints bound to this skill */
  readonly safetyConstraints: SkillSafetyConstraints;
  /** Natural language or structured prompt instructions describing how to perform the skill */
  readonly instructions: string;
  /** Optional metadata tags */
  readonly tags?: readonly string[];
}

/**
 * Skill Handler interface for executable skill logic.
 * Enforces clear separation between declarative instructions and executable tools.
 */
export interface SkillHandler<TInput = Record<string, unknown>, TOutput = unknown> {
  execute(
    input: TInput,
    context: SkillExecutionContext
  ): Promise<SkillExecutionResult<TOutput>>;
}

/**
 * Context passed into a skill handler during execution.
 */
export interface SkillExecutionContext {
  readonly skillId: string;
  readonly invokingAgentId: string;
  readonly callerPermissions: readonly string[];
  readonly executionId: string;
  readonly timeoutMs: number;
  readonly timestamp: number;
}

/**
 * Result returned from a skill invocation.
 */
export interface SkillExecutionResult<TData = unknown> {
  readonly success: boolean;
  readonly data?: TData;
  readonly error?: string;
  readonly executionLatencyMs: number;
  readonly provenance: SkillInvocationEvidence;
}

/**
 * Tamper-evident invocation evidence record.
 */
export interface SkillInvocationEvidence {
  readonly executionId: string;
  readonly skillId: string;
  readonly skillVersion: string;
  readonly invokingAgentId: string;
  readonly inputHashSha256: string;
  readonly outputHashSha256?: string;
  readonly executedAt: string;
  readonly status: 'SUCCESS' | 'FAILED' | 'REJECTED';
}

/**
 * Result of loading a skill for an agent.
 * Note: Loading a skill returns the validated instructions, constraints, and optionally
 * an executable handler. Loading alone DOES NOT claim task completion.
 */
export interface LoadedSkill {
  readonly manifest: SkillManifest;
  readonly isPermitted: boolean;
  readonly handlerAvailable: boolean;
  /** Execution handler if provided in the registry */
  readonly handler?: SkillHandler;
  readonly loadedAt: string;
}

/**
 * Error codes emitted by the skills framework.
 */
export type SkillErrorCode =
  | 'SKILL_NOT_FOUND'
  | 'SKILL_DISALLOWED_FOR_AGENT'
  | 'SKILL_ACTUATION_PROHIBITED'
  | 'MALFORMED_MANIFEST'
  | 'INVALID_INPUT'
  | 'EXECUTION_TIMEOUT'
  | 'EXECUTION_FAILED'
  | 'UNAUTHORIZED_CALLER';

export class SkillError extends Error {
  constructor(
    public readonly code: SkillErrorCode,
    message: string,
    public readonly details?: unknown
  ) {
    super(`[${code}] ${message}`);
    this.name = 'SkillError';
  }
}
