/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-020 — RDA (Release & Deployment Agent)
 * src/cubio/agents/rda/types.ts
 *
 * Authoritative contracts, types, bounds, checks, and release report schemas
 * for the Release & Deployment Agent (RDA).
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

export const RDA_AGENT_ID = 'AGENT-020-RDA' as const;
export const RDA_AGENT_NAME = 'Release & Deployment Agent' as const;
export const RDA_VERSION = '1.0.0' as const;

export type RDATaskType =
  | 'RELEASE_READINESS_AUDIT'
  | 'DRY_RUN_PREPARATION'
  | 'VALIDATE_DEPENDENCIES'
  | 'SCAN_SECRETS_SECURITY'
  | 'GENERATE_RELEASE_MANIFEST'
  | 'VALIDATE_ARTIFACT_INTEGRITY'
  | 'FULL_RELEASE_EVALUATION';

export type RDACheckStatus = 'PASS' | 'FAIL' | 'BLOCKED' | 'NOT_VERIFIED' | 'SKIPPED';

export type RDAReleaseOutcome = 'READY' | 'BLOCKED' | 'FAILED' | 'NOT_VERIFIED';

export type RDASeverity = 'INFO' | 'WARNING' | 'CRITICAL';

export interface RDABoundsConfig {
  readonly maxArtifacts: number;
  readonly maxFindings: number;
  readonly maxDurationMs: number;
  readonly maxFileSizeBytes: number;
}

export const DEFAULT_RDA_BOUNDS: RDABoundsConfig = {
  maxArtifacts: 50,
  maxFindings: 100,
  maxDurationMs: 30000,
  maxFileSizeBytes: 10 * 1024 * 1024, // 10MB
};

export interface RDACheckResult {
  readonly checkId: string;
  readonly name: string;
  readonly category: 'VERSION_CONFIG' | 'DEPENDENCY' | 'TEST_QUALITY' | 'SECURITY_SECRETS' | 'ARTIFACT_INTEGRITY' | 'PROTECTED_INVARIANTS';
  readonly status: RDACheckStatus;
  readonly severity: RDASeverity;
  readonly evidence: string;
  readonly details?: Record<string, unknown>;
}

export interface RDAReleaseManifest {
  readonly releaseId: string;
  readonly version: string;
  readonly commitHash: string;
  readonly timestamp: string;
  readonly isActuationBlocked: boolean;
  readonly isDryRun: boolean;
  readonly targetEnvironment: string;
  readonly artifacts: Array<{
    readonly path: string;
    readonly sha256: string;
    readonly sizeBytes: number;
  }>;
  readonly signature: string;
}

export interface RDARequest {
  readonly taskId: string;
  readonly taskType: RDATaskType;
  readonly targetVersion?: string;
  readonly isDryRun?: boolean;
  readonly customBounds?: Partial<RDABoundsConfig>;
  readonly context?: {
    readonly callerAgentId?: string;
    readonly targetEnvironment?: string;
    readonly customArtifactPaths?: string[];
    readonly requestedBy?: string;
    readonly testResultsSummary?: {
      readonly total: number;
      readonly passed: number;
      readonly failed: number;
      readonly suites: string[];
    };
  };
}

export interface RDAReport {
  readonly reportId: string;
  readonly taskId: string;
  readonly agentId: typeof RDA_AGENT_ID;
  readonly version: typeof RDA_VERSION;
  readonly outcome: RDAReleaseOutcome;
  readonly isActuationBlocked: true;
  readonly isDryRun: boolean;
  readonly evaluatedTimestamp: string;
  readonly totalChecks: number;
  readonly passedChecks: number;
  readonly failedChecks: number;
  readonly blockedChecks: number;
  readonly checks: readonly RDACheckResult[];
  readonly manifest?: RDAReleaseManifest;
  readonly remediationPlan: readonly string[];
  readonly limitations: readonly string[];
  readonly signature: string;
}
