/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-016 — SAA (System Architecture Agent)
 * src/cubio/agents/saa/architectureReportBuilder.ts
 *
 * Compiles final structured architecture reports, generates text-based Mermaid
 * architecture diagrams, and computes tamper-evident SHA-256 signatures.
 */

import * as crypto from 'crypto';
import {
  SAAReport,
  SAATaskRequest,
  SAAComponentRecord,
  SAARelationshipRecord,
  SAAContractValidationRecord,
  SAAFindingRecord,
  SAARecommendationRecord,
  SAAReportStatus,
} from './types';

export class ArchitectureReportBuilder {
  public static buildReport(params: {
    request: SAATaskRequest;
    status: SAAReportStatus;
    summary: string;
    components: readonly SAAComponentRecord[];
    relationships: readonly SAARelationshipRecord[];
    validations: readonly SAAContractValidationRecord[];
    findings: readonly SAAFindingRecord[];
    recommendations: readonly SAARecommendationRecord[];
    durationMs: number;
    generateDiagram?: boolean;
  }): SAAReport {
    const reportId = `REP_SAA_${crypto.randomBytes(6).toString('hex')}`;
    const requestId = params.request.requestId || `REQ_SAA_${Date.now()}`;
    const taskId = params.request.taskId || `TASK_SAA_${Date.now()}`;

    // Optional Mermaid architecture diagram generation
    let mermaidDiagram: string | undefined;
    if (params.generateDiagram) {
      mermaidDiagram = this.generateMermaid(params.components, params.relationships);
    }

    // Compute tamper-evident 64-character SHA-256 report checksum
    const hashPayload = JSON.stringify({
      reportId,
      requestId,
      taskId,
      status: params.status,
      componentsCount: params.components.length,
      relationshipsCount: params.relationships.length,
      validationsCount: params.validations.length,
      findingsCount: params.findings.length,
      recommendationsCount: params.recommendations.length,
      components: params.components.map((c) => c.componentId).sort(),
      findings: params.findings.map((f) => f.findingId).sort(),
    });
    const reportChecksum = crypto.createHash('sha256').update(hashPayload).digest('hex');

    return Object.freeze({
      reportId,
      requestId,
      taskId,
      status: params.status,
      summary: params.summary,
      componentInventory: params.components,
      relationships: params.relationships,
      contractValidations: params.validations,
      findings: params.findings,
      recommendations: params.recommendations,
      mermaidDiagram,
      executionDurationMs: params.durationMs,
      generatedAt: new Date().toISOString(),
      reportChecksum,
      is_actuation_blocked: true as const,
    });
  }

  private static generateMermaid(
    components: readonly SAAComponentRecord[],
    relationships: readonly SAARelationshipRecord[]
  ): string {
    const lines: string[] = ['flowchart TD'];

    // Add nodes (sanitize ID for Mermaid)
    for (const comp of components.slice(0, 30)) {
      const safeId = comp.name.replace(/[^A-Za-z0-9_]/g, '_');
      const label = comp.declaredSubsystem ? `${comp.name} [${comp.declaredSubsystem}]` : comp.name;
      lines.push(`  ${safeId}["${label}"]`);
    }

    // Add edges
    for (const rel of relationships.slice(0, 50)) {
      const fromSafe = pathBasename(rel.fromComponentId).replace(/[^A-Za-z0-9_]/g, '_');
      const toSafe = pathBasename(rel.toComponentId).replace(/[^A-Za-z0-9_]/g, '_');
      if (fromSafe && toSafe && fromSafe !== toSafe) {
        lines.push(`  ${fromSafe} --> ${toSafe}`);
      }
    }

    return lines.join('\n');
  }
}

function pathBasename(p: string): string {
  const parts = p.replace(/\\/g, '/').split('/');
  return parts[parts.length - 1] || p;
}
