/**
 * CUBiO AI � 3D Memory Studio
 * AGENT-008 � AOA (Agent Orchestration Agent)
 * src/cubio/agents/aoa/resultAggregator.ts
 *
 * Collects subtask outputs and produces structured, provenance-sealed reports.
 * Distinguishes successful results, failed tasks, blocked descendants,
 * missing evidence, and unverified claims.
 */

import * as crypto from 'crypto';
import {
  AOAOrchestrationRequest,
  AOASubtaskExecutionRecord,
  AOAOrchestrationResult,
} from './types';

export class ResultAggregator {
  /**
   * Aggregates execution records into an authoritative AOAOrchestrationResult.
   */
  public static aggregate(
    request: AOAOrchestrationRequest,
    records: readonly AOASubtaskExecutionRecord[],
    startTimestamp: number,
    completionTimestamp: number
  ): AOAOrchestrationResult {
    const successfulTasks: string[] = [];
    const failedTasks: string[] = [];
    const blockedTasks: string[] = [];
    const missingEvidenceTasks: string[] = [];
    const conflictingOutputs: string[] = [];
    const unverifiedClaims: string[] = [];

    for (const r of records) {
      if (r.state === 'SUCCEEDED') {
        successfulTasks.push(r.subtaskId);
        if (!r.evidenceHash) {
          missingEvidenceTasks.push(r.subtaskId);
        }
      } else if (r.state === 'BLOCKED') {
        blockedTasks.push(r.subtaskId);
      } else {
        failedTasks.push(r.subtaskId);
      }
    }

    let overallState: 'SUCCEEDED' | 'FAILED' | 'PARTIAL' | 'REJECTED' | 'TIMED_OUT' = 'SUCCEEDED';
    if (records.length > 0 && records.every((r) => r.state === 'REJECTED')) {
      overallState = 'REJECTED';
    } else if (failedTasks.length > 0 || blockedTasks.length > 0) {
      if (successfulTasks.length > 0) {
        overallState = 'PARTIAL';
      } else {
        overallState = 'FAILED';
      }
    }

    // Check for any timeout specifically
    if (records.some((r) => r.state === 'TIMED_OUT')) {
      if (successfulTasks.length === 0) {
        overallState = 'TIMED_OUT';
      } else {
        overallState = 'PARTIAL';
      }
    }

    // Compute master cryptographic provenance hash
    const rawBundle = JSON.stringify({
      orchestrationId: request.orchestrationId,
      objective: request.objective,
      records: records.map((r) => ({
        id: r.subtaskId,
        state: r.state,
        hash: r.evidenceHash || 'NO_EVIDENCE',
      })),
      totalDurationMs: completionTimestamp - startTimestamp,
    });

    const masterProvenanceHash = crypto
      .createHash('sha256')
      .update(rawBundle)
      .digest('hex');

    return Object.freeze({
      orchestrationId: request.orchestrationId,
      objective: request.objective,
      overallState,
      subtaskRecords: Object.freeze([...records]),
      successfulTasks: Object.freeze(successfulTasks),
      failedTasks: Object.freeze(failedTasks),
      blockedTasks: Object.freeze(blockedTasks),
      missingEvidenceTasks: Object.freeze(missingEvidenceTasks),
      conflictingOutputs: Object.freeze(conflictingOutputs),
      unverifiedClaims: Object.freeze(unverifiedClaims),
      startTimestamp,
      completionTimestamp,
      totalDurationMs: Math.max(1, completionTimestamp - startTimestamp),
      masterProvenanceHash,
      isActuationBlocked: true,
    });
  }

  /**
   * Formats aggregated results into clear GitHub markdown.
   */
  public static formatMarkdown(result: AOAOrchestrationResult): string {
    const lines: string[] = [
      `# AOA Multi-Agent Orchestration Report: \`${result.orchestrationId}\``,
      `**Objective**: ${result.objective}  `,
      `**Overall State**: \`${result.overallState}\`  `,
      `**Total Duration**: ${result.totalDurationMs}ms  `,
      `**Master Provenance SHA-256**: \`${result.masterProvenanceHash}\`  `,
      `**Actuation Lock**: \`${result.isActuationBlocked}\`  `,
      '',
      '## Subtask Execution Matrix',
      '| Subtask ID | Target Agent | Final State | Attempts | Duration | Evidence Hash |',
      '|---|---|---|:---:|:---:|---|',
    ];

    for (const r of result.subtaskRecords) {
      const hashSnippet = r.evidenceHash ? `\`${r.evidenceHash.slice(0, 16)}...\`` : '_None_';
      lines.push(
        `| \`${r.subtaskId}\` | \`${r.agentId}\` | **${r.state}** | ${r.attemptCount} | ${r.durationMs || 0}ms | ${hashSnippet} |`
      );
    }

    lines.push('');
    return lines.join('\n');
  }
}
