/**
 * CUBiO Data Integrity Analyzer
 * Audits record schema conformance, serialization round-trips, and referential integrity.
 */

import { DSADataIntegrityReport } from './types';

export class DataIntegrityAnalyzer {
  public validateRecords(targetName: string, records: any[]): DSADataIntegrityReport {
    const missingRequiredFields: string[] = [];
    const duplicateKeyCandidates: string[] = [];
    const seenIds = new Set<string>();

    let roundTripValid = true;

    for (const record of records) {
      if (!record || typeof record !== 'object') {
        missingRequiredFields.push('root object missing');
        continue;
      }

      // 1. Required StudioRecord fields: id, type, classification, dimension, status
      if (!record.id) missingRequiredFields.push('id');
      if (!record.type) missingRequiredFields.push('type');
      if (!record.classification) missingRequiredFields.push('classification');
      if (record.dimension === undefined) missingRequiredFields.push('dimension');
      if (!record.status) missingRequiredFields.push('status');

      // 2. Duplicate ID detection
      if (record.id) {
        if (seenIds.has(record.id)) {
          duplicateKeyCandidates.push(record.id);
        } else {
          seenIds.add(record.id);
        }
      }

      // 3. Serialization round-trip check
      try {
        const serialized = JSON.stringify(record);
        const deserialized = JSON.parse(serialized);
        if (deserialized.id !== record.id) {
          roundTripValid = false;
        }
      } catch {
        roundTripValid = false;
      }
    }

    const schemaCompliant = missingRequiredFields.length === 0 && duplicateKeyCandidates.length === 0;

    return {
      target: targetName,
      totalRecordsChecked: records.length,
      schemaCompliant,
      missingRequiredFields: Array.from(new Set(missingRequiredFields)),
      serializationRoundTripValid: roundTripValid,
      duplicateKeyCandidates,
      summary: schemaCompliant
        ? `All ${records.length} records verified schema-compliant and round-trip stable.`
        : `Integrity discrepancies detected: ${missingRequiredFields.length} missing fields, ${duplicateKeyCandidates.length} duplicates.`,
    };
  }
}
