/**
 * CUBiO AI — 3D Memory Studio
 * src/cubio/workspace/workspaceSecurityGuard.ts
 *
 * Sovereign Workspace Security, Path Containment & Write Authorization Guard.
 * Enforces:
 * 1. Root containment & path traversal protection.
 * 2. Symlink and NTFS directory junction escape prevention.
 * 3. Immutable protected authority shielding (database, address369, sealed checkpoints).
 * 4. Permanent Hardware Actuation Lockout (IS_ACTUATION_BLOCKED = true).
 * 5. Explicit user approval tokens for workspace file modifications.
 * 6. Atomic write execution with post-write disk readback verification.
 */

import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import { SecretRedactor } from '../security/secretRedactor.js';
import {
  ContainmentViolationType,
  ControlledWriteRequest,
  PathValidationResult,
  WorkspaceWritePolicy,
  WorkspaceWriteResult,
} from './types.js';

export const PROTECTED_REPOSITORY_FILES = Object.freeze([
  'data/cubio_studio.db',
  'src/core/address369.ts',
  'data/checkpoints/phase16_production_final_sealed_1m.3dmemory',
  'phase8_baseline_manifest.json',
]);

const SYSTEM_DIRECTORIES = Object.freeze([
  'windows',
  'system32',
  'syswow64',
  'program files',
  'etc',
  'usr',
  'bin',
  'sbin',
  'dev',
  'proc',
  'sys',
]);

interface ApprovalTokenRecord {
  readonly token: string;
  readonly proposalId?: string;
  readonly workspaceId: string;
  readonly taskId: string;
  readonly relativePath: string;
  readonly contentSha256: string;
  readonly issuedAt: number;
  readonly expiresAt: number;
  confirmed: boolean;
  used: boolean;
  operatorId?: string;
}

export class WorkspaceSecurityGuard {
  public static readonly IS_ACTUATION_BLOCKED = true;
  public static readonly LEGACY_STATIC_SALT = 'CUBIO_SOVEREIGN_SECURITY_TOKEN_SALT_2026';

  private static instance: WorkspaceSecurityGuard | null = null;
  private readonly hmacSecret: Buffer = crypto.randomBytes(32);
  private readonly issuedTokens = new Map<string, ApprovalTokenRecord>();

  // Server-side Human Operator Authentication Secret
  private humanOperatorSecret: string =
    process.env.CUBIO_HUMAN_OPERATOR_SECRET ||
    process.env.CUBIO_HUMAN_OPERATOR_KEY ||
    crypto.randomBytes(32).toString('hex');

  private constructor() {
    SecretRedactor.registerSensitiveString(this.humanOperatorSecret);
  }

  public static getInstance(): WorkspaceSecurityGuard {
    if (!WorkspaceSecurityGuard.instance) {
      WorkspaceSecurityGuard.instance = new WorkspaceSecurityGuard();
    }
    return WorkspaceSecurityGuard.instance;
  }

  /**
   * Sets an explicit human operator authorization secret.
   * Only authorized human management interfaces may configure this.
   */
  public setHumanOperatorSecret(secret: string): void {
    if (!secret || typeof secret !== 'string' || secret.trim().length < 16) {
      throw new Error('INVALID_OPERATOR_SECRET: Human operator secret must be at least 16 characters.');
    }
    SecretRedactor.unregisterSensitiveString(this.humanOperatorSecret);
    this.humanOperatorSecret = secret.trim();
    SecretRedactor.registerSensitiveString(this.humanOperatorSecret);
  }

  /**
   * Rotates the human operator authorization secret.
   * If a new secret is not provided, securely generates a new cryptographically random 32-byte secret.
   * By default, revokes and invalidates all previously issued active tokens.
   */
  public rotateHumanOperatorSecret(
    newSecret?: string,
    options?: { invalidateExistingTokens?: boolean }
  ): { rotated: boolean; secretFingerprint: string } {
    const oldSecret = this.humanOperatorSecret;
    const finalSecret =
      newSecret && typeof newSecret === 'string' && newSecret.trim().length >= 16
        ? newSecret.trim()
        : crypto.randomBytes(32).toString('hex');

    SecretRedactor.unregisterSensitiveString(oldSecret);
    this.humanOperatorSecret = finalSecret;
    SecretRedactor.registerSensitiveString(finalSecret);

    if (options?.invalidateExistingTokens !== false) {
      this.issuedTokens.clear();
    }

    const fingerprint = crypto.createHash('sha256').update(finalSecret).digest('hex').slice(0, 8).toUpperCase();
    return { rotated: true, secretFingerprint: `FP-${fingerprint}` };
  }

  /**
   * Immediately revokes the active human operator secret and invalidates all issued tokens.
   * Fails closed: no write proposals can be confirmed until a new operator secret is provisioned.
   */
  public revokeHumanOperatorSecret(): { revoked: boolean } {
    SecretRedactor.unregisterSensitiveString(this.humanOperatorSecret);
    this.humanOperatorSecret = crypto.randomBytes(32).toString('hex');
    SecretRedactor.registerSensitiveString(this.humanOperatorSecret);
    this.issuedTokens.clear();
    return { revoked: true };
  }

  /**
   * Returns current human operator authorization secret for verified tests/admin callers.
   */
  public getHumanOperatorSecret(): string {
    return this.humanOperatorSecret;
  }

  /**
   * Server-side authentication of human operators.
   * Prevents autonomous agents from self-approving write proposals.
   * Enforces caller identity separation and timing-safe secret validation.
   */
  public authenticateHumanOperator(
    operatorId: string,
    operatorAuthKey?: string
  ): { authenticated: boolean; reason?: string } {
    if (!operatorId || typeof operatorId !== 'string' || operatorId.trim().length === 0) {
      return { authenticated: false, reason: 'Operator ID must be a non-empty string.' };
    }

    const trimmedId = operatorId.trim();

    // Caller identity separation: Agents cannot pose as human operators
    if (/^(?:AGENT-|CUBIO-|SYSTEM|PMA|AOA|CDA|CEA|TGA|SGA|FUA|DRA|MEA|EIA)/i.test(trimmedId)) {
      return {
        authenticated: false,
        reason: `AGENT_SELF_APPROVAL_DETECTED: Agent principal "${trimmedId}" is forbidden from approving write proposals.`,
      };
    }

    if (!operatorAuthKey || typeof operatorAuthKey !== 'string') {
      return {
        authenticated: false,
        reason: 'MISSING_OPERATOR_CREDENTIALS: Human operator authorization key (operatorAuthKey) is required.',
      };
    }

    // Constant-time secret comparison
    const keyBuf = Buffer.from(operatorAuthKey.trim());
    const secBuf = Buffer.from(this.humanOperatorSecret);
    if (keyBuf.length !== secBuf.length || !crypto.timingSafeEqual(keyBuf, secBuf)) {
      return {
        authenticated: false,
        reason: 'INVALID_OPERATOR_CREDENTIALS: Provided operatorAuthKey does not match authorized server credential.',
      };
    }

    return { authenticated: true };
  }

  /**
   * Validates that targetPath is strictly contained inside workspaceRoot.
   * Intercepts directory traversal, null bytes, root breakouts, symlink escapes,
   * junction breakouts, and protected repository files.
   */
  public validatePathContainment(
    workspaceRoot: string,
    targetPath: string,
    options?: { allowedParentDirs?: readonly string[] }
  ): PathValidationResult {
    // 1. Actuation Lockout Invariant Check
    if (WorkspaceSecurityGuard.IS_ACTUATION_BLOCKED !== true) {
      throw new Error('CRITICAL_SECURITY_VIOLATION: IS_ACTUATION_BLOCKED must be permanently true.');
    }

    if (!targetPath || typeof targetPath !== 'string') {
      return {
        isValid: false,
        violationType: 'PATH_TRAVERSAL_DETECTED',
        reason: 'Target path must be a non-empty string.',
      };
    }

    // 2. Null Byte Injection Check
    if (targetPath.includes('\0') || targetPath.includes('%00')) {
      return {
        isValid: false,
        violationType: 'NULL_BYTE_INJECTION',
        reason: 'Null byte injection detected in target path.',
      };
    }

    // 3. Encoded Traversal Check
    const decoded = decodeURIComponent(targetPath);
    if (decoded !== targetPath) {
      // If targetPath had percent encoding, check decoded content for traversal
      if (
        decoded.includes('..') ||
        decoded.includes('/') ||
        decoded.includes('\\')
      ) {
        if (targetPath.includes('%2e') || targetPath.includes('%2E') || targetPath.includes('%2f') || targetPath.includes('%5c')) {
          return {
            isValid: false,
            violationType: 'PATH_TRAVERSAL_DETECTED',
            reason: 'URL-encoded directory traversal sequence detected.',
          };
        }
      }
    }

    // 4. Resolve Canonical Workspace Root
    if (!fs.existsSync(workspaceRoot)) {
      return {
        isValid: false,
        violationType: 'ROOT_ESCAPE_DETECTED',
        reason: `Workspace root does not exist: "${workspaceRoot}"`,
      };
    }

    const canonicalRoot = fs.realpathSync(path.resolve(workspaceRoot));

    // Root filesystem check
    const rootParsed = path.parse(canonicalRoot);
    if (canonicalRoot === rootParsed.root) {
      return {
        isValid: false,
        violationType: 'ROOT_ESCAPE_DETECTED',
        reason: `Cannot authorize root filesystem as workspace boundary: "${canonicalRoot}"`,
      };
    }

    // Enforce allowed parent directories if configured
    if (options?.allowedParentDirs && options.allowedParentDirs.length > 0) {
      const allowed = options.allowedParentDirs.some((allowedParent) => {
        const canonicalParent = fs.existsSync(allowedParent)
          ? fs.realpathSync(path.resolve(allowedParent))
          : path.resolve(allowedParent);
        const rel = path.relative(canonicalParent, canonicalRoot);
        return !rel.startsWith('..') && !path.isAbsolute(rel);
      });

      if (!allowed) {
        return {
          isValid: false,
          violationType: 'OUTSIDE_ALLOWED_PARENT',
          reason: `Workspace "${canonicalRoot}" is not within allowed parent directories.`,
        };
      }
    }

    // 5. Relative Containment Check
    const resolvedTarget = path.isAbsolute(targetPath)
      ? path.resolve(targetPath)
      : path.resolve(canonicalRoot, targetPath);

    const rel = path.relative(canonicalRoot, resolvedTarget);
    if (rel.startsWith('..') || path.isAbsolute(rel)) {
      return {
        isValid: false,
        violationType: 'PATH_TRAVERSAL_DETECTED',
        reason: `Target path "${targetPath}" escapes authorized workspace boundary "${canonicalRoot}".`,
      };
    }

    // 6. System Directory Inspection
    const normalizedParts = rel.toLowerCase().split(/[/\\]/);
    if (normalizedParts.some((p) => SYSTEM_DIRECTORIES.includes(p))) {
      return {
        isValid: false,
        violationType: 'SYSTEM_DIRECTORY_ACCESS',
        reason: `Access to system directory segment in "${rel}" is forbidden.`,
      };
    }

    // 7. Symlink and NTFS Junction Escape Check
    const symlinkCheck = this.isSymlinkOrJunctionEscape(canonicalRoot, resolvedTarget);
    if (symlinkCheck.isEscape) {
      return {
        isValid: false,
        violationType: symlinkCheck.isJunction ? 'JUNCTION_ESCAPE_DETECTED' : 'SYMLINK_ESCAPE_DETECTED',
        reason: symlinkCheck.reason,
      };
    }

    // 8. Protected Repository Authority Tampering Check
    const normRel = rel.replace(/\\/g, '/').toLowerCase();
    for (const prot of PROTECTED_REPOSITORY_FILES) {
      if (normRel === prot.toLowerCase()) {
        return {
          isValid: false,
          violationType: 'PROTECTED_AUTHORITY_TAMPER',
          reason: `Target "${rel}" is an immutable protected repository baseline. Direct modifications are blocked.`,
        };
      }
    }

    return {
      isValid: true,
      canonicalPath: resolvedTarget,
      relativePath: rel.replace(/\\/g, '/'),
    };
  }

  /**
   * Inspects path and all parent segments to detect symlinks or junctions pointing outside root.
   */
  public isSymlinkOrJunctionEscape(
    canonicalRoot: string,
    resolvedTarget: string
  ): { isEscape: boolean; isJunction?: boolean; reason?: string } {
    let current = resolvedTarget;
    const segmentsToCheck: string[] = [];

    // Collect all existing segments up to canonicalRoot
    while (current && current.length >= canonicalRoot.length) {
      segmentsToCheck.unshift(current);
      if (current === canonicalRoot) break;
      const parent = path.dirname(current);
      if (parent === current) break;
      current = parent;
    }

    for (const seg of segmentsToCheck) {
      if (!fs.existsSync(seg)) continue;

      try {
        const lstat = fs.lstatSync(seg);
        if (lstat.isSymbolicLink()) {
          const realTarget = fs.realpathSync(seg);
          const rel = path.relative(canonicalRoot, realTarget);
          if (rel.startsWith('..') || path.isAbsolute(rel)) {
            return {
              isEscape: true,
              isJunction: false,
              reason: `Symlink "${seg}" resolves to external location "${realTarget}" outside authorized workspace.`,
            };
          }
        }

        // On Windows, directory junctions report as directories with custom reparse attributes
        // or realpathSync resolves to target outside canonicalRoot
        const realSeg = fs.realpathSync(seg);
        const relSeg = path.relative(canonicalRoot, realSeg);
        if (relSeg.startsWith('..') || path.isAbsolute(relSeg)) {
          return {
            isEscape: true,
            isJunction: true,
            reason: `Directory junction or link "${seg}" escapes authorized root to "${realSeg}".`,
          };
        }
      } catch {
        // If broken link, handle as escape risk
        return {
          isEscape: true,
          reason: `Broken or unresolvable link detected at "${seg}".`,
        };
      }
    }

    return { isEscape: false };
  }

  /**
   * Computes a content-hash-bound approval action string.
   */
  public createApprovalAction(relativePath: string, content: string): string {
    const hash = crypto.createHash('sha256').update(content, 'utf8').digest('hex');
    return `WORKSPACE_WRITE:${relativePath.replace(/\\/g, '/').toLowerCase()}:${hash}`;
  }

  /**
   * Generates a tamper-evident user approval token bound to workspace, task, path, and content.
   * Tracks the minted token in the active session's token registry.
   */
  public createApprovalToken(
    workspaceIdOrTaskId: string,
    taskIdOrRelPath: string,
    relPathOrContentSha256: string,
    contentSha256OrOptions?:
      | string
      | { proposalId?: string; ttlMs?: number; autoConfirm?: boolean; operatorId?: string },
    options?: { proposalId?: string; ttlMs?: number; autoConfirm?: boolean; operatorId?: string }
  ): string {
    let wsId: string;
    let tId: string;
    let rPath: string;
    let cSha: string;
    let opts:
      | { proposalId?: string; ttlMs?: number; autoConfirm?: boolean; operatorId?: string }
      | undefined;

    if (typeof contentSha256OrOptions === 'string') {
      wsId = workspaceIdOrTaskId;
      tId = taskIdOrRelPath;
      rPath = relPathOrContentSha256;
      cSha = contentSha256OrOptions;
      opts = options;
    } else {
      wsId = 'DEFAULT_WORKSPACE';
      tId = workspaceIdOrTaskId;
      rPath = taskIdOrRelPath;
      cSha = relPathOrContentSha256;
      opts = contentSha256OrOptions;
    }

    const normWorkspaceId = wsId.trim().toUpperCase();
    const normRelPath = rPath.replace(/\\/g, '/').toLowerCase();
    const payload = `${normWorkspaceId}:${tId}:${normRelPath}:${cSha}`;
    const sig = crypto.createHmac('sha256', this.hmacSecret).update(payload).digest('hex').slice(0, 16).toUpperCase();
    const token = `AUTH-${sig}`;

    const now = Date.now();
    const ttlMs = opts?.ttlMs ?? 15 * 60 * 1000; // 15-minute validity window
    this.issuedTokens.set(token, {
      token,
      proposalId: opts?.proposalId,
      workspaceId: normWorkspaceId,
      taskId: tId,
      relativePath: normRelPath,
      contentSha256: cSha,
      issuedAt: now,
      expiresAt: now + ttlMs,
      confirmed: opts?.autoConfirm ?? true,
      used: false,
      operatorId: opts?.operatorId,
    });

    return token;
  }

  /**
   * Explicitly marks an issued token as confirmed by an authorized human operator.
   */
  public confirmToken(token: string): boolean {
    const record = this.issuedTokens.get(token);
    if (!record) return false;
    record.confirmed = true;
    return true;
  }

  /**
   * Marks a token as consumed to prevent replay attacks.
   */
  public markTokenUsed(token: string): void {
    const record = this.issuedTokens.get(token);
    if (record) {
      record.used = true;
    }
  }

  /**
   * Verifies an approval token against workspace, task, path, proposed content, expiration,
   * human confirmation, single-use replay status, and legacy salt forgery.
   */
  public verifyApprovalToken(
    token: string,
    workspaceIdOrTaskId: string,
    taskIdOrRelPath: string,
    relPathOrContentSha256: string,
    contentSha256?: string
  ): { isValid: boolean; reason?: string } {
    if (!token || typeof token !== 'string') {
      return { isValid: false, reason: 'Approval token is missing or invalid.' };
    }

    let wsId: string;
    let tId: string;
    let rPath: string;
    let cSha: string;

    if (contentSha256 !== undefined) {
      wsId = workspaceIdOrTaskId;
      tId = taskIdOrRelPath;
      rPath = relPathOrContentSha256;
      cSha = contentSha256;
    } else {
      wsId = 'DEFAULT_WORKSPACE';
      tId = workspaceIdOrTaskId;
      rPath = taskIdOrRelPath;
      cSha = relPathOrContentSha256;
    }

    const normWorkspaceId = wsId.trim().toUpperCase();
    const normRelPath = rPath.replace(/\\/g, '/').toLowerCase();
    const payload = `${normWorkspaceId}:${tId}:${normRelPath}:${cSha}`;

    // 1. Detect and reject forged tokens signed with the legacy static salt
    const legacySig = crypto
      .createHmac('sha256', WorkspaceSecurityGuard.LEGACY_STATIC_SALT)
      .update(payload)
      .digest('hex')
      .slice(0, 16)
      .toUpperCase();
    if (token === `AUTH-${legacySig}`) {
      return {
        isValid: false,
        reason: 'FORGED_APPROVAL_TOKEN: Token was signed using deprecated static salt. Dynamic tokens required.',
      };
    }

    // 2. Lookup token in issued registry
    const record = this.issuedTokens.get(token);
    if (!record) {
      return {
        isValid: false,
        reason: 'FORGED_APPROVAL_TOKEN: Token was not issued by active security guard session.',
      };
    }

    // 3. Workspace identity verification (Finding B)
    if (record.workspaceId !== normWorkspaceId) {
      return {
        isValid: false,
        reason: `WORKSPACE_MISMATCH: Approval token was issued for workspace "${record.workspaceId}", but presented against workspace "${normWorkspaceId}".`,
      };
    }

    // 4. Expiration Check
    if (Date.now() > record.expiresAt) {
      return {
        isValid: false,
        reason: 'EXPIRED_APPROVAL_TOKEN: Approval token has expired.',
      };
    }

    // 5. Replay Protection: Single-use enforcement
    if (record.used) {
      return {
        isValid: false,
        reason: 'TOKEN_ALREADY_USED: Approval token has already been consumed. Replay is forbidden.',
      };
    }

    // 6. Human Confirmation Check
    if (!record.confirmed) {
      return {
        isValid: false,
        reason: 'UNCONFIRMED_APPROVAL_TOKEN: Write proposal has not been confirmed by an authorized human operator.',
      };
    }

    // 7. Cryptographic and parameter binding check
    if (
      record.taskId !== tId ||
      record.relativePath !== normRelPath ||
      record.contentSha256 !== cSha
    ) {
      return {
        isValid: false,
        reason: 'INVALID_APPROVAL_SIGNATURE: Approval token does not match workspace, task ID, relative path, and content SHA-256 signature.',
      };
    }

    return { isValid: true };
  }

  /**
   * Securely executes a controlled write into an authorized workspace.
   */
  public async executeControlledWrite(
    workspaceRoot: string,
    request: ControlledWriteRequest,
    policy: WorkspaceWritePolicy = 'REQUIRE_APPROVAL_TOKEN',
    workspaceId?: string
  ): Promise<WorkspaceWriteResult> {
    // 1. Actuation Lockout Check
    if (WorkspaceSecurityGuard.IS_ACTUATION_BLOCKED !== true) {
      return {
        success: false,
        bytesWritten: 0,
        status: 'REJECTED',
        errorMessage: 'ACTUATION_LOCKOUT_VIOLATION: Hardware actuation is permanently blocked.',
      };
    }

    // 2. Validate Path Containment
    const validation = this.validatePathContainment(workspaceRoot, request.targetFilePath);
    if (!validation.isValid || !validation.canonicalPath || !validation.relativePath) {
      return {
        success: false,
        bytesWritten: 0,
        status: 'REJECTED',
        errorMessage: `SECURITY_REJECTION: ${validation.reason || 'Path containment check failed.'}`,
      };
    }

    // Derive deterministic effective workspace ID
    const canonicalRoot = validation.canonicalPath ? path.resolve(workspaceRoot) : workspaceRoot;
    const effectiveWorkspaceId = (
      workspaceId ||
      `WS-${crypto
        .createHash('sha256')
        .update(fs.existsSync(canonicalRoot) ? fs.realpathSync(canonicalRoot).toLowerCase() : canonicalRoot.toLowerCase())
        .digest('hex')
        .slice(0, 10)
        .toUpperCase()}`
    ).trim().toUpperCase();

    // 3. Check Policy
    if (policy === 'READ_ONLY') {
      return {
        success: false,
        canonicalPath: validation.canonicalPath,
        relativePath: validation.relativePath,
        bytesWritten: 0,
        status: 'REJECTED',
        errorMessage: 'READ_ONLY_VIOLATION: Workspace is mounted in read-only mode. All write attempts are blocked.',
      };
    }

    // 4. Calculate Content Hash
    const content = request.content || '';
    const contentSha256 = crypto.createHash('sha256').update(content, 'utf8').digest('hex');

    // 5. Enforce Approval Token
    if (policy === 'REQUIRE_APPROVAL_TOKEN') {
      if (!request.approvalToken) {
        const expectedToken = this.createApprovalToken(
          effectiveWorkspaceId,
          request.taskId,
          validation.relativePath,
          contentSha256,
          { autoConfirm: false }
        );
        return {
          success: false,
          canonicalPath: validation.canonicalPath,
          relativePath: validation.relativePath,
          bytesWritten: 0,
          status: 'APPROVAL_REQUIRED',
          approvalRequired: true,
          approvalAction: this.createApprovalAction(validation.relativePath, content),
          approvalTokenExpected: expectedToken,
          errorMessage: 'APPROVAL_REQUIRED: Explicit user approval token is required before modifying workspace files.',
        };
      }

      const tokenCheck = this.verifyApprovalToken(
        request.approvalToken,
        effectiveWorkspaceId,
        request.taskId,
        validation.relativePath,
        contentSha256
      );
      if (!tokenCheck.isValid) {
        return {
          success: false,
          canonicalPath: validation.canonicalPath,
          relativePath: validation.relativePath,
          bytesWritten: 0,
          status: 'REJECTED',
          errorMessage: tokenCheck.reason?.includes('WORKSPACE_MISMATCH')
            ? tokenCheck.reason
            : `FORGED_APPROVAL_TOKEN: ${tokenCheck.reason}`,
        };
      }

      // Mark token consumed upon verification
      this.markTokenUsed(request.approvalToken);
    }

    // 6. Atomic Write Execution
    try {
      const parentDir = path.dirname(validation.canonicalPath);
      if (!fs.existsSync(parentDir)) {
        fs.mkdirSync(parentDir, { recursive: true });
      }

      const tmpPath = `${validation.canonicalPath}.tmp.${Date.now()}`;
      fs.writeFileSync(tmpPath, content, 'utf8');
      fs.renameSync(tmpPath, validation.canonicalPath);

      // 7. Post-Write Disk Verification
      const readBack = fs.readFileSync(validation.canonicalPath, 'utf8');
      const verifiedSha256 = crypto.createHash('sha256').update(readBack, 'utf8').digest('hex');

      if (verifiedSha256 !== contentSha256) {
        return {
          success: false,
          canonicalPath: validation.canonicalPath,
          relativePath: validation.relativePath,
          bytesWritten: 0,
          status: 'FAILED',
          errorMessage: 'DISK_INTEGRITY_MISMATCH: Written file does not match expected SHA-256 upon readback.',
        };
      }

      return {
        success: true,
        canonicalPath: validation.canonicalPath,
        relativePath: validation.relativePath,
        bytesWritten: Buffer.byteLength(readBack, 'utf8'),
        sha256: verifiedSha256,
        status: 'APPLIED_AND_VERIFIED',
      };
    } catch (err: any) {
      return {
        success: false,
        canonicalPath: validation.canonicalPath,
        relativePath: validation.relativePath,
        bytesWritten: 0,
        status: 'FAILED',
        errorMessage: `WRITE_IO_ERROR: ${err.message}`,
      };
    }
  }
}
