/**
 * CUBiO Query Analysis Adapter
 * Evaluates SQL queries, detects whole-table scans, and recommends index coverage.
 */

import { DSAQueryAnalysisReport } from './types';

export class QueryAnalysisAdapter {
  public analyzeQuery(querySql: string): DSAQueryAnalysisReport {
    const trimmed = querySql.trim();
    const upper = trimmed.toUpperCase();

    const isSelect = upper.startsWith('SELECT');
    const hasLimit = upper.includes(' LIMIT ');
    const hasWhere = upper.includes(' WHERE ');
    const hasJoin = upper.includes(' JOIN ');

    let wholeTableScanRisk = false;
    let recommendation = 'Query follows bounded criteria pattern.';
    let estimatedComplexity = 'O(log N)';
    const missingIndexCandidates: string[] = [];

    if (isSelect) {
      if (!hasLimit && !hasWhere) {
        wholeTableScanRisk = true;
        estimatedComplexity = 'O(N) - Full Table Scan';
        recommendation = 'Add a WHERE clause and explicit LIMIT clause to prevent unbounded memory allocation.';
      } else if (hasWhere && !hasLimit) {
        // Query has WHERE but no LIMIT
        estimatedComplexity = 'O(k) where k is matching rows';
        recommendation = 'Consider adding LIMIT/OFFSET pagination to protect buffer pools.';
      }

      // Check for unindexed metadata queries
      if (upper.includes('RECORD_JSON') || upper.includes('JSON_EXTRACT')) {
        missingIndexCandidates.push('generated column or virtual index for json fields');
        recommendation += ' Extract frequently filtered JSON properties into first-class indexed columns.';
      }
    }

    return {
      querySqlOrDescription: querySql,
      isBounded: hasLimit || (hasWhere && !wholeTableScanRisk),
      wholeTableScanRisk,
      missingIndexCandidates,
      estimatedComplexity,
      recommendation,
    };
  }
}
