/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-009 — CEA (Code Execution Agent)
 * src/cubio/agents/cea/requestValidator.ts
 *
 * Strict request validator enforcing allowlist matching, argument safety,
 * path traversal denial, protected path immunity, and caller authentication.
 */

import * as path from 'path';
import {
  CEARequest,
  CEABoundsConfig,
  DEFAULT_CEA_BOUNDS,
  CEAPermittedCaller,
} from './types';
import { CommandRegistry } from './commandRegistry';
import { FrozenProtectionGuard } from '../../language/native/pma/frozenProtectionGuard';

export interface ValidationOutcome {
  readonly isValid: boolean;
  readonly errors: readonly string[];
  readonly sanitizedRequest?: CEARequest;
}

export class RequestValidator {
  private static readonly PERMITTED_CALLERS: readonly string[] = [
    'CUBIO-NATIVE-PMA',
    'AGENT-008-AOA',
    'AGENT-003-TGA',
    'AGENT-013-CDA',
    'AGENT-009-CEA',
    'SYSTEM_INTERNAL',
  ];

  // Shell metacharacters and suspicious control characters strictly forbidden in arguments
  // Note: Semi-colon or redirection are blocked; parentheses in JS code are checked per command
  private static readonly DANGEROUS_SHELL_CHARS_REGEX = /[|`$\r\n\0]/;
  // Rejection regex for inline script evaluation flags across all commands
  private static readonly INLINE_EXECUTION_FLAG_REGEX = /^(?:-e|--eval|-p|--print|--input-type=.*)$/i;

  private readonly registry: CommandRegistry;
  private readonly bounds: CEABoundsConfig;
  private readonly frozenGuard: FrozenProtectionGuard;
  private readonly rootDir: string;

  constructor(
    registry: CommandRegistry,
    bounds: CEABoundsConfig = DEFAULT_CEA_BOUNDS,
    customRootDir?: string
  ) {
    this.registry = registry;
    this.bounds = bounds;
    this.rootDir = customRootDir || process.cwd();
    this.frozenGuard = new FrozenProtectionGuard(this.rootDir);
  }

  /**
   * Validates and sanitizes a code execution request fail-closed.
   */
  public validate(request: CEARequest): ValidationOutcome {
    const errors: string[] = [];

    if (!request) {
      return { isValid: false, errors: ['Request object is null or undefined'] };
    }

    // 1. Mandatory Identity Fields
    if (!request.requestId || typeof request.requestId !== 'string' || request.requestId.trim().length === 0) {
      errors.push('Missing or invalid requestId');
    }
    if (!request.taskId || typeof request.taskId !== 'string' || request.taskId.trim().length === 0) {
      errors.push('Missing or invalid taskId');
    }

    // 2. Caller Authentication & Authorization
    if (!request.requestedBy || !RequestValidator.PERMITTED_CALLERS.includes(request.requestedBy)) {
      errors.push(`Unauthorized caller: '${request.requestedBy || 'UNKNOWN'}'`);
    }

    // 3. Actuation Lock Bypass Checks
    const rawAny = request as any;
    if (rawAny.is_actuation_blocked === false || rawAny.actuation_override === true || rawAny.force_execution === true) {
      errors.push('CRITICAL: Attempted hardware or actuation override detected and rejected');
    }

    // 4. Command Allowlist Lookup
    if (!request.commandId || !this.registry.isRegistered(request.commandId)) {
      errors.push(`Unregistered or unapproved command ID: '${request.commandId || 'NONE'}'`);
    }

    const approvedCmd = request.commandId ? this.registry.getCommand(request.commandId) : undefined;
    if (approvedCmd) {
      // 5. Operation Type Compatibility
      if (!approvedCmd.allowedOperationTypes.includes(request.operationType)) {
        errors.push(
          `Operation type '${request.operationType}' not permitted for command '${approvedCmd.commandId}'`
        );
      }

      // 6. Arguments Validation
      const args = request.arguments || [];
      if (args.length > this.bounds.maxArgumentCount) {
        errors.push(`Argument count (${args.length}) exceeds bound (${this.bounds.maxArgumentCount})`);
      }

      // Validate each argument against command allowed pattern
      if (approvedCmd.allowedArgumentsPattern && approvedCmd.allowedArgumentsPattern.length > 0) {
        if (args.length !== approvedCmd.allowedArgumentsPattern.length) {
          errors.push(`Argument count (${args.length}) does not match expected (${approvedCmd.allowedArgumentsPattern.length}) for command '${approvedCmd.commandId}'`);
        } else {
          for (let pIdx = 0; pIdx < args.length; pIdx++) {
            const pat = approvedCmd.allowedArgumentsPattern[pIdx];
            if (pat && !pat.test(args[pIdx])) {
              errors.push(`Argument at index ${pIdx} ('${args[pIdx]}') does not match allowed pattern for command '${approvedCmd.commandId}'`);
            }
          }
        }
      }

      for (let i = 0; i < args.length; i++) {
        const arg = args[i];
        if (typeof arg !== 'string') {
          errors.push(`Argument at index ${i} is not a string`);
          continue;
        }

        if (arg.length > this.bounds.maxArgumentLength) {
          errors.push(`Argument at index ${i} exceeds maximum length (${this.bounds.maxArgumentLength})`);
        }

        // Metacharacter rejection
        if (RequestValidator.DANGEROUS_SHELL_CHARS_REGEX.test(arg)) {
          errors.push(`Dangerous shell metacharacter detected in argument ${i}: '${arg}'`);
        }

        // Forbid shell redirection and semicolons unconditionally
        if (/[;&><]/.test(arg)) {
          errors.push(`Dangerous shell metacharacter detected in argument ${i}: '${arg}'`);
        }

        // Reject inline execution flags unconditionally
        if (RequestValidator.INLINE_EXECUTION_FLAG_REGEX.test(arg.trim())) {
          errors.push(`Inline execution flag is strictly forbidden: '${arg}'`);
        }

        // Path traversal rejection
        if (arg.includes('..') || arg.startsWith('/') || arg.includes(':\\')) {
          const resolvedPath = path.resolve(this.rootDir, arg);
          const relative = path.relative(this.rootDir, resolvedPath);
          if (relative.startsWith('..') || path.isAbsolute(relative)) {
            errors.push(`Path traversal outside workspace forbidden: '${arg}'`);
          }
        }

        // Protected Files Immunity Check
        const normalized = arg.replace(/\\/g, '/').toLowerCase();
        if (
          normalized.includes('data/cubio_studio.db') ||
          normalized.includes('address369.ts') ||
          normalized.includes('phase16_production_final_sealed_1m') ||
          this.frozenGuard.isProtected(arg)
        ) {
          // If write operation is attempted on protected paths, fail closed
          if (request.operationType !== 'INSPECTION' && request.operationType !== 'STATIC_ANALYSIS') {
            errors.push(`Protected sovereign asset touch rejected: '${arg}'`);
          }
        }
      }
    }

    // 7. Environment Overrides Check (No arbitrary environment manipulation)
    if (request.envOverrides && Object.keys(request.envOverrides).length > 0) {
      const forbiddenEnvKeys = ['NODE_OPTIONS', 'LD_PRELOAD', 'PATH', 'PYTHONPATH', 'SHELL'];
      for (const k of Object.keys(request.envOverrides)) {
        if (forbiddenEnvKeys.includes(k.toUpperCase())) {
          errors.push(`Unsafe environment variable override forbidden: '${k}'`);
        }
      }
    }

    if (errors.length > 0) {
      return { isValid: false, errors: Object.freeze(errors) };
    }

    return {
      isValid: true,
      errors: Object.freeze([]),
      sanitizedRequest: Object.freeze({
        ...request,
        timeoutMs: Math.min(
          request.timeoutMs || this.bounds.defaultTimeoutMs,
          approvedCmd ? approvedCmd.maxTimeoutMs : this.bounds.maxTimeoutMs
        ),
        outputLimitBytes: Math.min(
          request.outputLimitBytes || this.bounds.maxStdoutBytes,
          approvedCmd ? approvedCmd.maxStdoutBytes : this.bounds.maxStdoutBytes
        ),
      }),
    };
  }
}
