/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-016 — SAA (System Architecture Agent)
 * src/cubio/agents/saa/architectureContractInspector.ts
 *
 * Validates declared architectural contracts:
 * - AOA Agent Registry declarations vs. concrete invoker bindings
 * - Certified F1–F45 Layer Boundary isolation
 * - Frozen authority inviolability
 */

import {
  SAAComponentRecord,
  SAAContractValidationRecord,
  SAAFindingRecord,
  SAAContractStatus,
} from './types';
import { AgentRegistryAdapter } from '../aoa/agentRegistryAdapter';
import { ArchitectureReviewer } from '../../intelligence/universal/coding/analysis/architectureReviewer';

export class ArchitectureContractInspector {
  private readonly archReviewer: ArchitectureReviewer;

  constructor(customReviewer?: ArchitectureReviewer) {
    this.archReviewer = customReviewer || new ArchitectureReviewer();
  }

  /**
   * Inspects agent registry contracts in AOA to verify whether declared statuses
   * match real invoker bindings.
   */
  public inspectAgentRegistry(registry: AgentRegistryAdapter): {
    validations: readonly SAAContractValidationRecord[];
    findings: readonly SAAFindingRecord[];
  } {
    const validations: SAAContractValidationRecord[] = [];
    const findings: SAAFindingRecord[] = [];

    const allAgents = registry.listAgents();

    for (const agent of allAgents) {
      const entry = registry.getAgent(agent.agentId);
      const isCallable = typeof entry?.invoker?.invoke === 'function';

      let status: SAAContractStatus = 'CONSISTENT';
      let observed = `Status: ${agent.status}, Callable: ${isCallable}`;

      if (agent.status === 'IMPLEMENTED_CALLABLE' && !isCallable) {
        status = 'INCONSISTENT';
        observed = 'Status declared IMPLEMENTED_CALLABLE but invoker is missing';

        findings.push({
          findingId: `FIND_REG_${agent.agentId}`,
          category: 'REGISTRY_BINDING_MISMATCH',
          severity: 'CRITICAL',
          confidence: 'VERIFIED',
          title: `Agent Registry Mismatch: ${agent.agentId}`,
          description: `Agent ${agent.agentId} (${agent.name}) is registered as IMPLEMENTED_CALLABLE but lacks an active invoker binding.`,
          affectedComponents: [agent.agentId],
          evidenceReferences: ['src/cubio/agents/aoa/agentRegistryAdapter.ts'],
          expectedContract: 'Callable agents must have a functional invoke() binding in AOA',
          observedDiscrepancy: 'Missing invoker method',
          recommendedAction: `Bind ${agent.agentId} invoker in AOA or demote status to PLANNED.`,
          status: 'ACTIVE',
        });
      } else if (agent.status === 'PLANNED' && isCallable) {
        status = 'INCONSISTENT';
        observed = 'Status declared PLANNED but active invoker was bound';

        findings.push({
          findingId: `FIND_REG_PLANNED_${agent.agentId}`,
          category: 'REGISTRY_BINDING_MISMATCH',
          severity: 'HIGH',
          confidence: 'VERIFIED',
          title: `Premature Invoker Binding for Planned Agent: ${agent.agentId}`,
          description: `Agent ${agent.agentId} is marked PLANNED but has an active invoker attached.`,
          affectedComponents: [agent.agentId],
          evidenceReferences: ['src/cubio/agents/aoa/agentRegistryAdapter.ts'],
          expectedContract: 'Planned agents must remain strictly uncallable',
          observedDiscrepancy: 'Invoker binding found on PLANNED agent',
          recommendedAction: `Remove invoker binding or promote agent to IMPLEMENTED_CALLABLE.`,
          status: 'ACTIVE',
        });
      }

      validations.push({
        targetId: agent.agentId,
        contractType: 'AGENT_REGISTRY',
        status,
        declaredContract: `${agent.name} (${agent.agentId}) -> ${agent.status}`,
        observedBehavior: observed,
        evidencePath: 'src/cubio/agents/aoa/agentRegistryAdapter.ts',
      });
    }

    return {
      validations: Object.freeze(validations),
      findings: Object.freeze(findings),
    };
  }

  /**
   * Inspects layer boundaries across file contents using ArchitectureReviewer.
   */
  public inspectLayerBoundaries(files: Readonly<Record<string, string>>): {
    validations: readonly SAAContractValidationRecord[];
    findings: readonly SAAFindingRecord[];
  } {
    const validations: SAAContractValidationRecord[] = [];
    const findings: SAAFindingRecord[] = [];

    const review = this.archReviewer.reviewArchitecture(files);

    const boundaryStatus: SAAContractStatus = review.compliancePassed ? 'CONSISTENT' : 'INCONSISTENT';

    validations.push({
      targetId: 'LAYER_BOUNDARIES_ALL',
      contractType: 'SUBSYSTEM_BOUNDARY',
      status: boundaryStatus,
      declaredContract: 'Strict layer isolation (UI -> Orchestration -> Core) without bypass',
      observedBehavior: `CompliancePassed: ${review.compliancePassed}, AntiPatterns: ${review.detectedAntiPatterns.length}`,
      evidencePath: 'in-memory-review',
    });

    for (const antiPattern of review.detectedAntiPatterns) {
      findings.push({
        findingId: `FIND_LAYER_${findings.length + 1}`,
        category: 'LAYER_BOUNDARY_VIOLATION',
        severity: 'HIGH',
        confidence: 'VERIFIED',
        title: `Architectural Layer Boundary Violation`,
        description: antiPattern,
        affectedComponents: ['in-memory-files'],
        evidenceReferences: ['in-memory-files'],
        expectedContract: 'Strict boundary isolation without raw bypass or certified layer mutation',
        observedDiscrepancy: antiPattern,
        recommendedAction: 'Refactor calls to route through approved interfaces and safety gates.',
        status: 'ACTIVE',
      });
    }

    return {
      validations: Object.freeze(validations),
      findings: Object.freeze(findings),
    };
  }
}
