import * as fs from 'fs';
import { createHash } from 'crypto';

export const WORD_BOUNDARY_MARKER = '\u2581'; // '▁'

export const SPECIAL_TOKENS = [
  '<PAD>',
  '<UNK>',
  '<BOS>',
  '<EOS>',
  '<SEP>',
  '<MASK>',
  '<EPISTEMIC_FACT>',
  '<EPISTEMIC_DERIVATION>',
  '<EPISTEMIC_OBSERVATION>',
  '<EPISTEMIC_HYPOTHESIS>',
  '<EPISTEMIC_PREDICTION>',
  '<EPISTEMIC_ASSUMPTION>',
  '<EPISTEMIC_UNKNOWN>',
  '<SPATIAL_ANCHOR>',
  '<SPATIAL_CELL>',
  '<HARMONIC_369>',
];

export interface VocabData {
  vocabId: string;
  size: number;
  vocabHash: string;
  tokens: string[];
  merges: Array<[string, string]>;
}

export class NativeBpeTokenizer {
  public readonly vocab: string[];
  public readonly tokenToId: Map<string, number>;
  public readonly idToToken: Map<number, string>;
  public readonly sortedTokens: string[];
  public readonly maxTokenLen: number;
  public readonly vocabHash: string;

  constructor(tokens: string[]) {
    this.vocab = tokens;
    this.tokenToId = new Map();
    this.idToToken = new Map();

    tokens.forEach((t, i) => {
      this.tokenToId.set(t, i);
      this.idToToken.set(i, t);
    });

    this.sortedTokens = [...tokens].sort((a, b) => b.length - a.length);
    this.maxTokenLen = this.sortedTokens.length > 0 ? this.sortedTokens[0].length : 1;
    this.vocabHash = createHash('sha256').update(JSON.stringify(tokens)).digest('hex');
  }

  public tokenize(text: string): string[] {
    if (!text) return [];
    const normalized = text.split(' ').join(WORD_BOUNDARY_MARKER);
    const pieces: string[] = [];
    let i = 0;
    const len = normalized.length;

    while (i < len) {
      let matched = false;
      const endLimit = Math.min(len, i + this.maxTokenLen);

      for (let j = endLimit; j > i; j--) {
        const sub = normalized.substring(i, j);
        if (this.tokenToId.has(sub)) {
          pieces.push(sub);
          i = j;
          matched = true;
          break;
        }
      }

      if (!matched) {
        pieces.push(normalized[i]);
        i++;
      }
    }

    return pieces;
  }

  public encode(text: string, options?: { addSpecialTokens?: boolean }): number[] {
    const pieces = this.tokenize(text);
    const ids: number[] = [];

    if (options?.addSpecialTokens) {
      ids.push(2); // <BOS>
    }

    for (const p of pieces) {
      const id = this.tokenToId.get(p);
      if (id !== undefined) {
        ids.push(id);
      } else {
        ids.push(1); // <UNK>
      }
    }

    return ids;
  }

  public decode(tokenIds: number[], options?: { skipSpecialTokens?: boolean }): string {
    const skip = options?.skipSpecialTokens ?? true;
    const pieces: string[] = [];
    for (const id of tokenIds) {
      if (skip && (id >= 0 && id <= 5)) continue; // skip PAD, UNK, BOS, EOS, SEP, MASK
      const t = this.idToToken.get(id);
      if (t) pieces.push(t);
    }
    const merged = pieces.join('');
    return merged.split(WORD_BOUNDARY_MARKER).join(' ');
  }

  public getSpecialTokenId(name: string): number {
    switch (name.toUpperCase()) {
      case 'PAD': return 0;
      case 'UNK': return 1;
      case 'BOS': return 2;
      case 'EOS': return 3;
      case 'SEP': return 4;
      case 'MASK': return 5;
      default: return this.tokenToId.get(`<${name.toUpperCase()}>`) ?? 1;
    }
  }

  public static loadFromDisk(filePath: string): NativeBpeTokenizer {
    const data: VocabData = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    return new NativeBpeTokenizer(data.tokens);
  }
}
