/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-016 — SAA (System Architecture Agent)
 * src/cubio/agents/saa/systemArchitectureAgent.ts
 *
 * Central facade for AGENT-016-SAA.
 * Evaluates repository architecture, validates contracts, maps dependencies,
 * and produces evidence-backed reports with permanent actuation lockout.
 */

import {
  SAATaskRequest,
  SAAReport,
  SAABoundsConfig,
  DEFAULT_SAA_BOUNDS,
  SAAComponentRecord,
  SAARelationshipRecord,
  SAAContractValidationRecord,
  SAAFindingRecord,
  SAARecommendationRecord,
} from './types';
import { RepositoryInventoryAdapter } from './repositoryInventoryAdapter';
import { DependencyAnalysisAdapter } from './dependencyAnalysisAdapter';
import { ArchitectureContractInspector } from './architectureContractInspector';
import { ArchitectureFindingAnalyzer } from './architectureFindingAnalyzer';
import { ArchitectureReportBuilder } from './architectureReportBuilder';
import { AgentRegistryAdapter } from '../aoa/agentRegistryAdapter';

export class SystemArchitectureAgent {
  public static readonly AGENT_ID = 'AGENT-016-SAA';
  public static readonly AGENT_NAME = 'System Architecture Agent';
  public static readonly VERSION = '1.0.0';

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public get is_actuation_blocked(): boolean {
    return true;
  }

  private readonly defaultBounds: SAABoundsConfig;
  private readonly inventoryAdapter: RepositoryInventoryAdapter;
  private readonly dependencyAdapter: DependencyAnalysisAdapter;
  private readonly contractInspector: ArchitectureContractInspector;
  private readonly registryRef?: AgentRegistryAdapter;

  constructor(
    customBounds: SAABoundsConfig = DEFAULT_SAA_BOUNDS,
    customInventoryAdapter?: RepositoryInventoryAdapter,
    customDependencyAdapter?: DependencyAnalysisAdapter,
    customContractInspector?: ArchitectureContractInspector,
    customRegistry?: AgentRegistryAdapter
  ) {
    this.defaultBounds = customBounds;
    this.inventoryAdapter = customInventoryAdapter || new RepositoryInventoryAdapter();
    this.dependencyAdapter = customDependencyAdapter || new DependencyAnalysisAdapter();
    this.contractInspector = customContractInspector || new ArchitectureContractInspector();
    this.registryRef = customRegistry;
  }

  /**
   * Primary entry point: Executes a bounded system architecture review or inventory.
   */
  public async execute(request: SAATaskRequest): Promise<SAAReport> {
    const startTimeMs = Date.now();
    const requestId = request?.requestId || `REQ_SAA_${Date.now()}`;
    const taskId = request?.taskId || `TASK_SAA_${Date.now()}`;

    // 1. Fail-closed null / object validation
    if (!request || typeof request !== 'object') {
      return this.buildErrorReport(
        requestId,
        taskId,
        'FAILED',
        'Invalid architecture request: payload is null or not an object',
        startTimeMs
      );
    }

    // 2. Reject malicious actuation override attempts
    if (request.bypassActuationLock === true) {
      return this.buildErrorReport(
        requestId,
        taskId,
        'BLOCKED',
        'Hardware actuation override attempt rejected fail-closed. IS_ACTUATION_BLOCKED is immutable.',
        startTimeMs
      );
    }

    // 3. Resolve bounds
    const bounds: SAABoundsConfig = {
      ...this.defaultBounds,
      ...(request.bounds || {}),
    };

    // 4. Validate objective
    const objective = (request.objective || '').trim();
    if (!objective && !request.scope?.targetSubsystems && !request.scope?.targetFilePaths && !request.scope?.customFiles) {
      return this.buildErrorReport(
        requestId,
        taskId,
        'NEEDS_MORE_EVIDENCE',
        'Request is empty: lacks objective, target subsystems, target files, or custom files fixture.',
        startTimeMs
      );
    }

    try {
      // 5. Gather Component Inventory
      const components = this.inventoryAdapter.discoverComponents({
        targetSubsystems: request.scope?.targetSubsystems,
        targetFilePaths: request.scope?.targetFilePaths,
        customFiles: request.scope?.customFiles,
        bounds,
      });

      // 6. Map Dependencies and Analyze Cycles / Orphans
      const depAnalysis = this.dependencyAdapter.analyzeDependencies(
        components,
        request.scope?.customFiles,
        bounds
      );

      // 7. Validate Contracts (Registry & Layers)
      const validations: SAAContractValidationRecord[] = [];
      const contractFindings: SAAFindingRecord[] = [];

      // Check layer boundaries if custom in-memory files are present
      if (request.scope?.customFiles) {
        const layerResult = this.contractInspector.inspectLayerBoundaries(request.scope.customFiles);
        validations.push(...layerResult.validations);
        contractFindings.push(...layerResult.findings);
      }

      // Check agent registry contracts if registry reference is provided
      if (this.registryRef) {
        const regResult = this.contractInspector.inspectAgentRegistry(this.registryRef);
        validations.push(...regResult.validations);
        contractFindings.push(...regResult.findings);
      }

      // Combine findings
      const allFindings: readonly SAAFindingRecord[] = Object.freeze([
        ...depAnalysis.findings,
        ...contractFindings,
      ].slice(0, bounds.maxFindingsCount));

      // 8. Generate Recommendations
      const recommendations = ArchitectureFindingAnalyzer.generateRecommendations(
        allFindings,
        components,
        bounds
      );

      const durationMs = Date.now() - startTimeMs;
      const summary = `System Architecture Audit completed. Discovered ${components.length} components, mapped ${depAnalysis.relationships.length} relationships, verified ${validations.length} contracts, identified ${allFindings.length} findings.`;

      // 9. Build and Sign Final Report
      return ArchitectureReportBuilder.buildReport({
        request,
        status: 'SUCCEEDED',
        summary,
        components,
        relationships: depAnalysis.relationships,
        validations: Object.freeze(validations),
        findings: allFindings,
        recommendations,
        durationMs,
        generateDiagram: request.generateMermaidDiagram,
      });
    } catch (err: any) {
      return this.buildErrorReport(
        requestId,
        taskId,
        'FAILED',
        `Architecture evaluation failed: ${err?.message || String(err)}`,
        startTimeMs
      );
    }
  }

  /**
   * Adapter for AOA Invoker contract.
   */
  public async invoke(payload: Record<string, unknown>, timeoutMs?: number): Promise<SAAReport> {
    const request: SAATaskRequest = {
      requestId: (payload.requestId as string) || `REQ_AOA_${Date.now()}`,
      taskId: (payload.taskId as string) || `TASK_AOA_${Date.now()}`,
      taskType: (payload.taskType as any) || 'ARCHITECTURE_AUDIT',
      objective: (payload.objective as string) || (payload.prompt as string) || 'Architecture audit',
      scope: (payload.scope as any) || {
        targetSubsystems: payload.targetSubsystems as any,
        targetFilePaths: payload.targetFilePaths as any,
        customFiles: payload.customFiles as any,
      },
      bounds: {
        maxExecutionMs: timeoutMs || this.defaultBounds.maxExecutionMs,
      },
      bypassActuationLock: payload.bypassActuationLock as boolean,
      generateMermaidDiagram: payload.generateMermaidDiagram as boolean,
    };

    return this.execute(request);
  }

  private buildErrorReport(
    requestId: string,
    taskId: string,
    status: 'FAILED' | 'BLOCKED' | 'NEEDS_MORE_EVIDENCE',
    reason: string,
    startTimeMs: number
  ): SAAReport {
    const durationMs = Date.now() - startTimeMs;
    return ArchitectureReportBuilder.buildReport({
      request: { requestId, taskId, objective: reason },
      status,
      summary: reason,
      components: [],
      relationships: [],
      validations: [],
      findings: [
        {
          findingId: `FIND_ERR_${Date.now()}`,
          category: 'INSUFFICIENT_EVIDENCE',
          severity: status === 'BLOCKED' ? 'CRITICAL' : 'HIGH',
          confidence: 'VERIFIED',
          title: `Architecture Analysis Guard Triggered: ${status}`,
          description: reason,
          affectedComponents: [],
          evidenceReferences: [],
          status: 'ACTIVE',
        },
      ],
      recommendations: [],
      durationMs,
    });
  }
}
