  // ---------------------------------------------------------------------------
  // Stale Context & Staleness Filtering
  // ---------------------------------------------------------------------------

  /**
   * Checks whether a task record is considered stale based on age or maxAgeMs.
   */
  public isRecordStale(taskId: string, maxAgeMs?: number): boolean {
    const record = this.records.get(taskId);
    if (!record) return true;
    const limit = maxAgeMs ?? this.defaultMaxContextAgeMs;
    const recordTime = new Date(record.date).getTime();
    return Date.now() - recordTime > limit;
  }

  /**
   * Returns only fresh task records within the specified age window.
   */
  public getFreshRecords(maxAgeMs?: number): readonly PMATaskMemoryRecord[] {
    const limit = maxAgeMs ?? this.defaultMaxContextAgeMs;
    const now = Date.now();
    return Object.freeze(
      Array.from(this.records.values()).filter((r) => now - new Date(r.date).getTime() <= limit)
    );
  }

  /**
   * Returns only fresh architectural decisions within the specified age window.
   */
  public getFreshDecisions(maxAgeMs?: number): readonly PMAArchitecturalDecision[] {
    const limit = maxAgeMs ?? this.defaultMaxContextAgeMs;
    const now = Date.now();
    return Object.freeze(
      Array.from(this.decisions.values()).filter((d) => now - new Date(d.timestamp).getTime() <= limit)
    );
  }

