/**
 * CUBiO AI — 3D Memory Studio
 * Task-Scoped Shared Context, Memory & Result Handoff Framework
 * src/cubio/language/native/pma/pmaTaskContextManager.ts
 *
 * Implements Phase 22 requirements:
 * 1. Task-scoped context bundle containing objective, constraints, acceptance criteria,
 *    relevant files, prior verified outputs, and task status.
 * 2. Least-privilege access: Give each agent only the context and outputs needed for its assigned subtask.
 * 3. Preserves source task ID, source agent ID, provenance, output schema, integrity hash,
 *    and access permissions for shared results.
 * 4. Integrates with existing PMA ProjectMemory for persistent records without redundant storage.
 * 5. Strictly distinguishes persistent project memory from temporary execution context.
 * 6. Prevents unauthorized reads, accidental cross-task context leakage, secret exposure,
 *    stale-result reuse, and tampered-result acceptance.
 * 7. Handles missing, conflicting, expired, or unverified context fail-closed.
 * 8. Bridges downstream agent references to upstream results via verified handoff mechanism.
 * 9. Tamper-evident ledger of which context and result references each agent actually received.
 * 10. Avoids full-repo copying, conversation dumping, or output bloating into subtasks.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import * as crypto from 'crypto';
import {
  ProjectMemory,
  PMAArchitecturalDecision,
  PMATaskMemoryRecord,
} from './projectMemory';
import {
  PMAHandoffContract,
  PMAGitChanges,
  PMAReviewVerdict,
} from './types';
import { AOAHandoffBinding } from '../../agents/aoa/types';

export interface VerifiedTaskOutput {
  readonly sourceTaskId: string;
  readonly sourceAgentId: string;
  readonly outputPayload: Record<string, unknown>;
  readonly outputSchemaRef?: string;
  readonly integritySha256: string;
  readonly requiredPermission?: string;
  readonly producedAt: number;
  readonly maxAgeMs?: number;
  readonly isVerified: boolean;
}

export interface TaskContextBundle {
  readonly taskId: string;
  readonly objective: string;
  readonly tenantId: string;
  readonly constraints: readonly string[];
  readonly acceptanceCriteria: readonly string[];
  readonly relevantFiles: readonly string[];
  readonly allowedFiles: readonly string[];
  readonly protectedFiles: readonly string[];
  readonly createdAt: number;
  readonly ttlMs: number;
  readonly status: 'ACTIVE' | 'COMPLETED' | 'EXPIRED' | 'ABORTED';
  readonly verifiedOutputs: ReadonlyMap<string, VerifiedTaskOutput>; // sourceTaskId -> output
  readonly isActuationBlocked: boolean;
}

export interface AgentContextSlice {
  readonly taskId: string;
  readonly subtaskId: string;
  readonly targetAgentId: string;
  readonly objective: string;
  readonly scopedConstraints: readonly string[];
  readonly scopedAcceptanceCriteria: readonly string[];
  readonly scopedFiles: readonly string[];
  readonly boundUpstreamOutputs: Record<string, unknown>;
  readonly provenanceTrace: readonly Record<string, unknown>[];
  readonly sliceHashSha256: string;
  readonly generatedAt: number;
}

export interface ContextAccessAuditRecord {
  readonly auditId: string;
  readonly taskId: string;
  readonly subtaskId: string;
  readonly agentId: string;
  readonly requestedOutputs: readonly string[];
  readonly grantedOutputs: readonly string[];
  readonly deniedOutputs: readonly string[];
  readonly sliceHashSha256: string;
  readonly timestamp: number;
}

export class PMATaskContextManager {
  public static readonly IS_ACTUATION_BLOCKED = true;
  private static readonly DEFAULT_TTL_MS = 600000; // 10 minutes

  // In-memory temporary execution context bundles indexed by taskId
  private readonly taskContexts = new Map<string, TaskContextBundle>();

  // Context access ledger tracking what each agent actually received
  private readonly accessAuditLedger: ContextAccessAuditRecord[] = [];

  constructor(private readonly projectMemory?: ProjectMemory) {}

  /**
   * Initializes a temporary, task-scoped context bundle.
   */
  public createContextBundle(params: {
    taskId: string;
    objective: string;
    tenantId?: string;
    constraints?: readonly string[];
    acceptanceCriteria?: readonly string[];
    relevantFiles?: readonly string[];
    allowedFiles?: readonly string[];
    protectedFiles?: readonly string[];
    ttlMs?: number;
  }): TaskContextBundle {
    const now = Date.now();
    const bundle: TaskContextBundle = Object.freeze({
      taskId: params.taskId,
      objective: params.objective,
      tenantId: params.tenantId || 'root',
      constraints: Object.freeze([...(params.constraints || [])]),
      acceptanceCriteria: Object.freeze([...(params.acceptanceCriteria || [])]),
      relevantFiles: Object.freeze([...(params.relevantFiles || [])]),
      allowedFiles: Object.freeze([...(params.allowedFiles || [])]),
      protectedFiles: Object.freeze([...(params.protectedFiles || [])]),
      createdAt: now,
      ttlMs: params.ttlMs || PMATaskContextManager.DEFAULT_TTL_MS,
      status: 'ACTIVE',
      verifiedOutputs: new Map<string, VerifiedTaskOutput>(),
      isActuationBlocked: true,
    });

    this.taskContexts.set(params.taskId, bundle);
    return bundle;
  }

  /**
   * Retrieves an active context bundle, validating against expiration.
   */
  public getContextBundle(taskId: string): TaskContextBundle | undefined {
    const bundle = this.taskContexts.get(taskId);
    if (!bundle) return undefined;

    // Check expiration
    if (Date.now() - bundle.createdAt > bundle.ttlMs) {
      // Mark expired
      const expiredBundle: TaskContextBundle = {
        ...bundle,
        status: 'EXPIRED',
      };
      this.taskContexts.set(taskId, Object.freeze(expiredBundle));
      return expiredBundle;
    }

    return bundle;
  }

  /**
   * Records a verified upstream subtask output into the task-scoped context bundle.
   */
  public recordVerifiedOutput(params: {
    taskId: string;
    sourceTaskId: string;
    sourceAgentId: string;
    outputPayload: Record<string, unknown>;
    outputSchemaRef?: string;
    requiredPermission?: string;
    maxAgeMs?: number;
  }): VerifiedTaskOutput {
    const bundle = this.getContextBundle(params.taskId);
    if (!bundle) {
      throw new Error(`[CONTEXT_NOT_FOUND] No active context bundle found for task '${params.taskId}'.`);
    }

    if (bundle.status !== 'ACTIVE') {
      throw new Error(`[CONTEXT_INACTIVE] Context bundle for task '${params.taskId}' is ${bundle.status}.`);
    }

    // Compute tamper-evident SHA-256 hash
    const rawPayload = JSON.stringify(params.outputPayload || {});
    const integritySha256 = crypto.createHash('sha256').update(rawPayload).digest('hex');

    const verifiedOutput: VerifiedTaskOutput = Object.freeze({
      sourceTaskId: params.sourceTaskId,
      sourceAgentId: params.sourceAgentId,
      outputPayload: Object.freeze({ ...params.outputPayload }),
      outputSchemaRef: params.outputSchemaRef,
      integritySha256,
      requiredPermission: params.requiredPermission,
      producedAt: Date.now(),
      maxAgeMs: params.maxAgeMs,
      isVerified: true,
    });

    (bundle.verifiedOutputs as Map<string, VerifiedTaskOutput>).set(params.sourceTaskId, verifiedOutput);
    return verifiedOutput;
  }

  /**
   * Derives a scoped context slice for an agent executing a subtask,
   * enforcing least-privilege, permission boundaries, and integrity checks.
   */
  public deriveAgentContextSlice(params: {
    taskId: string;
    subtaskId: string;
    targetAgentId: string;
    subtaskObjective: string;
    relevantFileFilter?: readonly string[];
    handoffBindings?: readonly AOAHandoffBinding[];
    callerPermissions?: readonly string[];
    maxContextAgeMs?: number;
  }): AgentContextSlice {
    const bundle = this.getContextBundle(params.taskId);
    if (!bundle) {
      throw new Error(`[CONTEXT_NOT_FOUND] Task '${params.taskId}' has no registered context bundle.`);
    }

    if (bundle.status === 'EXPIRED') {
      throw new Error(`[CONTEXT_EXPIRED] Task context bundle for '${params.taskId}' has expired.`);
    }

    if (bundle.status !== 'ACTIVE') {
      throw new Error(`[CONTEXT_INACTIVE] Task context bundle for '${params.taskId}' is ${bundle.status}.`);
    }

    const callerPermissions = new Set(params.callerPermissions || []);
    const boundUpstreamOutputs: Record<string, unknown> = {};
    const provenanceTrace: Array<Record<string, unknown>> = [];
    const requestedOutputs: string[] = [];
    const grantedOutputs: string[] = [];
    const deniedOutputs: string[] = [];

    // Filter relevant files: only provide files relevant to this agent's slice
    const scopedFiles = params.relevantFileFilter
      ? bundle.allowedFiles.filter((f) => params.relevantFileFilter!.includes(f))
      : bundle.allowedFiles.slice(0, 5); // Default bounded slice

    let sliceHashSha256 = '';

    try {
      // Resolve handoff bindings if requested
      if (params.handoffBindings && params.handoffBindings.length > 0) {
        for (const binding of params.handoffBindings) {
          requestedOutputs.push(binding.sourceTaskId);
          const verifiedOutput = bundle.verifiedOutputs.get(binding.sourceTaskId);

          // Missing check
          if (!verifiedOutput) {
            deniedOutputs.push(binding.sourceTaskId);
            throw new Error(
              `[MISSING_CONTEXT_OUTPUT] Prerequisite output '${binding.sourceTaskId}' is missing from task context.`
            );
          }

          // Stale output check
          const maxOutputAge = params.maxContextAgeMs || verifiedOutput.maxAgeMs;
          if (maxOutputAge && Date.now() - verifiedOutput.producedAt > maxOutputAge) {
            deniedOutputs.push(binding.sourceTaskId);
            throw new Error(
              `[STALE_CONTEXT_OUTPUT] Upstream output '${binding.sourceTaskId}' is stale (produced ${Date.now() - verifiedOutput.producedAt}ms ago, max allowed is ${maxOutputAge}ms).`
            );
          }

          // Anti-spoofing agent mismatch
          if (verifiedOutput.sourceAgentId !== binding.sourceAgentId) {
            deniedOutputs.push(binding.sourceTaskId);
            throw new Error(
              `[AGENT_MISMATCH] Expected output from '${binding.sourceAgentId}', but output was produced by '${verifiedOutput.sourceAgentId}'.`
            );
          }

          // Integrity check
          if (binding.integritySha256 && binding.integritySha256 !== verifiedOutput.integritySha256) {
            deniedOutputs.push(binding.sourceTaskId);
            throw new Error(
              `[TAMPERED_CONTEXT_OUTPUT] Integrity hash mismatch for '${binding.sourceTaskId}'. Expected ${binding.integritySha256}, got ${verifiedOutput.integritySha256}.`
            );
          }

          // Schema check
          if (binding.expectedSchemaRef && verifiedOutput.outputSchemaRef && binding.expectedSchemaRef !== verifiedOutput.outputSchemaRef) {
            deniedOutputs.push(binding.sourceTaskId);
            throw new Error(
              `[SCHEMA_MISMATCH] Output schema '${verifiedOutput.outputSchemaRef}' does not match expected schema '${binding.expectedSchemaRef}'.`
            );
          }

          // Permission check
          const requiredPerm = binding.requiredPermission || verifiedOutput.requiredPermission;
          if (requiredPerm && !callerPermissions.has(requiredPerm)) {
            deniedOutputs.push(binding.sourceTaskId);
            throw new Error(
              `[PERMISSION_DENIED] Agent '${params.targetAgentId}' lacks required permission '${requiredPerm}' to read output from '${binding.sourceTaskId}'.`
            );
          }

          // Secret exposure prevention guard
          const SECRET_PATTERN = /(?:secret|password|bearer|auth[-_]?token|api[-_]?key|private[-_]?key|credential)/i;
          const isSecretKey =
            SECRET_PATTERN.test(binding.outputKeyPath) ||
            (binding.targetParameterKey && SECRET_PATTERN.test(binding.targetParameterKey));

          if (isSecretKey && !callerPermissions.has('READ_SECRETS') && !callerPermissions.has('ADMIN_SECRETS')) {
            deniedOutputs.push(binding.sourceTaskId);
            throw new Error(
              `[SECRET_EXPOSURE_BLOCKED] Attempted to expose sensitive/secret key '${binding.outputKeyPath}' to agent '${params.targetAgentId}' without READ_SECRETS permission.`
            );
          }

          // Extract keypath
          const extractedValue = this.extractValue(verifiedOutput.outputPayload, binding.outputKeyPath);
          if (extractedValue === undefined) {
            deniedOutputs.push(binding.sourceTaskId);
            throw new Error(
              `[MALFORMED_OUTPUT_KEYPATH] Key '${binding.outputKeyPath}' does not exist on output of '${binding.sourceTaskId}'.`
            );
          }

          // Check if extracted object payload leaks secrets internally
          if (
            typeof extractedValue === 'object' &&
            extractedValue !== null &&
            !callerPermissions.has('READ_SECRETS') &&
            !callerPermissions.has('ADMIN_SECRETS')
          ) {
            const keys = Object.keys(extractedValue as object);
            const leakedSecretKey = keys.find((k) => SECRET_PATTERN.test(k));
            if (leakedSecretKey) {
              deniedOutputs.push(binding.sourceTaskId);
              throw new Error(
                `[SECRET_EXPOSURE_BLOCKED] Extracted payload object contains sensitive field '${leakedSecretKey}' which cannot be exposed to '${params.targetAgentId}' without READ_SECRETS permission.`
              );
            }
          }

          const targetKey = binding.targetParameterKey || binding.outputKeyPath;
          boundUpstreamOutputs[targetKey] = extractedValue;
          grantedOutputs.push(binding.sourceTaskId);

          provenanceTrace.push({
            sourceTaskId: binding.sourceTaskId,
            sourceAgentId: binding.sourceAgentId,
            outputKeyPath: binding.outputKeyPath,
            targetParameterKey: targetKey,
            integritySha256: verifiedOutput.integritySha256,
            timestamp: Date.now(),
          });
        }
      }

      // Hash the resulting slice
      const slicePayload = JSON.stringify({
        taskId: params.taskId,
        subtaskId: params.subtaskId,
        targetAgentId: params.targetAgentId,
        subtaskObjective: params.subtaskObjective,
        scopedFiles,
        boundUpstreamOutputs,
      });
      sliceHashSha256 = crypto.createHash('sha256').update(slicePayload).digest('hex');

      return Object.freeze({
        taskId: params.taskId,
        subtaskId: params.subtaskId,
        targetAgentId: params.targetAgentId,
        objective: params.subtaskObjective,
        scopedConstraints: bundle.constraints,
        scopedAcceptanceCriteria: bundle.acceptanceCriteria,
        scopedFiles: Object.freeze(scopedFiles),
        boundUpstreamOutputs: Object.freeze(boundUpstreamOutputs),
        provenanceTrace: Object.freeze(provenanceTrace),
        sliceHashSha256,
        generatedAt: Date.now(),
      });
    } finally {
      // Audit record is ALWAYS appended
      const auditRecord: ContextAccessAuditRecord = Object.freeze({
        auditId: `AUDIT-${crypto.randomBytes(6).toString('hex').toUpperCase()}`,
        taskId: params.taskId,
        subtaskId: params.subtaskId,
        agentId: params.targetAgentId,
        requestedOutputs: Object.freeze(requestedOutputs),
        grantedOutputs: Object.freeze(grantedOutputs),
        deniedOutputs: Object.freeze(deniedOutputs),
        sliceHashSha256: sliceHashSha256 || 'N/A_DENIED',
        timestamp: Date.now(),
      });
      this.accessAuditLedger.push(auditRecord);
    }
  }

  /**
   * Closes an execution context bundle and marks it completed.
   */
  public closeContextBundle(taskId: string): void {
    const bundle = this.taskContexts.get(taskId);
    if (bundle) {
      this.taskContexts.set(taskId, Object.freeze({ ...bundle, status: 'COMPLETED' }));
    }
  }

  /**
   * Returns audit logs for a given task ID.
   */
  public getAccessAuditLogs(taskId?: string): readonly ContextAccessAuditRecord[] {
    if (!taskId) return Object.freeze([...this.accessAuditLedger]);
    return Object.freeze(this.accessAuditLedger.filter((a) => a.taskId === taskId));
  }

  /**
   * Returns the persistent ProjectMemory instance if configured.
   */
  public getProjectMemory(): ProjectMemory | undefined {
    return this.projectMemory;
  }

  /**
   * Queries shared architectural decisions from persistent ProjectMemory.
   */
  public querySharedDecisions(subsystem?: string): readonly PMAArchitecturalDecision[] {
    if (!this.projectMemory) return [];
    if (subsystem) {
      return this.projectMemory.getDecisionsBySubsystem(subsystem);
    }
    return this.projectMemory.getFreshDecisions();
  }

  /**
   * Records a shared architectural decision into persistent ProjectMemory.
   */
  public recordSharedDecision(params: {
    decisionId: string;
    taskId: string;
    subsystem: string;
    title: string;
    rationale: string;
    chosenStrategy: string;
    affectedFiles?: readonly string[];
    reusableCapabilities?: readonly string[];
  }): PMAArchitecturalDecision {
    if (!this.projectMemory) {
      throw new Error(
        `[PROJECT_MEMORY_UNAVAILABLE] Cannot record shared decision: ProjectMemory instance is not configured.`
      );
    }
    return this.projectMemory.recordDecision(params);
  }

  /**
   * Commits a completed task's verified outcome into persistent ProjectMemory.
   */
  public commitCompletedTaskMemory(params: {
    handoff: PMAHandoffContract;
    changes: PMAGitChanges;
    review: PMAReviewVerdict;
  }): PMATaskMemoryRecord {
    if (!this.projectMemory) {
      throw new Error(
        `[PROJECT_MEMORY_UNAVAILABLE] Cannot commit task memory: ProjectMemory instance is not configured.`
      );
    }
    return this.projectMemory.recordCompletedTask(
      params.handoff,
      params.changes,
      params.review
    );
  }

  private extractValue(target: Record<string, unknown>, path: string): unknown {
    if (!path || typeof path !== 'string') return undefined;
    if (Object.prototype.hasOwnProperty.call(target, path)) {
      return target[path];
    }
    const segments = path.split('.');
    let curr: any = target;
    for (const seg of segments) {
      if (curr === null || curr === undefined || typeof curr !== 'object') {
        return undefined;
      }
      curr = curr[seg];
    }
    return curr;
  }
}
