/**
 * CubiO — F10 Monotonic Global Rx Counter
 *
 * Rx_global(n+1) = Rx_global(n) + 1
 */

export class RxGlobalCounter {
  private static globalCounter = 0;

  public static nextGlobalRx(): number {
    this.globalCounter++;
    return this.globalCounter;
  }

  public static currentGlobalRx(): number {
    return this.globalCounter;
  }

  public static resetForTesting(val = 0): void {
    this.globalCounter = val;
  }
}
