/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-015 — BFA (Bug-Fixing Agent)
 * src/cubio/agents/bfa/regressionPlanner.ts
 *
 * Discovers and plans targeted regression checks for proposed bug fixes.
 */

import { BFADefectCategory, BFARegressionPlan } from './types';

export class RegressionPlanner {
  public static plan(
    category: BFADefectCategory,
    targetFilePath?: string,
    testSnippet?: string
  ): BFARegressionPlan {
    const suites: string[] = ['src/test_phase8_regression_lock.ts', 'src/test_phase9_regression_lock.ts'];
    const criteria: string[] = [
      'Zero typecheck regressions (npx tsc --noEmit)',
      'Zero runtime exceptions during reproduction test execution',
      'Deterministic output preservation across 50 iterations',
    ];

    let reproducingTestHint = testSnippet ? 'User-provided reproduction test snippet' : undefined;

    if (targetFilePath) {
      if (targetFilePath.includes('math') || targetFilePath.includes('369')) {
        suites.unshift('src/test_maa_mathematics_agent.ts');
        criteria.push('Modular invariants in Z/9Z preserved');
      } else if (targetFilePath.includes('coding') || targetFilePath.includes('cda')) {
        suites.unshift('src/test_cda_coding_agent.ts');
      } else if (targetFilePath.includes('security') || targetFilePath.includes('sga')) {
        suites.unshift('src/test_sga_security_agent.ts');
      }
    }

    if (category === 'COMPILER_TYPESCRIPT') {
      criteria.push('TypeScript compiler error TS codes cleared');
    } else if (category === 'RUNTIME_EXCEPTION') {
      criteria.push('Null dereference guards validated');
    }

    return Object.freeze({
      reproducingTestHint,
      suggestedVerificationSuites: Object.freeze(suites),
      acceptanceCriteria: Object.freeze(criteria),
      riskAssessment: 'Low to moderate regression risk. Verification suites must be executed independently prior to applying fix.',
    });
  }
}
