/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-011 — OMA (Observability & Monitoring Agent)
 * src/cubio/agents/oma/eventNormalizer.ts
 *
 * Ingests diverse telemetry events from AOA, CEA, SGA, BTWA, and TGA,
 * redacting sensitive tokens and normalizing into OMANormalizedEvent records.
 */

import { OMANormalizedEvent, OMAEventType, OMASeverity } from './types';
import { OutputSanitizer } from '../cea/outputSanitizer';

export class EventNormalizer {
  /**
   * Normalizes raw inputs into structured OMANormalizedEvent fail-closed.
   */
  public static normalize(raw: Partial<OMANormalizedEvent> | null | undefined): OMANormalizedEvent {
    const safeRaw = raw && typeof raw === 'object' ? raw : {};
    const timestamp = typeof safeRaw.timestamp === 'number' && safeRaw.timestamp > 0 ? safeRaw.timestamp : Date.now();
    const eventId = safeRaw.eventId || `evt_${timestamp.toString(36)}_${Math.random().toString(36).slice(2, 7)}`;
    const sourceAgentId = (safeRaw.sourceAgentId && typeof safeRaw.sourceAgentId === 'string' && safeRaw.sourceAgentId.trim())
      ? safeRaw.sourceAgentId.trim()
      : 'UNKNOWN_AGENT';

    let eventType: OMAEventType = safeRaw.eventType || 'EXECUTION_RECORD';
    let severity: OMASeverity = safeRaw.severity || 'INFO';
    let status = safeRaw.status || 'UNKNOWN';

    // Sanitize metadata to avoid secret leakage
    let sanitizedMeta: Record<string, unknown> = {};
    if (safeRaw.sanitizedMetadata && typeof safeRaw.sanitizedMetadata === 'object') {
      for (const [k, v] of Object.entries(safeRaw.sanitizedMetadata)) {
        if (typeof v === 'string') {
          sanitizedMeta[k] = OutputSanitizer.sanitize(v, 1024).sanitizedText;
        } else if (typeof v === 'number' || typeof v === 'boolean') {
          sanitizedMeta[k] = v;
        } else {
          try {
            const str = JSON.stringify(v);
            sanitizedMeta[k] = OutputSanitizer.sanitize(str, 1024).sanitizedText;
          } catch {
            sanitizedMeta[k] = '[UNSERIALIZABLE]';
          }
        }
      }
    }

    // Enforce 4KB maxMetadataBytes budget
    const serialized = JSON.stringify(sanitizedMeta);
    if (Buffer.byteLength(serialized, 'utf8') > 4096) {
      sanitizedMeta = {
        truncated: true,
        summary: `Metadata exceeded 4096 bytes budget and was truncated`,
      };
    }

    return Object.freeze({
      eventId,
      eventType,
      timestamp,
      sourceAgentId,
      taskId: safeRaw.taskId,
      correlationId: safeRaw.correlationId,
      severity,
      status,
      durationMs: typeof safeRaw.durationMs === 'number' ? Math.max(0, safeRaw.durationMs) : undefined,
      policyVersion: safeRaw.policyVersion || '1.0.0-CANONICAL',
      evidenceReferences: Object.freeze([...(safeRaw.evidenceReferences || [])]),
      sanitizedMetadata: Object.freeze(sanitizedMeta),
    });
  }
}
