export type SGADecisionOutcome =
  | 'ALLOW'
  | 'DENY'
  | 'BLOCKED'
  | 'REVIEW_REQUIRED'
  | 'ERROR';

export type SGASeverityLevel =
  | 'CRITICAL'
  | 'HIGH'
  | 'MEDIUM'
  | 'LOW'
  | 'INFORMATIONAL';

export interface SGAPrincipal {
  readonly principalId: string;
  readonly role: string;
  readonly authenticated: boolean;
  readonly declaredCapabilities: readonly string[];
  readonly delegationDepth?: number;
  readonly parentPrincipalId?: string;
}

export interface SGASecurityRequest {
  readonly requestId: string;
  readonly correlationId: string;
  readonly requestingPrincipal: SGAPrincipal;
  readonly targetOperation: string;
  readonly resourceScope: readonly string[];
  readonly payload?: Readonly<Record<string, unknown>>;
  readonly policyVersion?: string;
}

export interface SGAGuardEvaluationRecord {
  readonly guardName: string;
  readonly outcome: 'PASS' | 'FAIL' | 'BLOCKED' | 'EXCEPTION';
  readonly reasonCodes: readonly string[];
  readonly details?: string;
}

export interface SGASecurityDecision {
  readonly decisionId: string;
  readonly requestId: string;
  readonly correlationId: string;
  readonly requestingPrincipalId: string;
  readonly requestedOperation: string;
  readonly resourceScope: readonly string[];
  readonly decision: SGADecisionOutcome;
  readonly policyVersion: string;
  readonly evaluatedGuards: readonly SGAGuardEvaluationRecord[];
  readonly reasonCodes: readonly string[];
  readonly evidenceHash: string;
  readonly evaluatedAt: number;
  readonly reviewRequired: boolean;
  readonly isActuationBlocked: boolean;
}

export interface SGASecurityEvent {
  readonly eventId: string;
  readonly timestamp: number;
  readonly severity: SGASeverityLevel;
  readonly eventType: string;
  readonly principalId: string;
  readonly description: string;
  readonly details: Readonly<Record<string, unknown>>;
}

export interface SGABoundsConfig {
  readonly maxDelegationDepth: number;
  readonly maxResourceScopeEntries: number;
  readonly policyVersion: string;
  readonly maxRetainedEvents: number;
}

export const DEFAULT_SGA_BOUNDS: SGABoundsConfig = Object.freeze({
  maxDelegationDepth: 3,
  maxResourceScopeEntries: 32,
  policyVersion: '1.0.0-CANONICAL',
  maxRetainedEvents: 200,
});
