import {
  CubiOCodeAnalysisEngine,
} from '../../intelligence/universal/coding/analysis/codeAnalysisEngine';
import {
  RepositoryAnalysisReport,
  ErrorDiagnosisReport,
  DependencyAnalysisReport,
  TestAnalysisReport,
  ArchitectureReviewReport,
  BugFixReport,
  RegressionVerificationReport,
} from '../../intelligence/universal/coding/analysis/types';

export class CodeAnalysisAdapter {
  private readonly analysisEngine: CubiOCodeAnalysisEngine;

  constructor(customEngine?: CubiOCodeAnalysisEngine) {
    this.analysisEngine = customEngine || new CubiOCodeAnalysisEngine();
  }

  public diagnoseError(errorTrace: string, codeSnippet?: string): ErrorDiagnosisReport {
    return this.analysisEngine.diagnoseError(errorTrace, codeSnippet);
  }

  public fixBug(code: string, issueDescription: string): BugFixReport {
    return this.analysisEngine.fixBug(code, issueDescription);
  }

  public analyzeRepository(files: Readonly<Record<string, string>>): RepositoryAnalysisReport {
    return this.analysisEngine.analyzeRepository(files);
  }

  public analyzeDependencies(files: Readonly<Record<string, string>>): DependencyAnalysisReport {
    return this.analysisEngine.analyzeDependencies(files);
  }

  public analyzeTests(testCode: string, sourceCode?: string): TestAnalysisReport {
    return this.analysisEngine.analyzeTests(testCode, sourceCode);
  }

  public reviewArchitecture(files: Readonly<Record<string, string>>): ArchitectureReviewReport {
    return this.analysisEngine.reviewArchitecture(files);
  }

  public verifyRegression(
    originalCode: string,
    patchedCode: string,
    testCasesCount?: number
  ): RegressionVerificationReport {
    return this.analysisEngine.verifyRegression(originalCode, patchedCode, testCasesCount);
  }
}
