/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-016 — SAA (System Architecture Agent)
 * src/cubio/agents/saa/repositoryInventoryAdapter.ts
 *
 * Provides safe, bounded repository component and module discovery.
 * Reuses ProjectNavigator catalogs and RepositoryAnalyzer without unconstrained scans.
 */

import * as fs from 'fs';
import * as path from 'path';
import { SAAComponentRecord, SAABoundsConfig } from './types';
import { ProjectNavigator } from '../../language/native/pma/projectNavigator';
import { FrozenProtectionGuard } from '../../language/native/pma/frozenProtectionGuard';

export class RepositoryInventoryAdapter {
  private readonly projectNavigator: ProjectNavigator;
  private readonly frozenGuard: FrozenProtectionGuard;
  private readonly rootDir: string;

  constructor(customRootDir?: string, customNavigator?: ProjectNavigator) {
    this.rootDir = customRootDir || process.cwd();
    this.projectNavigator = customNavigator || new ProjectNavigator(this.rootDir);
    this.frozenGuard = new FrozenProtectionGuard(this.rootDir);
  }

  /**
   * Discovers components matching in-scope subsystems, file paths, or custom file maps.
   */
  public discoverComponents(params: {
    targetSubsystems?: readonly string[];
    targetFilePaths?: readonly string[];
    customFiles?: Readonly<Record<string, string>>;
    bounds: SAABoundsConfig;
  }): readonly SAAComponentRecord[] {
    const components: SAAComponentRecord[] = [];
    const seenPaths = new Set<string>();

    // 1. Process custom in-memory file fixtures if provided
    if (params.customFiles) {
      for (const [filePath, content] of Object.entries(params.customFiles)) {
        if (components.length >= params.bounds.maxFilesToInspect) break;
        components.push(this.analyzeFileContent(filePath, content));
        seenPaths.add(filePath);
      }
    }

    // 2. Process explicit file paths from disk (bounded)
    if (params.targetFilePaths) {
      for (const rawPath of params.targetFilePaths) {
        if (components.length >= params.bounds.maxFilesToInspect) break;
        const normalized = rawPath.replace(/\\/g, '/');
        if (seenPaths.has(normalized)) continue;

        const fullPath = path.isAbsolute(normalized) ? normalized : path.join(this.rootDir, normalized);
        if (fs.existsSync(fullPath) && fs.statSync(fullPath).isFile()) {
          try {
            const content = fs.readFileSync(fullPath, 'utf8');
            components.push(this.analyzeFileContent(normalized, content));
            seenPaths.add(normalized);
          } catch {
            // Unreadable or binary file safely skipped
          }
        }
      }
    }

    // 3. Process targeted subsystems using ProjectNavigator catalog
    if (params.targetSubsystems && params.targetSubsystems.length > 0) {
      for (const subId of params.targetSubsystems) {
        if (components.length >= params.bounds.maxFilesToInspect) break;
        const subDef = this.projectNavigator.getSubsystem(subId);
        if (subDef) {
          for (const keyFile of subDef.keyFiles) {
            if (components.length >= params.bounds.maxFilesToInspect) break;
            const normKey = keyFile.replace(/\\/g, '/');
            if (seenPaths.has(normKey)) continue;

            const fullPath = path.join(this.rootDir, normKey);
            if (fs.existsSync(fullPath)) {
              try {
                const content = fs.readFileSync(fullPath, 'utf8');
                components.push(this.analyzeFileContent(normKey, content, subId));
                seenPaths.add(normKey);
              } catch {}
            }
          }
        }
      }
    }

    return Object.freeze(components);
  }

  private analyzeFileContent(
    filePath: string,
    content: string,
    subsystemId?: string
  ): SAAComponentRecord {
    const lines = content.split('\n');
    const lineCount = lines.length;

    // Extract exported symbols
    const exportedSymbols: string[] = [];
    const exportMatches = content.matchAll(/export\s+(?:class|interface|type|const|function|enum)\s+([A-Za-z0-9_]+)/g);
    for (const m of exportMatches) {
      if (m[1]) exportedSymbols.push(m[1]);
    }

    // Extract imported module targets
    const importedModules: string[] = [];
    const importMatches = content.matchAll(/from\s+['"]([^'"]+)['"]/g);
    for (const m of importMatches) {
      if (m[1]) importedModules.push(m[1]);
    }

    let complexity: 'LOW' | 'MEDIUM' | 'HIGH' | 'EXTREME' = 'LOW';
    if (lineCount > 500) complexity = 'EXTREME';
    else if (lineCount > 250) complexity = 'HIGH';
    else if (lineCount > 100) complexity = 'MEDIUM';

    const normPath = filePath.replace(/\\/g, '/');
    const isFrozen = this.frozenGuard.isProtected(normPath);

    return Object.freeze({
      componentId: normPath,
      name: path.basename(normPath),
      sourcePath: normPath,
      exportedSymbols: Object.freeze(exportedSymbols),
      importedModules: Object.freeze(importedModules),
      declaredSubsystem: subsystemId,
      isFrozenAuthority: isFrozen,
      lineCount,
      complexity,
    });
  }
}
