/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-019 — POA (Performance Optimization Agent)
 * src/cubio/agents/poa/baselineBenchmarkRunner.ts
 *
 * Controlled, repeatable micro-benchmark executor with warm-up cycles,
 * statistical quantiles (P50, P95, P99), and strict timeout budgets.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import {
  POABenchmarkConfig,
  POABenchmarkResult,
  POALatencyPercentiles,
  POABoundsConfig,
  DEFAULT_POA_BOUNDS,
} from './types';

export class BaselineBenchmarkRunner {
  constructor(private readonly bounds: POABoundsConfig = DEFAULT_POA_BOUNDS) {}

  /**
   * Executes a synchronous micro-benchmark function repeatedly under controlled conditions.
   */
  public runSyncBenchmark(
    config: POABenchmarkConfig,
    workload: (iterationIndex: number) => void
  ): POABenchmarkResult {
    const iterations = Math.max(
      1,
      Math.min(config.iterations || 10, this.bounds.maxBenchmarkIterations)
    );
    const warmups = Math.max(
      0,
      Math.min(config.warmupIterations || 0, this.bounds.maxWarmupIterations)
    );
    const timeoutBudgetMs = config.timeoutBudgetMs || this.bounds.maxExecutionBudgetMs;

    // 1. Warm-up Phase
    for (let i = 0; i < warmups; i++) {
      workload(i);
    }

    // 2. Controlled Measurement Phase
    const samples: number[] = [];
    const startTimeTotal = performance.now();
    const startHeap = this.getHeapUsed();

    for (let i = 0; i < iterations; i++) {
      const iterStart = performance.now();
      workload(i);
      const iterDuration = Math.max(0.001, performance.now() - iterStart);
      samples.push(iterDuration);

      if (performance.now() - startTimeTotal > timeoutBudgetMs) {
        break; // Timeout budget reached, retain gathered samples safely
      }
    }

    const totalDurationMs = Math.max(0.01, performance.now() - startTimeTotal);
    const endHeap = this.getHeapUsed();
    const heapDeltaBytes = Math.max(0, endHeap - startHeap);

    return this.buildResult(config, samples, totalDurationMs, heapDeltaBytes, iterations, warmups);
  }

  /**
   * Executes an asynchronous micro-benchmark function repeatedly under controlled conditions.
   */
  public async runAsyncBenchmark(
    config: POABenchmarkConfig,
    workload: (iterationIndex: number) => Promise<void>
  ): Promise<POABenchmarkResult> {
    const iterations = Math.max(
      1,
      Math.min(config.iterations || 10, this.bounds.maxBenchmarkIterations)
    );
    const warmups = Math.max(
      0,
      Math.min(config.warmupIterations || 0, this.bounds.maxWarmupIterations)
    );
    const timeoutBudgetMs = config.timeoutBudgetMs || this.bounds.maxExecutionBudgetMs;

    // 1. Warm-up Phase
    for (let i = 0; i < warmups; i++) {
      await workload(i);
    }

    // 2. Controlled Measurement Phase
    const samples: number[] = [];
    const startTimeTotal = performance.now();
    const startHeap = this.getHeapUsed();

    for (let i = 0; i < iterations; i++) {
      const iterStart = performance.now();
      await workload(i);
      const iterDuration = Math.max(0.001, performance.now() - iterStart);
      samples.push(iterDuration);

      if (performance.now() - startTimeTotal > timeoutBudgetMs) {
        break;
      }
    }

    const totalDurationMs = Math.max(0.01, performance.now() - startTimeTotal);
    const endHeap = this.getHeapUsed();
    const heapDeltaBytes = Math.max(0, endHeap - startHeap);

    return this.buildResult(config, samples, totalDurationMs, heapDeltaBytes, iterations, warmups);
  }

  public calculatePercentiles(samples: readonly number[]): POALatencyPercentiles {
    if (!samples || samples.length === 0) {
      return { p50Ms: 0, p95Ms: 0, p99Ms: 0 };
    }

    const sorted = [...samples].sort((a, b) => a - b);
    const p50Idx = Math.floor(sorted.length * 0.5);
    const p95Idx = Math.min(sorted.length - 1, Math.floor(sorted.length * 0.95));
    const p99Idx = Math.min(sorted.length - 1, Math.floor(sorted.length * 0.99));

    return {
      p50Ms: Number(sorted[p50Idx].toFixed(3)),
      p95Ms: Number(sorted[p95Idx].toFixed(3)),
      p99Ms: Number(sorted[p99Idx].toFixed(3)),
    };
  }

  private buildResult(
    config: POABenchmarkConfig,
    samples: number[],
    totalDurationMs: number,
    heapDeltaBytes: number,
    intendedIterations: number,
    warmupIterations: number
  ): POABenchmarkResult {
    const sampleCount = samples.length;
    let minMs = 0;
    let maxMs = 0;
    let sumMs = 0;

    if (sampleCount > 0) {
      minMs = Math.min(...samples);
      maxMs = Math.max(...samples);
      sumMs = samples.reduce((acc, v) => acc + v, 0);
    }

    const averageMs = sampleCount > 0 ? sumMs / sampleCount : 0;
    const percentiles = this.calculatePercentiles(samples);
    const totalSec = Math.max(0.001, totalDurationMs / 1000);
    const opsPerSec = Math.round(sampleCount / totalSec);
    const isCompliant =
      percentiles.p95Ms <= this.bounds.p95LatencyWarningThresholdMs &&
      heapDeltaBytes <= this.bounds.heapDeltaWarningThresholdBytes;

    return {
      benchmarkId: config.benchmarkId,
      targetName: config.targetName,
      iterations: intendedIterations,
      warmupIterations,
      totalDurationMs: Number(totalDurationMs.toFixed(3)),
      minMs: Number(minMs.toFixed(3)),
      maxMs: Number(maxMs.toFixed(3)),
      averageMs: Number(averageMs.toFixed(3)),
      percentiles,
      opsPerSec,
      heapDeltaBytes,
      isCompliant,
      sampleCount,
      environment: {
        nodeVersion: typeof process !== 'undefined' ? process.version : 'unknown',
        platform: typeof process !== 'undefined' ? process.platform : 'unknown',
        timestamp: Date.now(),
      },
    };
  }

  private getHeapUsed(): number {
    try {
      if (typeof process !== 'undefined' && process.memoryUsage) {
        return process.memoryUsage().heapUsed;
      }
    } catch {}
    return 0;
  }
}
