/**
 * CUBiO AI — 3D Memory Studio
 * Phase 3C: Controlled Workspace Writer
 * src/cubio/security/controlledWorkspaceWriter.ts
 *
 * Implements strict, least-privilege, atomic workspace file modifications:
 * 1. Canonical workspace containment & boundary enforcement.
 * 2. Explicit allowedFiles authorization check.
 * 3. Immutable protected authority rejection (database, address369, Phase 8 manifests).
 * 4. Symlink escape & path traversal prevention.
 * 5. Pre-write stale-baseline SHA-256 validation immediately before writing.
 * 6. Explicit task-bound, file-bound, content-hash-bound approval for real workspace edits.
 * 7. Hardware actuation safety invariant preserved (IS_ACTUATION_BLOCKED = true).
 * 8. Narrowly scoped workspace-edit permission (WORKSPACE_EDIT_PERMITTED).
 * 9. Atomic sibling write without unsafe copy-overwrite fallback.
 * 10. Line ending preservation (CRLF/LF) and UTF-8 encoding.
 * 11. Post-write disk re-read verification with before/after SHA-256 and diff tracking.
 */

import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import * as os from 'os';
import { AgentSecurityBoundaryGuard } from './agentSecurityBoundaryGuard';
import { FrozenProtectionGuard } from '../language/native/pma/frozenProtectionGuard';

export type WorkspaceWritePolicy =
  | 'DISPOSABLE_AUTO_APPLY'
  | 'REQUIRE_USER_APPROVAL';

export type WorkspaceChangeStatus =
  | 'PROPOSED'
  | 'APPLIED_AND_VERIFIED'
  | 'APPROVAL_REQUIRED'
  | 'REJECTED'
  | 'FAILED';

export interface ControlledWriteRequest {
  readonly taskId: string;
  readonly targetFilePath: string;
  readonly proposedContent: string;
  readonly operation: 'CREATE' | 'MODIFY' | 'REPLACE';
  readonly expectedBaselineSha256?: string;
  readonly expectedPostSha256?: string;
  readonly rationale: string;
  readonly requestingAgentId: string;
  readonly approvalToken?: string;
}

export interface ControlledWriteContext {
  readonly workspaceRoot: string;
  readonly allowedFiles: readonly string[];
  readonly policy?: WorkspaceWritePolicy;
  readonly isDisposableWorkspace?: boolean;
}

export interface WorkspaceChangeRecord {
  readonly changeId: string;
  readonly taskId: string;
  readonly targetFilePath: string;
  readonly operation: 'CREATE' | 'MODIFY' | 'REPLACE';
  readonly status: WorkspaceChangeStatus;
  readonly baselineSha256?: string;
  readonly postWriteSha256?: string;
  readonly bytesWritten: number;
  readonly lineEnding: 'CRLF' | 'LF';
  readonly diffSummary: string;
  readonly verifiedOnDisk: boolean;
  readonly errorMessage?: string;
  readonly timestamp: string;
}

export class ControlledWorkspaceWriter {
  /**
   * Permanent Hardware Actuation Safety Invariant.
   * Workspace file writing NEVER touches or bypasses this lock.
   */
  public static readonly IS_ACTUATION_BLOCKED: boolean = true;

  /**
   * Narrowly scoped permission identifier for code workspace edits.
   * Completely decoupled from physical hardware actuation.
   */
  public static readonly WORKSPACE_EDIT_PERMISSION: string = 'WORKSPACE_EDIT_PERMITTED';

  private readonly frozenGuard: FrozenProtectionGuard;
  private readonly securityGuard: AgentSecurityBoundaryGuard;

  constructor(customRootDir?: string) {
    this.frozenGuard = new FrozenProtectionGuard(customRootDir);
    this.securityGuard = AgentSecurityBoundaryGuard.getInstance();
  }

  /**
   * Generates the canonical content-hash-bound approval action string.
   */
  public static createApprovalAction(normalizedRelativePath: string, content: string): string {
    const hash = crypto.createHash('sha256').update(content, 'utf8').digest('hex');
    return `WORKSPACE_EDIT:${normalizedRelativePath.replace(/\\/g, '/').toLowerCase()}:${hash}`;
  }

  /**
   * Determines if a path is within a designated disposable test workspace.
   * Under SAFE-005 and BUG-001 hardening:
   * In-workspace paths (including in-tree ./tmp/) are NEVER disposable.
   * Disposable paths MUST strictly reside within the OS temporary directory (os.tmpdir()).
   */
  public static isDisposablePath(filePath: string, workspaceRoot: string): boolean {
    try {
      const osTmpCanonical = fs.existsSync(os.tmpdir())
        ? fs.realpathSync(os.tmpdir())
        : path.resolve(os.tmpdir());

      const targetResolved = path.isAbsolute(filePath)
        ? path.resolve(filePath)
        : path.resolve(workspaceRoot, filePath);

      const targetCanonical = fs.existsSync(targetResolved)
        ? fs.realpathSync(targetResolved)
        : targetResolved;

      // Check if targetCanonical is strictly contained inside os.tmpdir()
      const relToOsTmp = path.relative(osTmpCanonical, targetCanonical);
      const isInsideOsTmp = !relToOsTmp.startsWith('..') && !path.isAbsolute(relToOsTmp);

      // Check if targetCanonical is inside the workspace
      const canonicalRoot = fs.existsSync(workspaceRoot)
        ? fs.realpathSync(workspaceRoot)
        : path.resolve(workspaceRoot);
      const relToWorkspace = path.relative(canonicalRoot, targetCanonical);
      const isInsideWorkspace = !relToWorkspace.startsWith('..') && !path.isAbsolute(relToWorkspace);

      // In-workspace paths are NEVER disposable, even if named 'tmp'
      if (isInsideWorkspace) {
        return false;
      }

      return isInsideOsTmp;
    } catch {
      return false;
    }
  }

  /**
   * Normalizes a file path for consistent boundary comparison.
   */
  private normalizePath(p: string): string {
    return p.replace(/\\/g, '/').trim().toLowerCase();
  }

  /**
   * Computes SHA-256 hash of a string or buffer.
   */
  private computeSha256(content: string | Buffer): string {
    return crypto.createHash('sha256').update(content).digest('hex').toUpperCase();
  }

  /**
   * Detects dominant line endings in existing text.
   */
  private detectLineEnding(text: string): 'CRLF' | 'LF' {
    const crlfCount = (text.match(/\r\n/g) || []).length;
    const lfCount = (text.match(/[^\r]\n/g) || []).length;
    return crlfCount > lfCount ? 'CRLF' : 'LF';
  }

  /**
   * Normalizes newlines in content to match target line ending.
   */
  private normalizeLineEndings(text: string, ending: 'CRLF' | 'LF'): string {
    const stripped = text.replace(/\r\n/g, '\n');
    return ending === 'CRLF' ? stripped.replace(/\n/g, '\r\n') : stripped;
  }

  /**
   * Generates a concise summary diff between original and proposed content.
   */
  private generateDiffSummary(original: string, updated: string): string {
    const origLines = original.split(/\r?\n/);
    const updatedLines = updated.split(/\r?\n/);
    return `Lines: ${origLines.length} -> ${updatedLines.length}; Bytes: ${Buffer.byteLength(original, 'utf8')} -> ${Buffer.byteLength(updated, 'utf8')}`;
  }

  /**
   * Validates workspace containment, path traversal tokens, and symlink escapes.
   */
  private validateContainment(
    targetFilePath: string,
    workspaceRoot: string
  ): { canonicalTarget: string; normalizedRelative: string } {
    if (!targetFilePath || typeof targetFilePath !== 'string') {
      throw new Error('PATH_INVALID: targetFilePath must be a non-empty string.');
    }

    // Fail closed if workspaceRoot is missing, invalid, or targeting root filesystem
    if (!workspaceRoot || typeof workspaceRoot !== 'string' || workspaceRoot.trim().length === 0) {
      throw new Error(
        'WORKSPACE_ROOT_REQUIRED: A validated, authorized workspaceRoot must be explicitly provided. Execution aborted to prevent targeting launcher directory.'
      );
    }

    const trimmedRoot = workspaceRoot.trim();
    if (!fs.existsSync(trimmedRoot)) {
      throw new Error(`WORKSPACE_NOT_FOUND: The specified workspace root does not exist: "${trimmedRoot}"`);
    }

    const stat = fs.statSync(trimmedRoot);
    if (!stat.isDirectory()) {
      throw new Error(`WORKSPACE_NOT_DIRECTORY: Workspace root is not a directory: "${trimmedRoot}"`);
    }

    const canonicalRoot = fs.realpathSync(path.resolve(trimmedRoot));
    const rootParsed = path.parse(canonicalRoot);
    if (canonicalRoot === rootParsed.root) {
      throw new Error(`UNAUTHORIZED_WORKSPACE_PATH: Root filesystem cannot be used as workspace root: "${canonicalRoot}"`);
    }

    // Reject obvious traversal injection tokens immediately
    if (
      targetFilePath.includes('../') ||
      targetFilePath.includes('..\\') ||
      targetFilePath.toLowerCase().includes('/etc/') ||
      targetFilePath.toLowerCase().includes('c:\\windows')
    ) {
      throw new Error(`PATH_TRAVERSAL_DETECTED: Target path contains directory traversal sequences: "${targetFilePath}"`);
    }

    const canonicalTarget = path.resolve(canonicalRoot, targetFilePath);

    // Verify canonical boundary
    const relative = path.relative(canonicalRoot, canonicalTarget);
    if (relative.startsWith('..') || path.isAbsolute(relative)) {
      throw new Error(`PATH_TRAVERSAL_DETECTED: Resolved path "${canonicalTarget}" escapes workspace root "${canonicalRoot}".`);
    }

    // Symlink escape check
    if (fs.existsSync(canonicalTarget)) {
      const realTarget = fs.realpathSync(canonicalTarget);
      const realRelative = path.relative(canonicalRoot, realTarget);
      if (realRelative.startsWith('..') || path.isAbsolute(realRelative)) {
        throw new Error(`SYMLINK_BOUNDARY_ESCAPE: Real path "${realTarget}" escapes workspace root "${canonicalRoot}".`);
      }
    } else {
      // Check closest existing parent directory for symlink escape
      let parent = path.dirname(canonicalTarget);
      while (parent.length >= canonicalRoot.length && !fs.existsSync(parent)) {
        parent = path.dirname(parent);
      }
      if (fs.existsSync(parent)) {
        const realParent = fs.realpathSync(parent);
        const realParentRel = path.relative(canonicalRoot, realParent);
        if (realParentRel.startsWith('..') || path.isAbsolute(realParentRel)) {
          throw new Error(`SYMLINK_BOUNDARY_ESCAPE: Parent path "${realParent}" escapes workspace root "${canonicalRoot}".`);
        }
      }
    }

    const normalizedRelative = relative.replace(/\\/g, '/');
    return { canonicalTarget, normalizedRelative };
  }

  /**
   * Enforces explicit allowedFiles scoping.
   */
  private validateAllowedScope(
    canonicalTarget: string,
    normalizedRelative: string,
    allowedFiles: readonly string[],
    workspaceRoot: string
  ): void {
    if (!allowedFiles || allowedFiles.length === 0) {
      throw new Error('SCOPE_VIOLATION: allowedFiles list is empty; zero writes authorized.');
    }

    const canonicalRoot = path.resolve(workspaceRoot);
    const normTarget = this.normalizePath(normalizedRelative);

    const isExplicitlyAllowed = allowedFiles.some((allowed) => {
      const normAllowed = this.normalizePath(allowed);
      if (normAllowed === normTarget) return true;

      // Also check canonical resolution if allowed path is absolute or prefixed
      const resolvedAllowed = path.resolve(canonicalRoot, allowed);
      if (path.resolve(canonicalTarget) === resolvedAllowed) return true;

      // Allow wildcard for directory boundary if explicitly provided with trailing slash/star
      if (normAllowed.endsWith('/*') && normTarget.startsWith(normAllowed.slice(0, -1))) return true;

      return false;
    });

    if (!isExplicitlyAllowed) {
      throw new Error(`OUT_OF_SCOPE_FILE_VIOLATION: File "${normalizedRelative}" is not in approved allowedFiles list.`);
    }
  }

  /**
   * Verifies that target is not a protected authority (database, address369, Phase 8 manifests).
   */
  private validateProtectedAuthorities(canonicalTarget: string, workspaceRoot: string): void {
    const canonicalRoot = path.resolve(workspaceRoot);
    const relPath = path.relative(canonicalRoot, canonicalTarget).replace(/\\/g, '/');
    const normRel = this.normalizePath(relPath);

    // 1. Check AgentSecurityBoundaryGuard canonical protected authorities
    for (const protectedFile of AgentSecurityBoundaryGuard.PROTECTED_FILES) {
      if (normRel === this.normalizePath(protectedFile) || normRel.includes(this.normalizePath(protectedFile))) {
        throw new Error(`PROTECTED_AUTHORITY_TAMPER_BLOCKED: Write to protected file "${protectedFile}" is permanently prohibited.`);
      }
    }

    // 2. Check FrozenProtectionGuard
    if (this.frozenGuard.isProtected(normRel) || this.frozenGuard.isProtected(canonicalTarget)) {
      throw new Error(`PROTECTED_AUTHORITY_TAMPER_BLOCKED: File "${normRel}" is certified frozen and immutable.`);
    }
  }

  /**
   * Applies an approved write request with atomic, verifiable semantics.
   */
  public applyWrite(
    request: ControlledWriteRequest,
    context: ControlledWriteContext
  ): WorkspaceChangeRecord {
    const changeId = `CHG-${Date.now()}-${crypto.randomBytes(3).toString('hex').toUpperCase()}`;
    const timestamp = new Date().toISOString();

    // 1. Permanent Safety Invariant check
    if (!ControlledWorkspaceWriter.IS_ACTUATION_BLOCKED) {
      throw new Error('CRITICAL_SECURITY_BREACH: IS_ACTUATION_BLOCKED safety invariant has been tampered with.');
    }

    // 2. Validate containment and symlinks
    let canonicalTarget: string;
    let normalizedRelative: string;
    try {
      const containment = this.validateContainment(request.targetFilePath, context.workspaceRoot);
      canonicalTarget = containment.canonicalTarget;
      normalizedRelative = containment.normalizedRelative;
    } catch (err: any) {
      return {
        changeId,
        taskId: request.taskId,
        targetFilePath: request.targetFilePath,
        operation: request.operation,
        status: 'REJECTED',
        bytesWritten: 0,
        lineEnding: 'LF',
        diffSummary: 'None (Containment violation)',
        verifiedOnDisk: false,
        errorMessage: err.message,
        timestamp,
      };
    }

    // 3. Validate protected authorities
    try {
      this.validateProtectedAuthorities(canonicalTarget, context.workspaceRoot);
    } catch (err: any) {
      return {
        changeId,
        taskId: request.taskId,
        targetFilePath: normalizedRelative,
        operation: request.operation,
        status: 'REJECTED',
        bytesWritten: 0,
        lineEnding: 'LF',
        diffSummary: 'None (Protected authority tampering attempt)',
        verifiedOnDisk: false,
        errorMessage: err.message,
        timestamp,
      };
    }

    // 4. Validate allowedFiles scope
    try {
      this.validateAllowedScope(canonicalTarget, normalizedRelative, context.allowedFiles, context.workspaceRoot);
    } catch (err: any) {
      return {
        changeId,
        taskId: request.taskId,
        targetFilePath: normalizedRelative,
        operation: request.operation,
        status: 'REJECTED',
        bytesWritten: 0,
        lineEnding: 'LF',
        diffSummary: 'None (Scope violation)',
        verifiedOnDisk: false,
        errorMessage: err.message,
        timestamp,
      };
    }

    // 5. Determine whether workspace is disposable test workspace
    // Under SAFE-005: isDisposableWorkspace is only valid if workspaceRoot is physically in os.tmpdir()
    const isOsTmpRoot = (() => {
      try {
        const osTmp = fs.existsSync(os.tmpdir()) ? fs.realpathSync(os.tmpdir()) : path.resolve(os.tmpdir());
        const root = fs.existsSync(context.workspaceRoot) ? fs.realpathSync(context.workspaceRoot) : path.resolve(context.workspaceRoot);
        const rel = path.relative(osTmp, root);
        return !rel.startsWith('..') && !path.isAbsolute(rel);
      } catch {
        return false;
      }
    })();

    const isDisposable =
      (context.isDisposableWorkspace === true && isOsTmpRoot) ||
      (context.policy === 'DISPOSABLE_AUTO_APPLY' &&
        ControlledWorkspaceWriter.isDisposablePath(normalizedRelative, context.workspaceRoot));

    // 6. Approval check for real workspace edits
    if (!isDisposable) {
      const requiredAction = ControlledWorkspaceWriter.createApprovalAction(
        normalizedRelative,
        request.proposedContent
      );

      const isApproved = this.securityGuard.verifyApprovalToken({
        taskId: request.taskId,
        action: requiredAction,
        token: request.approvalToken,
      });

      if (!isApproved) {
        return {
          changeId,
          taskId: request.taskId,
          targetFilePath: normalizedRelative,
          operation: request.operation,
          status: 'APPROVAL_REQUIRED',
          bytesWritten: 0,
          lineEnding: 'LF',
          diffSummary: 'Proposed modification awaiting explicit user approval token.',
          verifiedOnDisk: false,
          errorMessage: `APPROVAL_REQUIRED: Modification to real workspace file "${normalizedRelative}" requires explicit token for action "${requiredAction}".`,
          timestamp,
        };
      }
    }

    // 7. Inspect existing file & verify baseline hash
    const fileExists = fs.existsSync(canonicalTarget);
    let originalContent = '';
    let baselineSha256: string | undefined;
    let targetLineEnding: 'CRLF' | 'LF' = process.platform === 'win32' ? 'CRLF' : 'LF';

    if (fileExists) {
      originalContent = fs.readFileSync(canonicalTarget, 'utf8');
      baselineSha256 = this.computeSha256(originalContent);
      targetLineEnding = this.detectLineEnding(originalContent);

      if (request.expectedBaselineSha256) {
        if (baselineSha256.toUpperCase() !== request.expectedBaselineSha256.toUpperCase()) {
          return {
            changeId,
            taskId: request.taskId,
            targetFilePath: normalizedRelative,
            operation: request.operation,
            status: 'FAILED',
            baselineSha256,
            bytesWritten: 0,
            lineEnding: targetLineEnding,
            diffSummary: 'Stale baseline conflict',
            verifiedOnDisk: false,
            errorMessage: `STALE_BASELINE_CONFLICT: Expected baseline SHA-256 ${request.expectedBaselineSha256}, but disk contains ${baselineSha256}.`,
            timestamp,
          };
        }
      }
    } else {
      if (request.operation === 'MODIFY') {
        return {
          changeId,
          taskId: request.taskId,
          targetFilePath: normalizedRelative,
          operation: request.operation,
          status: 'FAILED',
          bytesWritten: 0,
          lineEnding: targetLineEnding,
          diffSummary: 'File not found',
          verifiedOnDisk: false,
          errorMessage: `FILE_NOT_FOUND_FOR_MODIFICATION: Target file "${normalizedRelative}" does not exist for MODIFY operation.`,
          timestamp,
        };
      }
    }

    // 8. Normalize proposed content line endings to preserve target formatting
    const normalizedContent = this.normalizeLineEndings(request.proposedContent, targetLineEnding);

    // 9. No-op detection
    if (fileExists && originalContent === normalizedContent) {
      return {
        changeId,
        taskId: request.taskId,
        targetFilePath: normalizedRelative,
        operation: request.operation,
        status: 'APPLIED_AND_VERIFIED',
        baselineSha256,
        postWriteSha256: baselineSha256,
        bytesWritten: 0,
        lineEnding: targetLineEnding,
        diffSummary: 'NO_OP: Content is identical to existing file.',
        verifiedOnDisk: true,
        timestamp,
      };
    }

    // 10. Atomic write via sibling temp file (NO UNSAFE COPY OVERWRITE FALLBACK!)
    const targetDir = path.dirname(canonicalTarget);
    if (!fs.existsSync(targetDir)) {
      fs.mkdirSync(targetDir, { recursive: true });
    }

    const tempFile = `${canonicalTarget}.tmp.${crypto.randomBytes(4).toString('hex')}`;
    let bytesWritten = 0;

    try {
      const buffer = Buffer.from(normalizedContent, 'utf8');
      bytesWritten = buffer.length;

      // Write and fsync temp file
      const fd = fs.openSync(tempFile, 'w');
      fs.writeSync(fd, buffer);
      fs.fsyncSync(fd);
      fs.closeSync(fd);

      // Atomic rename: fail-closed on rename failure without unsafe copy overwrite!
      fs.renameSync(tempFile, canonicalTarget);
    } catch (writeErr: any) {
      return {
        changeId,
        taskId: request.taskId,
        targetFilePath: normalizedRelative,
        operation: request.operation,
        status: 'FAILED',
        baselineSha256,
        bytesWritten: 0,
        lineEnding: targetLineEnding,
        diffSummary: 'Atomic write failed; original file preserved untouched.',
        verifiedOnDisk: false,
        errorMessage: `ATOMIC_WRITE_FAILED: ${writeErr.message || String(writeErr)}`,
        timestamp,
      };
    } finally {
      // Clean up orphaned temp file if it still exists
      if (fs.existsSync(tempFile)) {
        try {
          fs.unlinkSync(tempFile);
        } catch {}
      }
    }

    // 11. Immediate Post-Write Disk Re-Read Verification
    try {
      const postDiskContent = fs.readFileSync(canonicalTarget, 'utf8');
      const postWriteSha256 = this.computeSha256(postDiskContent);

      if (request.expectedPostSha256) {
        if (postWriteSha256.toUpperCase() !== request.expectedPostSha256.toUpperCase()) {
          return {
            changeId,
            taskId: request.taskId,
            targetFilePath: normalizedRelative,
            operation: request.operation,
            status: 'FAILED',
            baselineSha256,
            postWriteSha256,
            bytesWritten,
            lineEnding: targetLineEnding,
            diffSummary: 'Post-write hash mismatch on disk',
            verifiedOnDisk: false,
            errorMessage: `POST_WRITE_HASH_MISMATCH: Expected ${request.expectedPostSha256}, got ${postWriteSha256}.`,
            timestamp,
          };
        }
      }

      const diffSummary = this.generateDiffSummary(originalContent, postDiskContent);

      return {
        changeId,
        taskId: request.taskId,
        targetFilePath: normalizedRelative,
        operation: request.operation,
        status: 'APPLIED_AND_VERIFIED',
        baselineSha256,
        postWriteSha256,
        bytesWritten,
        lineEnding: targetLineEnding,
        diffSummary,
        verifiedOnDisk: true,
        timestamp,
      };
    } catch (verifyErr: any) {
      return {
        changeId,
        taskId: request.taskId,
        targetFilePath: normalizedRelative,
        operation: request.operation,
        status: 'FAILED',
        baselineSha256,
        bytesWritten,
        lineEnding: targetLineEnding,
        diffSummary: 'Verification read failed',
        verifiedOnDisk: false,
        errorMessage: `POST_WRITE_VERIFICATION_FAILED: ${verifyErr.message || String(verifyErr)}`,
        timestamp,
      };
    }
  }
}
