/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-014 — MAA (Mathematics Agent)
 * src/cubio/agents/maa/types.ts
 *
 * Authoritative contracts, request/report interfaces, derivation steps,
 * verification models, and safety boundary constraints for MAA.
 */

export type MAATaskType =
  | 'ARITHMETIC_EVALUATION'
  | 'ALGEBRAIC_SIMPLIFICATION'
  | 'MODULAR_ANALYSIS'
  | 'EQUATION_SOLVING'
  | 'STATISTICAL_SUMMARY'
  | 'MATRIX_CALCULATION'
  | 'WORD_PROBLEM_RESOLUTION';

export type MAARequestStatus =
  | 'SUCCEEDED'
  | 'PARTIAL'
  | 'INVALID_SYNTAX'
  | 'DIVISION_BY_ZERO'
  | 'BOUNDS_EXCEEDED'
  | 'BLOCKED'
  | 'FAILED'
  | 'TIMED_OUT'
  | 'CANCELLED';

export interface MAABoundsConfig {
  readonly maxExpressionLength: number; // default: 10,000 chars
  readonly maxNestingDepth: number; // default: 50
  readonly maxExecutionMs: number; // default: 10,000 ms
  readonly maxOutputBytes: number; // default: 131,072 bytes (128 KB)
  readonly maxMatrixDimension: number; // default: 100
  readonly maxNumberMagnitude: number; // default: 1e15 (prevents unsafe integer overflow)
}

export const DEFAULT_MAA_BOUNDS: MAABoundsConfig = Object.freeze({
  maxExpressionLength: 10_000,
  maxNestingDepth: 50,
  maxExecutionMs: 10_000,
  maxOutputBytes: 131_072,
  maxMatrixDimension: 100,
  maxNumberMagnitude: 1e15,
});

export interface MAAMathematicsRequest {
  readonly requestId: string;
  readonly taskId: string;
  readonly taskType: MAATaskType;
  readonly expression?: string;
  readonly prompt?: string;
  readonly variables?: Readonly<Record<string, number | string>>;
  readonly matrixA?: readonly (readonly number[])[];
  readonly matrixB?: readonly (readonly number[])[];
  readonly numericList?: readonly number[];
  readonly bounds?: Partial<MAABoundsConfig>;
  readonly bypassActuationLock?: boolean; // Attacker test payload - must be rejected
}

export interface MAADerivationStep {
  readonly stepNumber: number;
  readonly rule: string;
  readonly expressionBefore: string;
  readonly expressionAfter: string;
  readonly explanation: string;
}

export interface MAAVerificationRecord {
  readonly verified: boolean;
  readonly method: 'DUAL_EVALUATION' | 'REVERSE_OPERATION' | 'INVARIANT_CHECK' | 'FORMAL_PROOF' | 'NONE';
  readonly tolerance: number;
  readonly delta: number;
  readonly details: string;
}

export interface MAAMathematicsReport {
  readonly reportId: string;
  readonly requestId: string;
  readonly taskId: string;
  readonly taskType: MAATaskType;
  readonly status: MAARequestStatus;
  readonly resultValue?: number | string | boolean | readonly (readonly number[])[];
  readonly formattedResult: string;
  readonly explanation: string;
  readonly derivationSteps: readonly MAADerivationStep[];
  readonly verification: MAAVerificationRecord;
  readonly boundsEnforced: MAABoundsConfig;
  readonly executionDurationMs: number;
  readonly generatedAt: string;
  readonly reportChecksum: string;
  readonly is_actuation_blocked: true;
}
