/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-012 — RRA (Research & Retrieval Agent)
 * src/cubio/agents/rra/retrievalAdapter.ts
 *
 * Integrates CubiOResearchIntelligenceEngine and MEAMemoryAgent.
 * Enforces bounded offline collection, provenance checksums, and secret scrubbing.
 */

import * as crypto from 'crypto';
import { CubiOResearchIntelligenceEngine } from '../../intelligence/universal/research/researchIntelligenceEngine';
import { MEAMemoryAgent } from '../mea/memoryAgent';
import { OutputSanitizer } from '../cea/outputSanitizer';
import { RRASourceReference, RRASourceScope } from './types';

export class RetrievalAdapter {
  private readonly researchEngine: CubiOResearchIntelligenceEngine;
  private readonly memoryAgent: MEAMemoryAgent;

  constructor(
    customResearchEngine?: CubiOResearchIntelligenceEngine,
    customMemoryAgent?: MEAMemoryAgent
  ) {
    this.researchEngine = customResearchEngine || new CubiOResearchIntelligenceEngine();
    this.memoryAgent = customMemoryAgent || new MEAMemoryAgent();
  }

  /**
   * Retrieves sources across authorized scopes within maxSources limit.
   */
  public async retrieveSources(
    query: string,
    authorizedScopes: readonly RRASourceScope[],
    maxSources: number
  ): Promise<readonly RRASourceReference[]> {
    const results: RRASourceReference[] = [];
    const seenUris = new Set<string>();

    // 1. Sovereign KB / Research Intelligence Engine
    if (authorizedScopes.includes('SOVEREIGN_KB')) {
      try {
        const rawSources = await this.researchEngine.collectSources(query, maxSources);
        for (const s of rawSources) {
          if (!seenUris.has(s.url)) {
            seenUris.add(s.url);
            const sanitizedSnippet = OutputSanitizer.sanitize(s.snippet, 1024).sanitizedText;
            const contentChecksum = crypto
              .createHash('sha256')
              .update(s.fullContent || s.snippet, 'utf8')
              .digest('hex');

            results.push(
              Object.freeze({
                sourceId: s.sourceId,
                sourceType: 'SOVEREIGN_KB',
                title: s.title,
                uriOrLocation: s.url,
                snippet: sanitizedSnippet,
                reliabilityScore: s.reliabilityScore,
                domainCategory: s.domainCategory,
                publishedDate: s.publishedDate,
                author: s.author,
                contentChecksum,
              })
            );
          }
          if (results.length >= maxSources) break;
        }
      } catch (err) {
        // Fallback / log failure gracefully
      }
    }

    // 2. Project Memory / MEA
    if (results.length < maxSources && authorizedScopes.includes('PROJECT_MEMORY')) {
      try {
        const keywords = query.split(/\s+/).filter((k) => k.length >= 3);
        const meaBundle = await this.memoryAgent.retrieveContext({
          keywords,
          minRelevanceScore: 0.1,
        });

        for (const item of meaBundle.items) {
          if (!seenUris.has(item.sourcePathOrKey)) {
            seenUris.add(item.sourcePathOrKey);
            const sanitizedSnippet = OutputSanitizer.sanitize(item.snippet, 1024).sanitizedText;
            const contentChecksum =
              item.provenanceHash ||
              crypto.createHash('sha256').update(item.snippet, 'utf8').digest('hex');

            results.push(
              Object.freeze({
                sourceId: item.id,
                sourceType: 'PROJECT_MEMORY',
                title: item.title,
                uriOrLocation: item.sourcePathOrKey,
                snippet: sanitizedSnippet,
                reliabilityScore: Math.min(1.0, Math.max(0.1, item.relevanceScore)),
                domainCategory: 'TECHNICAL_ENGINEERING',
                contentChecksum,
              })
            );
          }
          if (results.length >= maxSources) break;
        }
      } catch (err) {
        // Safe continuation
      }
    }

    return Object.freeze(results.slice(0, maxSources));
  }

  public getResearchEngine(): CubiOResearchIntelligenceEngine {
    return this.researchEngine;
  }

  public getMemoryAgent(): MEAMemoryAgent {
    return this.memoryAgent;
  }
}
