/**
 * CUBiO State-T Architecture - StateTransition Operator
 */

import { StateTLifecycle } from './StateT';

export class StateTransition {
  static isValidTransition(current: StateTLifecycle, nextState: StateTLifecycle): boolean {
    if (current === StateTLifecycle.IDLE) {
      return nextState === StateTLifecycle.ROOT_ACTIVE || nextState === StateTLifecycle.INVALID_INPUT;
    }
    if (current === StateTLifecycle.ROOT_ACTIVE) {
      return nextState === StateTLifecycle.TRAJECTORY_ACTIVE || nextState === StateTLifecycle.INVALID_TRANSITION;
    }
    if (current === StateTLifecycle.TRAJECTORY_ACTIVE) {
      return nextState === StateTLifecycle.SPATIALIZED || nextState === StateTLifecycle.INVALID_TRANSITION;
    }
    if (current === StateTLifecycle.SPATIALIZED) {
      return nextState === StateTLifecycle.ADDRESSED || nextState === StateTLifecycle.SPATIAL_DRIFT;
    }
    if (current === StateTLifecycle.ADDRESSED) {
      return nextState === StateTLifecycle.STATE_EVALUATING || nextState === StateTLifecycle.INVALID_TRANSITION;
    }
    if (current === StateTLifecycle.STATE_EVALUATING) {
      return nextState === StateTLifecycle.STATE_TRANSITION || nextState === StateTLifecycle.INVALID_TRANSITION;
    }
    if (current === StateTLifecycle.STATE_TRANSITION) {
      return nextState === StateTLifecycle.STATE_STABLE || nextState === StateTLifecycle.STATE_CORRUPTED;
    }
    if (current === StateTLifecycle.STATE_STABLE) {
      return nextState === StateTLifecycle.STATE_COMMITTED || nextState === StateTLifecycle.ROLLBACK_REQUIRED;
    }
    if (current === StateTLifecycle.STATE_COMMITTED) {
      return nextState === StateTLifecycle.TRAJECTORY_ACTIVE || nextState === StateTLifecycle.ROLLBACK_REQUIRED;
    }
    return false;
  }
}
