/**
 * CUBiO AI - 3D Memory Studio
 * AGENT-008 - AOA (Agent Orchestration Agent)
 * src/cubio/agents/aoa/handoffResolver.ts
 *
 * Production Agent-to-Agent Data Handoff Resolver.
 * Resolves declarative AOAHandoffBinding references against completed upstream tasks,
 * verifying topological dependency declaration, upstream success state,
 * agent identity (anti-spoofing), access permissions, SHA-256 payload integrity,
 * and output key paths. Injects validated data and tamper-evident provenance.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import * as crypto from 'crypto';
import {
  AOASubtaskDefinition,
  AOASubtaskExecutionRecord,
  AOAHandoffBinding,
} from './types';

export interface HandoffResolutionOutcome {
  readonly success: boolean;
  readonly resolvedPayload: Record<string, unknown>;
  readonly error?: {
    readonly code: string;
    readonly message: string;
    readonly blockingDependency?: string;
  };
}

export class AOAHandoffResolver {
  /**
   * Resolves handoff bindings for a downstream subtask from the store of completed task records.
   */
  public static resolve(
    subtask: AOASubtaskDefinition,
    completedRecords: Map<string, AOASubtaskExecutionRecord>,
    callerPermissions: readonly string[] = []
  ): HandoffResolutionOutcome {
    const resolvedPayload: Record<string, unknown> = { ...subtask.payload };

    if (!subtask.handoffBindings || subtask.handoffBindings.length === 0) {
      return { success: true, resolvedPayload };
    }

    const boundData: Record<string, unknown> = {};
    const boundProvenance: Array<Record<string, unknown>> = [];

    for (const binding of subtask.handoffBindings) {
      // 1. Dependency Assertion: Bound task must be declared as a prerequisite dependency
      if (!subtask.dependencies.includes(binding.sourceTaskId)) {
        return {
          success: false,
          resolvedPayload,
          error: {
            code: 'UNDECLARED_DEPENDENCY_BINDING',
            message: 'Handoff source ' + binding.sourceTaskId + ' must be listed in subtask dependencies.',
            blockingDependency: binding.sourceTaskId,
          },
        };
      }

      // 2. Upstream Completion Check
      const upstream = completedRecords.get(binding.sourceTaskId);
      if (!upstream) {
        return {
          success: false,
          resolvedPayload,
          error: {
            code: 'UPSTREAM_TASK_NOT_COMPLETED',
            message: 'Prerequisite output for ' + binding.sourceTaskId + ' is missing or was not recorded.',
            blockingDependency: binding.sourceTaskId,
          },
        };
      }

      // 3. Upstream State Check (Must be SUCCEEDED)
      if (upstream.state !== 'SUCCEEDED') {
        return {
          success: false,
          resolvedPayload,
          error: {
            code: 'UPSTREAM_OUTPUT_FAILED',
            message: 'Cannot bind output from ' + binding.sourceTaskId + ' because state is ' + upstream.state,
            blockingDependency: binding.sourceTaskId,
          },
        };
      }

      // 4. Source Agent Identity Check (Anti-Spoofing / Confused Deputy Guard)
      if (upstream.agentId !== binding.sourceAgentId) {
        return {
          success: false,
          resolvedPayload,
          error: {
            code: 'AGENT_IDENTITY_MISMATCH',
            message: 'Expected source agent ' + binding.sourceAgentId + ', but task was produced by ' + upstream.agentId,
            blockingDependency: binding.sourceTaskId,
          },
        };
      }

      // 5. Access Permission Gate
      if (binding.requiredPermission && !callerPermissions.includes(binding.requiredPermission)) {
        return {
          success: false,
          resolvedPayload,
          error: {
            code: 'UNAUTHORIZED_HANDOFF_ACCESS',
            message: 'Caller lacks required permission ' + binding.requiredPermission,
            blockingDependency: binding.sourceTaskId,
          },
        };
      }

      // 6. Upstream Payload Extraction
      const upstreamResult = (upstream.resultPayload && typeof upstream.resultPayload === 'object')
        ? (upstream.resultPayload as Record<string, unknown>)
        : {};

      // 7. Cryptographic Hash / Tamper Verification
      const calculatedHash = crypto
        .createHash('sha256')
        .update(JSON.stringify(upstreamResult))
        .digest('hex');

      if (binding.integritySha256 && binding.integritySha256.toLowerCase() !== calculatedHash.toLowerCase()) {
        return {
          success: false,
          resolvedPayload,
          error: {
            code: 'INTEGRITY_TAMPER_DETECTED',
            message: 'Hash mismatch on upstream output ' + binding.sourceTaskId,
            blockingDependency: binding.sourceTaskId,
          },
        };
      }

      // 8. Key Path Extraction (Supports top-level key or dotted path)
      const extractedValue = this.extractValue(upstreamResult, binding.outputKeyPath);
      if (extractedValue === undefined) {
        return {
          success: false,
          resolvedPayload,
          error: {
            code: 'OUTPUT_KEYPATH_MALFORMED',
            message: 'Key path ' + binding.outputKeyPath + ' does not exist on upstream result from ' + binding.sourceTaskId,
            blockingDependency: binding.sourceTaskId,
          },
        };
      }

      // 9. Bind extracted value
      const targetKey = binding.targetParameterKey || binding.outputKeyPath;
      boundData[targetKey] = extractedValue;

      // Also directly bind into resolvedPayload top-level if targetParameterKey is specified
      resolvedPayload[targetKey] = extractedValue;

      boundProvenance.push({
        sourceTaskId: binding.sourceTaskId,
        sourceAgentId: binding.sourceAgentId,
        outputKeyPath: binding.outputKeyPath,
        targetParameterKey: targetKey,
        integrityHash: calculatedHash,
        consumedAt: Date.now(),
      });
    }

    resolvedPayload['upstreamInputs'] = Object.freeze(boundData);
    resolvedPayload['handoffProvenance'] = Object.freeze(boundProvenance);

    return {
      success: true,
      resolvedPayload,
    };
  }

  private static extractValue(target: Record<string, unknown>, path: string): unknown {
    if (!path || typeof path !== 'string') return undefined;
    if (Object.prototype.hasOwnProperty.call(target, path)) {
      return target[path];
    }

    const segments = path.split('.');
    let curr: any = target;
    for (const seg of segments) {
      if (curr === null || curr === undefined || typeof curr !== 'object') {
        return undefined;
      }
      curr = curr[seg];
    }
    return curr;
  }
}
