/**
 * CUBiO Frontend & UI Agent (FUA) Types & Interfaces
 * Agent ID: AGENT-017-FUA
 * Canonical Name: Frontend & UI Agent
 * Permanent Invariant: IS_ACTUATION_BLOCKED = true
 */

export const FUA_AGENT_ID = 'AGENT-017-FUA' as const;
export const FUA_AGENT_NAME = 'Frontend & UI Agent' as const;
export const FUA_VERSION = '1.0.0' as const;

export type FUATaskType =
  | 'COMPONENT_SPECIFICATION'
  | 'DESIGN_SYSTEM_ALIGNMENT'
  | 'LAYOUT_RESPONSIVE_ANALYSIS'
  | 'ACCESSIBILITY_AUDIT'
  | 'FRONTEND_SCAFFOLDING'
  | 'UI_REPOSITORY_INVENTORY';

export type FUAComponentCategory =
  | 'PRIMITIVE'
  | 'COMPOSITE'
  | 'MODAL'
  | 'DRAWER'
  | 'LAYOUT_SHELL'
  | 'PANEL'
  | 'CANVAS_VIEW';

export interface FUAPropDefinition {
  name: string;
  type: string;
  required: boolean;
  defaultValue?: string;
  description: string;
}

export interface FUAStateDefinition {
  name: string;
  type: string;
  initialValue: string;
  description: string;
}

export interface FUAEventDefinition {
  name: string;
  payloadType: string;
  description: string;
}

export interface FUAAccessibilityRule {
  role?: string;
  ariaLabels?: string[];
  keyboardInteractions?: string[];
  focusManagement?: string;
  wcagCriterion?: string;
}

export interface FUAResponsiveBehavior {
  mobileBreakpoint?: string;
  tabletBreakpoint?: string;
  desktopBreakpoint?: string;
  hideOnMobile?: boolean;
  collapseToDrawer?: boolean;
}

export interface FUAComponentSpec {
  componentName: string;
  category: FUAComponentCategory;
  description: string;
  props: FUAPropDefinition[];
  state: FUAStateDefinition[];
  events: FUAEventDefinition[];
  accessibility: FUAAccessibilityRule;
  responsive: FUAResponsiveBehavior;
  designTokens: string[];
  suggestedIcons?: string[];
}

export interface FUAAccessibilityFinding {
  element: string;
  issue: string;
  wcagLevel: 'A' | 'AA' | 'AAA';
  recommendation: string;
}

export interface FUAAccessibilityAudit {
  target: string;
  score: number; // 0 - 100
  passedRules: string[];
  violations: FUAAccessibilityFinding[];
  isWcagCompliant: boolean;
}

export interface FUADesignTokens {
  theme: string;
  colors: Record<string, string>;
  spacing: string[];
  typography: Record<string, string>;
  borderRadius: Record<string, string>;
  icons: string[];
}

export interface FUAScaffoldProposal {
  componentName: string;
  targetPath: string;
  framework: string;
  generatedCode: string;
  cdaHandoffTrace?: string;
  isActuationBlocked: boolean;
}

export interface FUABoundsConfig {
  maxComponents: number;
  maxPropsPerComponent: number;
  maxAuditFindings: number;
  maxExecutionTimeMs: number;
}

export const DEFAULT_FUA_BOUNDS: FUABoundsConfig = {
  maxComponents: 50,
  maxPropsPerComponent: 30,
  maxAuditFindings: 50,
  maxExecutionTimeMs: 10000,
};

export interface FUARequest {
  taskId: string;
  taskType: FUATaskType;
  componentName?: string;
  category?: FUAComponentCategory;
  targetPath?: string;
  rawRequirements?: string;
  context?: Record<string, any>;
  bounds?: Partial<FUABoundsConfig>;
}

export interface FUAReport {
  taskId: string;
  agentId: typeof FUA_AGENT_ID;
  taskType: FUATaskType;
  success: boolean;
  timestamp: string;
  isActuationBlocked: boolean;
  componentSpecs?: FUAComponentSpec[];
  accessibilityAudits?: FUAAccessibilityAudit[];
  designTokens?: FUADesignTokens;
  scaffoldProposals?: FUAScaffoldProposal[];
  inventorySummary?: {
    totalComponentsFound: number;
    directoriesScanned: string[];
    components: string[];
  };
  metrics: {
    durationMs: number;
    itemsProcessed: number;
  };
  errors?: string[];
  signature: string;
}
