/**
 * CUBiO Storage Inventory Adapter
 * Identifies and maps storage services, database files, and adapters.
 */

import * as fs from 'fs';
import * as path from 'path';
import { DSAStorageServiceDescriptor } from './types';

export class StorageInventoryAdapter {
  private readonly projectRoot: string;

  constructor(projectRoot: string = process.cwd()) {
    this.projectRoot = projectRoot;
  }

  public getStorageServices(): DSAStorageServiceDescriptor[] {
    const services: DSAStorageServiceDescriptor[] = [];

    // 1. Canonical VDB
    const canonicalDbPath = path.join(this.projectRoot, 'data', 'cubio_studio.db');
    if (fs.existsSync(canonicalDbPath)) {
      services.push({
        serviceName: 'Canonical VDB SQLite Database',
        sourcePath: 'data/cubio_studio.db',
        isAuthoritative: true,
        persistenceType: 'SQLITE_DISK',
        supportedOperations: ['SELECT', 'INDEX_SCAN', 'READ_ONLY_ACCESS'],
        boundIndexes: [
          'idx_records_type',
          'idx_records_dim',
          'idx_records_class',
          'idx_records_cluster',
        ],
      });
    }

    // 2. Funnel 71 SQLiteDataStore
    const sqlitePersistPath = path.join(this.projectRoot, 'src', 'funnel71', 'persistence', 'sqlitePersistence.ts');
    if (fs.existsSync(sqlitePersistPath)) {
      services.push({
        serviceName: 'SQLiteDataStore (Funnel 71)',
        sourcePath: 'src/funnel71/persistence/sqlitePersistence.ts',
        isAuthoritative: true,
        persistenceType: 'SQLITE_DISK',
        supportedOperations: ['get', 'getAll', 'query', 'create', 'update', 'remove', 'clear', 'hydrate'],
        boundIndexes: ['idx_records_type', 'idx_records_dim', 'idx_records_class', 'idx_records_cluster'],
      });
    }

    // 3. Virtual Data Storage Adapter
    const virtStoragePath = path.join(this.projectRoot, 'src', 'cubio', 'virtual_data', 'storageAdapter.ts');
    if (fs.existsSync(virtStoragePath)) {
      services.push({
        serviceName: 'SQLiteStorageAdapter (Virtual Data Service)',
        sourcePath: 'src/cubio/virtual_data/storageAdapter.ts',
        isAuthoritative: false, // Adapter layer wrapping authoritative store
        persistenceType: 'SQLITE_DISK',
        supportedOperations: ['get', 'getAll', 'save', 'delete', 'close'],
        boundIndexes: ['idx_records_type'],
      });
    }

    // 4. Read-Only VDB Adapter
    const roVdbPath = path.join(this.projectRoot, 'src', 'research', 'infinitylm', 'vdbReadOnlyAdapter.ts');
    if (fs.existsSync(roVdbPath)) {
      services.push({
        serviceName: 'Phase26VdbReadOnlyAdapter',
        sourcePath: 'src/research/infinitylm/vdbReadOnlyAdapter.ts',
        isAuthoritative: false, // Read-only consumer
        persistenceType: 'SQLITE_DISK',
        supportedOperations: ['getTotalRecordCount', 'getRecordById', 'getRecords', 'mapCellIdToPackedAddress'],
        boundIndexes: ['PRIMARY_KEY_id'],
      });
    }

    // 5. Funnel 02 Checkpoint Serializer
    const checkpointPath = path.join(this.projectRoot, 'src', 'funnel02', 'checkpoint.ts');
    if (fs.existsSync(checkpointPath)) {
      services.push({
        serviceName: 'Deterministic Checkpoint Serializer (Funnel 02)',
        sourcePath: 'src/funnel02/checkpoint.ts',
        isAuthoritative: false, // Snapshot/backup format, not primary live DB
        persistenceType: 'CHECKPOINT_BUNDLE',
        supportedOperations: ['serializeCheckpoint', 'verifyCheckpoint', 'restoreCheckpoint'],
        boundIndexes: ['MERKLE_ROOT_cells', 'MERKLE_ROOT_addresses'],
      });
    }

    return services;
  }
}
