import { AOAOrchestrationRequest, AOABoundsConfig, DEFAULT_AOA_BOUNDS } from './types';
import { AgentRegistryAdapter } from './agentRegistryAdapter';

export interface ValidationOutcome {
  readonly isValid: boolean;
  readonly errors: readonly string[];
  readonly sanitizedRequest?: AOAOrchestrationRequest;
}

export class TaskValidator {
  constructor(
    private readonly registry: AgentRegistryAdapter,
    private readonly bounds: AOABoundsConfig = DEFAULT_AOA_BOUNDS
  ) {}

  public validate(request: unknown): ValidationOutcome {
    const errors: string[] = [];

    if (!request || typeof request !== 'object' || Array.isArray(request)) {
      return { isValid: false, errors: ['Request must be a non-null JSON object.'] };
    }

    const req = request as Partial<AOAOrchestrationRequest>;

    if (!req.orchestrationId || typeof req.orchestrationId !== 'string' || !req.orchestrationId.trim()) {
      errors.push('orchestrationId is mandatory and must be a non-empty string.');
    }

    if (!req.objective || typeof req.objective !== 'string' || !req.objective.trim()) {
      errors.push('objective is mandatory and must be a non-empty string.');
    }

    if (!Array.isArray(req.subtasks)) {
      errors.push('subtasks must be an array of subtask definitions.');
      return { isValid: false, errors };
    }

    if (req.subtasks.length === 0) {
      errors.push('subtasks array cannot be empty.');
    }

    if (req.subtasks.length > this.bounds.maxSubtasksPerOrchestration) {
      errors.push('subtasks count (' + req.subtasks.length + ') exceeds maximum limit of ' + this.bounds.maxSubtasksPerOrchestration + '.');
    }

    const subtaskIds = new Set<string>();

    for (let i = 0; i < req.subtasks.length; i++) {
      const st = req.subtasks[i];
      if (!st || typeof st !== 'object') {
        errors.push('subtask[' + i + '] is malformed.');
        continue;
      }

      if (!st.subtaskId || typeof st.subtaskId !== 'string' || !st.subtaskId.trim()) {
        errors.push('subtask[' + i + '].subtaskId is required.');
      } else {
        if (subtaskIds.has(st.subtaskId)) {
          errors.push('Duplicate subtaskId detected: ' + st.subtaskId);
        }
        subtaskIds.add(st.subtaskId);
      }

      if (!st.targetAgentId || typeof st.targetAgentId !== 'string' || !st.targetAgentId.trim()) {
        errors.push('subtask[' + i + '].targetAgentId is required.');
      } else {
        const agent = this.registry.getAgent(st.targetAgentId);
        if (!agent) {
          errors.push('subtask[' + i + ']: Unknown agent ' + st.targetAgentId);
        } else if (agent.descriptor.status === 'PLANNED') {
          errors.push('subtask[' + i + ']: Agent ' + st.targetAgentId + ' is PLANNED and not yet implemented/callable.');
        }
      }

      if (!st.payload || typeof st.payload !== 'object') {
        errors.push('subtask[' + i + '].payload must be a valid object.');
      }

      if (st.dependencies && !Array.isArray(st.dependencies)) {
        errors.push('subtask[' + i + '].dependencies must be an array of strings.');
      }

      if (st.handoffBindings !== undefined) {
        if (!Array.isArray(st.handoffBindings)) {
          errors.push('subtask[' + i + '].handoffBindings must be an array of handoff binding objects.');
        } else {
          for (let bIdx = 0; bIdx < st.handoffBindings.length; bIdx++) {
            const b = st.handoffBindings[bIdx];
            if (!b || typeof b !== 'object') {
              errors.push('subtask[' + i + '].handoffBindings[' + bIdx + '] is malformed.');
              continue;
            }
            if (!b.sourceTaskId || typeof b.sourceTaskId !== 'string') {
              errors.push('subtask[' + i + '].handoffBindings[' + bIdx + '].sourceTaskId is required and must be a string.');
            }
            if (!b.sourceAgentId || typeof b.sourceAgentId !== 'string') {
              errors.push('subtask[' + i + '].handoffBindings[' + bIdx + '].sourceAgentId is required and must be a string.');
            }
            if (!b.outputKeyPath || typeof b.outputKeyPath !== 'string') {
              errors.push('subtask[' + i + '].handoffBindings[' + bIdx + '].outputKeyPath is required and must be a string.');
            }
          }
        }
      }

      if (st.requiredSkills !== undefined) {
        if (!Array.isArray(st.requiredSkills)) {
          errors.push('subtask[' + i + '].requiredSkills must be an array of skill ID strings.');
        } else {
          for (let sIdx = 0; sIdx < st.requiredSkills.length; sIdx++) {
            const skillId = st.requiredSkills[sIdx];
            if (!skillId || typeof skillId !== 'string') {
              errors.push('subtask[' + i + '].requiredSkills[' + sIdx + '] must be a non-empty string.');
            }
          }
        }
      }
    }

    for (const st of req.subtasks) {
      if (Array.isArray(st.dependencies)) {
        for (const depId of st.dependencies) {
          if (!subtaskIds.has(depId)) {
            errors.push('Subtask ' + st.subtaskId + ' references non-existent dependency ' + depId);
          }
          if (depId === st.subtaskId) {
            errors.push('Subtask ' + st.subtaskId + ' cannot depend on itself.');
          }
        }

        if (Array.isArray(st.handoffBindings)) {
          for (const b of st.handoffBindings) {
            if (b && b.sourceTaskId && !st.dependencies.includes(b.sourceTaskId)) {
              errors.push('Subtask ' + st.subtaskId + ' has handoff binding to ' + b.sourceTaskId + ' which is not declared in dependencies.');
            }
          }
        }
      }
    }

    const stringified = JSON.stringify(request).toLowerCase();
    if (stringified.includes('actuation_override') || stringified.includes('bypass_actuation')) {
      errors.push('Prohibited parameter: Hardware actuation override attempt blocked.');
    }

    if (errors.length > 0) {
      return { isValid: false, errors };
    }

    const sanitizedSubtasks = (req.subtasks || []).map((st) => ({
      ...st,
      dependencies: Array.isArray(st.dependencies) ? st.dependencies : [],
    }));

    const sanitized: AOAOrchestrationRequest = {
      ...(req as AOAOrchestrationRequest),
      subtasks: sanitizedSubtasks as any,
    };

    return { isValid: true, errors: [], sanitizedRequest: sanitized };
  }
}
