/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-009 — CEA (Code Execution Agent)
 * src/cubio/agents/cea/executionEvidence.ts
 *
 * Captures reproducible execution evidence and computes deterministic
 * SHA-256 provenance hashes over canonical JSON records.
 */

import * as crypto from 'crypto';
import { CEARequest, CEAResult, CEALifecycleState } from './types';

export class ExecutionEvidence {
  /**
   * Computes deterministic SHA-256 hash over canonical execution result fields.
   */
  public static computeEvidenceHash(resultPayload: {
    requestId: string;
    taskId: string;
    commandId: string;
    status: CEALifecycleState;
    exitCode: number | null;
    stdoutHash: string;
    stderrHash: string;
    durationMs: number;
    policyVersion: string;
    isActuationBlocked: boolean;
  }): string {
    const canonicalString = JSON.stringify({
      requestId: resultPayload.requestId,
      taskId: resultPayload.taskId,
      commandId: resultPayload.commandId,
      status: resultPayload.status,
      exitCode: resultPayload.exitCode,
      stdoutHash: resultPayload.stdoutHash,
      stderrHash: resultPayload.stderrHash,
      durationMs: resultPayload.durationMs,
      policyVersion: resultPayload.policyVersion,
      isActuationBlocked: resultPayload.isActuationBlocked,
    });

    return crypto.createHash('sha256').update(canonicalString, 'utf8').digest('hex');
  }

  /**
   * Hashes text content safely using SHA-256.
   */
  public static hashContent(content: string): string {
    return crypto.createHash('sha256').update(content || '', 'utf8').digest('hex');
  }

  /**
   * Formats execution result as GitHub Markdown evidence record.
   */
  public static formatMarkdownReport(result: CEAResult): string {
    return [
      `# CEA Code Execution Evidence: \`${result.requestId}\``,
      `**Task ID**: \`${result.taskId}\`  `,
      `**Command ID**: \`${result.commandId}\`  `,
      `**Final Status**: \`${result.status}\`  `,
      `**Exit Code**: \`${result.exitCode ?? 'N/A'}\`  `,
      `**Duration**: ${result.durationMs}ms  `,
      `**Evidence SHA-256**: \`${result.evidenceHash}\`  `,
      `**Actuation Lock**: \`${result.isActuationBlocked}\`  `,
      `**Sandbox Verified**: \`${result.sandboxVerified}\`  `,
      `**Truncated**: \`${result.truncated}\`  `,
      '',
      '### Standard Output',
      '```text',
      result.stdout ? result.stdout.trim() : '(Empty)',
      '```',
      '',
      result.stderr ? '### Standard Error\n```text\n' + result.stderr.trim() + '\n```' : '',
      result.failureReason ? `> **Failure Reason**: ${result.failureReason}` : '',
    ]
      .filter(Boolean)
      .join('\n');
  }
}
