/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-016 — SAA (System Architecture Agent)
 * src/cubio/agents/saa/types.ts
 *
 * Core type contracts for AGENT-016-SAA.
 * Defines architecture requests, component inventory, relationships,
 * finding classifications, contract validation, and structured reports.
 */

export type SAATaskType =
  | 'ARCHITECTURE_AUDIT'
  | 'COMPONENT_INVENTORY'
  | 'DEPENDENCY_CYCLE_ANALYSIS'
  | 'INTERFACE_CONTRACT_VALIDATION'
  | 'LAYER_BOUNDARY_CHECK'
  | 'RECOMMEND_CORRECTION';

export type SAAFindingCategory =
  | 'CIRCULAR_DEPENDENCY'
  | 'DISCONNECTED_MODULE'
  | 'DUPLICATE_RESPONSIBILITY'
  | 'LAYER_BOUNDARY_VIOLATION'
  | 'MISSING_CONTRACT'
  | 'REGISTRY_BINDING_MISMATCH'
  | 'ORPHAN_COMPONENT'
  | 'INSUFFICIENT_EVIDENCE'
  | 'ARCHITECTURE_DRIFT';

export type SAASeverity = 'CRITICAL' | 'HIGH' | 'MEDIUM' | 'LOW' | 'INFO';

export type SAAConfidenceLevel = 'VERIFIED' | 'HIGH' | 'MEDIUM' | 'INFERRED' | 'UNCERTAIN';

export type SAAContractStatus =
  | 'CONSISTENT'
  | 'INCONSISTENT'
  | 'MISSING_CONTRACT'
  | 'DISCONNECTED'
  | 'DUPLICATE_RESPONSIBILITY'
  | 'INSUFFICIENT_EVIDENCE'
  | 'NOT_APPLICABLE';

export type SAAReportStatus =
  | 'SUCCEEDED'
  | 'FAILED'
  | 'BLOCKED'
  | 'PARTIAL'
  | 'NEEDS_MORE_EVIDENCE';

export interface SAABoundsConfig {
  readonly maxFilesToInspect: number; // default: 200
  readonly maxRelationshipsToMap: number; // default: 500
  readonly maxFindingsCount: number; // default: 100
  readonly maxExecutionMs: number; // default: 15,000 ms
}

export const DEFAULT_SAA_BOUNDS: SAABoundsConfig = Object.freeze({
  maxFilesToInspect: 200,
  maxRelationshipsToMap: 500,
  maxFindingsCount: 100,
  maxExecutionMs: 15_000,
});

export interface SAARequestScope {
  readonly targetSubsystems?: readonly string[];
  readonly targetFilePaths?: readonly string[];
  readonly targetAgents?: readonly string[];
  readonly customFiles?: Readonly<Record<string, string>>; // In-memory inspection fixture
}

export interface SAATaskRequest {
  readonly requestId: string;
  readonly taskId: string;
  readonly taskType?: SAATaskType;
  readonly objective: string;
  readonly scope?: SAARequestScope;
  readonly bounds?: Partial<SAABoundsConfig>;
  readonly bypassActuationLock?: boolean; // Security adversarial test flag - must be rejected
  readonly generateMermaidDiagram?: boolean;
}

export interface SAAComponentRecord {
  readonly componentId: string;
  readonly name: string;
  readonly sourcePath: string;
  readonly exportedSymbols: readonly string[];
  readonly importedModules: readonly string[];
  readonly declaredSubsystem?: string;
  readonly isFrozenAuthority: boolean;
  readonly lineCount?: number;
  readonly complexity?: 'LOW' | 'MEDIUM' | 'HIGH' | 'EXTREME';
}

export interface SAARelationshipRecord {
  readonly fromComponentId: string;
  readonly toComponentId: string;
  readonly relationshipType: 'IMPORTS' | 'DEPENDS_ON' | 'BINDS_INVOKER' | 'VIOLATES_BOUNDARY';
  readonly isDirect: boolean;
}

export interface SAAFindingRecord {
  readonly findingId: string;
  readonly category: SAAFindingCategory;
  readonly severity: SAASeverity;
  readonly confidence: SAAConfidenceLevel;
  readonly title: string;
  readonly description: string;
  readonly affectedComponents: readonly string[];
  readonly evidenceReferences: readonly string[];
  readonly expectedContract?: string;
  readonly observedDiscrepancy?: string;
  readonly recommendedAction?: string;
  readonly status: 'ACTIVE' | 'RESOLVED' | 'SUPPRESSED';
}

export interface SAAContractValidationRecord {
  readonly targetId: string;
  readonly contractType: 'AGENT_REGISTRY' | 'SUBSYSTEM_BOUNDARY' | 'FROZEN_AUTHORITY' | 'INTERFACE_SIGNATURE';
  readonly status: SAAContractStatus;
  readonly declaredContract: string;
  readonly observedBehavior: string;
  readonly evidencePath: string;
}

export interface SAARecommendationRecord {
  readonly recommendationId: string;
  readonly title: string;
  readonly rationale: string;
  readonly targetComponents: readonly string[];
  readonly regressionRisks: readonly string[];
  readonly impact: 'HIGH' | 'MEDIUM' | 'LOW';
}

export interface SAAReport {
  readonly reportId: string;
  readonly requestId: string;
  readonly taskId: string;
  readonly status: SAAReportStatus;
  readonly summary: string;
  readonly componentInventory: readonly SAAComponentRecord[];
  readonly relationships: readonly SAARelationshipRecord[];
  readonly contractValidations: readonly SAAContractValidationRecord[];
  readonly findings: readonly SAAFindingRecord[];
  readonly recommendations: readonly SAARecommendationRecord[];
  readonly mermaidDiagram?: string;
  readonly executionDurationMs: number;
  readonly generatedAt: string;
  readonly reportChecksum: string;
  readonly is_actuation_blocked: true;
}
