/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-014 — MAA (Mathematics Agent)
 * src/cubio/agents/maa/expressionValidator.ts
 *
 * Safe AST / Expression Validator.
 * Tokenizes and checks input expressions without dynamic JavaScript execution (eval/Function).
 * Rejects injections, prototype pollution, dangerous characters, and excessively deep nesting.
 */

import { MAABoundsConfig } from './types';

export interface ValidationSuccess {
  readonly isValid: true;
  readonly sanitizedExpression: string;
  readonly depth: number;
}

export interface ValidationFailure {
  readonly isValid: false;
  readonly reason: string;
  readonly errorCode: 'INJECTION_DETECTED' | 'EXPRESSION_TOO_LONG' | 'NESTING_TOO_DEEP' | 'INVALID_CHARACTERS' | 'EMPTY_EXPRESSION';
}

export type ExpressionValidationResult = ValidationSuccess | ValidationFailure;

export class ExpressionValidator {
  private static readonly DISALLOWED_PATTERNS: readonly RegExp[] = [
    /\b(eval|Function|require|import|process|global|window|document)\b/i,
    /__proto__|prototype|constructor/i,
    /[;{}[\]`$\\]/,
    /<script/i,
    /=>/,
  ];

  public static validate(
    rawExpression: string,
    bounds: MAABoundsConfig
  ): ExpressionValidationResult {
    const trimmed = (rawExpression || '').trim();

    if (!trimmed) {
      return {
        isValid: false,
        reason: 'Mathematical expression is empty',
        errorCode: 'EMPTY_EXPRESSION',
      };
    }

    if (trimmed.length > bounds.maxExpressionLength) {
      return {
        isValid: false,
        reason: `Expression length (${trimmed.length}) exceeds maximum limit (${bounds.maxExpressionLength})`,
        errorCode: 'EXPRESSION_TOO_LONG',
      };
    }

    // Check for dangerous code injection patterns
    for (const pattern of this.DISALLOWED_PATTERNS) {
      if (pattern.test(trimmed)) {
        return {
          isValid: false,
          reason: `Potentially unsafe script injection or restricted token detected: ${pattern.source}`,
          errorCode: 'INJECTION_DETECTED',
        };
      }
    }

    // Verify parenthesis balance and max nesting depth
    let depth = 0;
    let maxDepth = 0;
    for (let i = 0; i < trimmed.length; i++) {
      const char = trimmed[i];
      if (char === '(') {
        depth++;
        if (depth > maxDepth) maxDepth = depth;
        if (depth > bounds.maxNestingDepth) {
          return {
            isValid: false,
            reason: `Parenthesis nesting depth (${depth}) exceeds maximum limit (${bounds.maxNestingDepth})`,
            errorCode: 'NESTING_TOO_DEEP',
          };
        }
      } else if (char === ')') {
        depth--;
        if (depth < 0) {
          return {
            isValid: false,
            reason: 'Mismatched parentheses: unexpected closing parenthesis ")"',
            errorCode: 'INVALID_CHARACTERS',
          };
        }
      }
    }

    if (depth !== 0) {
      return {
        isValid: false,
        reason: 'Mismatched parentheses: unclosed parenthesis "("',
        errorCode: 'INVALID_CHARACTERS',
      };
    }

    return {
      isValid: true,
      sanitizedExpression: trimmed,
      depth: maxDepth,
    };
  }
}
