/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-020 — RDA (Release & Deployment Agent)
 * src/cubio/agents/rda/releaseDeploymentAgent.ts
 *
 * Sovereign facade for AGENT-020-RDA.
 * Enforces permanent actuation lockout, non-destructive read-only release
 * evaluations, deterministic cryptographic manifest generation, secret scanning,
 * and fail-closed security gates.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import * as crypto from 'crypto';
import {
  RDA_AGENT_ID,
  RDA_AGENT_NAME,
  RDA_VERSION,
  RDARequest,
  RDAReport,
  RDABoundsConfig,
  DEFAULT_RDA_BOUNDS,
  RDATaskType,
} from './types';
import { SecretScanner } from './secretScanner';
import { ArtifactManifestGenerator } from './artifactManifestGenerator';
import { ReleaseReadinessEvaluator } from './releaseReadinessEvaluator';

export class ReleaseDeploymentAgent {
  public static readonly AGENT_ID = RDA_AGENT_ID;
  public static readonly AGENT_NAME = RDA_AGENT_NAME;
  public static readonly VERSION = RDA_VERSION;

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public get is_actuation_blocked(): boolean {
    return true;
  }

  private readonly bounds: RDABoundsConfig;
  private readonly secretScanner: SecretScanner;
  private readonly manifestGenerator: ArtifactManifestGenerator;
  private readonly readinessEvaluator: ReleaseReadinessEvaluator;

  constructor(customBounds?: Partial<RDABoundsConfig>, customRootDir?: string) {
    this.bounds = { ...DEFAULT_RDA_BOUNDS, ...(customBounds || {}) };
    this.secretScanner = new SecretScanner();
    this.manifestGenerator = new ArtifactManifestGenerator(this.bounds, customRootDir);
    this.readinessEvaluator = new ReleaseReadinessEvaluator(this.bounds, customRootDir);
  }

  /**
   * Public invoke entrypoint for AOA and general callers.
   */
  public async invoke(payload: Record<string, unknown>): Promise<RDAReport> {
    return this.execute(payload as unknown as RDARequest);
  }

  /**
   * Main task execution pipeline.
   */
  public async execute(request: RDARequest): Promise<RDAReport> {
    // 1. Fail closed on empty/null request
    if (!request || !request.taskId) {
      return this.generateFailedClosedReport(
        request?.taskId || 'REQ-UNKNOWN',
        'Request payload is null, undefined, or missing taskId.'
      );
    }

    // 2. Validate supported task type
    const validTasks: RDATaskType[] = [
      'RELEASE_READINESS_AUDIT',
      'DRY_RUN_PREPARATION',
      'VALIDATE_DEPENDENCIES',
      'SCAN_SECRETS_SECURITY',
      'GENERATE_RELEASE_MANIFEST',
      'VALIDATE_ARTIFACT_INTEGRITY',
      'FULL_RELEASE_EVALUATION',
    ];

    if (!validTasks.includes(request.taskType)) {
      return this.generateFailedClosedReport(
        request.taskId,
        `Unsupported task type: ${request.taskType}`
      );
    }

    try {
      const isDryRun = request.isDryRun ?? true;

      // 3. Run readiness evaluation
      const evalResult = this.readinessEvaluator.evaluate(request);

      // 4. Generate manifest if dry-run or release requested
      const artifactPaths = request.context?.customArtifactPaths || [
        'package.json',
        'data/cubio_studio.db',
        'src/core/address369.ts',
      ];

      const manifest = this.manifestGenerator.generateManifest(
        `REL-${request.taskId}`,
        request.targetVersion || '1.0.0',
        artifactPaths,
        isDryRun,
        request.context?.targetEnvironment || 'staging'
      );

      const passedChecks = evalResult.checks.filter(c => c.status === 'PASS').length;
      const failedChecks = evalResult.checks.filter(c => c.status === 'FAIL').length;
      const blockedChecks = evalResult.checks.filter(c => c.status === 'BLOCKED').length;

      const reportId = `RDA-REP-${Date.now()}`;
      const evaluatedTimestamp = new Date().toISOString();

      const rawContent = JSON.stringify({
        reportId,
        taskId: request.taskId,
        outcome: evalResult.outcome,
        isDryRun,
        checks: evalResult.checks,
        manifest,
      });

      const signature = crypto.createHash('sha256').update(rawContent).digest('hex');

      return {
        reportId,
        taskId: request.taskId,
        agentId: RDA_AGENT_ID,
        version: RDA_VERSION,
        outcome: evalResult.outcome,
        isActuationBlocked: true,
        isDryRun,
        evaluatedTimestamp,
        totalChecks: evalResult.checks.length,
        passedChecks,
        failedChecks,
        blockedChecks,
        checks: evalResult.checks,
        manifest,
        remediationPlan: evalResult.remediationPlan,
        limitations: evalResult.limitations,
        signature,
      };
    } catch (err: any) {
      return this.generateFailedClosedReport(
        request.taskId,
        `Unexpected execution error in RDA: ${err.message}`
      );
    }
  }

  /**
   * Helper to construct a safe fail-closed report.
   */
  private generateFailedClosedReport(taskId: string, errorReason: string): RDAReport {
    const reportId = `RDA-FAIL-${Date.now()}`;
    const timestamp = new Date().toISOString();
    const signature = crypto.createHash('sha256').update(reportId + taskId + errorReason).digest('hex');

    return {
      reportId,
      taskId,
      agentId: RDA_AGENT_ID,
      version: RDA_VERSION,
      outcome: 'FAILED',
      isActuationBlocked: true,
      isDryRun: true,
      evaluatedTimestamp: timestamp,
      totalChecks: 1,
      passedChecks: 0,
      failedChecks: 1,
      blockedChecks: 0,
      checks: [
        {
          checkId: 'CHK-ERR-01',
          name: 'Input & Execution Safety Guard',
          category: 'PROTECTED_INVARIANTS',
          status: 'FAIL',
          severity: 'CRITICAL',
          evidence: errorReason,
        },
      ],
      remediationPlan: [errorReason],
      limitations: ['Execution halted fail-closed due to validation or runtime guard trip.'],
      signature,
    };
  }
}
