/**
 * CUBiO Data & Storage Agent (DSA) Facade
 * Agent ID: AGENT-018-DSA
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import {
  DSA_AGENT_ID,
  DSA_AGENT_NAME,
  DSA_VERSION,
  DSARequest,
  DSAReport,
  DEFAULT_DSA_BOUNDS,
  DSABoundsConfig,
} from './types';
import { StorageInventoryAdapter } from './storageInventoryAdapter';
import { StorageContractInspector } from './storageContractInspector';
import { QueryAnalysisAdapter } from './queryAnalysisAdapter';
import { DataIntegrityAnalyzer } from './dataIntegrityAnalyzer';
import { MemoryLifecycleAnalyzer } from './memoryLifecycleAnalyzer';
import { CheckpointAdapter } from './checkpointAdapter';
import { StorageReportBuilder } from './storageReportBuilder';

export class DataStorageAgent {
  public readonly id = DSA_AGENT_ID;
  public readonly name = DSA_AGENT_NAME;
  public readonly version = DSA_VERSION;
  public readonly is_actuation_blocked: boolean = true;

  private readonly inventoryAdapter: StorageInventoryAdapter;
  private readonly contractInspector: StorageContractInspector;
  private readonly queryAdapter: QueryAnalysisAdapter;
  private readonly integrityAnalyzer: DataIntegrityAnalyzer;
  private readonly lifecycleAnalyzer: MemoryLifecycleAnalyzer;
  private readonly checkpointAdapter: CheckpointAdapter;
  private readonly reportBuilder: StorageReportBuilder;

  constructor(options?: {
    inventoryAdapter?: StorageInventoryAdapter;
    contractInspector?: StorageContractInspector;
    queryAdapter?: QueryAnalysisAdapter;
    integrityAnalyzer?: DataIntegrityAnalyzer;
    lifecycleAnalyzer?: MemoryLifecycleAnalyzer;
    checkpointAdapter?: CheckpointAdapter;
    reportBuilder?: StorageReportBuilder;
  }) {
    this.inventoryAdapter = options?.inventoryAdapter || new StorageInventoryAdapter();
    this.contractInspector = options?.contractInspector || new StorageContractInspector(this.inventoryAdapter);
    this.queryAdapter = options?.queryAdapter || new QueryAnalysisAdapter();
    this.integrityAnalyzer = options?.integrityAnalyzer || new DataIntegrityAnalyzer();
    this.lifecycleAnalyzer = options?.lifecycleAnalyzer || new MemoryLifecycleAnalyzer();
    this.checkpointAdapter = options?.checkpointAdapter || new CheckpointAdapter();
    this.reportBuilder = options?.reportBuilder || new StorageReportBuilder();
  }

  public async executeTask(request: DSARequest): Promise<DSAReport> {
    const startTime = Date.now();
    const bounds: DSABoundsConfig = { ...DEFAULT_DSA_BOUNDS, ...(request.bounds || {}) };
    const errors: string[] = [];

    // Permanent Safety Invariant Enforced
    if (!this.is_actuation_blocked) {
      throw new Error(`CRITICAL_SECURITY_BREACH: ${this.id} actuation lock is violated.`);
    }

    // Input Validation
    if (!request.taskId || !request.taskType) {
      errors.push('INVALID_REQUEST: taskId and taskType are strictly required.');
      return this.reportBuilder.buildReport(
        request,
        this.id,
        this.is_actuation_blocked,
        false,
        startTime,
        0,
        errors
      );
    }

    try {
      switch (request.taskType) {
        case 'STORAGE_INVENTORY': {
          const services = this.inventoryAdapter.getStorageServices();
          const bounded = services.slice(0, bounds.maxFindings);
          return this.reportBuilder.buildReport(
            request,
            this.id,
            this.is_actuation_blocked,
            true,
            startTime,
            bounded.length,
            errors,
            { inventory: bounded }
          );
        }

        case 'STORAGE_CONTRACT_AUDIT': {
          const { descriptors, findings } = this.contractInspector.auditStorageContracts();
          return this.reportBuilder.buildReport(
            request,
            this.id,
            this.is_actuation_blocked,
            true,
            startTime,
            descriptors.length,
            errors,
            {
              inventory: descriptors.slice(0, bounds.maxFindings),
              findings: findings.slice(0, bounds.maxFindings),
            }
          );
        }

        case 'QUERY_EFFICIENCY_ANALYSIS': {
          const query = request.targetPathOrQuery || 'SELECT * FROM studio_records';
          const analysis = this.queryAdapter.analyzeQuery(query);
          return this.reportBuilder.buildReport(
            request,
            this.id,
            this.is_actuation_blocked,
            true,
            startTime,
            1,
            errors,
            { queryAnalysis: [analysis] }
          );
        }

        case 'DATA_INTEGRITY_CHECK': {
          const target = request.targetPathOrQuery || 'StudioRecordFixture';
          const records = Array.isArray(request.rawPayload) ? request.rawPayload : [];
          const boundedRecords = records.slice(0, bounds.maxInspectedRecords);
          const integrityReport = this.integrityAnalyzer.validateRecords(target, boundedRecords);
          return this.reportBuilder.buildReport(
            request,
            this.id,
            this.is_actuation_blocked,
            true,
            startTime,
            boundedRecords.length,
            errors,
            { integrity: integrityReport }
          );
        }

        case 'MEMORY_LIFECYCLE_AUDIT': {
          const comp = request.targetPathOrQuery || 'MemoryTierCache';
          const lifecycle = this.lifecycleAnalyzer.evaluateComponentLifecycle(
            comp,
            request.rawPayload || request.context || {}
          );
          return this.reportBuilder.buildReport(
            request,
            this.id,
            this.is_actuation_blocked,
            true,
            startTime,
            1,
            errors,
            { lifecycle }
          );
        }

        case 'CHECKPOINT_VALIDATION': {
          const checkpointReport = this.checkpointAdapter.validateCheckpointMetadata(
            request.rawPayload
          );
          return this.reportBuilder.buildReport(
            request,
            this.id,
            this.is_actuation_blocked,
            true,
            startTime,
            1,
            errors,
            { checkpoint: checkpointReport }
          );
        }

        default: {
          errors.push(`UNKNOWN_TASK_TYPE: Unsupported taskType '${(request as any).taskType}'`);
          return this.reportBuilder.buildReport(
            request,
            this.id,
            this.is_actuation_blocked,
            false,
            startTime,
            0,
            errors
          );
        }
      }
    } catch (err: any) {
      errors.push(`EXECUTION_ERROR: ${err.message || String(err)}`);
      return this.reportBuilder.buildReport(
        request,
        this.id,
        this.is_actuation_blocked,
        false,
        startTime,
        0,
        errors
      );
    }
  }
}
