/**
 * CUBiO Storage Report Builder
 * Formats structured findings and computes cryptographic SHA-256 report signatures.
 */

import * as crypto from 'crypto';
import { DSAReport, DSARequest } from './types';

export class StorageReportBuilder {
  public buildReport(
    request: DSARequest,
    agentId: 'AGENT-018-DSA',
    isActuationBlocked: boolean,
    success: boolean,
    startTime: number,
    itemsInspected: number,
    errors: string[],
    additionalData?: Partial<DSAReport>
  ): DSAReport {
    const durationMs = Date.now() - startTime;

    const partialReport: Omit<DSAReport, 'signature'> = {
      taskId: request.taskId,
      agentId,
      taskType: request.taskType,
      success,
      timestamp: new Date().toISOString(),
      isActuationBlocked,
      metrics: {
        durationMs,
        itemsInspected,
      },
      errors: errors.length > 0 ? errors : undefined,
      ...additionalData,
    };

    const signature = crypto
      .createHash('sha256')
      .update(JSON.stringify(partialReport))
      .digest('hex');

    return {
      ...partialReport,
      signature,
    };
  }
}
