/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-015 — BFA (Bug-Fixing Agent)
 * src/cubio/agents/bfa/fixProposalBuilder.ts
 *
 * Constructs structured, non-destructive, auditable fix proposals.
 * Enforces strict boundary checks (rejects path traversal and protected files).
 */

import * as crypto from 'crypto';
import { BFAFixProposal } from './types';
import { FrozenProtectionGuard } from '../../language/native/pma/frozenProtectionGuard';

export class BFAFixProposalBuilder {
  private readonly frozenGuard: FrozenProtectionGuard;

  constructor(customRootDir?: string) {
    this.frozenGuard = new FrozenProtectionGuard(customRootDir);
  }

  public buildProposal(params: {
    defectId: string;
    targetFilePath?: string;
    originalCode?: string;
    proposedPatch: string;
    diffSummary: string;
    rationale: string;
    linesModified?: readonly number[];
  }): BFAFixProposal {
    const rawTarget = params.targetFilePath || 'src/cubio/unspecified.ts';
    const normalizedTarget = rawTarget.replace(/\\/g, '/');

    let status: 'PROPOSED' | 'INVALID' | 'BLOCKED' = 'PROPOSED';
    const risks: string[] = [];

    // 1. Boundary & Path Traversal Check
    if (
      normalizedTarget.includes('../') ||
      normalizedTarget.startsWith('/') ||
      /^[a-zA-Z]:/.test(normalizedTarget)
    ) {
      status = 'INVALID';
      risks.push('Path traversal attempt detected or absolute drive path forbidden.');
    }

    // 2. Frozen File Boundary Check
    if (this.frozenGuard.isProtected(normalizedTarget)) {
      status = 'BLOCKED';
      risks.push(`Modification of protected frozen authority blocked: ${normalizedTarget}`);
    }

    const proposalId = `FIX_PROP_${crypto.randomBytes(4).toString('hex')}`;
    const checksumPayload = JSON.stringify({
      proposalId,
      defectId: params.defectId,
      targetFilePath: normalizedTarget,
      proposedPatch: params.proposedPatch,
      status,
    });
    const proposalChecksum = crypto.createHash('sha256').update(checksumPayload).digest('hex');

    return Object.freeze({
      proposalId,
      defectId: params.defectId,
      targetFilePath: normalizedTarget,
      diffSummary: params.diffSummary,
      originalSnippet: params.originalCode,
      proposedSnippet: params.proposedPatch,
      linesModified: params.linesModified || [1],
      rationale: params.rationale,
      proposalChecksum,
      status,
      potentialRisks: Object.freeze(risks),
    });
  }
}
