/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-016 — SAA (System Architecture Agent)
 * src/cubio/agents/saa/dependencyAnalysisAdapter.ts
 *
 * Wraps DRA and DependencyAnalyzer to evaluate component relationships,
 * dependency cycles, topological sorting, and orphan modules.
 */

import {
  SAAComponentRecord,
  SAARelationshipRecord,
  SAAFindingRecord,
  SAABoundsConfig,
} from './types';
import { DRADependencyAgent } from '../dra/dependencyAgent';
import { DependencyAnalyzer } from '../../intelligence/universal/coding/analysis/dependencyAnalyzer';

export class DependencyAnalysisAdapter {
  private readonly draAgent: DRADependencyAgent;
  private readonly depAnalyzer: DependencyAnalyzer;

  constructor(customDra?: DRADependencyAgent, customDepAnalyzer?: DependencyAnalyzer) {
    this.draAgent = customDra || new DRADependencyAgent();
    this.depAnalyzer = customDepAnalyzer || new DependencyAnalyzer();
  }

  /**
   * Analyzes dependencies across components, mapping relationships and identifying cycles & orphans.
   */
  public analyzeDependencies(
    components: readonly SAAComponentRecord[],
    customFiles?: Readonly<Record<string, string>>,
    bounds?: SAABoundsConfig
  ): {
    relationships: readonly SAARelationshipRecord[];
    findings: readonly SAAFindingRecord[];
    cycles: readonly (readonly [string, string])[];
  } {
    const relationships: SAARelationshipRecord[] = [];
    const findings: SAAFindingRecord[] = [];
    const maxRel = bounds ? bounds.maxRelationshipsToMap : 500;

    // 1. If customFiles are present, run DependencyAnalyzer for detailed cycle & orphan detection
    let rawCycles: (readonly [string, string])[] = [];
    if (customFiles && Object.keys(customFiles).length > 0) {
      const depReport = this.depAnalyzer.analyzeDependencies(customFiles);
      rawCycles = depReport.circularDependencies;

      // Map circular dependency findings
      for (const [modA, modB] of depReport.circularDependencies) {
        findings.push({
          findingId: `FIND_CYCLE_${findings.length + 1}`,
          category: 'CIRCULAR_DEPENDENCY',
          severity: 'HIGH',
          confidence: 'VERIFIED',
          title: `Circular Dependency Detected: ${modA} <--> ${modB}`,
          description: `Direct cyclic reference detected between module ${modA} and ${modB}. Violates unidirectional architecture DAG.`,
          affectedComponents: [modA, modB],
          evidenceReferences: [modA, modB],
          expectedContract: 'Unidirectional acyclic dependency hierarchy (AOA/DRA standard)',
          observedDiscrepancy: `Two-way import loop between ${modA} and ${modB}`,
          recommendedAction: `Decouple modules using dependency inversion or common interface abstraction.`,
          status: 'ACTIVE',
        });
      }

      // Map orphan module findings
      for (const orphan of depReport.isolatedOrphanModules) {
        findings.push({
          findingId: `FIND_ORPHAN_${findings.length + 1}`,
          category: 'DISCONNECTED_MODULE',
          severity: 'LOW',
          confidence: 'MEDIUM',
          title: `Isolated Orphan Component: ${orphan}`,
          description: `Module ${orphan} neither imports nor is imported by any inspected component in the current analysis scope.`,
          affectedComponents: [orphan],
          evidenceReferences: [orphan],
          expectedContract: 'Components should be registered, invoked, or integrated into parent subsystems',
          observedDiscrepancy: 'Zero incoming and zero outgoing references in analyzed scope',
          recommendedAction: 'Verify whether module is an entry point, test harness, or deprecated code.',
          status: 'ACTIVE',
        });
      }
    }

    // 2. Build relationships from component import statements
    const compMap = new Map<string, SAAComponentRecord>();
    for (const c of components) {
      compMap.set(c.componentId, c);
    }

    for (const comp of components) {
      if (relationships.length >= maxRel) break;
      for (const imp of comp.importedModules) {
        if (relationships.length >= maxRel) break;

        // Check if imported target corresponds to a known in-scope component
        let matchedTarget: string | undefined;
        for (const targetId of compMap.keys()) {
          if (targetId.includes(imp) || imp.includes(targetId)) {
            matchedTarget = targetId;
            break;
          }
        }

        const targetId = matchedTarget || imp;
        relationships.push({
          fromComponentId: comp.componentId,
          toComponentId: targetId,
          relationshipType: 'IMPORTS',
          isDirect: true,
        });
      }
    }

    return {
      relationships: Object.freeze(relationships),
      findings: Object.freeze(findings),
      cycles: Object.freeze(rawCycles),
    };
  }

  /**
   * Delegates subsystem-level topological and cycle analysis to DRA.
   */
  public async analyzeSubsystems(subsystems: readonly string[]) {
    return this.draAgent.analyzeDependenciesAndReuse({
      prompt: 'System architecture subsystem topology audit',
      targetSubsystems: subsystems,
      auditCycles: true,
    });
  }
}
