/**
 * CUBiO Frontend & UI Agent (FUA) Facade
 * Agent ID: AGENT-017-FUA
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import * as crypto from 'crypto';
import {
  FUA_AGENT_ID,
  FUA_AGENT_NAME,
  FUA_VERSION,
  FUARequest,
  FUAReport,
  DEFAULT_FUA_BOUNDS,
  FUABoundsConfig,
  FUAComponentSpec,
} from './types';
import { FrontendInventoryAdapter } from './frontendInventoryAdapter';
import { DesignSystemAdapter } from './designSystemAdapter';
import { ComponentSpecificationBuilder } from './componentSpecificationBuilder';
import { UIAnalysisEngine } from './uiAnalysisEngine';
import { FrontendScaffoldAdapter } from './frontendScaffoldAdapter';

export class FrontendUIAgent {
  public readonly id = FUA_AGENT_ID;
  public readonly name = FUA_AGENT_NAME;
  public readonly version = FUA_VERSION;
  public readonly is_actuation_blocked: boolean = true;

  private readonly inventoryAdapter: FrontendInventoryAdapter;
  private readonly designSystem: DesignSystemAdapter;
  private readonly specBuilder: ComponentSpecificationBuilder;
  private readonly uiAnalysis: UIAnalysisEngine;
  private readonly scaffoldAdapter: FrontendScaffoldAdapter;

  constructor(options?: {
    inventoryAdapter?: FrontendInventoryAdapter;
    designSystem?: DesignSystemAdapter;
    specBuilder?: ComponentSpecificationBuilder;
    uiAnalysis?: UIAnalysisEngine;
    scaffoldAdapter?: FrontendScaffoldAdapter;
  }) {
    this.inventoryAdapter = options?.inventoryAdapter || new FrontendInventoryAdapter();
    this.designSystem = options?.designSystem || new DesignSystemAdapter();
    this.specBuilder = options?.specBuilder || new ComponentSpecificationBuilder(this.designSystem);
    this.uiAnalysis = options?.uiAnalysis || new UIAnalysisEngine();
    this.scaffoldAdapter = options?.scaffoldAdapter || new FrontendScaffoldAdapter();
  }

  public async executeTask(request: FUARequest): Promise<FUAReport> {
    const startTime = Date.now();
    const bounds: FUABoundsConfig = { ...DEFAULT_FUA_BOUNDS, ...(request.bounds || {}) };
    const errors: string[] = [];

    // Permanent Safety Invariant Enforced
    if (!this.is_actuation_blocked) {
      throw new Error(`CRITICAL_SECURITY_BREACH: ${this.id} actuation lock is violated.`);
    }

    // Input Validation
    if (!request.taskId || !request.taskType) {
      errors.push('INVALID_REQUEST: taskId and taskType are strictly required.');
      return this.buildReport(request, false, startTime, 0, errors);
    }

    try {
      switch (request.taskType) {
        case 'UI_REPOSITORY_INVENTORY': {
          const components = this.inventoryAdapter.scanFrontendComponents();
          const boundedComponents = components.slice(0, bounds.maxComponents);
          return this.buildReport(
            request,
            true,
            startTime,
            boundedComponents.length,
            errors,
            {
              inventorySummary: {
                totalComponentsFound: components.length,
                directoriesScanned: [
                  'src/components',
                  'src/cubio/web/components',
                  'src/cubio/web/agents_console',
                  'src/cubio/web',
                ],
                components: boundedComponents.map((c) => c.name),
              },
            }
          );
        }

        case 'DESIGN_SYSTEM_ALIGNMENT': {
          const tokens = this.designSystem.getTokens();
          return this.buildReport(request, true, startTime, 1, errors, {
            designTokens: tokens,
          });
        }

        case 'COMPONENT_SPECIFICATION': {
          const name = request.componentName || 'GenericComponent';
          const spec = this.specBuilder.buildSpecification(
            name,
            request.category || 'COMPOSITE',
            request.rawRequirements || ''
          );
          return this.buildReport(request, true, startTime, 1, errors, {
            componentSpecs: [spec],
          });
        }

        case 'ACCESSIBILITY_AUDIT': {
          const target = request.componentName || request.targetPath || 'ComponentTarget';
          const audit = this.uiAnalysis.performAccessibilityAudit(
            target,
            request.rawRequirements || ''
          );
          return this.buildReport(request, true, startTime, 1, errors, {
            accessibilityAudits: [audit],
          });
        }

        case 'LAYOUT_RESPONSIVE_ANALYSIS': {
          const name = request.componentName || 'LayoutTarget';
          const layout = this.uiAnalysis.analyzeResponsiveLayout(
            name,
            request.rawRequirements || ''
          );
          return this.buildReport(request, true, startTime, 1, errors, {
            inventorySummary: {
              totalComponentsFound: 1,
              directoriesScanned: [layout.layoutStrategy],
              components: layout.breakpointsSupported,
            },
          });
        }

        case 'FRONTEND_SCAFFOLDING': {
          const name = request.componentName || 'ScaffoldComponent';
          const targetPath = request.targetPath || `src/cubio/web/components/${name}.tsx`;
          const spec: FUAComponentSpec = this.specBuilder.buildSpecification(
            name,
            request.category || 'COMPOSITE',
            request.rawRequirements || ''
          );
          const proposal = await this.scaffoldAdapter.generateComponentScaffold(spec, targetPath);

          return this.buildReport(request, true, startTime, 1, errors, {
            componentSpecs: [spec],
            scaffoldProposals: [proposal],
          });
        }

        default: {
          errors.push(`UNKNOWN_TASK_TYPE: Unsupported taskType '${(request as any).taskType}'`);
          return this.buildReport(request, false, startTime, 0, errors);
        }
      }
    } catch (err: any) {
      errors.push(`EXECUTION_ERROR: ${err.message || String(err)}`);
      return this.buildReport(request, false, startTime, 0, errors);
    }
  }

  private buildReport(
    request: FUARequest,
    success: boolean,
    startTime: number,
    itemsProcessed: number,
    errors: string[],
    additionalData?: Partial<FUAReport>
  ): FUAReport {
    const durationMs = Date.now() - startTime;
    const partialReport: Omit<FUAReport, 'signature'> = {
      taskId: request.taskId,
      agentId: this.id,
      taskType: request.taskType,
      success,
      timestamp: new Date().toISOString(),
      isActuationBlocked: this.is_actuation_blocked,
      metrics: {
        durationMs,
        itemsProcessed,
      },
      errors: errors.length > 0 ? errors : undefined,
      ...additionalData,
    };

    const signature = crypto
      .createHash('sha256')
      .update(JSON.stringify(partialReport))
      .digest('hex');

    return {
      ...partialReport,
      signature,
    };
  }
}
