/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-012 — RRA (Research & Retrieval Agent)
 * src/cubio/agents/rra/researchAgent.ts
 *
 * Central facade for AGENT-012-RRA.
 * Performs evidence-grounded research, preserves provenance, detects conflicts,
 * and produces verifiable research reports.
 * Permanently locks is_actuation_blocked = true.
 */

import * as crypto from 'crypto';
import {
  RRAResearchRequest,
  RRAResearchReport,
  RRACitation,
  RRABoundsConfig,
  DEFAULT_RRA_BOUNDS,
  RRARequestStatus,
} from './types';
import { SourceRegistryAdapter } from './sourceRegistryAdapter';
import { RetrievalAdapter } from './retrievalAdapter';
import { ConflictDetector } from './conflictDetector';
import { ClaimEvidenceMapper } from './claimEvidenceMapper';
import { OutputSanitizer } from '../cea/outputSanitizer';

export class ResearchRetrievalAgent {
  public static readonly AGENT_ID = 'AGENT-012-RRA';
  public static readonly AGENT_NAME = 'Research & Retrieval Agent';
  public static readonly VERSION = '1.0.0';

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public get is_actuation_blocked(): boolean {
    return true;
  }

  private readonly bounds: RRABoundsConfig;
  private readonly retrievalAdapter: RetrievalAdapter;

  constructor(
    customBounds: RRABoundsConfig = DEFAULT_RRA_BOUNDS,
    customRetrievalAdapter?: RetrievalAdapter
  ) {
    this.bounds = customBounds;
    this.retrievalAdapter = customRetrievalAdapter || new RetrievalAdapter();
  }

  /**
   * Primary entry point: Executes a bounded, evidence-grounded research investigation.
   */
  public async research(request: RRAResearchRequest): Promise<RRAResearchReport> {
    const startTimeMs = Date.now();
    const requestId = request?.requestId || `REQ_RRA_${Date.now()}`;

    // 1. Validate request
    if (!request || typeof request !== 'object') {
      return this.buildErrorReport(requestId, '', 'FAILED', 'Invalid research request: payload is null or not an object', startTimeMs);
    }

    const query = (request.query || '').trim();
    if (query.length < this.bounds.minQueryLength) {
      return this.buildErrorReport(
        requestId,
        query,
        'FAILED',
        `Query length (${query.length}) is below minimum (${this.bounds.minQueryLength} characters)`,
        startTimeMs
      );
    }

    if (query.length > this.bounds.maxQueryLength) {
      return this.buildErrorReport(
        requestId,
        query.slice(0, 100) + '...',
        'FAILED',
        `Query length exceeds maximum limit (${this.bounds.maxQueryLength} characters)`,
        startTimeMs
      );
    }

    // 2. Validate source scopes
    const scopeValidation = SourceRegistryAdapter.validateScopes(request.authorizedSourceScopes);
    if (!scopeValidation.isValid) {
      return this.buildErrorReport(
        requestId,
        query,
        'BLOCKED',
        `Unauthorized or unapproved source scopes rejected: ${scopeValidation.rejectedScopes.join(', ')}`,
        startTimeMs
      );
    }

    // 3. Resolve bounds
    const maxSources = Math.min(
      request.maxSources || this.bounds.defaultMaxSources,
      this.bounds.hardMaxSources
    );
    const maxFindings = Math.min(
      request.maxFindings || this.bounds.defaultMaxFindings,
      this.bounds.hardMaxFindings
    );

    // 4. Retrieve sources from authorized local stores
    const sources = await this.retrievalAdapter.retrieveSources(
      query,
      scopeValidation.validScopes,
      maxSources
    );

    // 5. Detect cross-source divergences and conflicts
    const conflicts = ConflictDetector.detectConflicts(sources, query);

    // 6. Map claims and evidence
    const findings = ClaimEvidenceMapper.mapClaims(query, sources, conflicts, maxFindings);

    // 7. Format citations
    const citations: RRACitation[] = sources.map((s, idx) => ({
      index: idx + 1,
      sourceId: s.sourceId,
      title: s.title,
      uriOrLocation: s.uriOrLocation,
      inlineRef: `[^${idx + 1}]`,
      formattedReference: `[${idx + 1}] "${s.title}" — ${s.uriOrLocation}`,
    }));

    // 8. Determine final status
    let status: RRARequestStatus = 'SUCCEEDED';
    const limitations: string[] = [];

    if (sources.length === 0) {
      status = 'INSUFFICIENT_EVIDENCE';
      limitations.push('Zero relevant evidence items retrieved across approved local stores');
    } else if (conflicts.length > 0) {
      status = 'PARTIAL';
      limitations.push(`${conflicts.length} material contradiction(s) detected between sources`);
    }

    const durationMs = Date.now() - startTimeMs;
    const reportId = `REP_${crypto
      .createHash('sha256')
      .update(`${requestId}:${query}:${sources.length}:${findings.length}`)
      .digest('hex')
      .slice(0, 8)}`;

    const sanitizedQuery = OutputSanitizer.sanitize(query, 256).sanitizedText;
    const summary =
      sources.length > 0
        ? `Research on "${sanitizedQuery}" synthesized ${sources.length} source(s) and established ${findings.length} finding(s) with ${conflicts.length} contradiction(s).`
        : `Research on "${sanitizedQuery}" completed with insufficient supporting evidence.`;

    const reportChecksum = crypto
      .createHash('sha256')
      .update(
        JSON.stringify({
          reportId,
          requestId,
          query,
          sourcesCount: sources.length,
          findingsCount: findings.length,
          conflictsCount: conflicts.length,
          status,
        })
      )
      .digest('hex');

    return Object.freeze({
      reportId,
      requestId,
      query,
      status,
      sourcesRetrieved: sources,
      findings,
      conflicts,
      citations: Object.freeze(citations),
      summary,
      reportChecksum,
      durationMs,
      isActuationBlocked: true,
      limitations: Object.freeze(limitations),
      timestamp: Date.now(),
    });
  }

  /**
   * Invocation compatibility helper for AOA invoker contract.
   */
  public async invoke(payload: Record<string, unknown>): Promise<RRAResearchReport> {
    const query = typeof payload?.query === 'string' ? payload.query : (payload?.objective as string) || '';
    const req: RRAResearchRequest = {
      requestId: (payload?.requestId as string) || `AOA_RRA_${Date.now()}`,
      taskId: payload?.taskId as string,
      query,
      researchObjective: payload?.objective as string,
      authorizedSourceScopes: payload?.authorizedSourceScopes as any,
      maxSources: typeof payload?.maxSources === 'number' ? payload.maxSources : undefined,
    };
    return this.research(req);
  }

  private buildErrorReport(
    requestId: string,
    query: string,
    status: RRARequestStatus,
    errorMessage: string,
    startTimeMs: number
  ): RRAResearchReport {
    const reportId = `REP_ERR_${Date.now()}`;
    return Object.freeze({
      reportId,
      requestId,
      query,
      status,
      sourcesRetrieved: Object.freeze([]),
      findings: Object.freeze([]),
      conflicts: Object.freeze([]),
      citations: Object.freeze([]),
      summary: `Research terminated: ${errorMessage}`,
      reportChecksum: crypto.createHash('sha256').update(errorMessage).digest('hex'),
      durationMs: Date.now() - startTimeMs,
      isActuationBlocked: true,
      limitations: Object.freeze([errorMessage]),
      timestamp: Date.now(),
    });
  }
}
