/**
 * CUBiO Design System Adapter
 * Provides theme tokens, color scales, typography rules, and icon conventions.
 */

import { FUADesignTokens } from './types';

export class DesignSystemAdapter {
  private readonly tokens: FUADesignTokens;

  constructor() {
    this.tokens = {
      theme: 'CUBiO Sovereign Dark',
      colors: {
        backgroundPrimary: '#09090b', // zinc-950
        backgroundSecondary: '#18181b', // zinc-900
        backgroundTertiary: '#27272a', // zinc-800
        surfaceCard: 'rgba(24, 24, 27, 0.8)',
        borderMuted: '#27272a', // zinc-800
        borderSubtle: '#3f3f46', // zinc-700
        textPrimary: '#f4f4f5', // zinc-100
        textSecondary: '#a1a1aa', // zinc-400
        textMuted: '#71717a', // zinc-500
        accentPMA: '#e5a93c', // gold
        accentMEA: '#38bdf8', // sky-400
        accentSuccess: '#34d399', // emerald-400
        accentWarning: '#fbbf24', // amber-400
        accentError: '#f87171', // red-400
        accentPurple: '#c084fc', // purple-400
      },
      spacing: ['p-1', 'p-2', 'p-3', 'p-4', 'p-6', 'gap-2', 'gap-4', 'gap-6'],
      typography: {
        fontSans: 'ui-sans-serif, system-ui, -apple-system, sans-serif',
        fontMono: 'ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace',
        headingLarge: 'text-2xl font-bold tracking-tight',
        headingMedium: 'text-lg font-semibold',
        bodyRegular: 'text-sm text-zinc-300',
        caption: 'text-xs text-zinc-500',
      },
      borderRadius: {
        sm: 'rounded-sm',
        md: 'rounded-md',
        lg: 'rounded-lg',
        xl: 'rounded-xl',
        full: 'rounded-full',
      },
      icons: [
        'Terminal',
        'Layers',
        'Activity',
        'Shield',
        'Sliders',
        'Search',
        'Play',
        'Pause',
        'CheckCircle2',
        'XCircle',
        'AlertTriangle',
        'Info',
        'Box',
        'Cpu',
        'Maximize2',
      ],
    };
  }

  public getTokens(): FUADesignTokens {
    return { ...this.tokens };
  }

  public validateColorToken(tokenName: string): boolean {
    return tokenName in this.tokens.colors;
  }

  public getSuggestedIcon(concept: string): string {
    const lower = concept.toLowerCase();
    if (lower.includes('terminal') || lower.includes('command') || lower.includes('cli')) return 'Terminal';
    if (lower.includes('layer') || lower.includes('stack') || lower.includes('arch')) return 'Layers';
    if (lower.includes('metric') || lower.includes('health') || lower.includes('status')) return 'Activity';
    if (lower.includes('security') || lower.includes('auth') || lower.includes('gate')) return 'Shield';
    if (lower.includes('setting') || lower.includes('config')) return 'Sliders';
    if (lower.includes('search') || lower.includes('query')) return 'Search';
    if (lower.includes('play') || lower.includes('run')) return 'Play';
    if (lower.includes('stop') || lower.includes('pause')) return 'Pause';
    if (lower.includes('error') || lower.includes('fail')) return 'XCircle';
    if (lower.includes('warn')) return 'AlertTriangle';
    return 'Box';
  }
}
