/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-020 — RDA (Release & Deployment Agent)
 * src/cubio/agents/rda/artifactManifestGenerator.ts
 *
 * Scans, hashes, and generates cryptographic SHA-256 release manifests
 * for verified release artifacts.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import * as fs from 'fs';
import * as path from 'path';
import * as crypto from 'crypto';
import { RDAReleaseManifest, RDABoundsConfig, DEFAULT_RDA_BOUNDS } from './types';

export class ArtifactManifestGenerator {
  private readonly bounds: RDABoundsConfig;
  private readonly rootDir: string;

  constructor(bounds: RDABoundsConfig = DEFAULT_RDA_BOUNDS, customRootDir?: string) {
    this.bounds = bounds;
    this.rootDir = customRootDir || process.cwd();
  }

  /**
   * Generates a signed release manifest for a collection of file paths.
   */
  public generateManifest(
    releaseId: string,
    version: string,
    artifactPaths: string[],
    isDryRun: boolean = true,
    targetEnvironment: string = 'staging'
  ): RDAReleaseManifest {
    const artifacts: Array<{ path: string; sha256: string; sizeBytes: number }> = [];

    const effectivePaths = artifactPaths.slice(0, this.bounds.maxArtifacts);

    for (const relPath of effectivePaths) {
      const fullPath = path.resolve(this.rootDir, relPath);
      if (fs.existsSync(fullPath)) {
        try {
          const stats = fs.statSync(fullPath);
          if (stats.isFile() && stats.size <= this.bounds.maxFileSizeBytes) {
            const buf = fs.readFileSync(fullPath);
            const sha256 = crypto.createHash('sha256').update(buf).digest('hex').toUpperCase();
            artifacts.push({
              path: relPath.replace(/\\/g, '/'),
              sha256,
              sizeBytes: stats.size,
            });
          }
        } catch {
          // File read error skipped safely
        }
      }
    }

    // Determine commit hash safely without shell execution
    const commitHash = process.env.GIT_COMMIT || process.env.GITHUB_SHA || 'deterministic-uncommitted-local';
    const timestamp = new Date().toISOString();

    const rawPayload = JSON.stringify({
      releaseId,
      version,
      commitHash,
      timestamp,
      isActuationBlocked: true,
      isDryRun,
      targetEnvironment,
      artifacts,
    });

    const signature = crypto.createHash('sha256').update(rawPayload).digest('hex');

    return {
      releaseId,
      version,
      commitHash,
      timestamp,
      isActuationBlocked: true,
      isDryRun,
      targetEnvironment,
      artifacts,
      signature,
    };
  }

  /**
   * Verifies an existing manifest's artifacts against actual filesystem.
   */
  public verifyManifestArtifacts(manifest: RDAReleaseManifest): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    for (const art of manifest.artifacts) {
      const fullPath = path.resolve(this.rootDir, art.path);
      if (!fs.existsSync(fullPath)) {
        errors.push(`Missing artifact: ${art.path}`);
        continue;
      }

      try {
        const buf = fs.readFileSync(fullPath);
        const actualHash = crypto.createHash('sha256').update(buf).digest('hex').toUpperCase();
        if (actualHash !== art.sha256.toUpperCase()) {
          errors.push(`Hash mismatch for ${art.path}: expected ${art.sha256}, got ${actualHash}`);
        }
      } catch (err: any) {
        errors.push(`Error reading ${art.path}: ${err.message}`);
      }
    }

    return {
      valid: errors.length === 0,
      errors,
    };
  }
}
