/**
 * CUBiO UI Analysis Engine
 * Audits accessibility, responsive constraints, and hierarchy.
 */

import { FUAAccessibilityAudit, FUAAccessibilityFinding } from './types';

export class UIAnalysisEngine {
  public performAccessibilityAudit(target: string, codeOrDescription: string): FUAAccessibilityAudit {
    const violations: FUAAccessibilityFinding[] = [];
    const passedRules: string[] = [];

    const lower = codeOrDescription.toLowerCase();

    // 1. Image / Icon alt check
    if (lower.includes('<img') && !lower.includes('alt=')) {
      violations.push({
        element: 'img',
        issue: 'Image missing alt attribute',
        wcagLevel: 'A',
        recommendation: 'Add alt="" or descriptive alt text for screen readers',
      });
    } else {
      passedRules.push('Images have alternative text (WCAG 1.1.1)');
    }

    // 2. Button aria-label check
    const hasButton = lower.includes('<button') || lower.includes('role="button"');
    if (hasButton) {
      const hasAriaLabel = lower.includes('aria-label') || lower.includes('aria-labelledby');
      const hasTextContent = /<button[^>]*>[^<\s]+<\/button>/.test(codeOrDescription) || lower.includes('{children}') || lower.includes('children');
      if (!hasAriaLabel && !hasTextContent) {
        violations.push({
          element: 'button',
          issue: 'Interactive button missing accessible label or text content',
          wcagLevel: 'A',
          recommendation: 'Include aria-label or visible inner text in button',
        });
      } else {
        passedRules.push('Buttons have discernible text (WCAG 4.1.2)');
      }
    } else {
      passedRules.push('Buttons have discernible text (WCAG 4.1.2)');
    }

    // 3. Contrast & Focus indicator check
    if (lower.includes('outline-none') && !lower.includes('focus-visible:ring')) {
      violations.push({
        element: 'interactive element',
        issue: 'Focus outline removed without custom focus ring',
        wcagLevel: 'AA',
        recommendation: 'Add focus-visible:ring-2 focus-visible:ring-zinc-400 to preserve keyboard navigation',
      });
    } else {
      passedRules.push('Keyboard focus indicators present (WCAG 2.4.7)');
    }

    // 4. Dialog / Modal ARIA
    if (lower.includes('modal') || lower.includes('dialog')) {
      if (!lower.includes('role="dialog"') && !lower.includes('aria-modal="true"')) {
        violations.push({
          element: 'modal overlay',
          issue: 'Modal dialog missing role="dialog" or aria-modal="true"',
          wcagLevel: 'A',
          recommendation: 'Add role="dialog" and aria-modal="true" with aria-labelledby',
        });
      } else {
        passedRules.push('Modal dialog conforms to ARIA design pattern (WCAG 4.1.2)');
      }
    }

    const score = Math.max(0, 100 - violations.length * 25);
    const isWcagCompliant = violations.length === 0;

    return {
      target,
      score,
      passedRules,
      violations,
      isWcagCompliant,
    };
  }

  public analyzeResponsiveLayout(componentName: string, layoutHints: string): {
    breakpointsSupported: string[];
    layoutStrategy: string;
    isMobileReady: boolean;
  } {
    const isMobileReady = !layoutHints.includes('fixed-width') && !layoutHints.includes('min-w-[1200px]');
    return {
      breakpointsSupported: ['sm: 640px', 'md: 768px', 'lg: 1024px', 'xl: 1280px'],
      layoutStrategy: isMobileReady ? 'Mobile-First Fluid Flex/Grid' : 'Desktop Static Fallback',
      isMobileReady,
    };
  }
}
