import { MAADerivationStep } from './types';

export class ReasoningFormatter {
  public static formatSummary(
    taskType: string,
    steps: readonly MAADerivationStep[],
    baseExplanation: string
  ): string {
    if (!steps || steps.length === 0) {
      return baseExplanation || `Execution completed for ${taskType}`;
    }

    const stepLines = steps.map(
      (s) => `Step ${s.stepNumber} [${s.rule}]: ${s.expressionBefore} => ${s.expressionAfter} (${s.explanation})`
    );

    return `${baseExplanation}\n\nDerivation Proof:\n${stepLines.join('\n')}`;
  }
}
