/**
 * CUBiO Checkpoint Adapter
 * Validates .3dmemory checkpoint bundle metadata, headers, and Merkle tree roots.
 */

import { DSACheckpointReport } from './types';
import { FORMAT_MAGIC, SCHEMA_VERSION, TOTAL_SPATIAL_CELLS } from '../../../funnel02/constants';

export class CheckpointAdapter {
  public validateCheckpointMetadata(checkpoint: any): DSACheckpointReport {
    if (!checkpoint || typeof checkpoint !== 'object') {
      return {
        checkpointPathOrId: 'UNKNOWN',
        formatMagic: 'INVALID',
        schemaVersion: 0,
        isActuationBlocked: true,
        merkleRootValid: false,
        totalCells: 0,
        isValid: false,
      };
    }

    const header = checkpoint.header || {};
    const security = checkpoint.security || {};
    const integrity = checkpoint.integrity || {};

    const formatMagic = header.formatMagic || 'UNKNOWN';
    const schemaVersion = header.schemaVersion || 0;
    const isActuationBlocked = Boolean(security.is_actuation_blocked);
    const hasMerkleRoot = Boolean(integrity.cellsMerkleRoot && integrity.cellsMerkleRoot.length === 64);
    const totalCells = header.totalSpatialCells || (checkpoint.cells ? checkpoint.cells.length : 0);

    const isValid =
      formatMagic === FORMAT_MAGIC &&
      schemaVersion === SCHEMA_VERSION &&
      isActuationBlocked === true &&
      hasMerkleRoot &&
      totalCells === TOTAL_SPATIAL_CELLS;

    return {
      checkpointPathOrId: header.funnelName || '3D_MEMORY_CHECKPOINT',
      formatMagic,
      schemaVersion,
      isActuationBlocked,
      merkleRootValid: hasMerkleRoot,
      totalCells,
      isValid,
    };
  }
}
