/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-019 — POA (Performance Optimization Agent)
 * src/cubio/agents/poa/types.ts
 *
 * Authoritative contracts, types, bounds, findings, recommendations,
 * and baseline benchmark definitions for the Performance Optimization Agent.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

export const POA_AGENT_ID = 'AGENT-019-POA' as const;
export const POA_AGENT_NAME = 'Performance Optimization Agent' as const;
export const POA_VERSION = '1.0.0' as const;

export type POATaskType =
  | 'PROFILE_EXECUTION'
  | 'BENCHMARK_BASELINE'
  | 'ANALYZE_BOTTLENECK'
  | 'AUDIT_RESOURCES'
  | 'FULL_PERFORMANCE_AUDIT';

export type POABottleneckClassification =
  | 'MEASURED_BOTTLENECK'
  | 'STATIC_RISK'
  | 'INFERRED_CANDIDATE'
  | 'INSUFFICIENT_DATA'
  | 'NOT_MEASURED';

export type POASeverity = 'INFO' | 'WARNING' | 'CRITICAL';

export interface POALatencyPercentiles {
  readonly p50Ms: number;
  readonly p95Ms: number;
  readonly p99Ms: number;
}

export interface POARuntimeMeasurement {
  readonly label: string;
  readonly durationMs: number;
  readonly heapDeltaBytes: number;
  readonly rssDeltaBytes?: number;
  readonly timestamp: number;
  readonly successful: boolean;
  readonly error?: string;
}

export interface POABenchmarkConfig {
  readonly benchmarkId: string;
  readonly targetName: string;
  readonly iterations: number;
  readonly warmupIterations: number;
  readonly timeoutBudgetMs?: number;
}

export interface POABenchmarkResult {
  readonly benchmarkId: string;
  readonly targetName: string;
  readonly iterations: number;
  readonly warmupIterations: number;
  readonly totalDurationMs: number;
  readonly minMs: number;
  readonly maxMs: number;
  readonly averageMs: number;
  readonly percentiles: POALatencyPercentiles;
  readonly opsPerSec: number;
  readonly heapDeltaBytes: number;
  readonly isCompliant: boolean;
  readonly sampleCount: number;
  readonly environment: {
    readonly nodeVersion: string;
    readonly platform: string;
    readonly timestamp: number;
  };
}

export interface POABottleneckFinding {
  readonly findingId: string;
  readonly classification: POABottleneckClassification;
  readonly severity: POASeverity;
  readonly targetSubsystem: string;
  readonly title: string;
  readonly description: string;
  readonly evidence: string;
  readonly baselineMetrics?: {
    readonly durationMs?: number;
    readonly p95Ms?: number;
    readonly memoryDeltaBytes?: number;
    readonly complexity?: string;
  };
  readonly confidence: number; // 0.0 - 1.0
  readonly limitations?: string;
}

export interface POAOptimizationRecommendation {
  readonly recommendationId: string;
  readonly findingId: string;
  readonly owningSubsystem: string;
  readonly title: string;
  readonly proposedAction: string;
  readonly rationale: string;
  readonly expectedImpact: 'HIGH' | 'MEDIUM' | 'LOW';
  readonly riskLevel: 'LOW' | 'MEDIUM' | 'HIGH';
  readonly acceptanceCriteria: string;
  readonly requiredAuthorization: string;
  readonly requiresExternalPatchApproval: boolean;
}

export interface POABoundsConfig {
  readonly maxBenchmarkIterations: number;
  readonly maxWarmupIterations: number;
  readonly maxExecutionBudgetMs: number;
  readonly maxRetainedSamples: number;
  readonly maxReportFindings: number;
  readonly maxRecommendations: number;
  readonly heapDeltaWarningThresholdBytes: number;
  readonly p95LatencyWarningThresholdMs: number;
}

export const DEFAULT_POA_BOUNDS: POABoundsConfig = {
  maxBenchmarkIterations: 100,
  maxWarmupIterations: 10,
  maxExecutionBudgetMs: 5000,
  maxRetainedSamples: 500,
  maxReportFindings: 50,
  maxRecommendations: 20,
  heapDeltaWarningThresholdBytes: 5 * 1024 * 1024, // 5 MB
  p95LatencyWarningThresholdMs: 100,              // 100 ms
};

export interface POARequest {
  readonly taskId: string;
  readonly taskType: POATaskType;
  readonly targetSubsystem?: string;
  readonly querySqlOrComponent?: string;
  readonly benchmarkConfig?: Partial<POABenchmarkConfig>;
  readonly customBounds?: Partial<POABoundsConfig>;
  readonly payload?: Record<string, unknown>;
}

export interface POAReport {
  readonly reportId: string;
  readonly taskId: string;
  readonly status: 'SUCCEEDED' | 'FAILED' | 'BLOCKED' | 'PARTIAL';
  readonly agentId: typeof POA_AGENT_ID;
  readonly agentVersion: typeof POA_VERSION;
  readonly timestamp: number;
  readonly durationMs: number;
  readonly is_actuation_blocked: boolean;
  readonly benchmarkResult?: POABenchmarkResult;
  readonly runtimeMeasurement?: POARuntimeMeasurement;
  readonly findings: readonly POABottleneckFinding[];
  readonly recommendations: readonly POAOptimizationRecommendation[];
  readonly limitations: readonly string[];
  readonly signature: string; // 64-char hex SHA-256
}
