/**
 * CUBiO AI — 3D Memory Studio
 * Agent Skills Framework
 * src/cubio/skills/registry.ts
 *
 * Canonical in-memory registry for Agent Skills.
 * Provides skill registration, discovery by ID, discovery by capability,
 * validation, loading, and safe execution with provenance hashing.
 */

import { createHash } from 'crypto';
import {
  SkillManifest,
  SkillHandler,
  LoadedSkill,
  SkillExecutionContext,
  SkillExecutionResult,
  SkillInvocationEvidence,
  SkillError,
} from './types';
import { SkillValidator } from './validator';
import { getCanonical20Skills } from './canonicalSkills';

export interface RegisteredSkillRecord {
  readonly manifest: SkillManifest;
  readonly handler?: SkillHandler;
  readonly registeredAt: string;
}

export class SkillRegistry {
  private static instance?: SkillRegistry;
  private readonly skills: Map<string, RegisteredSkillRecord> = new Map();

  constructor() {
    this.bootstrapSampleCanonicalSkills();
  }

  /**
   * Singleton accessor for global registry.
   */
  public static getInstance(): SkillRegistry {
    if (!SkillRegistry.instance) {
      SkillRegistry.instance = new SkillRegistry();
    }
    return SkillRegistry.instance;
  }

  /**
   * Resets the registry (primarily for testing purposes).
   */
  public static resetInstance(): void {
    SkillRegistry.instance = undefined;
  }

  /**
   * Registers a new skill with preflight validation.
   */
  public registerSkill(manifest: SkillManifest, handler?: SkillHandler): void {
    const validation = SkillValidator.validateManifest(manifest);
    if (!validation.isValid) {
      throw new SkillError(
        'MALFORMED_MANIFEST',
        `Failed to register skill '${manifest?.skillId || 'UNKNOWN'}': ${validation.errors.join('; ')}`,
        validation.errors
      );
    }

    if (this.skills.has(manifest.skillId)) {
      throw new SkillError(
        'MALFORMED_MANIFEST',
        `Skill '${manifest.skillId}' is already registered in the registry.`
      );
    }

    this.skills.set(manifest.skillId, {
      manifest,
      handler,
      registeredAt: new Date().toISOString(),
    });
  }

  /**
   * Discovers a skill manifest by exact ID.
   */
  public getSkillManifest(skillId: string): SkillManifest | undefined {
    return this.skills.get(skillId)?.manifest;
  }

  /**
   * Discovers skills matching a given capability tag or query.
   */
  public discoverByCapability(capabilityTag: string): readonly SkillManifest[] {
    const normalized = capabilityTag.trim().toUpperCase();
    const results: SkillManifest[] = [];

    for (const record of this.skills.values()) {
      if (
        record.manifest.capabilities.some(
          (c) => c.toUpperCase() === normalized || c.toUpperCase().includes(normalized)
        )
      ) {
        results.push(record.manifest);
      }
    }

    return results;
  }

  /**
   * Lists all registered skill manifests.
   */
  public listAllSkills(): readonly SkillManifest[] {
    return Array.from(this.skills.values()).map((r) => r.manifest);
  }

  /**
   * Validated skill-loading interface.
   * Checks agent permission and manifest existence.
   * Loading a skill returns the validated instructions and handler without executing it.
   */
  public loadSkillForAgent(skillId: string, agentId: string): LoadedSkill {
    const record = this.skills.get(skillId);
    if (!record) {
      throw new SkillError(
        'SKILL_NOT_FOUND',
        `Skill '${skillId}' does not exist in the skill registry.`
      );
    }

    const isPermitted = SkillValidator.checkAgentPermission(record.manifest, agentId);
    if (!isPermitted) {
      throw new SkillError(
        'SKILL_DISALLOWED_FOR_AGENT',
        `Agent '${agentId}' is not authorized to access or load skill '${skillId}'. Permitted agents: ${record.manifest.permittedAgents.join(', ')}`
      );
    }

    return {
      manifest: record.manifest,
      isPermitted: true,
      handlerAvailable: !!record.handler,
      handler: record.handler,
      loadedAt: new Date().toISOString(),
    };
  }

  /**
   * Executes a registered skill with strict permission checks, timeout, and cryptographic evidence.
   */
  public async executeSkill(
    skillId: string,
    agentId: string,
    input: Record<string, unknown>,
    callerPermissions: readonly string[] = []
  ): Promise<SkillExecutionResult> {
    const startTime = Date.now();
    const executionId = `skillexec-${Date.now()}-${Math.random().toString(36).substring(2, 7)}`;
    const inputHash = createHash('sha256').update(JSON.stringify(input || {})).digest('hex');

    // 1. Load skill and assert agent authorization
    const loaded = this.loadSkillForAgent(skillId, agentId);
    const { manifest, handler } = loaded;

    // 2. Validate input schema
    const inputValidation = SkillValidator.validateInput(input, manifest.inputSchema);
    if (!inputValidation.isValid) {
      const evidence: SkillInvocationEvidence = {
        executionId,
        skillId,
        skillVersion: manifest.version,
        invokingAgentId: agentId,
        inputHashSha256: inputHash,
        executedAt: new Date().toISOString(),
        status: 'REJECTED',
      };
      return {
        success: false,
        error: `Input validation failed: ${inputValidation.errors.join('; ')}`,
        executionLatencyMs: Date.now() - startTime,
        provenance: evidence,
      };
    }

    // 3. Check handler availability
    if (!handler) {
      // Declarative instruction-only skill (provides prompt guidance to LLM/agent)
      const outputData = {
        skillType: 'DECLARATIVE_INSTRUCTION',
        instructions: manifest.instructions,
        applied: true,
      };
      const outputHash = createHash('sha256').update(JSON.stringify(outputData)).digest('hex');
      const evidence: SkillInvocationEvidence = {
        executionId,
        skillId,
        skillVersion: manifest.version,
        invokingAgentId: agentId,
        inputHashSha256: inputHash,
        outputHashSha256: outputHash,
        executedAt: new Date().toISOString(),
        status: 'SUCCESS',
      };
      return {
        success: true,
        data: outputData,
        executionLatencyMs: Date.now() - startTime,
        provenance: evidence,
      };
    }

    // 4. Execute handler with timeout safety
    const context: SkillExecutionContext = {
      skillId,
      invokingAgentId: agentId,
      callerPermissions,
      executionId,
      timeoutMs: manifest.safetyConstraints.maxTimeoutMs,
      timestamp: startTime,
    };

    let timerHandle: NodeJS.Timeout | undefined;
    try {
      const executionPromise = handler.execute(input, context);
      const timeoutPromise = new Promise<never>((_, reject) => {
        timerHandle = setTimeout(
          () => reject(new SkillError('EXECUTION_TIMEOUT', `Skill execution timed out after ${manifest.safetyConstraints.maxTimeoutMs}ms`)),
          manifest.safetyConstraints.maxTimeoutMs
        );
      });

      const result = await Promise.race([executionPromise, timeoutPromise]);
      return result;
    } catch (err: any) {
      const evidence: SkillInvocationEvidence = {
        executionId,
        skillId,
        skillVersion: manifest.version,
        invokingAgentId: agentId,
        inputHashSha256: inputHash,
        executedAt: new Date().toISOString(),
        status: 'FAILED',
      };
      return {
        success: false,
        error: err.message || 'Unknown error occurred during skill execution.',
        executionLatencyMs: Date.now() - startTime,
        provenance: evidence,
      };
    } finally {
      if (timerHandle !== undefined) {
        clearTimeout(timerHandle);
      }
    }
  }

  /**
   * Bootstraps default prototype skills and the 20 Core Agent Skills plus Ponytail code quality capability.
   */
  private bootstrapSampleCanonicalSkills(): void {
    // Bootstrap the 20 Core Skills + Shared Ponytail Capability
    const canonicalSkills = getCanonical20Skills();
    for (const def of canonicalSkills) {
      if (!this.skills.has(def.manifest.skillId)) {
        this.registerSkill(def.manifest, def.handler);
      }
    }

    // 1. Spatial Lattice Calculator (Deterministic Math Skill)
    this.registerSkill(
      {
        skillId: 'SKILL-369-LATTICE-CALC',
        name: 'Spatial 369 Lattice Transformation',
        purpose: 'Computes spatial discrete lattice mapping for cell coordinates using 369 formula.',
        version: '1.0.0',
        capabilities: ['SPATIAL_MATH', 'COORDINATE_TRANSFORM', 'LATTICE_INDEX'],
        inputSchema: {
          type: 'object',
          properties: {
            cellId: { type: 'number' },
          },
          required: ['cellId'],
        },
        outputSchema: {
          type: 'object',
          properties: {
            address369: { type: 'string' },
            modularRoot: { type: 'number' },
          },
          required: ['modularRoot'],
        },
        permittedAgents: ['AGENT-014-MAA', 'AGENT-012-SAA', 'CUBIO-NATIVE-PMA'],
        safetyConstraints: {
          allowFilesystemWrite: false,
          allowNetworkAccess: false,
          allowProcessSpawn: false,
          maxTimeoutMs: 5000,
        },
        instructions:
          'Given a cellId, calculate digital root modulo 9 (where 0 maps to 9) and return standard coordinate projection.',
      },
      {
        async execute(input: Record<string, unknown>, ctx: SkillExecutionContext): Promise<SkillExecutionResult> {
          const cellId = Number(input.cellId);
          const digitalRoot = ((cellId - 1) % 9) + 1;
          const outputData = {
            cellId,
            modularRoot: digitalRoot,
            latticeTier: digitalRoot % 3 === 0 ? 'HARMONIC_369' : 'STANDARD',
          };
          const inputHash = createHash('sha256').update(JSON.stringify(input)).digest('hex');
          const outputHash = createHash('sha256').update(JSON.stringify(outputData)).digest('hex');

          return {
            success: true,
            data: outputData,
            executionLatencyMs: 1,
            provenance: {
              executionId: ctx.executionId,
              skillId: ctx.skillId,
              skillVersion: '1.0.0',
              invokingAgentId: ctx.invokingAgentId,
              inputHashSha256: inputHash,
              outputHashSha256: outputHash,
              executedAt: new Date().toISOString(),
              status: 'SUCCESS',
            },
          };
        },
      }
    );

    // 2. Code AST Reusability Inspection (Audit Skill for DRA / SGA)
    this.registerSkill(
      {
        skillId: 'SKILL-CODE-REUSE-INSPECT',
        name: 'AST Code Reusability Inspector',
        purpose: 'Analyzes code fragments for potential duplication against canonical frozen authority records.',
        version: '1.0.0',
        capabilities: ['CODE_INSPECTION', 'REUSE_EVALUATION', 'DEPENDENCY_AUDIT'],
        inputSchema: {
          type: 'object',
          properties: {
            codeFragment: { type: 'string' },
            targetDomain: { type: 'string' },
          },
          required: ['codeFragment'],
        },
        outputSchema: {
          type: 'object',
          properties: {
            reuseRecommendation: { type: 'string' },
            conflictProbability: { type: 'number' },
          },
        },
        permittedAgents: ['AGENT-002-DRA', 'AGENT-004-SGA'],
        safetyConstraints: {
          allowFilesystemWrite: false,
          allowNetworkAccess: false,
          allowProcessSpawn: false,
          maxTimeoutMs: 10000,
        },
        instructions:
          'Scan provided codeFragment for spatial or memory logic. Compare against frozen authorities in data/ and src/core/.',
      },
      {
        async execute(input: Record<string, unknown>, ctx: SkillExecutionContext): Promise<SkillExecutionResult> {
          const fragment = String(input.codeFragment || '');
          const isSpatial = fragment.includes('address369') || fragment.includes('cellId');
          const outputData = {
            analyzedChars: fragment.length,
            reuseRecommendation: isSpatial ? 'REUSE_CORE_FROZEN_AUTHORITY' : 'PROCEED_NEW',
            conflictProbability: isSpatial ? 0.95 : 0.05,
          };
          const inputHash = createHash('sha256').update(JSON.stringify(input)).digest('hex');
          const outputHash = createHash('sha256').update(JSON.stringify(outputData)).digest('hex');

          return {
            success: true,
            data: outputData,
            executionLatencyMs: 2,
            provenance: {
              executionId: ctx.executionId,
              skillId: ctx.skillId,
              skillVersion: '1.0.0',
              invokingAgentId: ctx.invokingAgentId,
              inputHashSha256: inputHash,
              outputHashSha256: outputHash,
              executedAt: new Date().toISOString(),
              status: 'SUCCESS',
            },
          };
        },
      }
    );

    // 3. Declarative Instruction Skill (Universal Documentation Guidelines)
    this.registerSkill({
      skillId: 'SKILL-CLEAN-ARCHITECTURE-GUIDE',
      name: 'Clean Architecture Guidance',
      purpose: 'Standard guidelines for writing decoupled, dependency-injected TypeScript interfaces.',
      version: '1.0.0',
      capabilities: ['ARCHITECTURE_GUIDELINES', 'STYLE_GUIDE'],
      inputSchema: { type: 'object' },
      outputSchema: { type: 'object' },
      permittedAgents: ['*'], // Universal access
      safetyConstraints: {
        allowFilesystemWrite: false,
        allowNetworkAccess: false,
        allowProcessSpawn: false,
        maxTimeoutMs: 2000,
      },
      instructions:
        'Enforce clean interfaces: Separate types from implementations, depend on abstractions, avoid cyclical imports, and keep domain models pure.',
    });
  }
}
