/**
 * CUBiO AI — 3D Memory Studio
 * src/cubio/workspace/projectDiscoveryEngine.ts
 *
 * Sovereign Project Discovery Engine.
 * Generalizes workspace inspection for arbitrary external repositories.
 * Detects manifests, languages, entry points, architecture topologies,
 * dynamic subsystems, and test commands across Node.js, Python, Rust, Go, and Web.
 * Reports unsupported languages, empty directories, and edge cases honestly.
 */

import * as fs from 'fs';
import * as path from 'path';
import {
  ManifestInfo,
  SupportedLanguage,
  LanguageDetectionResult,
  DetectedLanguageBreakdown,
  EntryPointInfo,
  ArchitectureStyle,
  DynamicSubsystem,
  TestCommandInfo,
  ProjectSupportVerdict,
  ProjectDiscoveryProfile,
} from './types.js';

const IGNORED_DIRS = new Set([
  'node_modules',
  '.git',
  '.svn',
  '.hg',
  'dist',
  'build',
  'target',
  'out',
  '.next',
  '.nuxt',
  '.turbo',
  'vendor',
  '.venv',
  'venv',
  'env',
  '__pycache__',
  '.pytest_cache',
  '.mypy_cache',
  '.cargo',
  '.idea',
  '.vscode',
  'coverage',
  '.nyc_output',
  'tmp',
]);

const EXTENSION_LANGUAGE_MAP: Record<string, SupportedLanguage> = {
  '.ts': 'typescript',
  '.tsx': 'typescript',
  '.js': 'javascript',
  '.jsx': 'javascript',
  '.mjs': 'javascript',
  '.cjs': 'javascript',
  '.py': 'python',
  '.pyw': 'python',
  '.rs': 'rust',
  '.go': 'go',
  '.html': 'html',
  '.htm': 'html',
  '.css': 'css',
  '.scss': 'css',
  '.sass': 'css',
  '.less': 'css',
  '.c': 'c',
  '.h': 'c',
  '.cpp': 'cpp',
  '.cc': 'cpp',
  '.cxx': 'cpp',
  '.hpp': 'cpp',
  '.java': 'java',
  '.sh': 'shell',
  '.bash': 'shell',
  '.json': 'json',
  '.yaml': 'yaml',
  '.yml': 'yaml',
  '.md': 'markdown',
};

const CODE_LANGUAGES = new Set<SupportedLanguage>([
  'typescript',
  'javascript',
  'python',
  'rust',
  'go',
  'html',
  'css',
  'c',
  'cpp',
  'java',
  'shell',
]);

export class ProjectDiscoveryEngine {
  /**
   * Inspects a user-authorized workspace directory and produces a comprehensive profile.
   */
  public inspect(workspaceRoot: string): ProjectDiscoveryProfile {
    const canonicalRoot = fs.realpathSync(workspaceRoot);
    const workspaceName = path.basename(canonicalRoot) || 'workspace';
    const scanTimestamp = new Date().toISOString();

    // 1. Gather all files within safe depth (max 4 levels deep)
    const allFiles = this.collectFiles(canonicalRoot, 4);

    // 2. Discover Project Manifests
    const manifests = this.detectManifests(canonicalRoot, allFiles);

    // 3. Detect Languages
    const languages = this.detectLanguages(allFiles);

    // 4. Detect Entry Points
    const entryPoints = this.detectEntryPoints(canonicalRoot, allFiles, manifests, languages);

    // 5. Discover Dynamic Subsystems
    const subsystems = this.discoverDynamicSubsystems(canonicalRoot, allFiles);

    // 6. Detect Test Commands & Toolchains
    const testInfo = this.detectTestCommands(canonicalRoot, allFiles, manifests, languages);

    // 7. Determine Architecture Style
    const architectureStyle = this.determineArchitectureStyle(
      allFiles,
      manifests,
      languages,
      entryPoints
    );

    // 8. Formulate Honest Support Verdict
    const supportVerdict = this.formulateSupportVerdict(
      architectureStyle,
      manifests,
      languages,
      testInfo,
      allFiles.length
    );

    return {
      workspaceRoot: canonicalRoot,
      workspaceName,
      scanTimestamp,
      architectureStyle,
      manifests,
      languages,
      entryPoints,
      subsystems,
      testInfo,
      supportVerdict,
    };
  }

  // ---------------------------------------------------------------------------
  // Internal File Collector
  // ---------------------------------------------------------------------------
  private collectFiles(dir: string, maxDepth: number, currentDepth = 0): string[] {
    if (currentDepth > maxDepth) return [];
    const collected: string[] = [];

    try {
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        if (IGNORED_DIRS.has(entry.name)) continue;
        const fullPath = path.join(dir, entry.name);

        if (entry.isDirectory()) {
          collected.push(...this.collectFiles(fullPath, maxDepth, currentDepth + 1));
        } else if (entry.isFile()) {
          collected.push(fullPath);
        }
      }
    } catch {
      // Gracefully handle permission errors on individual subdirs
    }

    return collected;
  }

  // ---------------------------------------------------------------------------
  // Manifest Detection
  // ---------------------------------------------------------------------------
  private detectManifests(rootDir: string, files: readonly string[]): ManifestInfo[] {
    const manifests: ManifestInfo[] = [];

    for (const filePath of files) {
      const relPath = path.relative(rootDir, filePath).replace(/\\/g, '/');
      const filename = path.basename(filePath);

      // Node.js: package.json
      if (filename === 'package.json') {
        let summary: Record<string, unknown> = {};
        let isValid = true;
        let parseError: string | undefined;

        try {
          const raw = fs.readFileSync(filePath, 'utf8');
          const parsed = JSON.parse(raw);
          summary = {
            name: parsed.name,
            version: parsed.version,
            scripts: parsed.scripts ? Object.keys(parsed.scripts) : [],
            testScript: parsed.scripts?.test,
            dependenciesCount: Object.keys(parsed.dependencies || {}).length,
            devDependenciesCount: Object.keys(parsed.devDependencies || {}).length,
            main: parsed.main,
            bin: parsed.bin,
            workspaces: parsed.workspaces,
          };
        } catch (err: any) {
          isValid = false;
          parseError = `Malformed JSON in package.json: ${err.message}`;
        }

        manifests.push({
          type: 'NODE_PACKAGE_JSON',
          path: filePath,
          relativePath: relPath,
          isValid,
          parseError,
          contentSummary: summary,
        });
      }

      // Python: pyproject.toml
      if (filename === 'pyproject.toml') {
        let summary: Record<string, unknown> = {};
        try {
          const raw = fs.readFileSync(filePath, 'utf8');
          const hasBuildSystem = raw.includes('[build-system]');
          const hasProject = raw.includes('[project]');
          const hasPoetry = raw.includes('[tool.poetry]');
          summary = { hasBuildSystem, hasProject, hasPoetry };
        } catch {}

        manifests.push({
          type: 'PYTHON_PYPROJECT',
          path: filePath,
          relativePath: relPath,
          isValid: true,
          contentSummary: summary,
        });
      }

      // Python: setup.py
      if (filename === 'setup.py') {
        manifests.push({
          type: 'PYTHON_SETUP_PY',
          path: filePath,
          relativePath: relPath,
          isValid: true,
        });
      }

      // Python: requirements.txt
      if (filename === 'requirements.txt') {
        manifests.push({
          type: 'PYTHON_REQUIREMENTS',
          path: filePath,
          relativePath: relPath,
          isValid: true,
        });
      }

      // Rust: Cargo.toml
      if (filename === 'Cargo.toml') {
        let summary: Record<string, unknown> = {};
        try {
          const raw = fs.readFileSync(filePath, 'utf8');
          const isWorkspace = raw.includes('[workspace]');
          const hasLib = raw.includes('[lib]');
          const hasBin = raw.includes('[[bin]]');
          summary = { isWorkspace, hasLib, hasBin };
        } catch {}

        manifests.push({
          type: 'RUST_CARGO',
          path: filePath,
          relativePath: relPath,
          isValid: true,
          contentSummary: summary,
        });
      }

      // Go: go.mod
      if (filename === 'go.mod') {
        let summary: Record<string, unknown> = {};
        try {
          const raw = fs.readFileSync(filePath, 'utf8');
          const modLine = raw.split('\n').find((l) => l.startsWith('module '));
          const goLine = raw.split('\n').find((l) => l.startsWith('go '));
          summary = {
            module: modLine ? modLine.replace('module ', '').trim() : undefined,
            goVersion: goLine ? goLine.replace('go ', '').trim() : undefined,
          };
        } catch {}

        manifests.push({
          type: 'GO_MOD',
          path: filePath,
          relativePath: relPath,
          isValid: true,
          contentSummary: summary,
        });
      }

      // Web: index.html
      if (filename === 'index.html') {
        manifests.push({
          type: 'WEB_INDEX_HTML',
          path: filePath,
          relativePath: relPath,
          isValid: true,
        });
      }

      // Web: Vite / Webpack / Next config
      if (
        filename === 'vite.config.ts' ||
        filename === 'vite.config.js' ||
        filename === 'webpack.config.js' ||
        filename === 'next.config.js' ||
        filename === 'next.config.mjs'
      ) {
        manifests.push({
          type: 'WEB_CONFIG',
          path: filePath,
          relativePath: relPath,
          isValid: true,
          contentSummary: { configTool: filename.split('.')[0] },
        });
      }

      // Dockerfile & Makefile
      if (filename === 'Dockerfile') {
        manifests.push({
          type: 'DOCKERFILE',
          path: filePath,
          relativePath: relPath,
          isValid: true,
        });
      }
      if (filename === 'Makefile') {
        manifests.push({
          type: 'MAKEFILE',
          path: filePath,
          relativePath: relPath,
          isValid: true,
        });
      }
    }

    return manifests;
  }

  // ---------------------------------------------------------------------------
  // Language Detection
  // ---------------------------------------------------------------------------
  private detectLanguages(files: readonly string[]): LanguageDetectionResult {
    const counts = new Map<SupportedLanguage, number>();
    let totalCodeFiles = 0;

    for (const filePath of files) {
      const ext = path.extname(filePath).toLowerCase();
      const lang = EXTENSION_LANGUAGE_MAP[ext];
      if (lang) {
        counts.set(lang, (counts.get(lang) || 0) + 1);
        if (CODE_LANGUAGES.has(lang)) {
          totalCodeFiles++;
        }
      }
    }

    if (totalCodeFiles === 0) {
      return {
        primaryLanguage: 'unsupported',
        detectedLanguages: [],
        totalSourceFiles: 0,
      };
    }

    const breakdowns: DetectedLanguageBreakdown[] = [];
    for (const [lang, count] of counts.entries()) {
      if (CODE_LANGUAGES.has(lang)) {
        breakdowns.push({
          language: lang,
          fileCount: count,
          percentage: Math.round((count / totalCodeFiles) * 100),
        });
      }
    }

    breakdowns.sort((a, b) => b.fileCount - a.fileCount);
    const primaryLanguage = breakdowns.length > 0 ? breakdowns[0].language : 'unsupported';

    return {
      primaryLanguage,
      detectedLanguages: breakdowns,
      totalSourceFiles: totalCodeFiles,
    };
  }

  // ---------------------------------------------------------------------------
  // Entry Point Detection
  // ---------------------------------------------------------------------------
  private detectEntryPoints(
    rootDir: string,
    files: readonly string[],
    manifests: readonly ManifestInfo[],
    languages: LanguageDetectionResult
  ): EntryPointInfo[] {
    const entryPoints: EntryPointInfo[] = [];
    const relFileSet = new Set(
      files.map((f) => path.relative(rootDir, f).replace(/\\/g, '/'))
    );

    // 1. From package.json main/bin
    const pkgManifest = manifests.find((m) => m.type === 'NODE_PACKAGE_JSON');
    if (pkgManifest?.contentSummary) {
      const main = pkgManifest.contentSummary.main as string | undefined;
      if (main && relFileSet.has(main.replace(/^\.\//, ''))) {
        const clean = main.replace(/^\.\//, '');
        entryPoints.push({
          path: path.join(rootDir, clean),
          relativePath: clean,
          language: clean.endsWith('.ts') ? 'typescript' : 'javascript',
          role: 'library_entry',
        });
      }

      const bin = pkgManifest.contentSummary.bin;
      if (typeof bin === 'string' && relFileSet.has(bin.replace(/^\.\//, ''))) {
        const clean = bin.replace(/^\.\//, '');
        entryPoints.push({
          path: path.join(rootDir, clean),
          relativePath: clean,
          language: clean.endsWith('.ts') ? 'typescript' : 'javascript',
          role: 'cli_entry',
        });
      } else if (typeof bin === 'object' && bin !== null) {
        for (const [binName, binPath] of Object.entries(bin)) {
          const clean = (binPath as string).replace(/^\.\//, '');
          if (relFileSet.has(clean)) {
            entryPoints.push({
              path: path.join(rootDir, clean),
              relativePath: clean,
              language: clean.endsWith('.ts') ? 'typescript' : 'javascript',
              role: 'cli_entry',
            });
          }
        }
      }
    }

    // 2. Conventional Candidates
    const candidates: { rel: string; lang: SupportedLanguage; role: EntryPointInfo['role'] }[] = [
      // Web
      { rel: 'index.html', lang: 'html', role: 'web_index' },
      { rel: 'public/index.html', lang: 'html', role: 'web_index' },
      { rel: 'src/main.tsx', lang: 'typescript', role: 'web_index' },
      { rel: 'src/main.jsx', lang: 'javascript', role: 'web_index' },
      { rel: 'src/index.tsx', lang: 'typescript', role: 'web_index' },
      { rel: 'src/App.tsx', lang: 'typescript', role: 'web_index' },
      // Node / TS
      { rel: 'src/index.ts', lang: 'typescript', role: 'library_entry' },
      { rel: 'src/index.js', lang: 'javascript', role: 'library_entry' },
      { rel: 'src/main.ts', lang: 'typescript', role: 'application_entry' },
      { rel: 'src/server.ts', lang: 'typescript', role: 'application_entry' },
      { rel: 'index.ts', lang: 'typescript', role: 'library_entry' },
      { rel: 'index.js', lang: 'javascript', role: 'library_entry' },
      { rel: 'server.js', lang: 'javascript', role: 'application_entry' },
      // Python
      { rel: 'main.py', lang: 'python', role: 'application_entry' },
      { rel: 'app.py', lang: 'python', role: 'application_entry' },
      { rel: 'src/main.py', lang: 'python', role: 'application_entry' },
      { rel: 'src/app.py', lang: 'python', role: 'application_entry' },
      { rel: 'cli.py', lang: 'python', role: 'cli_entry' },
      // Rust
      { rel: 'src/main.rs', lang: 'rust', role: 'cli_entry' },
      { rel: 'src/lib.rs', lang: 'rust', role: 'library_entry' },
      // Go
      { rel: 'main.go', lang: 'go', role: 'application_entry' },
    ];

    for (const c of candidates) {
      if (relFileSet.has(c.rel) && !entryPoints.some((ep) => ep.relativePath === c.rel)) {
        entryPoints.push({
          path: path.join(rootDir, c.rel),
          relativePath: c.rel,
          language: c.lang,
          role: c.role,
        });
      }
    }

    return entryPoints;
  }

  // ---------------------------------------------------------------------------
  // Dynamic Subsystem Discovery
  // ---------------------------------------------------------------------------
  private discoverDynamicSubsystems(rootDir: string, files: readonly string[]): DynamicSubsystem[] {
    const subsystemMap = new Map<
      string,
      {
        dir: string;
        files: string[];
        tests: string[];
      }
    >();

    for (const filePath of files) {
      const relPath = path.relative(rootDir, filePath).replace(/\\/g, '/');
      const parts = relPath.split('/');

      let subDir: string | null = null;
      if (parts.length > 1) {
        if (parts[0] === 'src' && parts.length > 2) {
          subDir = `src/${parts[1]}`;
        } else if (parts[0] === 'pkg' && parts.length > 2) {
          subDir = `pkg/${parts[1]}`;
        } else {
          subDir = parts[0];
        }
      }

      if (subDir && !IGNORED_DIRS.has(subDir)) {
        if (!subsystemMap.has(subDir)) {
          subsystemMap.set(subDir, { dir: subDir, files: [], tests: [] });
        }
        const record = subsystemMap.get(subDir)!;
        const isTest =
          relPath.toLowerCase().includes('test') ||
          relPath.toLowerCase().includes('spec') ||
          parts[0] === 'tests';

        if (isTest) {
          record.tests.push(relPath);
        } else {
          record.files.push(relPath);
        }
      }
    }

    const subsystems: DynamicSubsystem[] = [];
    for (const [dir, record] of subsystemMap.entries()) {
      const allSubFiles = [...record.files, ...record.tests];
      if (allSubFiles.length === 0) continue;

      const subId = dir.replace(/[^a-zA-Z0-9]/g, '_').toUpperCase();
      const subName = dir
        .split('/')
        .map((p) => p.charAt(0).toUpperCase() + p.slice(1))
        .join(' ');

      // Extract semantic keywords from filenames
      const keywords = new Set<string>();
      keywords.add(dir.toLowerCase());
      for (const p of dir.split('/')) {
        keywords.add(p.toLowerCase());
      }
      for (const f of allSubFiles.slice(0, 5)) {
        const base = path.basename(f, path.extname(f)).toLowerCase();
        keywords.add(base);
      }

      subsystems.push({
        id: subId,
        name: subName,
        primaryDir: dir,
        keyFiles: record.files.slice(0, 10),
        tests: record.tests.slice(0, 10),
        keywords: Array.from(keywords),
        fileCount: allSubFiles.length,
      });
    }

    subsystems.sort((a, b) => b.fileCount - a.fileCount);
    return subsystems;
  }

  // ---------------------------------------------------------------------------
  // Test Command Detection
  // ---------------------------------------------------------------------------
  private detectTestCommands(
    rootDir: string,
    files: readonly string[],
    manifests: readonly ManifestInfo[],
    languages: LanguageDetectionResult
  ): TestCommandInfo {
    const relFiles = files.map((f) => path.relative(rootDir, f).replace(/\\/g, '/'));
    const testFiles = relFiles.filter(
      (f) =>
        f.includes('/test') ||
        f.includes('/tests/') ||
        f.endsWith('_test.go') ||
        f.endsWith('_test.rs') ||
        f.endsWith('.test.ts') ||
        f.endsWith('.test.js') ||
        f.endsWith('.spec.ts') ||
        f.endsWith('.spec.js') ||
        path.basename(f).startsWith('test_')
    );

    // 1. Node.js project
    const pkgManifest = manifests.find((m) => m.type === 'NODE_PACKAGE_JSON');
    if (pkgManifest?.contentSummary?.testScript) {
      const script = pkgManifest.contentSummary.testScript as string;
      const isPlaceholder = script.includes('no test specified');
      if (!isPlaceholder) {
        return {
          framework: script.includes('vitest')
            ? 'vitest'
            : script.includes('jest')
            ? 'jest'
            : script.includes('mocha')
            ? 'mocha'
            : 'npm-scripts',
          testCommand: 'npm test',
          testFilesPattern: '**/*.{test,spec}.{ts,js}',
          detectedTestFileCount: testFiles.length,
          isSupported: true,
          notes: `Configured via package.json: "${script}"`,
        };
      }
    }

    // 2. Rust Cargo
    const cargoManifest = manifests.find((m) => m.type === 'RUST_CARGO');
    if (cargoManifest || languages.primaryLanguage === 'rust') {
      return {
        framework: 'cargo-test',
        testCommand: 'cargo test',
        testFilesPattern: 'tests/**/*.rs, src/**/*_test.rs',
        detectedTestFileCount: testFiles.length,
        isSupported: true,
        notes: 'Native Rust test harness detected via Cargo.',
      };
    }

    // 3. Go Module
    const goManifest = manifests.find((m) => m.type === 'GO_MOD');
    if (goManifest || languages.primaryLanguage === 'go') {
      return {
        framework: 'go-test',
        testCommand: 'go test ./...',
        testFilesPattern: '**/*_test.go',
        detectedTestFileCount: testFiles.length,
        isSupported: true,
        notes: 'Native Go test suite detected via go.mod.',
      };
    }

    // 4. Python
    if (languages.primaryLanguage === 'python' || manifests.some((m) => m.type.startsWith('PYTHON_'))) {
      const hasPytest = relFiles.some((f) => f.includes('pytest') || f.endsWith('conftest.py'));
      return {
        framework: hasPytest ? 'pytest' : 'unittest',
        testCommand: hasPytest ? 'pytest' : 'python -m unittest',
        testFilesPattern: 'tests/**/test_*.py',
        detectedTestFileCount: testFiles.length,
        isSupported: true,
        notes: `Python testing framework detected (${hasPytest ? 'pytest' : 'unittest'}).`,
      };
    }

    // 5. Web static or unknown
    if (testFiles.length > 0) {
      return {
        detectedTestFileCount: testFiles.length,
        isSupported: false,
        notes: 'Test files detected but no standard automated runner manifest found.',
      };
    }

    return {
      detectedTestFileCount: 0,
      isSupported: false,
      notes: 'No automated test runner or test files detected in workspace.',
    };
  }

  // ---------------------------------------------------------------------------
  // Architecture Style Determination
  // ---------------------------------------------------------------------------
  private determineArchitectureStyle(
    files: readonly string[],
    manifests: readonly ManifestInfo[],
    languages: LanguageDetectionResult,
    entryPoints: readonly EntryPointInfo[]
  ): ArchitectureStyle {
    if (files.length === 0) {
      return 'EMPTY_PROJECT';
    }

    if (languages.totalSourceFiles === 0) {
      return 'UNSUPPORTED_PROJECT_TYPE';
    }

    // Monorepo check
    const pkgManifest = manifests.find((m) => m.type === 'NODE_PACKAGE_JSON');
    if (pkgManifest?.contentSummary?.workspaces) {
      return 'MONOREPO';
    }
    const cargoManifest = manifests.find((m) => m.type === 'RUST_CARGO');
    if (cargoManifest?.contentSummary?.isWorkspace) {
      return 'MONOREPO';
    }

    // Web SPA / Static
    const hasWebManifest = manifests.some(
      (m) => m.type === 'WEB_INDEX_HTML' || m.type === 'WEB_CONFIG'
    );
    if (hasWebManifest) {
      return manifests.some((m) => m.type === 'WEB_CONFIG')
        ? 'WEB_APPLICATION'
        : 'WEB_STATIC';
    }

    // Multi-Language (distinct primary programming languages, ignoring auxiliary web markup)
    const backendLangs = languages.detectedLanguages.filter(
      (l) => l.language !== 'html' && l.language !== 'css' && l.percentage >= 25
    );
    if (backendLangs.length >= 2) {
      return 'MULTI_LANGUAGE';
    }

    // Node.js
    if (languages.primaryLanguage === 'typescript' || languages.primaryLanguage === 'javascript') {
      const hasCli = entryPoints.some((ep) => ep.role === 'cli_entry');
      const hasLib = entryPoints.some((ep) => ep.role === 'library_entry');
      if (hasCli) return 'NODE_APPLICATION';
      if (hasLib) return 'NODE_LIBRARY';
      return 'NODE_APPLICATION';
    }

    // Python
    if (languages.primaryLanguage === 'python') {
      const hasPkg = manifests.some(
        (m) => m.type === 'PYTHON_SETUP_PY' || m.type === 'PYTHON_PYPROJECT'
      );
      return hasPkg ? 'PYTHON_PACKAGE' : 'PYTHON_APPLICATION';
    }

    // Rust
    if (languages.primaryLanguage === 'rust') {
      const isBin = entryPoints.some((ep) => ep.role === 'cli_entry');
      return isBin ? 'RUST_BINARY' : 'RUST_LIBRARY';
    }

    // Go
    if (languages.primaryLanguage === 'go') {
      const hasMain = entryPoints.some((ep) => ep.role === 'application_entry');
      return hasMain ? 'GO_SERVICE' : 'GO_MODULE';
    }

    return 'GENERIC_SOURCE_TREE';
  }

  // ---------------------------------------------------------------------------
  // Support Verdict Formulation
  // ---------------------------------------------------------------------------
  private formulateSupportVerdict(
    style: ArchitectureStyle,
    manifests: readonly ManifestInfo[],
    languages: LanguageDetectionResult,
    testInfo: TestCommandInfo,
    fileCount: number
  ): ProjectSupportVerdict {
    if (style === 'EMPTY_PROJECT' || fileCount === 0) {
      return {
        isSupported: false,
        explanation:
          'Workspace is completely empty. No files, manifests, or source code were detected.',
        detectedFeatures: [],
        unsupportedFeatures: ['No project manifest', 'No source files'],
        recommendations: [
          'Initialize a project with a package.json, Cargo.toml, pyproject.toml, or go.mod.',
          'Add source code files to the authorized directory.',
        ],
      };
    }

    if (style === 'UNSUPPORTED_PROJECT_TYPE' || languages.totalSourceFiles === 0) {
      return {
        isSupported: false,
        explanation:
          'Workspace contains no recognized programming languages, manifests, or web assets.',
        detectedFeatures: [`Files present: ${fileCount}`],
        unsupportedFeatures: [
          'No supported programming languages detected',
          'No build manifests detected',
        ],
        recommendations: [
          'Ensure the authorized directory points to a valid Node.js, Python, Rust, Go, or Web project root.',
        ],
      };
    }

    const detectedFeatures: string[] = [
      `Primary Language: ${languages.primaryLanguage}`,
      `Architecture: ${style}`,
      `Source Files: ${languages.totalSourceFiles}`,
    ];

    if (manifests.length > 0) {
      detectedFeatures.push(`Manifests: ${manifests.map((m) => m.relativePath).join(', ')}`);
    }

    if (testInfo.isSupported && testInfo.testCommand) {
      detectedFeatures.push(`Test Suite: ${testInfo.testCommand} (${testInfo.framework})`);
    }

    const unsupportedFeatures: string[] = [];
    const recommendations: string[] = [];

    if (!testInfo.isSupported) {
      unsupportedFeatures.push('Automated test suite not detected');
      recommendations.push('Configure a test script or harness to enable automated regression testing.');
    }

    const invalidManifests = manifests.filter((m) => !m.isValid);
    if (invalidManifests.length > 0) {
      unsupportedFeatures.push(
        `Corrupted manifests: ${invalidManifests.map((m) => m.relativePath).join(', ')}`
      );
      recommendations.push('Fix syntax errors in corrupted project manifests.');
    }

    return {
      isSupported: true,
      explanation: `Successfully onboarded ${style} project with ${languages.primaryLanguage} primary language.`,
      detectedFeatures,
      unsupportedFeatures,
      recommendations,
    };
  }
}
