/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-011 — OMA (Observability & Monitoring Agent)
 * src/cubio/agents/oma/observabilityAgent.ts
 *
 * Central facade for AGENT-011-OMA.
 * Ingests multi-agent telemetry events, updates bounded rolling metrics,
 * evaluates health states and alert triggers, and produces sanitized digests.
 * Permanently locks is_actuation_blocked = true.
 */

import {
  OMANormalizedEvent,
  OMAMetricSummary,
  OMAAgentHealthRecord,
  OMAAlertRecord,
  OMABoundsConfig,
  DEFAULT_OMA_BOUNDS,
} from './types';
import { EventNormalizer } from './eventNormalizer';
import { MetricsAggregator } from './metricsAggregator';
import { HealthEvaluator } from './healthEvaluator';
import { AlertEvaluator } from './alertEvaluator';
import { DiagnosticReporter } from './diagnosticReporter';

export class ObservabilityMonitoringAgent {
  public static readonly AGENT_ID = 'AGENT-011-OMA';
  public static readonly AGENT_NAME = 'Observability & Monitoring Agent';
  public static readonly VERSION = '1.0.0';

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public get is_actuation_blocked(): boolean {
    return true;
  }

  private readonly aggregator: MetricsAggregator;
  private readonly alertEvaluator: AlertEvaluator;
  private readonly bounds: OMABoundsConfig;

  constructor(customBounds: OMABoundsConfig = DEFAULT_OMA_BOUNDS) {
    this.bounds = customBounds;
    this.aggregator = new MetricsAggregator(this.bounds);
    this.alertEvaluator = new AlertEvaluator(this.bounds);
  }

  /**
   * Ingests a raw telemetry event from any agent.
   */
  public ingest(rawEvent: Partial<OMANormalizedEvent>): OMANormalizedEvent {
    const event = EventNormalizer.normalize(rawEvent);
    this.aggregator.recordEvent(event);
    this.alertEvaluator.evaluate(this.aggregator.getRetainedEvents());
    return event;
  }

  /**
   * AOA AgentInvoker contract compatibility helper.
   */
  public async invoke(payload: Record<string, unknown>): Promise<OMAMetricSummary> {
    if (payload && payload.eventType) {
      this.ingest(payload as any);
    }
    return this.getMetricSummary();
  }

  /**
   * Retrieves summary metrics over the current bounded window.
   */
  public getMetricSummary(): OMAMetricSummary {
    return this.aggregator.computeSummary();
  }

  /**
   * Evaluates operational health of an individual agent.
   */
  public getAgentHealth(agentId: string): OMAAgentHealthRecord {
    return HealthEvaluator.evaluateAgentHealth(agentId, this.aggregator.getRetainedEvents());
  }

  /**
   * Retrieves active triggered alerts.
   */
  public getAlerts(): readonly OMAAlertRecord[] {
    return this.alertEvaluator.getRetainedAlerts();
  }

  /**
   * Generates a full Markdown digest across all monitored agents.
   */
  public generateDigest(monitoredAgentIds: readonly string[] = []): string {
    const metrics = this.getMetricSummary();
    const healthRecords = monitoredAgentIds.map((id) => this.getAgentHealth(id));
    const alerts = this.getAlerts();
    return DiagnosticReporter.formatMarkdownDigest(metrics, healthRecords, alerts);
  }
}
