/**
 * CUBiO AI — 3D Memory Studio
 * src/cubio/workspace/workspaceManager.ts
 *
 * Sovereign Workspace Authorization & Selection Manager.
 * Controls workspace boundaries, path containment, active workspace switching,
 * symlink/junction security, and maintains the registry of user-authorized external projects.
 */

import * as crypto from 'crypto';
import * as fs from 'fs';
import * as path from 'path';
import {
  AuthorizedWorkspace,
  ControlledWriteRequest,
  PathValidationResult,
  ProjectDiscoveryProfile,
  WorkspaceAuthorizationOptions,
  WorkspaceSecurityConfig,
  WorkspaceWriteResult,
  WriteApprovalProposal,
  ConfirmWriteApprovalRequest,
  ConfirmWriteApprovalResult,
} from './types.js';
import { ProjectDiscoveryEngine } from './projectDiscoveryEngine.js';
import { WorkspaceSecurityGuard } from './workspaceSecurityGuard.js';

export class WorkspaceManager {
  private static instance: WorkspaceManager | null = null;
  private readonly workspaces = new Map<string, AuthorizedWorkspace>();
  private readonly pendingProposals = new Map<string, WriteApprovalProposal>();
  private activeWorkspaceId: string | null = null;
  private readonly discoveryEngine = new ProjectDiscoveryEngine();
  private readonly securityGuard = WorkspaceSecurityGuard.getInstance();

  public static getInstance(): WorkspaceManager {
    if (!WorkspaceManager.instance) {
      WorkspaceManager.instance = new WorkspaceManager();
    }
    return WorkspaceManager.instance;
  }

  /**
   * Authorizes and registers an external workspace directory.
   * Performs path containment, existence validation, and initial project discovery.
   */
  public authorizeWorkspace(
    rawPath: string,
    options?: WorkspaceAuthorizationOptions
  ): AuthorizedWorkspace {
    if (!rawPath || typeof rawPath !== 'string' || rawPath.trim().length === 0) {
      throw new Error('INVALID_WORKSPACE_PATH: Workspace path must be a non-empty string.');
    }

    const resolvedPath = path.resolve(rawPath.trim());
    if (!fs.existsSync(resolvedPath)) {
      throw new Error(`WORKSPACE_NOT_FOUND: The specified path does not exist: "${resolvedPath}"`);
    }

    const stat = fs.statSync(resolvedPath);
    if (!stat.isDirectory()) {
      throw new Error(
        `WORKSPACE_NOT_DIRECTORY: Target path is a file, not a directory: "${resolvedPath}"`
      );
    }

    // Resolve canonical path following symlinks to prevent directory traversal escapes
    const canonicalPath = fs.realpathSync(resolvedPath);

    // Prevent authorization of dangerous system roots
    const rootParsed = path.parse(canonicalPath);
    if (canonicalPath === rootParsed.root) {
      throw new Error(
        `UNAUTHORIZED_WORKSPACE_PATH: Root filesystem cannot be authorized as a workspace: "${canonicalPath}"`
      );
    }

    // Enforce allowed parent directories if configured
    if (options?.allowedParentDirs && options.allowedParentDirs.length > 0) {
      const allowed = options.allowedParentDirs.some((allowedParent) => {
        const canonicalParent = fs.existsSync(allowedParent)
          ? fs.realpathSync(path.resolve(allowedParent))
          : path.resolve(allowedParent);
        const rel = path.relative(canonicalParent, canonicalPath);
        return !rel.startsWith('..') && !path.isAbsolute(rel);
      });

      if (!allowed) {
        throw new Error(
          `UNAUTHORIZED_WORKSPACE_PATH: Workspace "${canonicalPath}" lies outside configured allowed directories.`
        );
      }
    }

    // Generate deterministic workspace identifier
    const workspaceId = `WS-${crypto
      .createHash('sha256')
      .update(canonicalPath.toLowerCase())
      .digest('hex')
      .slice(0, 10)
      .toUpperCase()}`;

    // Inspect project
    const profile = this.discoveryEngine.inspect(canonicalPath);
    const now = new Date().toISOString();

    const isFirst = this.workspaces.size === 0;
    const shouldBeActive = isFirst || this.activeWorkspaceId === null;

    const isReadOnly = Boolean(options?.readOnly);
    const securityConfig: WorkspaceSecurityConfig = {
      policy: isReadOnly ? 'READ_ONLY' : (options?.policy || 'REQUIRE_APPROVAL_TOKEN'),
      allowedParentDirs: options?.allowedParentDirs,
      allowSymlinks: false,
    };

    const authorized: AuthorizedWorkspace = {
      workspaceId,
      canonicalPath,
      label: options?.label || path.basename(canonicalPath),
      authorizedAt: now,
      lastInspectedAt: now,
      profile,
      isActive: shouldBeActive,
      readOnly: isReadOnly,
      securityConfig,
    };

    if (shouldBeActive) {
      this.activeWorkspaceId = workspaceId;
    }

    this.workspaces.set(workspaceId, authorized);
    return authorized;
  }

  /**
   * Inspects a workspace by ID or path. Defaults to currently active workspace.
   */
  public inspectWorkspace(workspaceIdOrPath?: string): ProjectDiscoveryProfile {
    const ws = this.resolveWorkspace(workspaceIdOrPath);
    if (!ws) {
      throw new Error(
        'NO_ACTIVE_WORKSPACE: No active authorized workspace. Onboard a workspace first.'
      );
    }

    const profile = this.discoveryEngine.inspect(ws.canonicalPath);
    const updated: AuthorizedWorkspace = {
      ...ws,
      lastInspectedAt: new Date().toISOString(),
      profile,
    };

    this.workspaces.set(ws.workspaceId, updated);
    return profile;
  }

  /**
   * Validates path containment for a target file inside an authorized workspace.
   */
  public validatePathContainment(
    targetPath: string,
    workspaceIdOrPath?: string
  ): PathValidationResult {
    const ws = this.resolveWorkspace(workspaceIdOrPath);
    if (!ws) {
      return {
        isValid: false,
        reason: 'NO_ACTIVE_WORKSPACE: No active authorized workspace found for containment check.',
      };
    }

    return this.securityGuard.validatePathContainment(ws.canonicalPath, targetPath, {
      allowedParentDirs: ws.securityConfig.allowedParentDirs,
    });
  }

  /**
   * Registers a pending write approval proposal.
   * Enforces two-step approval flow: Does NOT issue an active write token until
   * confirmWriteApproval is explicitly invoked by an authorized human operator.
   */
  public requestWriteApproval(
    taskId: string,
    targetPath: string,
    content: string,
    workspaceIdOrPath?: string
  ): WriteApprovalProposal {
    const ws = this.resolveWorkspace(workspaceIdOrPath);
    if (!ws) {
      throw new Error('NO_ACTIVE_WORKSPACE: No active authorized workspace.');
    }

    const containment = this.securityGuard.validatePathContainment(ws.canonicalPath, targetPath);
    if (!containment.isValid || !containment.relativePath) {
      throw new Error(`SECURITY_REJECTION: ${containment.reason}`);
    }

    const contentSha256 = crypto.createHash('sha256').update(content, 'utf8').digest('hex');
    const approvalAction = this.securityGuard.createApprovalAction(containment.relativePath, content);
    const proposalId = `PROP-${crypto.randomBytes(8).toString('hex').toUpperCase()}`;

    const proposal: WriteApprovalProposal = {
      proposalId,
      taskId,
      targetFilePath: targetPath,
      relativePath: containment.relativePath,
      contentSha256,
      requestedAt: Date.now(),
      workspaceId: ws.workspaceId,
      approvalAction,
      requiresConfirmation: true,
      status: 'PENDING_HUMAN_APPROVAL',
      message:
        'Write proposal registered. Explicit human confirmation via confirm_write_approval is required before token issuance.',
    };

    this.pendingProposals.set(proposalId, proposal);
    return proposal;
  }

  /**
   * Sets the server-side human operator authorization secret.
   */
  public setHumanOperatorSecret(secret: string): void {
    this.securityGuard.setHumanOperatorSecret(secret);
  }

  /**
   * Rotates the server-side human operator authorization secret.
   * By default invalidates all active tokens.
   */
  public rotateHumanOperatorSecret(
    newSecret?: string,
    options?: { invalidateExistingTokens?: boolean }
  ): { rotated: boolean; secretFingerprint: string } {
    if (options?.invalidateExistingTokens !== false) {
      this.pendingProposals.clear();
    }
    return this.securityGuard.rotateHumanOperatorSecret(newSecret, options);
  }

  /**
   * Revokes the active operator secret and clears all proposals and issued tokens.
   */
  public revokeHumanOperatorSecret(): { revoked: boolean } {
    this.pendingProposals.clear();
    return this.securityGuard.revokeHumanOperatorSecret();
  }

  /**
   * Retrieves the server-side human operator authorization secret for verified admin/testing flows.
   */
  public getHumanOperatorSecret(): string {
    return this.securityGuard.getHumanOperatorSecret();
  }

  /**
   * Confirms or rejects a pending file write approval proposal.
   * Requires authentic human operator credentials (operatorAuthKey) to prevent
   * autonomous agents from self-approving write proposals.
   * Only upon verified human authorization and explicit APPROVE decision is the
   * workspace-bound cryptographic write token minted and activated.
   */
  public confirmWriteApproval(request: ConfirmWriteApprovalRequest): ConfirmWriteApprovalResult {
    const { proposalId, decision, operatorId, operatorAuthKey } = request;
    const proposal = this.pendingProposals.get(proposalId);
    if (!proposal) {
      return {
        success: false,
        status: 'PROPOSAL_NOT_FOUND',
        proposalId,
        message: `Proposal "${proposalId}" was not found or has expired.`,
      };
    }

    if (proposal.status !== 'PENDING_HUMAN_APPROVAL') {
      return {
        success: false,
        status: 'PROPOSAL_EXPIRED',
        proposalId,
        message: `Proposal "${proposalId}" is already finalized with status: ${proposal.status}.`,
      };
    }

    // 1. Authenticate human operator server-side (Finding A)
    const authCheck = this.securityGuard.authenticateHumanOperator(operatorId || '', operatorAuthKey);
    if (!authCheck.authenticated) {
      return {
        success: false,
        status: 'REJECTED_UNAUTHORIZED_OPERATOR',
        proposalId,
        message: `UNAUTHORIZED_OPERATOR: ${authCheck.reason}`,
      };
    }

    // 2. Decision check
    if (decision !== 'APPROVE') {
      (proposal as any).status = 'REJECTED';
      return {
        success: false,
        status: 'REJECTED_BY_OPERATOR',
        proposalId,
        message: `Proposal "${proposalId}" was rejected by human operator "${operatorId}".`,
      };
    }

    // 3. Mint single-use, workspace-bound token (Finding B)
    const targetWsId = proposal.workspaceId || 'DEFAULT_WORKSPACE';
    const token = this.securityGuard.createApprovalToken(
      targetWsId,
      proposal.taskId,
      proposal.relativePath,
      proposal.contentSha256,
      { proposalId, autoConfirm: true, ttlMs: 15 * 60 * 1000, operatorId }
    );
    (proposal as any).status = 'APPROVED';

    return {
      success: true,
      status: 'APPROVED',
      proposalId,
      approvalToken: token,
      expiresInSeconds: 900,
      message: `Proposal "${proposalId}" confirmed by authenticated human operator "${operatorId}". Single-use approval token issued for workspace "${targetWsId}".`,
    };
  }

  /**
   * Executes a controlled write to a file inside the authorized workspace.
   */
  public async writeWorkspaceFile(
    request: ControlledWriteRequest,
    workspaceIdOrPath?: string
  ): Promise<WorkspaceWriteResult> {
    const ws = this.resolveWorkspace(workspaceIdOrPath);
    if (!ws) {
      return {
        success: false,
        bytesWritten: 0,
        status: 'REJECTED',
        errorMessage: 'NO_ACTIVE_WORKSPACE: No active authorized workspace found.',
      };
    }

    return this.securityGuard.executeControlledWrite(
      ws.canonicalPath,
      request,
      ws.securityConfig.policy,
      ws.workspaceId
    );
  }

  /**
   * Sets the active workspace by ID or path.
   */
  public setActiveWorkspace(workspaceIdOrPath: string): AuthorizedWorkspace {
    const target = this.resolveWorkspace(workspaceIdOrPath);
    if (!target) {
      throw new Error(
        `WORKSPACE_NOT_FOUND: Authorized workspace not found for identifier "${workspaceIdOrPath}".`
      );
    }

    for (const [id, ws] of this.workspaces.entries()) {
      this.workspaces.set(id, {
        ...ws,
        isActive: id === target.workspaceId,
      });
    }

    this.activeWorkspaceId = target.workspaceId;
    return this.workspaces.get(target.workspaceId)!;
  }

  /**
   * Retrieves the currently active authorized workspace.
   */
  public getActiveWorkspace(): AuthorizedWorkspace | null {
    if (!this.activeWorkspaceId) return null;
    return this.workspaces.get(this.activeWorkspaceId) || null;
  }

  /**
   * Lists all currently authorized workspaces.
   */
  public listAuthorizedWorkspaces(): readonly AuthorizedWorkspace[] {
    return Array.from(this.workspaces.values());
  }

  /**
   * Revokes authorization for a workspace.
   */
  public revokeWorkspace(workspaceIdOrPath: string): boolean {
    const target = this.resolveWorkspace(workspaceIdOrPath);
    if (!target) return false;

    this.workspaces.delete(target.workspaceId);
    if (this.activeWorkspaceId === target.workspaceId) {
      const remaining = Array.from(this.workspaces.values());
      if (remaining.length > 0) {
        this.setActiveWorkspace(remaining[0].workspaceId);
      } else {
        this.activeWorkspaceId = null;
      }
    }
    return true;
  }

  /**
   * Clears all workspaces (useful in test harnesses).
   */
  public reset(): void {
    this.workspaces.clear();
    this.pendingProposals.clear();
    this.activeWorkspaceId = null;
  }

  /**
   * Resolves an authorized workspace by ID or path, or returns active workspace if omitted.
   */
  public getWorkspace(workspaceIdOrPath?: string): AuthorizedWorkspace | null {
    return this.resolveWorkspace(workspaceIdOrPath);
  }

  // ---------------------------------------------------------------------------
  // Internal Resolver
  // ---------------------------------------------------------------------------
  private resolveWorkspace(workspaceIdOrPath?: string): AuthorizedWorkspace | null {
    if (!workspaceIdOrPath) {
      return this.getActiveWorkspace();
    }

    // Direct ID match
    if (this.workspaces.has(workspaceIdOrPath)) {
      return this.workspaces.get(workspaceIdOrPath)!;
    }

    // Path match
    let targetCanonical = workspaceIdOrPath;
    try {
      if (fs.existsSync(workspaceIdOrPath)) {
        targetCanonical = fs.realpathSync(workspaceIdOrPath);
      }
    } catch {}

    for (const ws of this.workspaces.values()) {
      if (
        ws.canonicalPath.toLowerCase() === targetCanonical.toLowerCase() ||
        ws.label.toLowerCase() === workspaceIdOrPath.toLowerCase()
      ) {
        return ws;
      }
    }

    return null;
  }
}
