/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-009 — CEA (Code Execution Agent)
 * src/cubio/agents/cea/commandRegistry.ts
 *
 * Deny-by-default registry of pre-approved commands, validated executables,
 * argument constraints, and operation boundaries.
 */

import { CEAApprovedCommand } from './types';

export class CommandRegistry {
  private readonly registry: Map<string, CEAApprovedCommand> = new Map();

  constructor() {
    this.bootstrapApprovedCommands();
  }

  private bootstrapApprovedCommands(): void {
    // 1. TSX Test Runner (Single test file execution)
    this.register({
      commandId: 'CMD_TSX_RUNNER',
      description: 'Run targeted TypeScript test or verification script via tsx',
      executable: process.platform === 'win32' ? 'npx.cmd' : 'npx',
      allowedArgumentsPattern: [
        /^tsx$/,
        /^(src\/test_[a-zA-Z0-9_-]+\.ts|tests\/[a-zA-Z0-9_\/-]+\.ts)$/,
      ],
      allowedOperationTypes: ['TEST_EXECUTION', 'STATIC_ANALYSIS'],
      maxTimeoutMs: 60_000,
      maxStdoutBytes: 512 * 1024,
      maxStderrBytes: 256 * 1024,
      allowsNetwork: false,
      allowsFilesystemWrite: false,
      requiredAuthorizationLevel: 'INTERNAL_AOA',
    });

    // 2. TypeScript Type Check (noEmit)
    this.register({
      commandId: 'CMD_TSC_TYPECHECK',
      description: 'Run static TypeScript compiler type checking without emitting files',
      executable: process.platform === 'win32' ? 'npx.cmd' : 'npx',
      allowedArgumentsPattern: [
        /^tsc$/,
        /^(?:--noEmit|--skipLibCheck|-p|tsconfig\.json)$/,
      ],
      allowedOperationTypes: ['TYPE_CHECK', 'STATIC_ANALYSIS'],
      maxTimeoutMs: 90_000,
      maxStdoutBytes: 256 * 1024,
      maxStderrBytes: 128 * 1024,
      allowsNetwork: false,
      allowsFilesystemWrite: false,
      requiredAuthorizationLevel: 'INTERNAL_AOA',
    });

    // 3. Git Status Inspect (Read-only status check)
    this.register({
      commandId: 'CMD_GIT_STATUS',
      description: 'Inspect workspace git status in short or porcelain mode',
      executable: 'git',
      allowedArgumentsPattern: [
        /^status$/,
        /^(?:--short|--porcelain|-s)$/,
      ],
      allowedOperationTypes: ['INSPECTION'],
      maxTimeoutMs: 15_000,
      maxStdoutBytes: 128 * 1024,
      maxStderrBytes: 64 * 1024,
      allowsNetwork: false,
      allowsFilesystemWrite: false,
      requiredAuthorizationLevel: 'TGA_RUNNER',
    });
  }

  public register(cmd: CEAApprovedCommand): void {
    this.registry.set(cmd.commandId, Object.freeze({ ...cmd }));
  }

  public getCommand(commandId: string): CEAApprovedCommand | undefined {
    return this.registry.get(commandId);
  }

  public isRegistered(commandId: string): boolean {
    return this.registry.has(commandId);
  }

  public listCommandIds(): readonly string[] {
    return Object.freeze(Array.from(this.registry.keys()));
  }
}
