export interface CanonicalSkillDefinition {
  readonly manifest: SkillManifest;
  readonly handler?: SkillHandler;
}

function createEvidence(
  ctx: SkillExecutionContext,
  input: Record<string, unknown>,
  output: unknown,
  status: 'SUCCESS' | 'FAILED' | 'REJECTED' = 'SUCCESS'
) {
  const inputHash = createHash('sha256').update(JSON.stringify(input || {})).digest('hex');
  const outputHash = createHash('sha256').update(JSON.stringify(output || {})).digest('hex');
  return {
    executionId: ctx.executionId,
    skillId: ctx.skillId,
    skillVersion: '1.0.0',
    invokingAgentId: ctx.invokingAgentId,
    inputHashSha256: inputHash,
    outputHashSha256: outputHash,
    executedAt: new Date().toISOString(),
    status,
  };
}

