/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-019 — POA (Performance Optimization Agent)
 * src/cubio/agents/poa/performanceOptimizationAgent.ts
 *
 * Sovereign facade for AGENT-019-POA.
 * Enforces permanent actuation lockout, non-destructive read-only profiling,
 * evidence-linked bottleneck classification, and cryptographic SHA-256 signatures.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import * as crypto from 'crypto';
import {
  POA_AGENT_ID,
  POA_AGENT_NAME,
  POA_VERSION,
  POARequest,
  POAReport,
  POABoundsConfig,
  DEFAULT_POA_BOUNDS,
  POABottleneckFinding,
  POAOptimizationRecommendation,
  POABenchmarkResult,
  POARuntimeMeasurement,
} from './types';
import { RuntimeProfiler } from './runtimeProfiler';
import { BaselineBenchmarkRunner } from './baselineBenchmarkRunner';
import { POAMetricsAdapter } from './metricsAdapter';
import { StoragePerformanceAdapter } from './storagePerformanceAdapter';
import { BottleneckAnalyzer } from './bottleneckAnalyzer';
import { RecommendationBuilder } from './recommendationBuilder';

export class PerformanceOptimizationAgent {
  public static readonly AGENT_ID = POA_AGENT_ID;
  public static readonly AGENT_NAME = POA_AGENT_NAME;
  public static readonly VERSION = POA_VERSION;

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public get is_actuation_blocked(): boolean {
    return true;
  }

  private readonly bounds: POABoundsConfig;
  private readonly profiler: RuntimeProfiler;
  private readonly benchmarkRunner: BaselineBenchmarkRunner;
  private readonly metricsAdapter: POAMetricsAdapter;
  private readonly storageAdapter: StoragePerformanceAdapter;
  private readonly bottleneckAnalyzer: BottleneckAnalyzer;
  private readonly recommendationBuilder: RecommendationBuilder;

  constructor(customBounds?: Partial<POABoundsConfig>) {
    this.bounds = { ...DEFAULT_POA_BOUNDS, ...(customBounds || {}) };
    this.profiler = new RuntimeProfiler(this.bounds);
    this.benchmarkRunner = new BaselineBenchmarkRunner(this.bounds);
    this.metricsAdapter = new POAMetricsAdapter();
    this.storageAdapter = new StoragePerformanceAdapter();
    this.bottleneckAnalyzer = new BottleneckAnalyzer(this.bounds);
    this.recommendationBuilder = new RecommendationBuilder(this.bounds);
  }

  public getBounds(): POABoundsConfig {
    return this.bounds;
  }

  public getMetricsAdapter(): POAMetricsAdapter {
    return this.metricsAdapter;
  }

  public getStorageAdapter(): StoragePerformanceAdapter {
    return this.storageAdapter;
  }

  public getBenchmarkRunner(): BaselineBenchmarkRunner {
    return this.benchmarkRunner;
  }

  /**
   * Main entry point for executing POA performance audit and benchmark requests.
   */
  public async execute(request: POARequest): Promise<POAReport> {
    const startTime = performance.now();

    // 1. Request Validation (Fail-closed)
    if (!request || typeof request !== 'object') {
      return this.buildReport('UNKNOWN', 'FAILED', 0, [], [], ['Null or invalid request object']);
    }

    const taskId = request.taskId || (request.payload?.taskId as string) || `POA-TASK-${Date.now().toString(36)}`;

    if ((request.payload as any)?.actuation_override || (request.payload as any)?.bypassActuationLock) {
      return this.buildReport(
        taskId,
        'BLOCKED',
        0,
        [],
        [],
        ['Hardware actuation override is permanently blocked (IS_ACTUATION_BLOCKED = true)']
      );
    }

    const findings: POABottleneckFinding[] = [];
    const limitations: string[] = [];
    let benchmarkResult: POABenchmarkResult | undefined;
    let runtimeMeasurement: POARuntimeMeasurement | undefined;

    try {
      switch (request.taskType) {
        case 'PROFILE_EXECUTION': {
          const fnToProfile = (request.payload?.workloadFn as any) || (() => {
            // Default harmless workload if none supplied
            let sum = 0;
            for (let i = 0; i < 1000; i++) sum += i;
            return sum;
          });

          const { measurement } = this.profiler.profileSync(
            request.targetSubsystem || 'DefaultTask',
            fnToProfile
          );
          runtimeMeasurement = measurement;

          if (measurement.durationMs > this.bounds.p95LatencyWarningThresholdMs) {
            findings.push({
              findingId: `FIND-PROF-${request.taskId}`,
              classification: 'MEASURED_BOTTLENECK',
              severity: 'WARNING',
              targetSubsystem: request.targetSubsystem || 'Execution',
              title: `High Execution Duration in ${request.targetSubsystem || 'Execution'}`,
              description: `Execution duration of ${measurement.durationMs}ms exceeded threshold.`,
              evidence: `Single profile durationMs=${measurement.durationMs}, heapDelta=${measurement.heapDeltaBytes}`,
              confidence: 0.8,
            });
          }
          break;
        }

        case 'BENCHMARK_BASELINE': {
          const config = {
            benchmarkId: request.benchmarkConfig?.benchmarkId || `BENCH-${taskId}`,
            targetName: request.benchmarkConfig?.targetName || request.targetSubsystem || 'BenchmarkTarget',
            iterations: request.benchmarkConfig?.iterations || 20,
            warmupIterations: request.benchmarkConfig?.warmupIterations || 5,
            timeoutBudgetMs: request.benchmarkConfig?.timeoutBudgetMs || this.bounds.maxExecutionBudgetMs,
          };

          const workload = (request.payload?.workloadFn as any) || (() => {
            // Default harmless benchmark workload
            let res = 0;
            for (let i = 0; i < 500; i++) res += (i * 3) % 7;
            return res;
          });

          benchmarkResult = this.benchmarkRunner.runSyncBenchmark(config, workload);
          const benchFindings = this.bottleneckAnalyzer.analyzeBenchmark(benchmarkResult);
          findings.push(...benchFindings);
          break;
        }

        case 'ANALYZE_BOTTLENECK': {
          if (request.querySqlOrComponent) {
            if (request.querySqlOrComponent.toUpperCase().includes('SELECT')) {
              // Analyze SQL query
              const queryReport = this.storageAdapter.evaluateQuery(request.querySqlOrComponent);
              const qFindings = this.bottleneckAnalyzer.analyzeQueryReport(queryReport);
              findings.push(...qFindings);
            } else {
              // Analyze component lifecycle
              const lifecycleReport = this.storageAdapter.evaluateLifecycle(
                request.querySqlOrComponent,
                request.payload?.config || {}
              );
              const lcFindings = this.bottleneckAnalyzer.analyzeLifecycleReport(lifecycleReport);
              findings.push(...lcFindings);
            }
          } else {
            limitations.push('No querySqlOrComponent provided for bottleneck analysis.');
          }
          break;
        }

        case 'AUDIT_RESOURCES': {
          const lifecycleReport = this.storageAdapter.evaluateLifecycle(
            request.targetSubsystem || 'TargetResource',
            request.payload?.config || {}
          );
          findings.push(...this.bottleneckAnalyzer.analyzeLifecycleReport(lifecycleReport));
          break;
        }

        case 'FULL_PERFORMANCE_AUDIT': {
          // 1. Run Baseline Benchmark
          const benchConfig = {
            benchmarkId: `FULL-BENCH-${request.taskId}`,
            targetName: request.targetSubsystem || 'FullSystemProfile',
            iterations: 15,
            warmupIterations: 3,
          };
          benchmarkResult = this.benchmarkRunner.runSyncBenchmark(benchConfig, () => {
            let acc = 0;
            for (let i = 0; i < 300; i++) acc += (i * 2) % 5;
            return acc;
          });
          findings.push(...this.bottleneckAnalyzer.analyzeBenchmark(benchmarkResult));

          // 2. Audit Query if supplied
          if (request.querySqlOrComponent && request.querySqlOrComponent.toUpperCase().includes('SELECT')) {
            const queryReport = this.storageAdapter.evaluateQuery(request.querySqlOrComponent);
            findings.push(...this.bottleneckAnalyzer.analyzeQueryReport(queryReport));
          }
          break;
        }

        default:
          return this.buildReport(taskId, 'FAILED', 0, [], [], [
            `Unsupported taskType: ${request.taskType}`,
          ]);
      }

      const recommendations = this.recommendationBuilder.buildRecommendations(findings);
      const durationMs = Number((performance.now() - startTime).toFixed(3));

      return this.buildReport(
        taskId,
        'SUCCEEDED',
        durationMs,
        findings,
        recommendations,
        limitations,
        benchmarkResult,
        runtimeMeasurement
      );
    } catch (err: any) {
      const durationMs = Number((performance.now() - startTime).toFixed(3));
      return this.buildReport(taskId, 'FAILED', durationMs, [], [], [
        `Unhandled error in POA: ${err?.message || String(err)}`,
      ]);
    }
  }

  private buildReport(
    taskId: string,
    status: 'SUCCEEDED' | 'FAILED' | 'BLOCKED' | 'PARTIAL',
    durationMs: number,
    findings: POABottleneckFinding[],
    recommendations: POAOptimizationRecommendation[],
    limitations: string[],
    benchmarkResult?: POABenchmarkResult,
    runtimeMeasurement?: POARuntimeMeasurement
  ): POAReport {
    const reportData = {
      reportId: `REP-POA-${taskId}-${Date.now().toString(36)}`,
      taskId,
      status,
      agentId: POA_AGENT_ID,
      agentVersion: POA_VERSION,
      timestamp: Date.now(),
      durationMs,
      is_actuation_blocked: true,
      benchmarkResult,
      runtimeMeasurement,
      findings: findings.slice(0, this.bounds.maxReportFindings),
      recommendations: recommendations.slice(0, this.bounds.maxRecommendations),
      limitations,
    };

    const signature = crypto
      .createHash('sha256')
      .update(JSON.stringify(reportData))
      .digest('hex');

    return Object.freeze({
      ...reportData,
      signature,
    });
  }
}
