/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-014 — MAA (Mathematics Agent)
 * src/cubio/agents/maa/mathEngineAdapter.ts
 *
 * Mathematical Engine Adapter.
 * Integrates:
 * 1. DeterministicArithmeticRouter (word problems, arithmetic, comparisons)
 * 2. VerifiedMathSolver (modular arithmetic in Z/9Z, digital roots, cyclic proofs)
 * 3. Math369 (modular matrix rotations and transformations)
 * 4. Safe AST Recursive-Descent Parser for compound expressions (+, -, *, /, ^, %, abs, sqrt, log)
 *
 * Completely deterministic. Zero external network calls. Zero dynamic eval.
 */

import { DeterministicArithmeticRouter } from '../../model/native_foundation/deterministic_arithmetic_router';
import { VerifiedMathSolver } from '../../intelligence/universal/native369/solvers/verifiedMathSolver';
import { Math369 } from '../../engine_369/math369';
import {
  MAATaskType,
  MAADerivationStep,
  MAABoundsConfig,
} from './types';

export interface EngineEvaluationResult {
  readonly success: boolean;
  readonly resultValue?: number | string | boolean | readonly (readonly number[])[];
  readonly formattedResult: string;
  readonly derivationSteps: readonly MAADerivationStep[];
  readonly explanation: string;
  readonly error?: string;
  readonly isDivisionByZero?: boolean;
}

export class MathEngineAdapter {
  private readonly verifiedSolver = new VerifiedMathSolver();

  /**
   * Evaluates mathematical requests across different task types.
   */
  public evaluate(
    taskType: MAATaskType,
    expression: string,
    prompt: string,
    variables: Readonly<Record<string, number | string>> = {},
    matrixA?: readonly (readonly number[])[],
    matrixB?: readonly (readonly number[])[],
    numericList?: readonly number[],
    bounds?: MAABoundsConfig
  ): EngineEvaluationResult {
    switch (taskType) {
      case 'WORD_PROBLEM_RESOLUTION':
        return this.solveWordProblem(prompt || expression);

      case 'MODULAR_ANALYSIS':
        return this.solveModular(expression || prompt);

      case 'MATRIX_CALCULATION':
        return this.solveMatrix(matrixA, matrixB, bounds);

      case 'STATISTICAL_SUMMARY':
        return this.solveStatistics(numericList || this.extractNumbers(expression || prompt));

      case 'ALGEBRAIC_SIMPLIFICATION':
      case 'EQUATION_SOLVING':
      case 'ARITHMETIC_EVALUATION':
      default:
        return this.evaluateExpression(expression || prompt, variables, bounds);
    }
  }

  /**
   * Solves word problems and basic arithmetic via DeterministicArithmeticRouter.
   */
  private solveWordProblem(input: string): EngineEvaluationResult {
    const resolution = DeterministicArithmeticRouter.resolve(input);
    if (resolution.isMatch && resolution.result !== undefined) {
      const steps: MAADerivationStep[] = [
        {
          stepNumber: 1,
          rule: `PATTERN_DETECTION_${resolution.operation || 'WORD_PROBLEM'}`,
          expressionBefore: input,
          expressionAfter: `Identified operands: A=${resolution.operandA}, B=${resolution.operandB}`,
          explanation: `Parsed entities: ${resolution.matchedPattern || 'Deterministic Word Pattern'}`,
        },
        {
          stepNumber: 2,
          rule: 'DETERMINISTIC_RESOLUTION',
          expressionBefore: `${resolution.operandA} [${resolution.operation}] ${resolution.operandB}`,
          expressionAfter: String(resolution.result),
          explanation: resolution.responseText || `Computed result: ${resolution.result}`,
        },
      ];

      return {
        success: true,
        resultValue: resolution.result,
        formattedResult: String(resolution.result),
        derivationSteps: steps,
        explanation: resolution.responseText || `Resolved pattern ${resolution.matchedPattern} to ${resolution.result}`,
      };
    }

    // Fall back to general word problem arithmetic extraction
    const numbers = this.extractNumbers(input);
    const lower = input.toLowerCase();
    if (numbers.length >= 2) {
      if (lower.includes('total') || lower.includes('combined') || lower.includes('plus') || lower.includes('add') || lower.includes('together')) {
        const sum = numbers.reduce((a, b) => a + b, 0);
        return {
          success: true,
          resultValue: sum,
          formattedResult: String(sum),
          derivationSteps: [
            {
              stepNumber: 1,
              rule: 'WORD_PROBLEM_TOTAL_SUM',
              expressionBefore: `Extracted quantities: ${numbers.join(', ')}`,
              expressionAfter: String(sum),
              explanation: `Extracted addends from word problem and computed sum = ${sum}`,
            },
          ],
          explanation: `Computed total sum of ${numbers.join(' + ')} = ${sum}`,
        };
      }
      if (lower.includes('remain') || lower.includes('left') || lower.includes('difference') || lower.includes('removed') || lower.includes('take away')) {
        const diff = numbers[0] - numbers[1];
        return {
          success: true,
          resultValue: diff,
          formattedResult: String(diff),
          derivationSteps: [
            {
              stepNumber: 1,
              rule: 'WORD_PROBLEM_REMAINING_DIFF',
              expressionBefore: `${numbers[0]} - ${numbers[1]}`,
              expressionAfter: String(diff),
              explanation: `Computed difference of extracted quantities = ${diff}`,
            },
          ],
          explanation: `Computed remaining balance ${numbers[0]} - ${numbers[1]} = ${diff}`,
        };
      }
    }

    // Fall back to general expression evaluator
    return this.evaluateExpression(input);
  }

  /**
   * Solves modular arithmetic and digital roots via VerifiedMathSolver and Math369.
   */
  private solveModular(input: string): EngineEvaluationResult {
    // Look for explicit number
    const numMatch = input.match(/-?\d+(\.\d+)?/);
    const n = numMatch ? parseFloat(numMatch[0]) : 9;

    const modularSection = this.verifiedSolver.solveVerifiedMath(n);
    const dr = Math369.computeDigitalRoot(n);

    const steps: MAADerivationStep[] = [
      {
        stepNumber: 1,
        rule: 'MODULAR_CONGRUENCE_Z9',
        expressionBefore: `n = ${n}`,
        expressionAfter: `dr(n) = ${dr}, n mod 9 = ${modularSection.modularClassMod9}`,
        explanation: 'Applied digital root reduction dr(n) = 1 + ((n - 1) mod 9) in Z/9Z.',
      },
      {
        stepNumber: 2,
        rule: 'CYCLIC_INVARIANT_ANALYSIS',
        expressionBefore: `Node class: ${dr}`,
        expressionAfter: modularSection.isTriadicInvariantNode ? 'Triadic Invariant Node {3, 6, 9}' : 'Doubling Orbit Node {1, 2, 4, 8, 7, 5}',
        explanation: modularSection.formalMathematicalProof,
      },
    ];

    return {
      success: true,
      resultValue: dr,
      formattedResult: `Digital Root: ${dr}, Modulo 9: ${modularSection.modularClassMod9}`,
      derivationSteps: steps,
      explanation: modularSection.formalMathematicalProof,
    };
  }

  /**
   * Evaluates matrix operations deterministically.
   */
  private solveMatrix(
    matrixA?: readonly (readonly number[])[],
    matrixB?: readonly (readonly number[])[],
    bounds?: MAABoundsConfig
  ): EngineEvaluationResult {
    if (!matrixA || matrixA.length === 0 || !matrixA[0]) {
      return {
        success: false,
        formattedResult: 'Error: Matrix A is empty or invalid',
        derivationSteps: [],
        explanation: 'Matrix calculation requires at least one non-empty matrix',
        error: 'Invalid matrix input',
      };
    }

    const rowsA = matrixA.length;
    const colsA = matrixA[0].length;
    const maxDim = bounds?.maxMatrixDimension || 100;

    if (rowsA > maxDim || colsA > maxDim) {
      return {
        success: false,
        formattedResult: 'Error: Matrix dimension exceeds safety bounds',
        derivationSteps: [],
        explanation: `Matrix dimensions (${rowsA}x${colsA}) exceed maximum bound of ${maxDim}`,
        error: 'Matrix bounds exceeded',
      };
    }

    // If matrixB is provided, perform matrix multiplication
    if (matrixB && matrixB.length > 0 && matrixB[0]) {
      const rowsB = matrixB.length;
      const colsB = matrixB[0].length;

      if (colsA !== rowsB) {
        return {
          success: false,
          formattedResult: 'Error: Incompatible matrix dimensions for multiplication',
          derivationSteps: [],
          explanation: `Cannot multiply ${rowsA}x${colsA} matrix with ${rowsB}x${colsB} matrix: column count of A must equal row count of B`,
          error: 'Dimension mismatch',
        };
      }

      const product: number[][] = [];
      for (let i = 0; i < rowsA; i++) {
        product[i] = [];
        for (let j = 0; j < colsB; j++) {
          let sum = 0;
          for (let k = 0; k < colsA; k++) {
            sum += matrixA[i][k] * matrixB[k][j];
          }
          product[i][j] = sum;
        }
      }

      const steps: MAADerivationStep[] = [
        {
          stepNumber: 1,
          rule: 'MATRIX_DIMENSION_VERIFICATION',
          expressionBefore: `A: ${rowsA}x${colsA}, B: ${rowsB}x${colsB}`,
          expressionAfter: `Result: ${rowsA}x${colsB}`,
          explanation: 'Verified inner dimensions match for dot product calculation.',
        },
        {
          stepNumber: 2,
          rule: 'INNER_PRODUCT_COMPUTATION',
          expressionBefore: 'C[i][j] = sum(A[i][k] * B[k][j])',
          expressionAfter: JSON.stringify(product),
          explanation: `Computed matrix multiplication across ${rowsA}x${colsB} cells.`,
        },
      ];

      return {
        success: true,
        resultValue: product,
        formattedResult: JSON.stringify(product),
        derivationSteps: steps,
        explanation: `Successfully computed ${rowsA}x${colsB} matrix product`,
      };
    }

    // Single matrix determinant (if 2x2) or trace
    if (rowsA === 2 && colsA === 2) {
      const det = matrixA[0][0] * matrixA[1][1] - matrixA[0][1] * matrixA[1][0];
      return {
        success: true,
        resultValue: det,
        formattedResult: `Determinant: ${det}`,
        derivationSteps: [
          {
            stepNumber: 1,
            rule: 'DETERMINANT_2X2',
            expressionBefore: `|[[${matrixA[0][0]}, ${matrixA[0][1]}], [${matrixA[1][0]}, ${matrixA[1][1]}]]|`,
            expressionAfter: `(${matrixA[0][0]} * ${matrixA[1][1]}) - (${matrixA[0][1]} * ${matrixA[1][0]}) = ${det}`,
            explanation: 'Applied ad - bc formula for 2x2 matrix determinant.',
          },
        ],
        explanation: `Computed 2x2 determinant = ${det}`,
      };
    }

    // Default trace for square matrices
    if (rowsA === colsA) {
      let trace = 0;
      for (let i = 0; i < rowsA; i++) trace += matrixA[i][i];
      return {
        success: true,
        resultValue: trace,
        formattedResult: `Trace: ${trace}`,
        derivationSteps: [
          {
            stepNumber: 1,
            rule: 'MATRIX_TRACE',
            expressionBefore: `diag(A) for ${rowsA}x${rowsA}`,
            expressionAfter: `sum = ${trace}`,
            explanation: 'Summed elements along main diagonal.',
          },
        ],
        explanation: `Computed square matrix trace = ${trace}`,
      };
    }

    return {
      success: true,
      resultValue: matrixA,
      formattedResult: JSON.stringify(matrixA),
      derivationSteps: [],
      explanation: 'Matrix ingested without transformation',
    };
  }

  /**
   * Computes statistical summary (mean, median, min, max, variance, stdDev).
   */
  private solveStatistics(numbers: readonly number[]): EngineEvaluationResult {
    if (!numbers || numbers.length === 0) {
      return {
        success: false,
        formattedResult: 'Error: No numeric values provided for statistical calculation',
        derivationSteps: [],
        explanation: 'Statistical summary requires at least one number',
        error: 'Empty dataset',
      };
    }

    const n = numbers.length;
    const sorted = [...numbers].sort((a, b) => a - b);
    const sum = numbers.reduce((acc, val) => acc + val, 0);
    const mean = sum / n;

    const median = n % 2 === 0
      ? (sorted[n / 2 - 1] + sorted[n / 2]) / 2
      : sorted[Math.floor(n / 2)];

    const min = sorted[0];
    const max = sorted[n - 1];

    const variance = numbers.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0) / n;
    const stdDev = Math.sqrt(variance);

    const summary = {
      count: n,
      sum,
      mean: parseFloat(mean.toFixed(6)),
      median: parseFloat(median.toFixed(6)),
      min,
      max,
      variance: parseFloat(variance.toFixed(6)),
      stdDev: parseFloat(stdDev.toFixed(6)),
    };

    const steps: MAADerivationStep[] = [
      {
        stepNumber: 1,
        rule: 'DATASET_SORT_AND_SUM',
        expressionBefore: `Count: ${n}`,
        expressionAfter: `Sorted: [${sorted.slice(0, 10).join(', ')}${n > 10 ? '...' : ''}], Sum: ${sum}`,
        explanation: 'Sorted input sample and computed total sum.',
      },
      {
        stepNumber: 2,
        rule: 'CENTRAL_TENDENCY_MOMENTS',
        expressionBefore: 'mean = sum / n, median = mid(sorted)',
        expressionAfter: `Mean: ${summary.mean}, Median: ${summary.median}, Min: ${min}, Max: ${max}`,
        explanation: 'Evaluated central tendencies and extrema.',
      },
      {
        stepNumber: 3,
        rule: 'DISPERSION_ANALYSIS',
        expressionBefore: 'variance = sum((x - mean)^2) / n, stdDev = sqrt(variance)',
        expressionAfter: `Variance: ${summary.variance}, StdDev: ${summary.stdDev}`,
        explanation: 'Evaluated second-order central moment and dispersion.',
      },
    ];

    return {
      success: true,
      resultValue: summary.mean,
      formattedResult: `Mean: ${summary.mean}, Median: ${summary.median}, Min: ${min}, Max: ${max}, StdDev: ${summary.stdDev}`,
      derivationSteps: steps,
      explanation: `Computed statistical metrics for ${n} items`,
    };
  }

  /**
   * Safe recursive-descent expression evaluator (no eval).
   * Supports: +, -, *, /, ^, %, abs, sqrt, log, and variable substitution.
   */
  public evaluateExpression(
    expr: string,
    variables: Readonly<Record<string, number | string>> = {},
    bounds?: MAABoundsConfig
  ): EngineEvaluationResult {
    try {
      // 1. Variable substitution
      let processed = expr;
      for (const [key, val] of Object.entries(variables)) {
        const regex = new RegExp(`\\b${key}\\b`, 'g');
        processed = processed.replace(regex, String(val));
      }

      // 2. Safe Recursive-Descent Tokenizer and Evaluator
      const evaluator = new SafeExpressionEvaluator(processed, bounds);
      const evalResult = evaluator.parse();
      if (evalResult.success) {
        return evalResult;
      }

      // 3. Fallback to DeterministicArithmeticRouter for natural language phrases
      const routerResult = DeterministicArithmeticRouter.resolve(expr);
      if (routerResult.isMatch && routerResult.result !== undefined) {
        if (routerResult.result === 'UNDEFINED') {
          return {
            success: false,
            formattedResult: 'Error: Division by zero is undefined',
            derivationSteps: [],
            explanation: 'Division by zero is undefined',
            error: 'Division by zero detected',
            isDivisionByZero: true,
          };
        }
        return {
          success: true,
          resultValue: routerResult.result,
          formattedResult: String(routerResult.result),
          derivationSteps: [
            {
              stepNumber: 1,
              rule: 'ARITHMETIC_ROUTER',
              expressionBefore: expr,
              expressionAfter: String(routerResult.result),
              explanation: routerResult.responseText || `Resolved arithmetic to ${routerResult.result}`,
            },
          ],
          explanation: routerResult.responseText || `Computed ${routerResult.result}`,
        };
      }

      return evalResult;
    } catch (err: any) {
      const isDivZero = /division by zero/i.test(err?.message || '');
      return {
        success: false,
        formattedResult: `Error: ${err?.message || 'Calculation failed'}`,
        derivationSteps: [],
        explanation: err?.message || 'Calculation error',
        error: err?.message || 'Calculation error',
        isDivisionByZero: isDivZero,
      };
    }
  }

  private extractNumbers(text: string): number[] {
    const matches = text.match(/-?\d+(\.\d+)?/g);
    return matches ? matches.map(Number) : [];
  }
}

/**
 * Safe Recursive-Descent Mathematical Parser.
 * Grammar:
 * Expr    := Term (('+' | '-') Term)*
 * Term    := Factor (('*' | '/' | '%') Factor)*
 * Factor  := Power ('^' Power)*
 * Power   := ('+' | '-')? Primary
 * Primary := Number | FunctionCall | '(' Expr ')'
 */
class SafeExpressionEvaluator {
  private pos = 0;
  private readonly str: string;
  private readonly steps: MAADerivationStep[] = [];
  private stepCounter = 1;
  private readonly bounds?: MAABoundsConfig;

  constructor(expression: string, bounds?: MAABoundsConfig) {
    let clean = expression.replace(/^(?:calculate|compute|what is|find the value of|evaluate)\s+/i, '');
    this.str = clean.replace(/\s+/g, '');
    this.bounds = bounds;
  }

  public parse(): EngineEvaluationResult {
    if (!this.str) {
      return {
        success: false,
        formattedResult: 'Error: Empty expression',
        derivationSteps: [],
        explanation: 'No expression provided',
        error: 'Empty expression',
      };
    }

    const value = this.parseExpr();

    if (this.pos < this.str.length) {
      throw new Error(`Unexpected token at position ${this.pos}: '${this.str.slice(this.pos)}'`);
    }

    // Magnitude check
    const maxMag = this.bounds?.maxNumberMagnitude || 1e15;
    if (Math.abs(value) > maxMag && isFinite(value)) {
      throw new Error(`Computed value ${value} exceeds safety threshold ${maxMag}`);
    }

    const formatted = Number.isInteger(value) ? String(value) : String(parseFloat(value.toFixed(10)));

    return {
      success: true,
      resultValue: value,
      formattedResult: formatted,
      derivationSteps: this.steps,
      explanation: `Evaluated expression to ${formatted}`,
    };
  }

  private parseExpr(): number {
    let result = this.parseTerm();

    while (this.pos < this.str.length) {
      const op = this.str[this.pos];
      if (op === '+' || op === '-') {
        this.pos++;
        const nextTerm = this.parseTerm();
        const prev = result;
        if (op === '+') {
          result = result + nextTerm;
          this.addStep('ADDITION', `${prev} + ${nextTerm}`, String(result));
        } else {
          result = result - nextTerm;
          this.addStep('SUBTRACTION', `${prev} - ${nextTerm}`, String(result));
        }
      } else {
        break;
      }
    }

    return result;
  }

  private parseTerm(): number {
    let result = this.parseFactor();

    while (this.pos < this.str.length) {
      const op = this.str[this.pos];
      if (op === '*' || op === '/' || op === '%') {
        this.pos++;
        const nextFactor = this.parseFactor();
        const prev = result;
        if (op === '*') {
          result = result * nextFactor;
          this.addStep('MULTIPLICATION', `${prev} * ${nextFactor}`, String(result));
        } else if (op === '/') {
          if (nextFactor === 0) {
            throw new Error('Division by zero detected');
          }
          result = result / nextFactor;
          this.addStep('DIVISION', `${prev} / ${nextFactor}`, String(result));
        } else if (op === '%') {
          if (nextFactor === 0) {
            throw new Error('Modulo by zero detected');
          }
          result = result % nextFactor;
          this.addStep('MODULO', `${prev} % ${nextFactor}`, String(result));
        }
      } else {
        break;
      }
    }

    return result;
  }

  private parseFactor(): number {
    let base = this.parseUnary();

    if (this.pos < this.str.length && this.str[this.pos] === '^') {
      this.pos++;
      const exponent = this.parseFactor(); // Right-associative
      const prev = base;
      base = Math.pow(base, exponent);
      this.addStep('EXPONENTIATION', `${prev} ^ ${exponent}`, String(base));
    }

    return base;
  }

  private parseUnary(): number {
    if (this.pos < this.str.length) {
      const char = this.str[this.pos];
      if (char === '+') {
        this.pos++;
        return this.parseUnary();
      }
      if (char === '-') {
        this.pos++;
        const val = this.parseUnary();
        return -val;
      }
    }
    return this.parsePrimary();
  }

  private parsePrimary(): number {
    if (this.pos >= this.str.length) {
      throw new Error('Unexpected end of expression');
    }

    // Parentheses
    if (this.str[this.pos] === '(') {
      this.pos++;
      const val = this.parseExpr();
      if (this.pos >= this.str.length || this.str[this.pos] !== ')') {
        throw new Error('Missing closing parenthesis');
      }
      this.pos++;
      return val;
    }

    // Named Functions (sqrt, abs, log, sin, cos, tan) or constants (pi, e)
    const letterMatch = this.str.slice(this.pos).match(/^[a-zA-Z]+/);
    if (letterMatch) {
      const name = letterMatch[0].toLowerCase();
      this.pos += name.length;

      if (name === 'pi') return Math.PI;
      if (name === 'e') return Math.E;

      // Function calls require '('
      if (this.pos < this.str.length && this.str[this.pos] === '(') {
        this.pos++;
        const arg = this.parseExpr();
        if (this.pos >= this.str.length || this.str[this.pos] !== ')') {
          throw new Error(`Missing closing parenthesis for function ${name}`);
        }
        this.pos++;

        let res: number;
        switch (name) {
          case 'sqrt':
            if (arg < 0) throw new Error('Square root of negative number not supported');
            res = Math.sqrt(arg);
            break;
          case 'abs':
            res = Math.abs(arg);
            break;
          case 'log':
            if (arg <= 0) throw new Error('Logarithm of non-positive number undefined');
            res = Math.log(arg);
            break;
          case 'sin':
            res = Math.sin(arg);
            break;
          case 'cos':
            res = Math.cos(arg);
            break;
          case 'tan':
            res = Math.tan(arg);
            break;
          default:
            throw new Error(`Unsupported mathematical function: ${name}`);
        }

        this.addStep(`FUNCTION_${name.toUpperCase()}`, `${name}(${arg})`, String(res));
        return res;
      }

      throw new Error(`Unrecognized symbol or missing argument list for: ${name}`);
    }

    // Numbers (integers or decimals)
    const numMatch = this.str.slice(this.pos).match(/^\d+(\.\d+)?/);
    if (numMatch) {
      const numStr = numMatch[0];
      this.pos += numStr.length;
      return parseFloat(numStr);
    }

    throw new Error(`Invalid character at position ${this.pos}: '${this.str[this.pos]}'`);
  }

  private addStep(rule: string, before: string, after: string): void {
    this.steps.push({
      stepNumber: this.stepCounter++,
      rule,
      expressionBefore: before,
      expressionAfter: after,
      explanation: `Evaluated ${before} = ${after}`,
    });
  }
}
