/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-013 — CDA (Coding Agent)
 * src/cubio/agents/cda/patchProposalBuilder.ts
 *
 * Constructs structured, non-destructive, auditable patch proposals.
 * Enforces strict boundary checks (rejects path traversal and protected files).
 */

import * as crypto from 'crypto';
import * as path from 'path';
import {
  CDAPatchProposal,
  CDAPatchStatus,
  CDAPatchOperation,
} from './types';
import { FrozenProtectionGuard } from '../../language/native/pma/frozenProtectionGuard';

export class PatchProposalBuilder {
  private readonly frozenGuard: FrozenProtectionGuard;

  constructor(customRootDir?: string) {
    this.frozenGuard = new FrozenProtectionGuard(customRootDir);
  }

  /**
   * Builds a verified patch proposal or flags it as INVALID / BLOCKED.
   */
  public buildProposal(params: {
    taskId: string;
    targetFilePath: string;
    operation: CDAPatchOperation;
    rationale: string;
    originalContent?: string;
    proposedContent: string;
    diffSummary: string;
    linesModified?: readonly number[];
    regressionRisks?: readonly string[];
    verificationCommands?: readonly string[];
  }): CDAPatchProposal {
    const rawTarget = params.targetFilePath || 'unknown_target.ts';
    const normalizedTarget = rawTarget.replace(/\\/g, '/');

    // 1. Boundary & Path Traversal Check
    let patchStatus: CDAPatchStatus = 'PROPOSED';
    const risks: string[] = params.regressionRisks ? [...params.regressionRisks] : [];
    const commands: string[] = params.verificationCommands
      ? [...params.verificationCommands]
      : ['npx tsc --noEmit'];

    if (normalizedTarget.includes('../') || normalizedTarget.startsWith('/') || /^[a-zA-Z]:/.test(normalizedTarget)) {
      patchStatus = 'INVALID';
      risks.push('Path traversal attempt detected or absolute path forbidden.');
    }

    // 2. Frozen File Boundary Check
    if (this.frozenGuard.isProtected(normalizedTarget)) {
      patchStatus = 'BLOCKED';
      risks.push(`Modification of protected frozen authority blocked: ${normalizedTarget}`);
    }

    // 3. Compute Checksums
    const targetPathChecksum = crypto
      .createHash('sha256')
      .update(normalizedTarget)
      .digest('hex');

    const proposalContentDigest = crypto
      .createHash('sha256')
      .update(
        `${params.taskId}:${normalizedTarget}:${params.operation}:${params.proposedContent}`
      )
      .digest('hex');

    const proposalId = `PROP_${proposalContentDigest.slice(0, 12).toUpperCase()}`;

    return Object.freeze({
      proposalId,
      taskId: params.taskId,
      targetFilePath: normalizedTarget,
      operation: params.operation,
      patchStatus,
      rationale: params.rationale,
      originalContentExcerpt: params.originalContent ? params.originalContent.slice(0, 500) : undefined,
      proposedContent: params.proposedContent,
      diffSummary: params.diffSummary,
      linesModified: Object.freeze(params.linesModified ? [...params.linesModified] : [1]),
      targetPathChecksum,
      proposalChecksum: proposalContentDigest,
      potentialRegressionRisks: Object.freeze(risks),
      suggestedVerificationCommands: Object.freeze(commands),
    });
  }
}
