/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-015 — BFA (Bug-Fixing Agent)
 * src/cubio/agents/bfa/diagnosticAdapter.ts
 *
 * Integrates existing diagnostic engines:
 * - ErrorDiagnoser
 * - BugFixer
 * - RegressionVerifier
 * - debugCodeSnippet
 * - VirtualSandbox
 */

import { CubiOCodeAnalysisEngine } from '../../intelligence/universal/coding/analysis/codeAnalysisEngine';
import { debugCodeSnippet } from '../../intelligence/universal/coding/codeDebugger';
import { VirtualSandbox, SandboxExecutionOutcome } from '../../intelligence/universal/coding/sandbox/virtualSandbox';
import {
  ErrorDiagnosisReport,
  BugFixReport,
  RegressionVerificationReport,
} from '../../intelligence/universal/coding/analysis/types';

export class DiagnosticAdapter {
  private readonly analysisEngine = new CubiOCodeAnalysisEngine();
  private readonly sandbox = new VirtualSandbox();

  public diagnoseError(errorTrace: string, codeSnippet?: string): ErrorDiagnosisReport {
    return this.analysisEngine.diagnoseError(errorTrace, codeSnippet);
  }

  public fixBug(code: string, issueDescription: string): BugFixReport {
    return this.analysisEngine.fixBug(code, issueDescription);
  }

  public verifyRegression(
    originalCode: string,
    patchedCode: string,
    testCasesCount?: number
  ): RegressionVerificationReport {
    return this.analysisEngine.verifyRegression(originalCode, patchedCode, testCasesCount);
  }

  public debugSnippet(code: string, errorTrace: string) {
    return debugCodeSnippet({ code, errorTrace });
  }

  public async executeInSandbox(
    code: string,
    inputPayload?: Record<string, unknown>
  ): Promise<SandboxExecutionOutcome> {
    return this.sandbox.executeIsolated(code, inputPayload);
  }
}
