/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-015 — BFA (Bug-Fixing Agent)
 * src/cubio/agents/bfa/types.ts
 *
 * Contracts, request/report interfaces, root-cause models,
 * fix proposals, regression plans, and bounds for BFA.
 */

export type BFADefectCategory =
  | 'COMPILER_TYPESCRIPT'
  | 'SYNTAX_ERROR'
  | 'RUNTIME_EXCEPTION'
  | 'TEST_FAILURE'
  | 'LOGIC_REGRESSION'
  | 'DEPENDENCY_FAULT'
  | 'UNKNOWN';

export type BFARequestStatus =
  | 'DIAGNOSED'
  | 'FIX_PROPOSED'
  | 'NEEDS_MORE_EVIDENCE'
  | 'VERIFICATION_PENDING'
  | 'VERIFIED'
  | 'VERIFICATION_FAILED'
  | 'BLOCKED'
  | 'FAILED'
  | 'TIMED_OUT';

export interface BFABoundsConfig {
  readonly maxErrorTraceLength: number; // default: 20,000 chars
  readonly maxCodeInputLength: number; // default: 50,000 chars
  readonly maxPromptLength: number; // default: 4,000 chars
  readonly maxOutputBytes: number; // default: 131,072 bytes (128 KB)
  readonly maxExecutionMs: number; // default: 10,000 ms
}

export const DEFAULT_BFA_BOUNDS: BFABoundsConfig = Object.freeze({
  maxErrorTraceLength: 20_000,
  maxCodeInputLength: 50_000,
  maxPromptLength: 4_000,
  maxOutputBytes: 131_072,
  maxExecutionMs: 10_000,
});

export interface BFADefectRequest {
  readonly requestId: string;
  readonly taskId: string;
  readonly defectDescription?: string;
  readonly errorTrace?: string;
  readonly codeSnippet?: string;
  readonly targetFilePath?: string;
  readonly testSnippet?: string;
  readonly existingFiles?: Readonly<Record<string, string>>;
  readonly bounds?: Partial<BFABoundsConfig>;
  readonly bypassActuationLock?: boolean; // Attacker test payload - must be rejected
}

export interface BFARootCauseCandidate {
  readonly causeId: string;
  readonly category: BFADefectCategory;
  readonly symptomSummary: string;
  readonly rootCauseHypothesis: string;
  readonly supportingEvidence: string;
  readonly confidence: number; // 0.0 to 1.0
  readonly isConfirmed: boolean;
  readonly affectedFile?: string;
  readonly affectedLine?: number;
}

export interface BFAFixProposal {
  readonly proposalId: string;
  readonly defectId: string;
  readonly targetFilePath: string;
  readonly diffSummary: string;
  readonly originalSnippet?: string;
  readonly proposedSnippet: string;
  readonly linesModified: readonly number[];
  readonly rationale: string;
  readonly proposalChecksum: string;
  readonly status: 'PROPOSED' | 'INVALID' | 'BLOCKED';
  readonly potentialRisks: readonly string[];
}

export interface BFARegressionPlan {
  readonly reproducingTestHint?: string;
  readonly suggestedVerificationSuites: readonly string[];
  readonly acceptanceCriteria: readonly string[];
  readonly riskAssessment: string;
}

export interface BFADefectReport {
  readonly reportId: string;
  readonly requestId: string;
  readonly taskId: string;
  readonly status: BFARequestStatus;
  readonly category: BFADefectCategory;
  readonly summary: string;
  readonly rootCauseCandidates: readonly BFARootCauseCandidate[];
  readonly fixProposal?: BFAFixProposal;
  readonly regressionPlan: BFARegressionPlan;
  readonly boundsEnforced: BFABoundsConfig;
  readonly executionDurationMs: number;
  readonly generatedAt: string;
  readonly reportChecksum: string;
  readonly is_actuation_blocked: true;
}
