/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-019 — POA (Performance Optimization Agent)
 * src/cubio/agents/poa/metricsAdapter.ts
 *
 * Interfaces with AGENT-011 (OMA) metrics and telemetry without duplicating
 * metric aggregators or in-memory ring buffers.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import { MetricsAggregator } from '../oma/metricsAggregator';
import { OMAMetricSummary, OMANormalizedEvent } from '../oma/types';
import { POALatencyPercentiles } from './types';

export class POAMetricsAdapter {
  private readonly omaAggregator: MetricsAggregator;

  constructor(customOmaAggregator?: MetricsAggregator) {
    this.omaAggregator = customOmaAggregator || new MetricsAggregator();
  }

  /**
   * Ingests external normalized events into the underlying OMA aggregator.
   */
  public ingestEvent(event: OMANormalizedEvent): void {
    this.omaAggregator.recordEvent(event);
  }

  /**
   * Fetches summary statistics and translates them into POA-compatible representations.
   */
  public getSummary(): {
    totalEvents: number;
    averageDurationMs: number;
    percentiles: POALatencyPercentiles;
    successRate: number;
  } {
    const summary: OMAMetricSummary = this.omaAggregator.computeSummary();
    const successRate =
      summary.totalEvents > 0
        ? Number((summary.successCount / summary.totalEvents).toFixed(4))
        : 1.0;

    return {
      totalEvents: summary.totalEvents,
      averageDurationMs: summary.averageDurationMs,
      percentiles: {
        p50Ms: summary.percentiles.p50Ms,
        p95Ms: summary.percentiles.p95Ms,
        p99Ms: summary.percentiles.p99Ms,
      },
      successRate,
    };
  }

  public calculateQuantiles(samples: readonly number[]): POALatencyPercentiles {
    const raw = this.omaAggregator.calculatePercentiles(samples);
    return {
      p50Ms: raw.p50Ms,
      p95Ms: raw.p95Ms,
      p99Ms: raw.p99Ms,
    };
  }
}
