/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-015 — BFA (Bug-Fixing Agent)
 * src/cubio/agents/bfa/bugFixingAgent.ts
 *
 * Central facade for AGENT-015-BFA.
 * Specializes in defect triage, root-cause analysis, fix proposals, and regression planning.
 * Enforces permanent actuation lockout (IS_ACTUATION_BLOCKED = true).
 * Non-destructive patch policy: never writes directly to disk.
 */

import * as crypto from 'crypto';
import {
  BFADefectRequest,
  BFADefectReport,
  BFABoundsConfig,
  DEFAULT_BFA_BOUNDS,
  BFARequestStatus,
} from './types';
import { DefectClassifier } from './defectClassifier';
import { DiagnosticAdapter } from './diagnosticAdapter';
import { RootCauseAnalyzer } from './rootCauseAnalyzer';
import { BFAFixProposalBuilder } from './fixProposalBuilder';
import { RegressionPlanner } from './regressionPlanner';

export class BugFixingAgent {
  public static readonly AGENT_ID = 'AGENT-015-BFA';
  public static readonly AGENT_NAME = 'Bug-Fixing Agent';
  public static readonly VERSION = '1.0.0';

  /**
   * Permanent Architectural Safety Invariant.
   * Immutable and fail-closed.
   */
  public get is_actuation_blocked(): boolean {
    return true;
  }

  private readonly defaultBounds: BFABoundsConfig;
  private readonly diagnosticAdapter: DiagnosticAdapter;
  private readonly proposalBuilder: BFAFixProposalBuilder;

  constructor(
    customBounds: BFABoundsConfig = DEFAULT_BFA_BOUNDS,
    customDiagnosticAdapter?: DiagnosticAdapter,
    customProposalBuilder?: BFAFixProposalBuilder
  ) {
    this.defaultBounds = customBounds;
    this.diagnosticAdapter = customDiagnosticAdapter || new DiagnosticAdapter();
    this.proposalBuilder = customProposalBuilder || new BFAFixProposalBuilder();
  }

  /**
   * Primary entry point: Executes a bounded defect diagnosis and fix proposal.
   */
  public async execute(request: BFADefectRequest): Promise<BFADefectReport> {
    const startTimeMs = Date.now();
    const requestId = request?.requestId || `REQ_BFA_${Date.now()}`;
    const taskId = request?.taskId || `TASK_BFA_${Date.now()}`;

    // 1. Fail-closed null/type validation
    if (!request || typeof request !== 'object') {
      return this.buildErrorReport(
        requestId,
        taskId,
        'FAILED',
        'UNKNOWN',
        'Invalid defect request: payload is null or not an object',
        startTimeMs,
        this.defaultBounds
      );
    }

    // 2. Reject malicious actuation override attempts
    if (request.bypassActuationLock === true) {
      return this.buildErrorReport(
        requestId,
        taskId,
        'BLOCKED',
        'UNKNOWN',
        'Hardware actuation override attempt rejected fail-closed. IS_ACTUATION_BLOCKED is immutable.',
        startTimeMs,
        this.defaultBounds
      );
    }

    // 3. Resolve bounds
    const bounds: BFABoundsConfig = {
      ...this.defaultBounds,
      ...(request.bounds || {}),
    };

    // 4. Defect Intake and Classification
    const classification = DefectClassifier.classify(request, bounds);
    if (!classification.isValid) {
      let status: BFARequestStatus = 'FAILED';
      if (classification.errorCode === 'EMPTY_PAYLOAD') status = 'NEEDS_MORE_EVIDENCE';
      if (classification.errorCode === 'BOUNDS_EXCEEDED') status = 'FAILED';

      return this.buildErrorReport(
        requestId,
        taskId,
        status,
        classification.category,
        classification.failureReason || 'Defect payload validation failed',
        startTimeMs,
        bounds
      );
    }

    // 5. Root Cause Analysis
    const errorTrace = (request.errorTrace || '').trim();
    const description = (request.defectDescription || '').trim();
    const codeSnippet = request.codeSnippet;

    const rootCauses = RootCauseAnalyzer.analyze(
      classification.category,
      errorTrace,
      description,
      codeSnippet,
      this.diagnosticAdapter
    );

    // 6. Generate Fix Proposal (if code snippet or issue description exists)
    let fixProposal;
    if (codeSnippet || errorTrace || description) {
      const code = codeSnippet || '// Code site identified from trace';
      let proposedPatch = code;
      let diffSummary = 'Defensive fix applied';
      let rationale = 'Addressed identified defect pattern';

      if (codeSnippet) {
        const bugFix = this.diagnosticAdapter.fixBug(codeSnippet, description || errorTrace || 'Identified bug');
        proposedPatch = bugFix.fixedCode;
        diffSummary = bugFix.diffSummary;
        rationale = bugFix.rootCauseSummary;
      } else {
        proposedPatch = `// Fix for ${errorTrace.slice(0, 80)}\n${code}`;
      }

      fixProposal = this.proposalBuilder.buildProposal({
        defectId: taskId,
        targetFilePath: request.targetFilePath,
        originalCode: codeSnippet,
        proposedPatch,
        diffSummary,
        rationale,
      });
    }

    // 7. Regression Planning
    const regressionPlan = RegressionPlanner.plan(
      classification.category,
      request.targetFilePath,
      request.testSnippet
    );

    // 8. Determine final report status
    let finalStatus: BFARequestStatus = 'DIAGNOSED';
    if (fixProposal) {
      if (fixProposal.status === 'BLOCKED') {
        finalStatus = 'BLOCKED';
      } else if (fixProposal.status === 'INVALID') {
        finalStatus = 'FAILED';
      } else {
        finalStatus = 'FIX_PROPOSED';
      }
    }

    // Optional in-memory verification if testSnippet provided
    if (request.testSnippet && fixProposal && fixProposal.status === 'PROPOSED') {
      try {
        const outcome = await this.diagnosticAdapter.executeInSandbox(request.testSnippet);
        if (outcome.success) {
          finalStatus = 'VERIFIED';
        } else {
          finalStatus = 'VERIFICATION_FAILED';
        }
      } catch {
        finalStatus = 'VERIFICATION_FAILED';
      }
    }

    const durationMs = Date.now() - startTimeMs;

    // 9. Build final report and SHA-256 signature
    const baseReport = {
      reportId: `REP_BFA_${crypto.randomBytes(6).toString('hex')}`,
      requestId,
      taskId,
      status: finalStatus,
      category: classification.category,
      summary: `Defect analyzed as ${classification.category}. ${rootCauses[0]?.rootCauseHypothesis || 'Analysis complete.'}`,
      rootCauseCandidates: rootCauses,
      fixProposal,
      regressionPlan,
      boundsEnforced: bounds,
      executionDurationMs: durationMs,
      generatedAt: new Date().toISOString(),
      is_actuation_blocked: true as const,
    };

    const checksumPayload = JSON.stringify({
      reportId: baseReport.reportId,
      requestId,
      taskId,
      status: baseReport.status,
      category: baseReport.category,
      proposalChecksum: fixProposal?.proposalChecksum || 'NO_PROPOSAL',
      is_actuation_blocked: true,
    });
    const reportChecksum = crypto.createHash('sha256').update(checksumPayload).digest('hex');

    return Object.freeze({
      ...baseReport,
      reportChecksum,
    });
  }

  /**
   * Invokes BFA adhering to AOA AgentInvoker contract.
   */
  public async invoke(payload: Record<string, unknown>, timeoutMs?: number): Promise<BFADefectReport> {
    const req = payload as unknown as BFADefectRequest;
    return this.execute(req);
  }

  private buildErrorReport(
    requestId: string,
    taskId: string,
    status: BFARequestStatus,
    category: any,
    errorMessage: string,
    startTimeMs: number,
    bounds: BFABoundsConfig
  ): BFADefectReport {
    const reportId = `REP_BFA_ERR_${crypto.randomBytes(6).toString('hex')}`;
    const baseReport = {
      reportId,
      requestId,
      taskId,
      status,
      category,
      summary: `Defect analysis failed: ${errorMessage}`,
      rootCauseCandidates: [],
      regressionPlan: {
        suggestedVerificationSuites: [],
        acceptanceCriteria: [],
        riskAssessment: errorMessage,
      },
      boundsEnforced: bounds,
      executionDurationMs: Date.now() - startTimeMs,
      generatedAt: new Date().toISOString(),
      is_actuation_blocked: true as const,
    };

    const checksum = crypto.createHash('sha256').update(JSON.stringify(baseReport)).digest('hex');

    return Object.freeze({
      ...baseReport,
      reportChecksum: checksum,
    });
  }
}
