/**
 * CUBiO AI — 3D Memory Studio
 * AGENT-010 — SGA (Security & Governance Agent)
 * src/cubio/agents/sga/policyEvaluationAdapter.ts
 *
 * Facade connecting SGA to CUBiO's canonical guards:
 * - FrozenProtectionGuard (Core DB & Address369 immutability)
 * - ExternalModelGuard (Zero cloud model & network isolation)
 * - SovereigntySafetyGuard (Actuation lock & runtime dependency checks)
 * - MvpV2CorePrivacySecurityGate (Architectural privacy defense)
 */

import { SGAGuardEvaluationRecord } from './types';
import { FrozenProtectionGuard } from '../../language/native/pma/frozenProtectionGuard';
import { ExternalModelGuard } from '../../model/native_foundation/external_model_guard';
import { SovereigntySafetyGuard } from '../../language/native/pma/sovereigntySafetyGuard';
import { MvpV2CorePrivacySecurityGate } from '../../integration/mvpV2CorePrivacySecurityGate';
import { IS_ACTUATION_BLOCKED } from '../../../funnel02/constants';

export class PolicyEvaluationAdapter {
  private readonly frozenGuard: FrozenProtectionGuard;
  private readonly externalModelGuard: ExternalModelGuard;
  private readonly sovereigntyGuard: SovereigntySafetyGuard;
  private readonly privacyGate: MvpV2CorePrivacySecurityGate;

  constructor(customRootDir?: string) {
    const root = customRootDir || process.cwd();
    this.frozenGuard = new FrozenProtectionGuard(root);
    this.externalModelGuard = new ExternalModelGuard();
    this.sovereigntyGuard = new SovereigntySafetyGuard();
    this.privacyGate = new MvpV2CorePrivacySecurityGate(root);
  }

  /**
   * Evaluates all applicable guards against a proposed operation and resource scope.
   */
  public evaluateGuards(
    operation: string,
    resourceScope: readonly string[],
    payload?: Readonly<Record<string, unknown>>
  ): readonly SGAGuardEvaluationRecord[] {
    const records: SGAGuardEvaluationRecord[] = [];

    // 1. Permanent Actuation Lock Guard
    if (!IS_ACTUATION_BLOCKED) {
      records.push({
        guardName: 'CanonicalActuationLockGuard',
        outcome: 'BLOCKED',
        reasonCodes: ['ACTUATION_LOCK_COMPROMISED'],
        details: 'CRITICAL: Global IS_ACTUATION_BLOCKED invariant is false',
      });
    } else {
      records.push({
        guardName: 'CanonicalActuationLockGuard',
        outcome: 'PASS',
        reasonCodes: ['ACTUATION_LOCK_VERIFIED'],
      });
    }

    // Check payload for override attempts
    if (payload) {
      const p = payload as any;
      if (p.actuation_override === true || p.is_actuation_blocked === false || p.force_execution === true) {
        records.push({
          guardName: 'ActuationOverrideDefenseGuard',
          outcome: 'BLOCKED',
          reasonCodes: ['UNAUTHORIZED_ACTUATION_ATTEMPT'],
          details: 'Caller attempted to override hardware actuation lock',
        });
      }
    }

    // 2. Frozen Asset Protection Guard
    let frozenViolation = false;
    const violatedFiles: string[] = [];
    for (const res of resourceScope) {
      const norm = res.replace(/\\/g, '/').toLowerCase();
      if (
        norm.includes('data/cubio_studio.db') ||
        norm.includes('address369.ts') ||
        norm.includes('constants.ts') ||
        norm.includes('guard.ts') ||
        operation.includes('MUTATE_SECURITY') ||
        this.frozenGuard.isProtected(res)
      ) {
        if (operation !== 'INSPECTION' && operation !== 'READ_AUDIT' && operation !== 'STATIC_ANALYSIS') {
          frozenViolation = true;
          violatedFiles.push(res);
        }
      }
    }

    if (frozenViolation) {
      records.push({
        guardName: 'FrozenProtectionGuard',
        outcome: 'BLOCKED',
        reasonCodes: ['PROTECTED_ASSET_MUTATION_DENIED'],
        details: `Attempted modification of protected files: ${violatedFiles.join(', ')}`,
      });
    } else {
      records.push({
        guardName: 'FrozenProtectionGuard',
        outcome: 'PASS',
        reasonCodes: ['PROTECTED_ASSET_INTEGRITY_VERIFIED'],
      });
    }

    // 3. Sovereignty & External Model Guard
    let externalModelViolation = false;
    if (payload) {
      const strPayload = JSON.stringify(payload);
      if (/openai|anthropic|gemini|llama|qwen|claude|gpt-4/i.test(strPayload)) {
        externalModelViolation = true;
      }
    }

    if (externalModelViolation) {
      records.push({
        guardName: 'ExternalModelGuard',
        outcome: 'BLOCKED',
        reasonCodes: ['EXTERNAL_AI_DEPENDENCY_DETECTED'],
        details: 'Attempted to invoke prohibited external cloud AI dependency',
      });
    } else {
      records.push({
        guardName: 'ExternalModelGuard',
        outcome: 'PASS',
        reasonCodes: ['SOVEREIGN_NATIVE_ONLY'],
      });
    }

    // 4. Architectural Privacy Gate
    const hasPrototypePollution = payload && Object.prototype.hasOwnProperty.call(payload, '__proto__');
    if (hasPrototypePollution) {
      records.push({
        guardName: 'MvpV2CorePrivacySecurityGate',
        outcome: 'BLOCKED',
        reasonCodes: ['PROTOTYPE_POLLUTION_DETECTED'],
      });
    } else {
      records.push({
        guardName: 'MvpV2CorePrivacySecurityGate',
        outcome: 'PASS',
        reasonCodes: ['PRIVACY_STANDARDS_MET'],
      });
    }

    return Object.freeze(records);
  }
}
