/**
 * CUBiO AI � 3D Memory Studio
 * AGENT-008 � AOA (Agent Orchestration Agent)
 * src/cubio/agents/aoa/types.ts
 *
 * Authoritative type contracts for CUBiO's native Agent Orchestration Agent.
 * Defines agent registry interfaces, task lifecycle state machines,
 * DAG dependency models, execution bounds, invocation adapters,
 * and aggregated multi-agent forensic report contracts.
 */

export type AOAAgentStatus =
  | 'IMPLEMENTED_CALLABLE'
  | 'IMPLEMENTED_UNAVAILABLE'
  | 'EXPERIMENTAL'
  | 'PLANNED'
  | 'FAILED_REGISTRATION';

export interface AOAAgentCapabilityDescriptor {
  readonly agentId: string;
  readonly name: string;
  readonly version: string;
  readonly status: AOAAgentStatus;
  readonly declaredCapabilities: readonly string[];
  readonly inputSchemaRef: string;
  readonly outputSchemaRef: string;
  readonly requiredPermissions: readonly string[];
  readonly supportsTimeout: boolean;
  readonly supportsCancellation: boolean;
}

/**
 * Production Agent-to-Agent Data Handoff Binding Contract
 */
export interface AOAHandoffBinding {
  /** The unique subtaskId of the prerequisite upstream task */
  readonly sourceTaskId: string;
  /** The expected canonical agent ID of the source (prevents confused deputy / spoofing) */
  readonly sourceAgentId: string;
  /** Key or path within the upstream result payload to extract */
  readonly outputKeyPath: string;
  /** Destination key where the extracted data will be bound in downstream payload */
  readonly targetParameterKey?: string;
  /** Optional expected schema reference (e.g. 'cubio://schema/maa/math_report') */
  readonly expectedSchemaRef?: string;
  /** Optional expected SHA-256 integrity hash of the upstream output payload */
  readonly integritySha256?: string;
  /** Permission required by downstream agent to consume this upstream output */
  readonly requiredPermission?: string;
}

export type AOATaskLifecycleState =
  | 'CREATED'
  | 'VALIDATED'
  | 'READY'
  | 'RUNNING'
  | 'SUCCEEDED'
  | 'FAILED'
  | 'BLOCKED'
  | 'CANCELLED'
  | 'TIMED_OUT'
  | 'PARTIAL'
  | 'RETRY_PENDING'
  | 'REJECTED';

export interface AOASubtaskDefinition {
  readonly subtaskId: string;
  readonly targetAgentId: string;
  readonly objective: string;
  readonly payload: Readonly<Record<string, unknown>>;
  readonly dependencies?: readonly string[]; // IDs of prerequisite subtasks
  readonly acceptanceCriteria?: readonly string[];
  readonly permissionBoundary?: readonly string[];
  readonly timeoutMs?: number;
  readonly maxRetries?: number;
  readonly expectedOutputSchemaRef?: string;
  readonly handoffBindings?: readonly AOAHandoffBinding[];
  readonly requiredSkills?: readonly string[];
}

export interface AOAOrchestrationRequest {
  readonly orchestrationId: string;
  readonly objective: string;
  readonly callerId?: string;
  readonly subtasks: readonly AOASubtaskDefinition[];
  readonly constraints?: readonly string[];
  readonly acceptanceCriteria?: readonly string[];
  readonly permittedTools?: readonly string[];
  readonly overallTimeoutMs?: number;
  readonly maxConcurrency?: number;
  readonly tenantId?: string;
  readonly callerPermissions?: readonly string[];
}

export interface AOASubtaskExecutionRecord {
  readonly subtaskId: string;
  readonly agentId: string;
  readonly state: AOATaskLifecycleState;
  readonly attemptCount: number;
  readonly startTimeMs?: number;
  readonly completionTimeMs?: number;
  readonly durationMs?: number;
  readonly resultPayload?: unknown;
  readonly evidenceHash?: string;
  readonly executedSkills?: readonly Record<string, unknown>[];
  readonly error?: {
    readonly code: string;
    readonly message: string;
    readonly retryable: boolean;
    readonly blockingDependencies?: readonly string[];
  };
}

export interface AOAOrchestrationResult {
  readonly orchestrationId: string;
  readonly objective: string;
  readonly overallState: 'SUCCEEDED' | 'FAILED' | 'PARTIAL' | 'REJECTED' | 'TIMED_OUT';
  readonly subtaskRecords: readonly AOASubtaskExecutionRecord[];
  readonly successfulTasks: readonly string[];
  readonly failedTasks: readonly string[];
  readonly blockedTasks: readonly string[];
  readonly missingEvidenceTasks: readonly string[];
  readonly conflictingOutputs: readonly string[];
  readonly unverifiedClaims: readonly string[];
  readonly startTimestamp: number;
  readonly completionTimestamp: number;
  readonly totalDurationMs: number;
  readonly masterProvenanceHash: string;
  readonly isActuationBlocked: boolean;
}

export interface AOADagValidationResult {
  readonly isValid: boolean;
  readonly topologicalOrder: readonly string[];
  readonly cyclesDetected: readonly (readonly string[])[];
  readonly unresolvableDependencies: readonly string[];
  readonly errors: readonly string[];
}

export interface AOABoundsConfig {
  readonly maxSubtasksPerOrchestration: number; // default: 32
  readonly maxDependencyDepth: number; // default: 8
  readonly maxConcurrentInvocations: number; // default: 4
  readonly maxRetryCount: number; // default: 3
  readonly defaultTaskTimeoutMs: number; // default: 15000
  readonly maxOutputSizeBytes: number; // default: 65536 (64 KB)
}

export const DEFAULT_AOA_BOUNDS: AOABoundsConfig = Object.freeze({
  maxSubtasksPerOrchestration: 32,
  maxDependencyDepth: 8,
  maxConcurrentInvocations: 4,
  maxRetryCount: 3,
  defaultTaskTimeoutMs: 15000,
  maxOutputSizeBytes: 65536,
});
