/**
 * CUBiO AI - 3D Memory Studio
 * AGENT-008 - AOA (Agent Orchestration Agent)
 * src/cubio/agents/aoa/orchestrationAgent.ts
 *
 * Master orchestrator implementing Directed Acyclic Graph (DAG) task scheduling,
 * concurrency bounds, failure cascade aborts, dynamic agent-to-agent data handoff,
 * and comprehensive forensic evidence aggregation across all 20 CUBiO agents.
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 */

import {
  AOAOrchestrationRequest,
  AOAOrchestrationResult,
  AOASubtaskExecutionRecord,
  AOABoundsConfig,
  DEFAULT_AOA_BOUNDS,
} from './types';
import { AgentRegistryAdapter } from './agentRegistryAdapter';
import { TaskValidator } from './taskValidator';
import { DependencyScheduler } from './dependencyScheduler';
import { AgentInvocationAdapter } from './agentInvocationAdapter';
import { ResultAggregator } from './resultAggregator';
import { AOAHandoffResolver } from './handoffResolver';
import { SkillRegistry } from '../../skills/registry';
import { DynamicSkillInvoker } from '../../skills/dynamicSkillInvoker';

// Verified existing agent imports
import { MEAMemoryAgent } from '../mea/memoryAgent';
import { DRADependencyAgent } from '../dra/dependencyAgent';
import { TGAGateAgent } from '../tga/gateAgent';
import { EIAEvidenceAgent } from '../eia/evidenceAgent';
import { TheMGAgent } from '../themg/mgAgent';
import { BackgroundTaskWatchdogAgent } from '../watchdog/watchdogAgent';

// Additional leaf agent imports
import { CodeExecutionAgent } from '../cea/ceaAgent';
import { SecurityGovernanceAgent } from '../sga/securityAuditAgent';
import { ObservabilityMonitoringAgent } from '../oma/observabilityAgent';
import { ResearchRetrievalAgent } from '../rra/researchAgent';
import { CodingAgent } from '../cda/codingAgent';
import { MathematicsAgent } from '../maa/mathematicsAgent';
import { BugFixingAgent } from '../bfa/bugFixingAgent';
import { SystemArchitectureAgent } from '../saa/systemArchitectureAgent';
import { FrontendUIAgent } from '../fua/frontendUIAgent';
import { DataStorageAgent } from '../dsa/dataStorageAgent';
import { PerformanceOptimizationAgent } from '../poa/performanceOptimizationAgent';
import { ReleaseDeploymentAgent } from '../rda/releaseDeploymentAgent';
import { RDAAOAAdapter } from '../rda/aoaAdapter';

import { IS_ACTUATION_BLOCKED } from '../../intelligence/core/coreEngineContract';

export class AgentOrchestrationAgent {
  public static readonly AGENT_ID = 'AGENT-008-AOA';
  public static readonly AGENT_NAME = 'Agent Orchestration Agent';
  public readonly is_actuation_blocked: boolean = true;

  private readonly registry: AgentRegistryAdapter;
  private readonly validator: TaskValidator;
  private readonly scheduler: DependencyScheduler;
  private readonly invocationAdapter: AgentInvocationAdapter;
  private readonly bounds: AOABoundsConfig;

  constructor(customBounds?: Partial<AOABoundsConfig>) {
    if (!IS_ACTUATION_BLOCKED) {
      throw new Error('FAIL_CLOSED_AOA: Actuation lock must be active (IS_ACTUATION_BLOCKED === true)');
    }

    this.bounds = { ...DEFAULT_AOA_BOUNDS, ...customBounds };
    this.registry = new AgentRegistryAdapter();
    this.validator = new TaskValidator(this.registry, this.bounds);
    this.scheduler = new DependencyScheduler(this.bounds);
    this.invocationAdapter = new AgentInvocationAdapter(this.registry, this.bounds);

    this.wireCertifiedAgents();
  }

  /**
   * Wires verified existing agents directly into registry invokers.
   */
  private wireCertifiedAgents(): void {
    // 1. MEA
    try {
      const mea = new MEAMemoryAgent();
      this.registry.bindInvoker('AGENT-001-MEA', {
        invoke: async (payload) => mea.retrieveContext(payload as any),
      });
    } catch {}

    // 2. DRA
    try {
      const dra = new DRADependencyAgent();
      this.registry.bindInvoker('AGENT-002-DRA', {
        invoke: async (payload) => dra.analyzeDependenciesAndReuse(payload as any),
      });
    } catch {}

    // 3. TGA
    try {
      const tga = new TGAGateAgent();
      this.registry.bindInvoker('AGENT-003-TGA', {
        invoke: async (payload) => tga.executeGates(payload as any),
      });
    } catch {}

    // 4. EIA
    try {
      const eia = new EIAEvidenceAgent();
      this.registry.bindInvoker('AGENT-004-EIA', {
        invoke: async (payload) => eia.auditEvidence(payload as any),
      });
    } catch {}

    // 5. TheMG
    try {
      const themg = new TheMGAgent();
      this.registry.bindInvoker('AGENT-005-TheMG', {
        invoke: async (payload) => themg.planSolution(payload as any),
      });
    } catch {}

    // 6. BTWA
    try {
      const btwa = new BackgroundTaskWatchdogAgent();
      this.registry.bindInvoker('AGENT-006-BTWA', {
        invoke: async (payload) => btwa.getActiveStatus(),
      });
    } catch {}

    // 7. CEA
    try {
      const cea = new CodeExecutionAgent();
      this.registry.bindInvoker('AGENT-009-CEA', {
        invoke: async (payload) => cea.execute(payload as any),
      });
    } catch {}

    // 8. SGA
    try {
      const sga = new SecurityGovernanceAgent();
      this.registry.bindInvoker('AGENT-010-SGA', {
        invoke: async (payload) => sga.invoke(payload as any),
      });
    } catch {}

    // 9. OMA
    try {
      const oma = new ObservabilityMonitoringAgent();
      this.registry.bindInvoker('AGENT-011-OMA', {
        invoke: async (payload) => oma.invoke(payload as any),
      });
    } catch {}

    // 10. RRA
    try {
      const rra = new ResearchRetrievalAgent();
      this.registry.bindInvoker('AGENT-012-RRA', {
        invoke: async (payload) => rra.invoke(payload as any),
      });
    } catch {}

    // 11. CDA
    try {
      const cda = new CodingAgent();
      this.registry.bindInvoker('AGENT-013-CDA', {
        invoke: async (payload) => cda.invoke(payload as any),
      });
    } catch {}

    // 12. MAA
    try {
      const maa = new MathematicsAgent();
      this.registry.bindInvoker('AGENT-014-MAA', {
        invoke: async (payload) => maa.invoke(payload as any),
      });
    } catch {}

    // 13. BFA
    try {
      const bfa = new BugFixingAgent();
      this.registry.bindInvoker('AGENT-015-BFA', {
        invoke: async (payload) => bfa.invoke(payload as any),
      });
    } catch {}

    // 14. SAA
    try {
      const saa = new SystemArchitectureAgent(undefined, undefined, undefined, undefined, this.registry);
      this.registry.bindInvoker('AGENT-016-SAA', {
        invoke: async (payload) => saa.invoke(payload as any),
      });
    } catch {}

    // 15. FUA
    try {
      const fua = new FrontendUIAgent();
      this.registry.bindInvoker('AGENT-017-FUA', {
        invoke: async (payload) => fua.executeTask(payload as any),
      });
    } catch {}

    // 16. DSA
    try {
      const dsa = new DataStorageAgent();
      this.registry.bindInvoker('AGENT-018-DSA', {
        invoke: async (payload) => dsa.executeTask(payload as any),
      });
    } catch {}

    // 17. POA
    try {
      const poa = new PerformanceOptimizationAgent();
      this.registry.bindInvoker('AGENT-019-POA', {
        invoke: async (payload) => poa.execute(payload as any),
      });
    } catch {}

    // 18. RDA
    try {
      const rda = new ReleaseDeploymentAgent();
      this.registry.bindInvoker('AGENT-020-RDA', new RDAAOAAdapter(rda));
    } catch {}
  }

  public getRegistry(): AgentRegistryAdapter {
    return this.registry;
  }

  public getBounds(): AOABoundsConfig {
    return this.bounds;
  }

  /**
   * Primary entry point: Executes a complete multi-agent orchestration request.
   */
  public async orchestrate(request: AOAOrchestrationRequest): Promise<AOAOrchestrationResult> {
    const startTimestamp = Date.now();

    // 1. Task Intake & Validation Gate
    const validation = this.validator.validate(request);
    if (!validation.isValid) {
      return ResultAggregator.aggregate(
        request,
        request.subtasks ? request.subtasks.map((s) => ({
          subtaskId: s.subtaskId || 'UNKNOWN',
          agentId: s.targetAgentId || 'UNKNOWN',
          state: 'REJECTED' as const,
          attemptCount: 0,
          error: {
            code: 'REQUEST_VALIDATION_FAILED',
            message: validation.errors.join('; '),
            retryable: false,
          },
        })) : [],
        startTimestamp,
        Date.now()
      );
    }

    const sanitizedReq = validation.sanitizedRequest!;

    // 2. DAG Scheduling & Cycle Detection
    const dag = this.scheduler.validateDag(sanitizedReq.subtasks);
    if (!dag.isValid) {
      return ResultAggregator.aggregate(
        sanitizedReq,
        sanitizedReq.subtasks.map((s) => ({
          subtaskId: s.subtaskId,
          agentId: s.targetAgentId,
          state: 'BLOCKED' as const,
          attemptCount: 0,
          error: {
            code: 'CYCLIC_OR_INVALID_DAG',
            message: dag.errors.join('; '),
            retryable: false,
          },
        })),
        startTimestamp,
        Date.now()
      );
    }

    // 3. Partition into execution layers
    const layers = this.scheduler.partitionExecutionLayers(
      sanitizedReq.subtasks,
      dag.topologicalOrder
    );

    const subtaskMap = new Map(sanitizedReq.subtasks.map((s) => [s.subtaskId, s]));
    const records: AOASubtaskExecutionRecord[] = [];
    const completedTasks = new Map<string, AOASubtaskExecutionRecord>();
    const failedOrBlockedTasks = new Set<string>();

    // Determine effective concurrency bound
    const boundsConcurrency = (this.bounds as any).maxConcurrency ?? this.bounds.maxConcurrentInvocations ?? 4;
    const effectiveConcurrency = Math.max(
      1,
      typeof sanitizedReq.maxConcurrency === 'number' && sanitizedReq.maxConcurrency > 0
        ? sanitizedReq.maxConcurrency
        : boundsConcurrency
    );

    // 4. Layer-by-layer execution with concurrency throttling
    for (const layer of layers) {
      for (let i = 0; i < layer.length; i += effectiveConcurrency) {
        const chunk = layer.slice(i, i + effectiveConcurrency);
        const chunkPromises = chunk.map(async (subtaskId) => {
          const st = subtaskMap.get(subtaskId)!;

          // Check if any prerequisite failed or was blocked
          const blockingPrereq = st.dependencies.find((d) => failedOrBlockedTasks.has(d));
          if (blockingPrereq) {
            failedOrBlockedTasks.add(subtaskId);
            const record: AOASubtaskExecutionRecord = {
              subtaskId,
              agentId: st.targetAgentId,
              state: 'BLOCKED',
              attemptCount: 0,
              startTimeMs: Date.now(),
              completionTimeMs: Date.now(),
              durationMs: 0,
              error: {
                code: 'DEPENDENCY_FAILED',
                message: "Prerequisite subtask '" + blockingPrereq + "' failed or was blocked.",
                retryable: false,
                blockingDependencies: [blockingPrereq],
              },
            };
            return record;
          }

          // Verify requiredSkills and load instructions if declared
          let currentPayload = { ...st.payload };
          if (st.requiredSkills && st.requiredSkills.length > 0) {
            const skillRegistry = SkillRegistry.getInstance();
            const loadedSkillsData: Record<string, unknown>[] = [];
            for (const reqSkillId of st.requiredSkills) {
              try {
                const loaded = skillRegistry.loadSkillForAgent(reqSkillId, st.targetAgentId);
                loadedSkillsData.push({
                  skillId: loaded.manifest.skillId,
                  name: loaded.manifest.name,
                  instructions: loaded.manifest.instructions,
                  capabilities: loaded.manifest.capabilities,
                });
              } catch (skillErr: any) {
                failedOrBlockedTasks.add(subtaskId);
                const record: AOASubtaskExecutionRecord = {
                  subtaskId,
                  agentId: st.targetAgentId,
                  state: 'BLOCKED',
                  attemptCount: 0,
                  startTimeMs: Date.now(),
                  completionTimeMs: Date.now(),
                  durationMs: 0,
                  error: {
                    code: 'REQUIRED_SKILL_UNAVAILABLE',
                    message: `Required skill '${reqSkillId}' could not be loaded for agent '${st.targetAgentId}': ${skillErr.message}`,
                    retryable: false,
                  },
                };
                return record;
              }
            }
            currentPayload = {
              ...currentPayload,
              loadedSkills: loadedSkillsData,
            };
          }

          // Production Agent-to-Agent Data Handoff Resolution
          let taskToExecute: typeof st = {
            ...st,
            payload: currentPayload,
          };
          if (st.handoffBindings && st.handoffBindings.length > 0) {
            const handoffResult = AOAHandoffResolver.resolve(
              taskToExecute,
              completedTasks,
              sanitizedReq.callerPermissions || []
            );

            if (!handoffResult.success) {
              failedOrBlockedTasks.add(subtaskId);
              const record: AOASubtaskExecutionRecord = {
                subtaskId,
                agentId: st.targetAgentId,
                state: 'BLOCKED',
                attemptCount: 0,
                startTimeMs: Date.now(),
                completionTimeMs: Date.now(),
                durationMs: 0,
                error: {
                  code: handoffResult.error?.code || 'HANDOFF_RESOLUTION_FAILED',
                  message: handoffResult.error?.message || 'Agent-to-agent data handoff resolution failed.',
                  retryable: false,
                  blockingDependencies: handoffResult.error?.blockingDependency
                    ? [handoffResult.error.blockingDependency]
                    : undefined,
                },
              };
              return record;
            }

            // Use the validated payload containing genuine upstream inputs
            taskToExecute = {
              ...st,
              payload: handoffResult.resolvedPayload,
            };
          }

          // Execute task
          const record = await this.invocationAdapter.executeSubtask(taskToExecute);

          // Phase 21: Dynamic Agent-to-Skill Runtime Invocation
          // If task succeeded, agent dynamically applies relevant registered skills
          let skillTraces: any[] = [];
          if (record.state === 'SUCCEEDED') {
            const dynamicSkillInvoker = new DynamicSkillInvoker();
            const skillRes = await dynamicSkillInvoker.invokeSkillsForSubtask(
              taskToExecute,
              sanitizedReq.callerPermissions || []
            );
            if (skillRes.executedSkillTraces.length > 0) {
              skillTraces = [...skillRes.executedSkillTraces];
            }
          }

          const enrichedRecord: AOASubtaskExecutionRecord = {
            ...record,
            executedSkills: skillTraces.length > 0 ? skillTraces : undefined,
          };

          if (enrichedRecord.state !== 'SUCCEEDED') {
            failedOrBlockedTasks.add(subtaskId);
          }
          return enrichedRecord;
        });

        const chunkResults = await Promise.all(chunkPromises);
        for (const res of chunkResults) {
          records.push(res);
          completedTasks.set(res.subtaskId, res);
        }
      }
    }

    const completionTimestamp = Date.now();
    return ResultAggregator.aggregate(
      sanitizedReq,
      records,
      startTimestamp,
      completionTimestamp
    );
  }
}
