/**
 * CUBiO AI — 3D Memory Studio
 * src/cubio/mcp/server.ts
 *
 * Dedicated Local Model Context Protocol (MCP) Stdio Server.
 * Exposes CUBiO's 20-Agent sovereign multi-agent architecture to external AI clients
 * (e.g., Claude Desktop, Cursor, Antigravity, GitHub Copilot).
 *
 * Exposes exactly three tools:
 * 1. list_agents: Discover all registered agents and their statuses.
 * 2. get_agent_capabilities: Detailed capabilities and schema refs for a specified agent.
 * 3. orchestrate_tasks: Dispatches DAG task requests to AgentOrchestrationAgent (AOA).
 *
 * Permanent Safety Invariant: IS_ACTUATION_BLOCKED = true
 * Diagnostics sent to stderr; stdout strictly reserved for MCP JSON-RPC protocol.
 */

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
} from '@modelcontextprotocol/sdk/types.js';
import { AgentOrchestrationAgent } from '../agents/aoa/orchestrationAgent.js';
import { AOAOrchestrationRequest } from '../agents/aoa/types.js';
import { SkillRegistry } from '../skills/registry.js';
import { PMATaskSubmissionService } from '../language/native/pma/pmaTaskSubmissionService.js';
import { WorkspaceManager } from '../workspace/workspaceManager.js';
import { SecretRedactor } from '../security/secretRedactor.js';

export function createCubiOMcpServer(serverInfo?: { name?: string; version?: string }): Server {
  const aoa = new AgentOrchestrationAgent();
  const registry = aoa.getRegistry();

  const server = new Server(
    {
      name: serverInfo?.name || 'cubio-agentic-ai-mcp',
      version: serverInfo?.version || '1.0.0',
    },
    {
      capabilities: {
        tools: {},
      },
    }
  );

  // 1. List Tools Handler
  server.setRequestHandler(ListToolsRequestSchema, async () => {
    return {
      tools: [
        {
          name: 'list_agents',
          description:
            'List all registered CUBiO agents, their canonical identifiers, names, versions, and lifecycle statuses.',
          inputSchema: {
            type: 'object',
            properties: {
              statusFilter: {
                type: 'string',
                description:
                  'Optional filter by agent status (e.g. IMPLEMENTED_CALLABLE, PLANNED).',
              },
            },
            required: [],
          },
        },
        {
          name: 'get_agent_capabilities',
          description:
            'Retrieve declared capabilities, required permissions, and input/output schema references for a specific CUBiO agent ID.',
          inputSchema: {
            type: 'object',
            properties: {
              agentId: {
                type: 'string',
                description:
                  'Canonical identifier of the agent (e.g. AGENT-014-MAA, AGENT-019-POA, AGENT-020-RDA).',
              },
            },
            required: ['agentId'],
          },
        },
        {
          name: 'orchestrate_tasks',
          description:
            'Submit a multi-agent orchestration request to the Agent Orchestration Agent (AOA). Supports DAG dependencies, timeouts, and returns signed results.',
          inputSchema: {
            type: 'object',
            properties: {
              orchestrationId: {
                type: 'string',
                description: 'Unique identifier for this orchestration job.',
              },
              objective: {
                type: 'string',
                description: 'High-level objective of the multi-agent task.',
              },
              subtasks: {
                type: 'array',
                description: 'List of subtasks to schedule and execute in DAG dependency order.',
                items: {
                  type: 'object',
                  properties: {
                    subtaskId: {
                      type: 'string',
                      description: 'Unique identifier for this subtask node.',
                    },
                    targetAgentId: {
                      type: 'string',
                      description: 'ID of the agent to invoke (e.g. AGENT-014-MAA).',
                    },
                    objective: {
                      type: 'string',
                      description: 'Specific subtask objective.',
                    },
                                        handoffBindings: {
                      type: 'array',
                      description: 'Optional explicit upstream data handoff bindings.',
                      items: {
                        type: 'object',
                        properties: {
                          sourceTaskId: { type: 'string' },
                          sourceAgentId: { type: 'string' },
                          outputKeyPath: { type: 'string' },
                          targetParameterKey: { type: 'string' },
                          expectedSchemaRef: { type: 'string' },
                          integritySha256: { type: 'string' },
                          requiredPermission: { type: 'string' }
                        },
                        required: ['sourceTaskId', 'sourceAgentId', 'outputKeyPath']
                      }
                    },
                    payload: {
                      type: 'object',
                      description: 'Arbitrary JSON payload passed to the target agent.',
                    },
                    dependencies: {
                      type: 'array',
                      items: { type: 'string' },
                      description: 'Subtask IDs that must complete before this subtask executes.',
                    },
                    timeoutMs: {
                      type: 'number',
                      description: 'Optional execution timeout budget in milliseconds.',
                    },
                  },
                  required: ['subtaskId', 'targetAgentId', 'objective', 'payload'],
                },
              },
              overallTimeoutMs: {
                type: 'number',
                description: 'Optional global timeout for the entire DAG in milliseconds.',
              },
            },
            required: ['orchestrationId', 'objective', 'subtasks'],
          },
        },
        {
          name: 'discover_skills',
          description:
            'Discover agent skills registered in the CUBiO Skills Framework by exact skillId or capability keyword. Also supports listing all available skills.',
          inputSchema: {
            type: 'object',
            properties: {
              skillId: {
                type: 'string',
                description: 'Optional exact skill identifier (e.g. SKILL-369-LATTICE-CALC).',
              },
              capability: {
                type: 'string',
                description: 'Optional capability keyword to search (e.g. SPATIAL_MATH, CODE_INSPECTION).',
              },
            },
          },
        },
        {
          name: 'execute_skill',
          description:
            'Execute a validated agent skill on behalf of an authorized agent. Performs input validation, permission check, and emits tamper-evident execution provenance.',
          inputSchema: {
            type: 'object',
            properties: {
              skillId: {
                type: 'string',
                description: 'ID of the skill to execute (e.g. SKILL-369-LATTICE-CALC).',
              },
              agentId: {
                type: 'string',
                description: 'ID of the agent invoking the skill (e.g. AGENT-014-MAA).',
              },
              input: {
                type: 'object',
                description: 'Input arguments matching the skill inputSchema.',
              },
              callerPermissions: {
                type: 'array',
                items: { type: 'string' },
                description: 'Optional caller permission scopes.',
              },
            },
            required: ['skillId', 'agentId', 'input'],
          },
        },
        {
          name: 'submit_task',
          description:
            'Universal user-facing task submission entry point managed by the Native Project Manager Agent (PMA). Submit any natural-language objective without manually selecting agents, skills, or DAG structure. Evaluates scope, detects clarification needs, and enforces safety bounds.',
          inputSchema: {
            type: 'object',
            properties: {
              objective: {
                type: 'string',
                description: 'The natural-language goal or instruction for CUBiO (e.g. "Change the heading text in the website\'s hero section to \'Build Better with CUBiO\'").',
              },
              projectContext: {
                type: 'string',
                description: 'Optional additional context, domain requirements, or constraints.',
              },
              relevantFiles: {
                type: 'array',
                items: { type: 'string' },
                description: 'Optional list of file paths or patterns relevant to this task.',
              },
              callerId: {
                type: 'string',
                description: 'Optional identifier of the submitting user or client.',
              },
              autoExecute: {
                type: 'boolean',
                description: 'Optional. If true, automatically coordinates and executes the accepted task through AOA in a single turn without requiring a separate execute_task call.',
              },
              workspacePath: {
                type: 'string',
                description: 'Optional path to the user-authorized project workspace directory for this task.',
              },
            },
            required: ['objective'],
          },
        },
        {
          name: 'get_task_status',
          description:
            'Query the status, routing state, constraints, and progress of a task previously submitted through PMA.',
          inputSchema: {
            type: 'object',
            properties: {
              taskId: {
                type: 'string',
                description: 'The unique task identifier returned by submit_task.',
              },
            },
            required: ['taskId'],
          },
        },
        {
          name: 'execute_task',
          description:
            'Execute an accepted task by allowing PMA to select specialist agents, generate a DAG, delegate through AOA, and update the task record with genuine execution results.',
          inputSchema: {
            type: 'object',
            properties: {
              taskId: {
                type: 'string',
                description: 'The unique task identifier returned by submit_task to execute.',
              },
              workspacePath: {
                type: 'string',
                description: 'Optional path to the target authorized workspace.',
              },
            },
            required: ['taskId'],
          },
        },
        {
          name: 'onboard_workspace',
          description:
            'Authorize and onboard an external project directory for inspection and task execution. Performs security boundary checks, manifest detection, language detection, architecture identification, and test harness discovery.',
          inputSchema: {
            type: 'object',
            properties: {
              workspacePath: {
                type: 'string',
                description: 'Absolute or relative path to the external repository or project workspace to onboard.',
              },
              label: {
                type: 'string',
                description: 'Optional human-readable label or alias for the workspace.',
              },
            },
            required: ['workspacePath'],
          },
        },
        {
          name: 'inspect_workspace',
          description:
            'Inspect an authorized workspace and return its complete project discovery profile: manifests, language breakdown, entry points, dynamic subsystems, architecture topology, test commands, and support verdict.',
          inputSchema: {
            type: 'object',
            properties: {
              workspacePath: {
                type: 'string',
                description: 'Optional workspace path or ID to inspect. If omitted, inspects the currently active workspace.',
              },
              includeSubsystems: {
                type: 'boolean',
                description: 'Optional. If true, includes detailed dynamic subsystem definitions.',
              },
            },
          },
        },
        {
          name: 'select_workspace',
          description:
            'Select the active workspace from the registry of user-authorized workspaces for subsequent task operations.',
          inputSchema: {
            type: 'object',
            properties: {
              workspaceIdOrPath: {
                type: 'string',
                description: 'The unique workspace ID (e.g. WS-...) or canonical path to set as active.',
              },
            },
            required: ['workspaceIdOrPath'],
          },
        },
        {
          name: 'list_workspaces',
          description:
            'List all currently authorized workspaces, their active status, paths, and inspection timestamps.',
          inputSchema: {
            type: 'object',
            properties: {
              detailed: {
                type: 'boolean',
                description: 'Optional. If true, includes full project discovery profiles in listing.',
              },
            },
          },
        },
        {
          name: 'authorize_workspace',
          description:
            'Explicitly configure and authorize an external workspace root with security containment boundaries, read-only enforcement, and write approval policies.',
          inputSchema: {
            type: 'object',
            properties: {
              workspacePath: {
                type: 'string',
                description: 'The root filesystem path to authorize as a contained workspace boundary.',
              },
              label: {
                type: 'string',
                description: 'Optional human-readable label or alias for the workspace.',
              },
              readOnly: {
                type: 'boolean',
                description: 'Optional. If true, mounts the workspace in read-only mode, blocking all write operations.',
              },
              allowedParentDirs: {
                type: 'array',
                items: { type: 'string' },
                description: 'Optional list of allowed parent directory paths that the workspace canonical path must reside within.',
              },
              policy: {
                type: 'string',
                enum: ['READ_ONLY', 'REQUIRE_APPROVAL_TOKEN', 'PERMITTED_IN_DISPOSABLE'],
                description: 'Write policy for this workspace. Defaults to REQUIRE_APPROVAL_TOKEN.',
              },
            },
            required: ['workspacePath'],
          },
        },
        {
          name: 'verify_path_containment',
          description:
            'Security audit tool to verify whether a given path is contained within the authorized workspace root. Detects directory traversal, root breakouts, symlink escapes, junction redirects, and protected authority baseline tampering.',
          inputSchema: {
            type: 'object',
            properties: {
              targetPath: {
                type: 'string',
                description: 'The target relative or absolute path to test for containment.',
              },
              workspacePath: {
                type: 'string',
                description: 'Optional workspace path or ID. If omitted, uses active workspace.',
              },
            },
            required: ['targetPath'],
          },
        },
        {
          name: 'request_write_approval',
          description:
            'Generate a cryptographic, content-hash-bound user approval token required to propose or apply a write modification to a file within an authorized workspace.',
          inputSchema: {
            type: 'object',
            properties: {
              taskId: {
                type: 'string',
                description: 'The unique task ID requesting write authorization.',
              },
              targetFilePath: {
                type: 'string',
                description: 'The target relative file path within the authorized workspace.',
              },
              content: {
                type: 'string',
                description: 'The exact content proposed to be written.',
              },
              workspacePath: {
                type: 'string',
                description: 'Optional workspace path or ID. If omitted, uses active workspace.',
              },
            },
            required: ['taskId', 'targetFilePath', 'content'],
          },
        },
        {
          name: 'confirm_write_approval',
          description:
            'Confirm or reject a pending file write approval proposal. Required human-in-the-loop gate before write token is minted.',
          inputSchema: {
            type: 'object',
            properties: {
              proposalId: {
                type: 'string',
                description: 'The proposal ID generated by request_write_approval.',
              },
              decision: {
                type: 'string',
                enum: ['APPROVE', 'REJECT'],
                description: 'Confirmation decision ("APPROVE" or "REJECT").',
              },
              operatorId: {
                type: 'string',
                description: 'Identifier of the human operator or authorized supervisor granting approval.',
              },
              operatorAuthKey: {
                type: 'string',
                description:
                  'Mandatory server-side human operator authorization credential. Autonomous agents cannot self-approve without this key.',
              },
              rationale: {
                type: 'string',
                description: 'Optional justification for granting or denying write approval.',
              },
            },
            required: ['proposalId', 'decision', 'operatorId', 'operatorAuthKey'],
          },
        },
        {
          name: 'write_workspace_file',
          description:
            'Securely write or replace a file within an authorized workspace. Enforces root containment, symlink/junction escape prevention, immutable protected authority defense, valid user approval tokens, and post-write disk readback verification.',
          inputSchema: {
            type: 'object',
            properties: {
              taskId: {
                type: 'string',
                description: 'The unique task ID executing the write operation.',
              },
              targetFilePath: {
                type: 'string',
                description: 'The target file path relative to the authorized workspace root.',
              },
              content: {
                type: 'string',
                description: 'The content to write into the target file.',
              },
              approvalToken: {
                type: 'string',
                description: 'The cryptographic approval token generated by request_write_approval or user consent.',
              },
              workspacePath: {
                type: 'string',
                description: 'Optional workspace path or ID. If omitted, uses active workspace.',
              },
              rationale: {
                type: 'string',
                description: 'Optional audit explanation for the file modification.',
              },
            },
            required: ['taskId', 'targetFilePath', 'content'],
          },
        },
      ],
    };
  });

  // 2. Call Tool Handler
  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const { name, arguments: args } = request.params;
    console.error(`[CUBiO MCP] Handling tool invocation: ${name}`);

    try {
      const executeTool = async () => {
        if (name === 'list_agents') {
        const filter = args?.statusFilter as string | undefined;
        let agents = registry.listAgents();
        if (filter) {
          agents = agents.filter((a) => a.status === filter);
        }
        return {
          content: [
            {
              type: 'text',
              text: JSON.stringify(
                {
                  totalAgents: agents.length,
                  agents: agents.map((a) => ({
                    agentId: a.agentId,
                    name: a.name,
                    version: a.version,
                    status: a.status,
                    declaredCapabilities: a.declaredCapabilities,
                  })),
                },
                null,
                2
              ),
            },
          ],
        };
      }

      if (name === 'get_agent_capabilities') {
        const agentId = args?.agentId as string;
        if (!agentId || typeof agentId !== 'string') {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameter "agentId" must be a non-empty string.',
                }),
              },
            ],
          };
        }

        const agentEntry = registry.getAgent(agentId);
        if (!agentEntry) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'AGENT_NOT_FOUND',
                  message: `Agent with ID "${agentId}" was not found in the AOA registry.`,
                }),
              },
            ],
          };
        }

        return {
          content: [
            {
              type: 'text',
              text: JSON.stringify(agentEntry.descriptor, null, 2),
            },
          ],
        };
      }

      if (name === 'orchestrate_tasks') {
        if (!args || typeof args !== 'object') {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_PAYLOAD',
                  message: 'Orchestration request payload is required.',
                }),
              },
            ],
          };
        }

        const orchestrationReq: AOAOrchestrationRequest = {
          orchestrationId: String(args.orchestrationId || `ORCH-${Date.now()}`),
          objective: String(args.objective || 'Default external objective'),
          subtasks: Array.isArray(args.subtasks)
            ? (args.subtasks as any[]).map((st) => ({
                subtaskId: String(st.subtaskId || `SUB-${Date.now()}`),
                targetAgentId: String(st.targetAgentId || ''),
                objective: String(st.objective || ''),
                payload: st.payload && typeof st.payload === 'object' ? st.payload : {},
                dependencies: Array.isArray(st.dependencies) ? st.dependencies : [],
                handoffBindings: Array.isArray(st.handoffBindings) ? st.handoffBindings : undefined,
                timeoutMs: typeof st.timeoutMs === 'number' ? st.timeoutMs : undefined,
              }))
            : [],
          overallTimeoutMs:
            typeof args.overallTimeoutMs === 'number' ? args.overallTimeoutMs : undefined,
          callerPermissions: Array.isArray(args.callerPermissions) ? args.callerPermissions : undefined,
        };

        const result = await aoa.orchestrate(orchestrationReq);

        return {
          content: [
            {
              type: 'text',
              text: JSON.stringify(result, null, 2),
            },
          ],
        };
      }

      if (name === 'discover_skills') {
        const skillRegistry = SkillRegistry.getInstance();
        const skillId = args?.skillId as string | undefined;
        const capability = args?.capability as string | undefined;

        if (skillId) {
          const manifest = skillRegistry.getSkillManifest(skillId);
          if (!manifest) {
            return {
              isError: true,
              content: [
                {
                  type: 'text',
                  text: JSON.stringify({
                    error: 'SKILL_NOT_FOUND',
                    message: `Skill with ID "${skillId}" was not found in the registry.`,
                  }),
                },
              ],
            };
          }
          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify(manifest, null, 2),
              },
            ],
          };
        }

        if (capability) {
          const matching = skillRegistry.discoverByCapability(capability);
          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify(
                  {
                    capabilityQuery: capability,
                    totalMatches: matching.length,
                    skills: matching,
                  },
                  null,
                  2
                ),
              },
            ],
          };
        }

        const all = skillRegistry.listAllSkills();
        return {
          content: [
            {
              type: 'text',
              text: JSON.stringify(
                {
                  totalSkills: all.length,
                  skills: all,
                },
                null,
                2
              ),
            },
          ],
        };
      }

      if (name === 'execute_skill') {
        const skillRegistry = SkillRegistry.getInstance();
        const skillId = args?.skillId as string;
        const agentId = args?.agentId as string;
        const input = (args?.input || {}) as Record<string, unknown>;
        const callerPermissions = Array.isArray(args?.callerPermissions)
          ? (args.callerPermissions as string[])
          : [];

        if (!skillId || !agentId) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameters "skillId" and "agentId" are required.',
                }),
              },
            ],
          };
        }

        const result = await skillRegistry.executeSkill(
          skillId,
          agentId,
          input,
          callerPermissions
        );

        return {
          isError: !result.success,
          content: [
            {
              type: 'text',
              text: JSON.stringify(result, null, 2),
            },
          ],
        };
      }

      if (name === 'submit_task') {
        const submissionService = PMATaskSubmissionService.getInstance();
        const objective = args?.objective as string;
        const projectContext = args?.projectContext as string | undefined;
        const relevantFiles = Array.isArray(args?.relevantFiles)
          ? (args.relevantFiles as string[])
          : undefined;
        const callerId = args?.callerId as string | undefined;
        const autoExecute = Boolean(args?.autoExecute);

        const workspacePath = args?.workspacePath as string | undefined;
        let effectiveWorkspaceRoot: string | undefined = undefined;
        if (workspacePath) {
          const wsManager = WorkspaceManager.getInstance();
          try {
            const ws = wsManager.getWorkspace(workspacePath) || wsManager.authorizeWorkspace(workspacePath);
            effectiveWorkspaceRoot = ws.canonicalPath;
          } catch (authErr: any) {
            return {
              isError: true,
              content: [
                {
                  type: 'text',
                  text: JSON.stringify({
                    error: 'UNAUTHORIZED_WORKSPACE_PATH',
                    message: authErr.message || `Failed to authorize workspace: "${workspacePath}"`,
                  }),
                },
              ],
            };
          }
        } else {
          const activeWs = WorkspaceManager.getInstance().getActiveWorkspace();
          if (activeWs) {
            effectiveWorkspaceRoot = activeWs.canonicalPath;
          }
        }

        const isPmaMention = typeof objective === 'string' && /^\s*@pma\b/i.test(objective);
        const shouldAutoExecute = autoExecute || isPmaMention;

        if (shouldAutoExecute) {
          const autoResult = await submissionService.submitAndExecuteTask({
            objective,
            projectContext,
            relevantFiles,
            callerId: callerId || 'MCP_CLIENT',
            autoExecute: true,
            workspaceRoot: effectiveWorkspaceRoot,
          });

          return {
            isError: !autoResult.success,
            content: [
              {
                type: 'text',
                text: JSON.stringify(autoResult, null, 2),
              },
            ],
          };
        }

        const submissionResult = submissionService.submitTask({
          objective,
          projectContext,
          relevantFiles,
          callerId: callerId || 'MCP_CLIENT',
          workspaceRoot: effectiveWorkspaceRoot,
        });

        return {
          isError: !submissionResult.success,
          content: [
            {
              type: 'text',
              text: JSON.stringify(submissionResult, null, 2),
            },
          ],
        };
      }

      if (name === 'get_task_status') {
        const submissionService = PMATaskSubmissionService.getInstance();
        const taskId = args?.taskId as string;

        if (!taskId) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameter "taskId" is required.',
                }),
              },
            ],
          };
        }

        const taskRecord = submissionService.getTask(taskId);
        if (!taskRecord) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'TASK_NOT_FOUND',
                  message: `Task with ID "${taskId}" was not found.`,
                }),
              },
            ],
          };
        }

        return {
          content: [
            {
              type: 'text',
              text: JSON.stringify(taskRecord, null, 2),
            },
          ],
        };
      }

      if (name === 'execute_task') {
        const submissionService = PMATaskSubmissionService.getInstance();
        const taskId = args?.taskId as string;
        const workspacePath = args?.workspacePath as string | undefined;

        if (!taskId) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameter "taskId" is required.',
                }),
              },
            ],
          };
        }

        let effectiveWorkspaceRoot: string | undefined = undefined;
        if (workspacePath) {
          const wsManager = WorkspaceManager.getInstance();
          try {
            const ws = wsManager.getWorkspace(workspacePath) || wsManager.authorizeWorkspace(workspacePath);
            effectiveWorkspaceRoot = ws.canonicalPath;
          } catch (authErr: any) {
            return {
              isError: true,
              content: [
                {
                  type: 'text',
                  text: JSON.stringify({
                    error: 'UNAUTHORIZED_WORKSPACE_PATH',
                    message: authErr.message || `Failed to authorize workspace: "${workspacePath}"`,
                  }),
                },
              ],
            };
          }
        }

        try {
          const executedRecord = await submissionService.executeTask(taskId, {
            workspaceRoot: effectiveWorkspaceRoot,
          });
          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify(executedRecord, null, 2),
              },
            ],
          };
        } catch (execErr: any) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'EXECUTION_FAILED',
                  message: execErr.message || 'Task execution failed.',
                }),
              },
            ],
          };
        }
      }

      if (name === 'onboard_workspace') {
        const workspacePath = args?.workspacePath as string;
        const label = args?.label as string | undefined;

        if (!workspacePath || typeof workspacePath !== 'string') {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameter "workspacePath" is required and must be a non-empty string.',
                }),
              },
            ],
          };
        }

        try {
          const wsManager = WorkspaceManager.getInstance();
          const authorized = wsManager.authorizeWorkspace(workspacePath, { label });

          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify(
                  {
                    success: true,
                    workspaceId: authorized.workspaceId,
                    canonicalPath: authorized.canonicalPath,
                    label: authorized.label,
                    isActive: authorized.isActive,
                    architectureStyle: authorized.profile?.architectureStyle,
                    primaryLanguage: authorized.profile?.languages.primaryLanguage,
                    manifests: authorized.profile?.manifests.map((m) => m.relativePath),
                    entryPoints: authorized.profile?.entryPoints.map((ep) => ep.relativePath),
                    testCommand: authorized.profile?.testInfo.testCommand,
                    supportVerdict: authorized.profile?.supportVerdict,
                  },
                  null,
                  2
                ),
              },
            ],
          };
        } catch (err: any) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'ONBOARDING_FAILED',
                  message: err.message,
                }),
              },
            ],
          };
        }
      }

      if (name === 'inspect_workspace') {
        const workspacePath = args?.workspacePath as string | undefined;
        const includeSubsystems = args?.includeSubsystems !== false;

        try {
          const wsManager = WorkspaceManager.getInstance();
          const profile = wsManager.inspectWorkspace(workspacePath);

          const payload = {
            ...profile,
            subsystems: includeSubsystems ? profile.subsystems : undefined,
          };

          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify(payload, null, 2),
              },
            ],
          };
        } catch (err: any) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INSPECTION_FAILED',
                  message: err.message,
                }),
              },
            ],
          };
        }
      }

      if (name === 'select_workspace') {
        const workspaceIdOrPath = args?.workspaceIdOrPath as string;
        if (!workspaceIdOrPath || typeof workspaceIdOrPath !== 'string') {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameter "workspaceIdOrPath" is required.',
                }),
              },
            ],
          };
        }

        try {
          const wsManager = WorkspaceManager.getInstance();
          const selected = wsManager.setActiveWorkspace(workspaceIdOrPath);

          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify(
                  {
                    success: true,
                    workspaceId: selected.workspaceId,
                    canonicalPath: selected.canonicalPath,
                    label: selected.label,
                    isActive: selected.isActive,
                  },
                  null,
                  2
                ),
              },
            ],
          };
        } catch (err: any) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'SELECTION_FAILED',
                  message: err.message,
                }),
              },
            ],
          };
        }
      }

      if (name === 'list_workspaces') {
        const detailed = Boolean(args?.detailed);
        const wsManager = WorkspaceManager.getInstance();
        const list = wsManager.listAuthorizedWorkspaces();
        const active = wsManager.getActiveWorkspace();

        return {
          content: [
            {
              type: 'text',
              text: JSON.stringify(
                {
                  totalWorkspaces: list.length,
                  activeWorkspaceId: active?.workspaceId || null,
                  workspaces: list.map((ws) => ({
                    workspaceId: ws.workspaceId,
                    canonicalPath: ws.canonicalPath,
                    label: ws.label,
                    isActive: ws.isActive,
                    authorizedAt: ws.authorizedAt,
                    lastInspectedAt: ws.lastInspectedAt,
                    profile: detailed ? ws.profile : undefined,
                  })),
                },
                null,
                2
              ),
            },
          ],
        };
      }

      if (name === 'authorize_workspace') {
        const workspacePath = args?.workspacePath as string;
        const label = args?.label as string | undefined;
        const readOnly = Boolean(args?.readOnly);
        const allowedParentDirs = Array.isArray(args?.allowedParentDirs) ? (args.allowedParentDirs as string[]) : undefined;
        const policy = args?.policy as any;

        if (!workspacePath || typeof workspacePath !== 'string') {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameter "workspacePath" is required and must be a non-empty string.',
                }),
              },
            ],
          };
        }

        try {
          const wsManager = WorkspaceManager.getInstance();
          const authorized = wsManager.authorizeWorkspace(workspacePath, {
            label,
            readOnly,
            allowedParentDirs,
            policy,
          });

          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify(
                  {
                    success: true,
                    workspaceId: authorized.workspaceId,
                    canonicalPath: authorized.canonicalPath,
                    label: authorized.label,
                    isActive: authorized.isActive,
                    readOnly: authorized.readOnly,
                    securityConfig: authorized.securityConfig,
                    architectureStyle: authorized.profile?.architectureStyle,
                    primaryLanguage: authorized.profile?.languages.primaryLanguage,
                  },
                  null,
                  2
                ),
              },
            ],
          };
        } catch (err: any) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'AUTHORIZATION_FAILED',
                  message: err.message,
                }),
              },
            ],
          };
        }
      }

      if (name === 'verify_path_containment') {
        const targetPath = args?.targetPath as string;
        const workspacePath = args?.workspacePath as string | undefined;

        if (!targetPath || typeof targetPath !== 'string') {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameter "targetPath" is required.',
                }),
              },
            ],
          };
        }

        const wsManager = WorkspaceManager.getInstance();
        const result = wsManager.validatePathContainment(targetPath, workspacePath);

        return {
          isError: !result.isValid,
          content: [
            {
              type: 'text',
              text: JSON.stringify(result, null, 2),
            },
          ],
        };
      }

      if (name === 'request_write_approval') {
        const taskId = args?.taskId as string;
        const targetFilePath = args?.targetFilePath as string;
        const content = typeof args?.content === 'string' ? args.content : '';
        const workspacePath = args?.workspacePath as string | undefined;

        if (!taskId || !targetFilePath) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameters "taskId" and "targetFilePath" are required.',
                }),
              },
            ],
          };
        }

        try {
          const wsManager = WorkspaceManager.getInstance();
          const approval = wsManager.requestWriteApproval(taskId, targetFilePath, content, workspacePath);

          return {
            content: [
              {
                type: 'text',
                text: JSON.stringify(approval, null, 2),
              },
            ],
          };
        } catch (err: any) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'APPROVAL_REQUEST_FAILED',
                  message: err.message,
                }),
              },
            ],
          };
        }
      }

      if (name === 'confirm_write_approval') {
        const proposalId = args?.proposalId as string;
        const decision = args?.decision as 'APPROVE' | 'REJECT';
        const operatorId = args?.operatorId as string | undefined;
        const operatorAuthKey = args?.operatorAuthKey as string | undefined;
        const rationale = args?.rationale as string | undefined;

        if (!proposalId || !decision) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameters "proposalId" and "decision" are required.',
                }),
              },
            ],
          };
        }

        try {
          const wsManager = WorkspaceManager.getInstance();
          const confirmResult = wsManager.confirmWriteApproval({
            proposalId,
            decision,
            operatorId: operatorId || '',
            operatorAuthKey,
            rationale,
          });

          return {
            isError: !confirmResult.success,
            content: [
              {
                type: 'text',
                text: JSON.stringify(confirmResult, null, 2),
              },
            ],
          };
        } catch (err: any) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'CONFIRM_APPROVAL_FAILED',
                  message: err.message,
                }),
              },
            ],
          };
        }
      }

      if (name === 'write_workspace_file') {
        const taskId = args?.taskId as string;
        const targetFilePath = args?.targetFilePath as string;
        const content = typeof args?.content === 'string' ? args.content : '';
        const approvalToken = args?.approvalToken as string | undefined;
        const workspacePath = args?.workspacePath as string | undefined;
        const rationale = args?.rationale as string | undefined;

        if (!taskId || !targetFilePath) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'INVALID_ARGUMENT',
                  message: 'Parameters "taskId" and "targetFilePath" are required.',
                }),
              },
            ],
          };
        }

        try {
          const wsManager = WorkspaceManager.getInstance();
          const writeResult = await wsManager.writeWorkspaceFile(
            {
              taskId,
              targetFilePath,
              content,
              approvalToken,
              rationale,
            },
            workspacePath
          );

          return {
            isError: !writeResult.success,
            content: [
              {
                type: 'text',
                text: JSON.stringify(writeResult, null, 2),
              },
            ],
          };
        } catch (err: any) {
          return {
            isError: true,
            content: [
              {
                type: 'text',
                text: JSON.stringify({
                  error: 'WRITE_EXECUTION_ERROR',
                  message: err.message,
                }),
              },
            ],
          };
        }
      }

        return {
          isError: true,
          content: [
            {
              type: 'text',
              text: JSON.stringify({
                error: 'TOOL_NOT_FOUND',
                message: `Requested tool "${name}" is not supported by CUBiO MCP server.`,
              }),
            },
          ],
        };
      };

      const rawResult = await executeTool();
      if (rawResult.content && Array.isArray(rawResult.content)) {
        rawResult.content = rawResult.content.map((item: any) => {
          if (item && item.type === 'text' && typeof item.text === 'string') {
            return {
              ...item,
              text: SecretRedactor.redact(item.text).text,
            };
          }
          return item;
        });
      }
      return rawResult;
    } catch (err: any) {
      const safeMessage = SecretRedactor.redact(err?.message || 'An unexpected error occurred during execution.').text;
      console.error(`[CUBiO MCP] Error executing tool ${name}:`, safeMessage);
      return {
        isError: true,
        content: [
          {
            type: 'text',
            text: JSON.stringify({
              error: 'EXECUTION_ERROR',
              message: safeMessage,
            }),
          },
        ],
      };
    }
  });

  return server;
}

export async function runMcpStdioServer(): Promise<void> {
  const server = createCubiOMcpServer();
  const transport = new StdioServerTransport();

  // BUG-005: Robust stdio lifecycle listeners to prevent orphaned zombie processes
  // when client host disconnects, terminates, or cancels the session task.
  transport.onclose = () => {
    console.error('[CUBiO MCP] Stdio transport closed by client host. Exiting.');
    process.exit(0);
  };

  process.stdin.on('close', () => {
    console.error('[CUBiO MCP] Stdin closed by client host. Exiting.');
    process.exit(0);
  });

  process.stdin.on('end', () => {
    console.error('[CUBiO MCP] Stdin ended by client host. Exiting.');
    process.exit(0);
  });

  console.error('[CUBiO MCP] Connecting StdioServerTransport...');
  await server.connect(transport);
  console.error('[CUBiO MCP] Stdio server connected and listening.');
}

// Standalone execution entry
if (process.argv[1] && process.argv[1].endsWith('server.ts')) {
  runMcpStdioServer().catch((err) => {
    console.error('[CUBiO MCP] Fatal server error:', err);
    process.exit(1);
  });
}
