/**
 * CUBiO AI — 3D Memory Studio
 * src/cubio/security/secretRedactor.ts
 *
 * Universal Secret & Sensitive Credential Redactor.
 * Intercepts and masks secrets, tokens, passwords, and private keys in textual outputs,
 * diagnostic logs, persistent memory ledgers, and MCP tool responses.
 *
 * Guarantees zero sensitive data leakage across stdio, memory, or reports.
 */

export interface RedactionResult {
  readonly text: string;
  readonly redactionCount: number;
  readonly matchesFound: readonly string[];
}

export class SecretRedactor {
  private static readonly RULES: readonly { readonly name: string; readonly pattern: RegExp; readonly replacement: string | ((match: string, ...groups: any[]) => string) }[] = [
    // 1. Private Keys
    {
      name: 'PRIVATE_KEY',
      pattern: /-----BEGIN (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----[\s\S]*?-----END (?:RSA |EC |OPENSSH |DSA )?PRIVATE KEY-----/g,
      replacement: '[REDACTED_PRIVATE_KEY]',
    },
    // 2. GitHub Personal Access Tokens & OAuth
    {
      name: 'GITHUB_TOKEN',
      pattern: /(?:ghp|gho|ghu|ghs|ghr)_[a-zA-Z0-9]{36}/g,
      replacement: '[REDACTED_GITHUB_TOKEN]',
    },
    {
      name: 'GITHUB_FINE_GRAINED',
      pattern: /github_pat_[a-zA-Z0-9_]{82}/g,
      replacement: '[REDACTED_GITHUB_PAT]',
    },
    // 3. OpenAI / Anthropic / AI API Keys
    {
      name: 'AI_PROVIDER_KEY',
      pattern: /sk-(?:proj-|live-|ant-)?[a-zA-Z0-9_\-]{20,}/g,
      replacement: '[REDACTED_API_KEY]',
    },
    // 4. Google API Keys
    {
      name: 'GOOGLE_API_KEY',
      pattern: /AIzaSy[a-zA-Z0-9_\-]{20,}/g,
      replacement: '[REDACTED_GOOGLE_KEY]',
    },
    // 5. AWS Access Key IDs
    {
      name: 'AWS_ACCESS_KEY',
      pattern: /\b(?:AKIA|ASIA)[0-9A-Z]{16}\b/g,
      replacement: '[REDACTED_AWS_KEY]',
    },
    // 6. Webhook Secrets & Live Keys
    {
      name: 'WEBHOOK_SECRET',
      pattern: /whsec_[a-zA-Z0-9_\-]{24,}/gi,
      replacement: '[REDACTED_WEBHOOK_SECRET]',
    },
    // 7. Bearer / Authorization Headers
    {
      name: 'BEARER_TOKEN',
      pattern: /(Bearer\s+)[a-zA-Z0-9_\-\.=+/]{20,}/gi,
      replacement: '$1[REDACTED_BEARER_TOKEN]',
    },
    // 8. Key-Value Formats: API Key & Operator Authentication Keys
    {
      name: 'KV_API_KEY_QUOTED',
      pattern: /((?:\\?['"]?(?:api[_-]?key|apikey|operator[_-]?auth[_-]?key|auth[_-]?key)\\?['"]?)\s*[:=]\s*)(\\?['"])[a-zA-Z0-9_\-]{8,}\2/gi,
      replacement: '$1$2[REDACTED_API_KEY]$2',
    },
    {
      name: 'KV_API_KEY_UNQUOTED',
      pattern: /((?:\\?['"]?(?:api[_-]?key|apikey|operator[_-]?auth[_-]?key|auth[_-]?key)\\?['"]?)\s*[:=]\s*)[a-zA-Z0-9_\-]{8,}/gi,
      replacement: '$1[REDACTED_API_KEY]',
    },
    // 9. Key-Value Formats: Secret
    {
      name: 'KV_SECRET_QUOTED',
      pattern: /((?:\\?['"]?(?:secret|client[_-]?secret|auth[_-]?token|operator[_-]?secret|operator[_-]?key)\\?['"]?)\s*[:=]\s*)(\\?['"])[a-zA-Z0-9_\-]{8,}\2/gi,
      replacement: '$1$2[REDACTED_SECRET]$2',
    },
    {
      name: 'KV_SECRET_UNQUOTED',
      pattern: /((?:\\?['"]?(?:secret|client[_-]?secret|auth[_-]?token|operator[_-]?secret|operator[_-]?key)\\?['"]?)\s*[:=]\s*)[a-zA-Z0-9_\-]{8,}/gi,
      replacement: '$1[REDACTED_SECRET]',
    },
    // 10. Key-Value Formats: Password
    {
      name: 'KV_PASSWORD_QUOTED',
      pattern: /((?:\\?['"]?(?:password|passwd|pwd)\\?['"]?)\s*[:=]\s*)(\\?['"])[^'"\\\r\n]{4,}\2/gi,
      replacement: '$1$2[REDACTED_PASSWORD]$2',
    },
    {
      name: 'KV_PASSWORD_UNQUOTED',
      pattern: /((?:\\?['"]?(?:password|passwd|pwd)\\?['"]?)\s*[:=]\s*)[^\s'",;]{6,}/gi,
      replacement: '$1[REDACTED_PASSWORD]',
    },
    // 11. Environment Variable Assignments: API_SECRET=... / SECRET_KEY=...
    {
      name: 'ENV_SECRET_QUOTED',
      pattern: /([A-Z0-9_]*(?:SECRET|KEY|PASSWORD|TOKEN|AUTH)[A-Z0-9_]*\s*=\s*)(\\?['"])[^'"\\\r\n]{6,}\2/g,
      replacement: '$1$2[REDACTED_ENV_VALUE]$2',
    },
    {
      name: 'ENV_SECRET_UNQUOTED',
      pattern: /([A-Z0-9_]*(?:SECRET|KEY|PASSWORD|TOKEN|AUTH)[A-Z0-9_]*\s*=\s*)[^\s'",\r\n]{6,}/g,
      replacement: '$1[REDACTED_ENV_VALUE]',
    },
  ];

  private static readonly dynamicSecrets = new Set<string>();

  /**
   * Registers a dynamic secret string for unconditional redaction.
   * Ensures that raw secret values are masked wherever they appear in logs or errors,
   * even without a key prefix.
   */
  public static registerSensitiveString(secret: string): void {
    if (secret && typeof secret === 'string' && secret.trim().length >= 8) {
      SecretRedactor.dynamicSecrets.add(secret.trim());
    }
  }

  /**
   * Unregisters a sensitive secret string (e.g. upon rotation or revocation).
   */
  public static unregisterSensitiveString(secret: string): void {
    if (secret && typeof secret === 'string') {
      SecretRedactor.dynamicSecrets.delete(secret.trim());
    }
  }

  /**
   * Clears all registered dynamic sensitive strings.
   */
  public static clearSensitiveStrings(): void {
    SecretRedactor.dynamicSecrets.clear();
  }

  /**
   * Redacts sensitive patterns and registered dynamic secrets in a given string.
   */
  public static redact(text: string): RedactionResult {
    if (!text || typeof text !== 'string') {
      return { text: text ?? '', redactionCount: 0, matchesFound: [] };
    }

    let result = text;
    let count = 0;
    const matches: string[] = [];

    // 1. Direct redaction of registered dynamic secrets (raw values without keys)
    for (const secret of SecretRedactor.dynamicSecrets) {
      if (result.includes(secret)) {
        count++;
        matches.push('DYNAMIC_OPERATOR_SECRET');
        result = result.replaceAll(secret, '[REDACTED_OPERATOR_SECRET]');
      }
    }

    // 2. Pattern-based rule evaluation
    for (const rule of SecretRedactor.RULES) {
      rule.pattern.lastIndex = 0;
      if (rule.pattern.test(result)) {
        rule.pattern.lastIndex = 0;
        const found = result.match(rule.pattern);
        if (found) {
          count += found.length;
          matches.push(rule.name);
        }
        rule.pattern.lastIndex = 0;
        result = result.replace(rule.pattern, rule.replacement as any);
      }
    }

    return {
      text: result,
      redactionCount: count,
      matchesFound: Object.freeze(matches),
    };
  }

  /**
   * Recursively sanitizes JSON/object data structures by redacting string values.
   */
  public static redactObject<T>(obj: T): T {
    if (obj === null || obj === undefined) return obj;
    if (typeof obj === 'string') {
      return SecretRedactor.redact(obj).text as unknown as T;
    }
    if (Array.isArray(obj)) {
      return obj.map((item) => SecretRedactor.redactObject(item)) as unknown as T;
    }
    if (typeof obj === 'object') {
      const cloned: Record<string, any> = {};
      for (const [key, value] of Object.entries(obj)) {
        if (
          typeof value === 'string' &&
          /^(?:operator[_-]?auth[_-]?key|operator[_-]?key|auth[_-]?key|secret|client[_-]?secret|password|passwd|token|apikey|api[_-]?key)$/i.test(key)
        ) {
          cloned[key] = '[REDACTED_SECRET]';
        } else {
          cloned[key] = SecretRedactor.redactObject(value);
        }
      }
      return cloned as T;
    }
    return obj;
  }
}
